// Content for Swipe Right? (Dating & Apps (node g45, ages 18-22, Chapter 6)) NEW v2 build to GDD 45
// (mechanic-embodying), the College dating node (Thread D · Relationships). Reworks the old ModesEngine build
// onto the shared v2 engine. "Dating now runs on apps and DMs: meet safely, spot the fakes, handle rejection
// both ways, and treat people like people, not profiles." 84 researched, India-grounded scenarios across
// dating-now → meeting-safely → fakes-and-ghosts → date-with-respect → profiles-are-people → tools-and-help,
// each encoded as one of the shared v2 play actions (branch / strike-rewrite / sort / reflect / role-play /
// spot / match): no binary "tap the right card". Lead: branch (your move), strike-rewrite (bust the myth),
// role-play (say the line). Practical safety, NEVER fear-mongering: meet in public, tell a trusted friend, your
// own way home, stay sober, trust your gut, video-verify before meeting. Verify AI-generated & catfish profiles
// (a live video call is the reliable check); be skeptical of fast love and money asks (romance scams); ghosting
// and leading-on isn't okay; rejection is survivable both ways. Profiles are people; consent and decency don't
// pause for apps (carried from g44/g31). Even-handed across genders and orientations. India: dating often hidden
// from family, so tell a trusted friend even if not family; image-based abuse/harassment routes to cybercrime
// 1930 / cybercrime.gov.in, 1098/181. Builds on g24 (GLRL), g40 (Firewall), g44 (Consent, For Real); precedes
// g46. gameId "swipe-right".
import type { V2GameConfig, Scenario } from "./v2-schema";

const SCENARIOS: Scenario[] = [
  {"id":"sr-001","cat":"dating-now","type":"strike-rewrite","hook":"\"A dating profile shows what someone's really like.\"","myth":{"un":"A profile shows what someone's really like.","re":"A profile is a curated highlight reel; you only really learn someone over time.","why":"Best photos and lines aren't the whole person."},"relearn":"A profile is a highlight reel; you learn someone over time, not from a profile.","persona":"any","source":"realistic expectations"},
  {"id":"sr-002","cat":"dating-now","type":"reflect","hook":"Lensy: apps are just one doorway to meeting people, not a scoreboard. Sit right with you?","prompt":"What do you think?","options":["Yes","Not a scoreboard","Just a doorway"],"affirm":"Treating matches as people, not points, makes the whole thing healthier and kinder.","relearn":"Apps are a doorway to meeting people, not a scoreboard.","persona":"any","source":"healthy framing"},
  {"id":"sr-003","cat":"dating-now","type":"sort","hook":"Sort: a realistic expectation, or an app-fuelled illusion?","items":[{"id":"a","text":"Most chats won't go anywhere, and that's normal"},{"id":"b","text":"The right person is one perfect swipe away"},{"id":"c","text":"People are more than their best photos"},{"id":"d","text":"More matches means more worth"},{"id":"e","text":"You learn someone slowly, over real talk"},{"id":"f","text":"A great profile must mean a great person"}],"bins":[{"id":"real","label":"Realistic","valence":"pos"},{"id":"illusion","label":"Illusion","valence":"neg"}],"key":{"a":"real","b":"illusion","c":"real","d":"illusion","e":"real","f":"illusion"},"relearn":"Fizzling chats, people-over-photos and slow-knowing are real; 'perfect swipe' and match-counting are illusion.","persona":"any","source":"expectations"},
  {"id":"sr-004","cat":"dating-now","type":"branch","persona":"Deepak","source":"self-worth","hook":"Your last five matches have all fizzled out after a few messages.","steps":[{"prompt":"You're lying in bed scrolling through the dead chats. What do you tell yourself?","options":[{"text":"Something must be wrong with me","then":"You lie awake listing your flaws. The list gets longer."},{"text":"Other people clearly have it easier","then":"You scroll a friend's stories full of dates and feel worse."},{"text":"Most chats fade. It's not a verdict on me","then":"You put the phone down. It still stings, but it's smaller.","best":true},{"text":"I just need better photos and I'll be fine","then":"You spend an hour on photos. Your mood now hangs on the next match."}],"why":"Chats fizzling is normal. It says nothing about your worth."},{"prompt":"The next day, your friend Ravi jokes that maybe you're just not app material. What do you do?","options":[{"text":"Agree that you're just not app material","then":"The label sticks. You stop replying to the matches you do have."},{"text":"Laugh, and say fizzles happen to everyone","then":"Ravi admits most of his chats die too. You both feel better.","best":true},{"text":"Ask him to rewrite your whole profile","then":"Ravi makes you sound like someone else. The new matches don't feel like yours."},{"text":"Get defensive and change the subject","then":"Ravi backs off, but his line replays in your head all day."}],"why":"Fizzles happen to everyone. Saying so out loud keeps a joke from becoming a verdict."},{"prompt":"That weekend, you notice your mood rises and falls with every match. What do you do?","options":[{"text":"Swipe more, to get more matches faster","then":"You match more, chat less, and feel emptier."},{"text":"Pay for a premium plan to boost your profile","then":"The boost brings more likes. Your mood still swings with each one."},{"text":"Take a break from the app for a while","then":"The first days feel odd. By Sunday, you've caught up with two old friends.","best":true},{"text":"Turn off notifications but keep checking","then":"You check even more often now, just to be sure."}],"why":"A break when the app drains you is a healthy choice, not giving up."},{"prompt":"A few weeks later, you match with Divya and the chat flows easily. What do you do?","options":[{"text":"Treat it as proof you're finally worth something","then":"When she's slow to reply one day, the old spiral comes right back."},{"text":"Pour everything in, since this one has to work","then":"You send long messages. Divya's replies get shorter."},{"text":"Hold back so a fizzle won't hurt this time","then":"Your replies come out careful and flat. The chat slows."},{"text":"Enjoy the chat as it is, with no big stakes","then":"You chat for a few days, then suggest chai. Divya says yes.","best":true}],"why":"Enjoying a chat for what it is, not as a verdict on you, keeps it light."}],"debrief":"Apps churn. Most chats fade for no deep reason, and it says nothing about your worth.","relearn":"Chats fizzling is normal and not a verdict on your worth."},
  {"id":"sr-005","cat":"dating-now","type":"strike-rewrite","hook":"\"Everyone's hooking up constantly; I'm behind.\"","myth":{"un":"Everyone's hooking up constantly; I'm behind.","re":"App life is a highlight reel; people share wins, not the quiet weeks, and there's no timetable.","why":"You're comparing to a curated feed again."},"relearn":"There's no dating timetable; you're comparing to a highlight reel.","persona":"any","source":"comparison"},
  {"id":"sr-006","cat":"dating-now","type":"reflect","hook":"Lensy: going slow, or taking breaks from apps, is completely fine. Permission granted?","prompt":"What do you think?","options":["Yes","Slow is fine","Breaks are healthy"],"affirm":"Your pace is yours; slowing down or stepping back is a healthy choice, not a failure.","relearn":"Going slow or taking breaks from apps is completely fine.","persona":"any","source":"your pace"},
  {"id":"sr-007","cat":"dating-now","type":"sort","hook":"Sort: a green way to use apps, or a draining one?","items":[{"id":"a","text":"Chatting with a few people you click with"},{"id":"b","text":"Doomscrolling profiles for hours"},{"id":"c","text":"Logging off when it stops being fun"},{"id":"d","text":"Tying your mood to your match count"},{"id":"e","text":"Taking a break when apps feel like a chore"},{"id":"f","text":"Refreshing for a 'like' every few minutes"}],"bins":[{"id":"green","label":"Healthy","valence":"pos"},{"id":"drain","label":"Draining","valence":"neg"}],"key":{"a":"green","b":"drain","c":"green","d":"drain","e":"green","f":"drain"},"relearn":"Chatting with a few, logging off and taking breaks is healthy; doomscrolling, mood-by-matches and refresh-craving drains.","persona":"any","source":"healthy use"},
  {"id":"sr-008","cat":"dating-now","type":"spot","hook":"Spot the two illusions about how dating works now.","scene":[{"id":"a","text":"\"We might just not click, and that's okay\"","trick":false},{"id":"b","text":"\"This match will definitely be The One\"","trick":true},{"id":"c","text":"\"I'll know them properly only over time\"","trick":false},{"id":"d","text":"\"A good profile proves they're a good partner\"","trick":true},{"id":"e","text":"\"It's fine if this chat just fades out\"","trick":false}],"why":"'Definitely The One' and 'good profile = good partner' are illusions; clicks are uncertain, knowing takes time.","relearn":"Real dating expects uncertain clicks and slow-knowing, not a verdict from a profile.","persona":"any","source":"expectations"},
  {"id":"sr-009","cat":"dating-now","type":"reflect","hook":"Lensy: you bring your whole self to dating, you're not just a profile either. Worth remembering?","prompt":"What do you think?","options":["Yes","I'm more than a profile","Whole self"],"affirm":"You're a whole person, not a set of photos, and so is everyone you meet.","relearn":"You're a whole person, not a profile, and so is everyone you meet.","persona":"any","source":"profiles are people"},
  {"id":"sr-010","cat":"dating-now","type":"branch","persona":"any","source":"app design","hook":"Your dating app keeps nudging you to swipe faster or pay up so you don't miss out.","steps":[{"prompt":"A pop-up says your likes expire in ten minutes. What do you do?","options":[{"text":"Swipe fast through everyone before time runs out","then":"You swipe right on thirty people and can't remember any of them."},{"text":"Close it. Urgency is how the app sells","then":"The timer runs out. Nothing about your matches seems different.","best":true},{"text":"Pay just this once to see who liked you","then":"You see four faces. None of them message you."},{"text":"Leave it open and keep glancing at the timer","then":"You spend the ten minutes watching a countdown."}],"why":"That countdown is designed to rush you. Stepping back puts you in charge."},{"prompt":"That evening, you notice you've opened the app twenty times today. What do you do?","options":[{"text":"Turn on every notification so you never miss a match","then":"Your phone buzzes through dinner, and your mood goes up and down with it."},{"text":"Delete it in a rage, then reinstall at midnight","then":"By midnight you're back, swiping faster to make up for lost time."},{"text":"Tell yourself everyone checks this much","then":"It's easier not to notice. Tomorrow you open it thirty times."},{"text":"Set yourself one short app time a day","then":"The app sits quieter in your day. You actually read the profiles you open.","best":true}],"why":"Using the app on purpose, not on impulse, beats being pulled by its design."},{"prompt":"A friend says the paid plan is the only way to get real matches. What do you do?","options":[{"text":"Buy it straight away so you don't fall behind","then":"The payment goes through. Your chats feel the same as before."},{"text":"Decide free users just can't find anyone","then":"You start feeling like the app has already sorted you."},{"text":"Pay for a year, since it's cheaper per month","then":"You're locked in for a year. The urgency pop-ups don't stop."},{"text":"Decide calmly, on your own terms, if it's worth it","then":"You look at what it actually offers, and decide to wait a month.","best":true}],"why":"Paying or not is your call. Making it calmly, not in a rush, is the point."}],"debrief":"Apps are designed to keep you swiping. Using them on purpose beats being rushed.","relearn":"Notice the app's urgency design and date on your own terms."},
  {"id":"sr-011","cat":"dating-now","type":"strike-rewrite","hook":"\"If you matched, you owe them a reply or a date.\"","myth":{"un":"If you matched, you owe them a reply or a date.","re":"Matching owes nothing; you can stop talking or change your mind any time.","why":"A match is an opening, not a contract."},"relearn":"Matching owes nothing; you can change your mind any time.","persona":"any","source":"no obligation"},
  {"id":"sr-012","cat":"dating-now","type":"sort","hook":"Sort: a healthy reason to date, or a shaky one?","items":[{"id":"a","text":"You're curious and open to meeting people"},{"id":"b","text":"To prove you're wanted"},{"id":"c","text":"You enjoy getting to know someone"},{"id":"d","text":"Because everyone else seems to be"},{"id":"e","text":"You'd like real company, in your own time"},{"id":"f","text":"To make an ex jealous"}],"bins":[{"id":"healthy","label":"Healthy","valence":"pos"},{"id":"shaky","label":"Shaky","valence":"neg"}],"key":{"a":"healthy","b":"shaky","c":"healthy","d":"shaky","e":"healthy","f":"shaky"},"relearn":"Curiosity, enjoying people and wanting company are healthy reasons; proving your worth, FOMO and spite are shaky.","persona":"any","source":"motivation"},
  {"id":"sr-013","cat":"dating-now","type":"reflect","hook":"Lensy: the goal isn't winning the app, it's meeting someone you actually like. Agree?","prompt":"What do you think?","options":["Yes","Real connection","Not winning"],"affirm":"Real connection, not app stats, is the whole point; keep your eyes on that.","relearn":"The goal is real connection, not winning the app.","persona":"any","source":"the goal"},
  {"id":"sr-014","cat":"dating-now","type":"match","hook":"Match the dating reality to what it means for you.","pairs":[{"left":"A profile is a highlight reel","right":"Learn them over time"},{"left":"Most chats fizzle","right":"It's normal, not about you"},{"left":"Matching owes nothing","right":"You can stop any time"},{"left":"Apps are a doorway","right":"Not a scoreboard to win"},{"left":"Slowing down is fine","right":"Your pace is yours"}],"relearn":"Highlight reels, fizzling chats, no-obligation matches, doorways-not-scoreboards and your-own-pace are the realistic basics.","persona":"any","source":"reality basics"},
  {"id":"sr-015","cat":"meeting-safely","type":"branch","persona":"Ananya","source":"meet safely","hook":"You're meeting your app match Parth in person for the first time this Sunday.","steps":[{"prompt":"He suggests you just come over to his place since it's easier. What do you do?","options":[{"text":"Go to his place. It's only chai","then":"Parth sends his address, and nobody else knows where you're going."},{"text":"Suggest a busy cafe instead","then":"Parth says sure, and sends a cafe near the metro.","best":true},{"text":"Invite him to your place instead","then":"Parth agrees fast, and now he knows where you live."},{"text":"Meet at his building's gate, then decide","then":"Parth agrees, and you'll be at his door with no plan if it feels off."}],"why":"A first meet goes in public. Somewhere private can come much later, if ever."},{"prompt":"The night before, you're thinking about who to tell. What do you do?","options":[{"text":"Tell nobody. It's your business","then":"The plan stays in your head and nowhere else."},{"text":"Post a hint on your story instead","then":"A few people react, but nobody knows where you'll be."},{"text":"Tell a friend it's a date, but not where","then":"Your friend is excited, but has no idea where you'll be."},{"text":"Text a trusted friend the place and time","then":"Your friend Diya replies: \"Got it. Text me after!\"","best":true}],"why":"A trusted friend who knows where you are is your safety net."},{"prompt":"On Sunday morning, Parth offers to pick you up. What do you do?","options":[{"text":"Thank him, and say you'll make your own way","then":"Parth replies: \"Cool. See you there at four.\"","best":true},{"text":"Accept. It'd be rude to say no","then":"Parth asks for your address so he can come by."},{"text":"Accept, but get picked up at the corner","then":"He still learns your street, and drives you both."},{"text":"Tell him you don't get in strangers' cars","then":"Parth replies: \"Wow. Okay, stranger.\""}],"why":"Your own way there and back means you decide when the date ends."},{"prompt":"An hour in, it's going fine, but you're ready to go. What do you do?","options":[{"text":"Stay longer so he doesn't feel rejected","then":"You stay an extra hour, checking the time."},{"text":"Say you've had fun and head off","then":"Parth smiles. \"Same. Let's do this again.\"","best":true},{"text":"Invent an emergency so you can leave","then":"Parth offers to drive you, worried."},{"text":"Wait for him to end it first","then":"The date stretches on, and you're too tired to enjoy it."}],"why":"You can leave whenever you like. A warm, short goodbye is enough."},{"prompt":"On the way home, your phone buzzes. What do you do?","options":[{"text":"Ignore it till tomorrow. You're fine","then":"Nobody hears from you, and any worry stays unanswered."},{"text":"Reply to Parth first, and forget the rest","then":"Parth is sweet, but no one else knows you're out."},{"text":"Text your friend that you're on your way","then":"Your friend sends a thumbs up, and you can relax.","best":true},{"text":"Post a date selfie with the cafe tagged","then":"Everyone can see where you were, and where you've just left."}],"why":"A quick 'on my way' text closes the loop on a safe first meet."}],"debrief":"A public place and a friend who knows are the foundation of meeting safely.","relearn":"Meet first in public and tell a trusted friend where you'll be."},
  {"id":"sr-016","cat":"meeting-safely","type":"sort","hook":"Sort: a meet-safe basic, or a risk?","items":[{"id":"a","text":"Your own transport there and back"},{"id":"b","text":"Letting them pick you up first time"},{"id":"c","text":"Staying sober enough to think clearly"},{"id":"d","text":"Telling no one where you are"},{"id":"e","text":"Meeting in a busy public spot"},{"id":"f","text":"Going straight to their place"}],"bins":[{"id":"safe","label":"Meet-safe","valence":"pos"},{"id":"risk","label":"Risk","valence":"neg"}],"key":{"a":"safe","b":"risk","c":"safe","d":"risk","e":"safe","f":"risk"},"relearn":"Your own transport, staying clear-headed and a public spot are meet-safe; being picked up, telling no one or going to their place are risks.","persona":"any","source":"meet safely"},
  {"id":"sr-017","cat":"meeting-safely","type":"role-play","persona":"any","source":"safety net","hook":"You're meeting a match tomorrow and want your flatmate Neha to know the plan.","setup":"She's folding laundry when you bring it up.","steps":[{"prompt":"Neha asks: \"Big date tomorrow? Where are you off to?\"","options":[{"text":"\"Somewhere in town. I'll tell you all about it after, promise.\"","then":"Neha nods. \"Okay, have fun.\" She has no idea where you'll be."},{"text":"\"It's only a first date. Nothing to worry about.\"","then":"\"Sure,\" she says, and goes back to the laundry."},{"text":"\"The cafe near the station at 7. I'll text you when I'm home.\"","then":"Neha grins. \"Deal. If I don't hear by 11, I'm calling you.\"","best":true},{"text":"\"Just call me at 9 with a fake emergency, okay?\"","then":"Neha laughs. \"Sure. But where are you even going?\""}],"why":"A place, a time and a check-in give your friend what they need to have your back."},{"prompt":"Neha texts at 9: \"All okay? Where are you guys now?\"","options":[{"text":"\"Yes! Having fun. I'll tell you everything tomorrow.\"","then":"\"Yay,\" she replies. She doesn't know where you are, and won't expect a text tonight."},{"text":"\"All good! Moved to Brew Lab next door. Home by 11.\"","then":"\"Perfect,\" she replies. \"I'll keep my phone on.\"","best":true},{"text":"\"Relax. I can look after myself.\"","then":"She sends a thumbs up and goes quiet. You feel a bit bad for snapping."},{"text":"\"Can't talk. Tell you later.\"","then":"\"Okay...\" she replies, and starts wondering where you are."}],"why":"A quick update when plans change keeps your safety net useful."},{"prompt":"Next morning, Neha asks: \"So, how'd it go? Want me as your check-in next time too?\"","options":[{"text":"\"Yes please. Place, time, and a text when I'm home.\"","then":"\"Deal,\" Neha says. \"And you do the same for me.\"","best":true},{"text":"\"No need. It went fine, so I'll skip it next time.\"","then":"Neha raises an eyebrow. \"Your call.\" Next time nobody will know where you are."},{"text":"\"Maybe. I don't want to bother you every time.\"","then":"\"You're not a bother,\" she says, but you leave it vague."},{"text":"\"Sure, but I'll just text after. You don't need the plan.\"","then":"\"Okay,\" she says. She'd know you're home, but not where to look if you weren't."}],"why":"Checking in every time, even after a good date, is what makes it a habit."}],"relearn":"Tell a trusted friend the plan and check in after; a simple safety net."},
  {"id":"sr-018","cat":"meeting-safely","type":"branch","persona":"any","source":"trust your gut","hook":"An hour into a date with Aakash, something feels off, though you can't say what.","steps":[{"prompt":"He's pleasant enough, but your gut is uneasy. What do you do?","options":[{"text":"Stay, since leaving would seem rude","then":"The unease grows as he orders another round."},{"text":"Trust it, head home, and text a friend","then":"Aakash says okay and asks for the bill. Your friend replies: \"Text me once you're home.\"","best":true},{"text":"Tell yourself you're being dramatic","then":"You push the feeling down, and it keeps pushing back."},{"text":"Text a friend, and stay put for now","then":"Your friend replies 'u ok?', and you're still sitting there uneasy."}],"why":"You can leave any time, and your gut needs no reason. A friend in the loop helps."},{"prompt":"As the evening ends, Aakash asks why you seemed distant. What do you say?","options":[{"text":"Just that you're ready to head home","then":"Aakash nods slowly. \"Okay. Get home safe.\"","best":true},{"text":"Promise to explain properly over text later","then":"Aakash says he'll wait for it. Now you feel you owe him an answer."},{"text":"Apologise, and promise you'll relax next time","then":"He smiles and suggests a second date right away."},{"text":"List everything that felt off to you","then":"Aakash argues each point, and you're still standing there."}],"why":"You don't owe a reason. A short, honest line is enough."},{"prompt":"Aakash texts the next day asking for a second date. What do you do?","options":[{"text":"Say yes so you don't seem unfair","then":"A second date gets booked, and the unease returns."},{"text":"Wonder if your gut ruined a good thing","then":"You reread his text, and start doubting yourself."},{"text":"Say yes, but only somewhere public","then":"The plan's safer, but you're going when your gut said no."},{"text":"Thank him and say it's not for you","then":"Aakash replies: \"No worries. Take care.\"","best":true}],"why":"Your gut's no carries forward. A brief, kind no is enough."}],"debrief":"Trusting your gut and leaving is always allowed. You never owe your time at the cost of your safety.","relearn":"If your gut says leave, leave; you don't owe a reason."},
  {"id":"sr-019","cat":"meeting-safely","type":"sort","hook":"Sort: keeps you safer on a first meet, or not?","items":[{"id":"a","text":"Meeting in a busy public spot"},{"id":"b","text":"Sharing your home address upfront"},{"id":"c","text":"Having your own way home"},{"id":"d","text":"Getting very drunk to relax"},{"id":"e","text":"Telling a friend the plan"},{"id":"f","text":"Going dark, replying to no one"}],"bins":[{"id":"safer","label":"Safer","valence":"pos"},{"id":"not","label":"Not","valence":"neg"}],"key":{"a":"safer","b":"not","c":"safer","d":"not","e":"safer","f":"not"},"relearn":"A public spot, your own way home and a friend told keep you safer; sharing your address, getting wasted or going dark don't.","persona":"any","source":"meet safely"},
  {"id":"sr-020","cat":"meeting-safely","type":"branch","persona":"any","source":"red flag","hook":"Before your first meet, Tushar suggests skipping the cafe and coming to his flat.","steps":[{"prompt":"He says cafes are loud and his flat is 'chill'. What do you do?","options":[{"text":"Agree, since keen people don't need rules","then":"Tushar sends his address, and nobody else knows it."},{"text":"Worry that saying no will seem uptight","then":"You type and delete three replies while he waits."},{"text":"Say you'll keep the first meet public","then":"Tushar replies, \"Okay, cafe it is,\" with a shrug emoji.","best":true},{"text":"Suggest a park, but let him pick which","then":"Tushar picks one far from you, and offers to drive."}],"why":"A public first meet is a normal boundary. A real match understands."},{"prompt":"Your friend Mehak asks how the plan with Tushar is going. What do you say?","options":[{"text":"Tell her he pushed for his flat","then":"Mehak frowns. \"That push is the red flag. Keep it public.\"","best":true},{"text":"Say it's all fine, and change the subject","then":"Mehak lets it go, and you're left with the doubt."},{"text":"Say you'll decide on the day","then":"Mehak says okay, but neither of you has a plan."},{"text":"Laugh that you're probably overreacting","then":"Mehak laughs too, and the push never gets named."}],"why":"Telling a friend the full plan lets someone safe spot the flag with you."},{"prompt":"On the day, Tushar messages that his place is 'way easier' than any cafe. What do you do?","options":[{"text":"Believe you'll lose him if you say no","then":"The worry grows, and his messages keep coming."},{"text":"Keep it public, or cancel if he won't","then":"Tushar writes: \"Fine. Cafe. Still don't see why you're so stiff.\"","best":true},{"text":"Follow a friend's tip to 'just go with it'","then":"You start to waver, and Tushar pushes harder."},{"text":"Lecture him on what red flags are","then":"Tushar gets defensive, and the chat turns into a debate."}],"why":"Pressure to skip the public meet is a flag, and never your fault. Hold your plan."},{"prompt":"Then Tushar texts that a 'real' connection means trusting him at his place. What do you do?","options":[{"text":"Wonder if he's right about real connection","then":"You start doubting your own plan."},{"text":"Send him an article on dating safety","then":"He replies: \"Wow, so you think I'm dangerous?\""},{"text":"Tell him it's a no, and call off the meet","then":"Tushar sends one sulky text, then goes silent. Your weekend is yours again.","best":true},{"text":"Decide it's your fault for seeming too keen","then":"The guilt makes you second-guess everything you said."}],"why":"Pushing again and again past your plan is the red flag, and it's on him. You can walk away."}],"debrief":"Pressure to skip a public first meet is itself a red flag. A good match respects it.","relearn":"Keep the first meet public; pressure to skip it is a red flag."},
  {"id":"sr-021","cat":"meeting-safely","type":"spot","hook":"Spot the two unsafe first-meet plans here.","scene":[{"id":"a","text":"Busy cafe, friend knows, own cab home","trick":false},{"id":"b","text":"Their flat, no one told, their car","trick":true},{"id":"c","text":"Daytime, public, sober, phone charged","trick":false},{"id":"d","text":"Late-night, private, no way home","trick":true},{"id":"e","text":"Met at a market, fare in hand","trick":false}],"why":"Going to a private place with no one told and no way home are the unsafe plans; public, told-a-friend, own-ride ones are safe.","relearn":"A safer first meet is public, told-a-friend, own-transport and sober.","persona":"any","source":"meet safely"},
  {"id":"sr-022","cat":"meeting-safely","type":"role-play","persona":"any","source":"video-verify","hook":"You've been chatting with Tanvi for two weeks and want a video call before you meet.","setup":"She's in a chatty mood tonight.","steps":[{"prompt":"Tanvi asks: \"Coffee on Saturday? I know a great place.\"","options":[{"text":"\"Saturday works! We can skip a call, right?\"","then":"\"Sure!\" she says, and sends the cafe name. You still haven't seen her live."},{"text":"\"Only if you prove you're real first.\"","then":"A pause. \"Prove it how? That sounds a bit harsh.\""},{"text":"\"Sounds fun! Quick video call first?\"","then":"\"Oh, sure!\" Tanvi says. \"This week's packed, but soon.\"","best":true},{"text":"\"Sure. Can you send a selfie with today's date?\"","then":"\"Um, okay?\" A selfie arrives. It could still be edited or made by AI."}],"why":"Framing a call as fun keeps it light, and a live call is the check that works."},{"prompt":"Two days later, Tanvi writes: \"My friend asked if we've video-called yet. Is a call a must for you?\"","options":[{"text":"\"Not really. The photos are enough for me.\"","then":"\"Okay!\" she says. Saturday is now a meet with someone you haven't seen live."},{"text":"\"Yes. For me it's just a normal first step.\"","then":"\"Fair,\" Tanvi says. \"Honestly, it makes me feel safer too.\"","best":true},{"text":"\"It is. You might be hiding something.\"","then":"Tanvi goes quiet. \"Hiding what, exactly?\""},{"text":"\"Whatever you're comfortable with is fine by me.\"","then":"\"Cool,\" she says, and the call quietly drops off the plan."}],"why":"Calling it a normal step, without apology or attack, makes it easy to keep."},{"prompt":"On Friday, Tanvi asks: \"So are we still on for coffee tomorrow?\"","options":[{"text":"\"Yes, after a quick call tonight. Say 8?\"","then":"\"8 works,\" she replies with a smiley. The call is on the calendar.","best":true},{"text":"\"Yes! See you there.\"","then":"She sends the time. You'll meet a face you've only seen in photos."},{"text":"\"Let me see how I feel tomorrow.\"","then":"\"Oh, okay,\" she says, unsure where she stands."},{"text":"\"Only if you send me your college ID first.\"","then":"\"My college ID?\" Tanvi types, then stops. \"That's a lot.\""}],"why":"Holding the call before the meet, warmly, gets you both there safely."}],"relearn":"A quick video call before meeting verifies they're real and lowers risk."},
  {"id":"sr-023","cat":"meeting-safely","type":"branch","persona":"Aarti","source":"India / told a friend","hook":"Your family doesn't know you're dating, and you're meeting Imran on Saturday.","steps":[{"prompt":"You feel you can't tell anyone where you'll be. What do you do?","options":[{"text":"Tell no one, to keep it fully secret","then":"Only you and Imran know where you'll be on Saturday."},{"text":"Tell a trusted friend, even if not family","then":"Your friend Sneha replies: \"Got it. Send me the cafe name?\"","best":true},{"text":"Tell a friend it's a date, but not where","then":"Your friend is excited, but can't help if plans change."},{"text":"Post the plan on your close-friends story","then":"A few people react, but nobody's really keeping track."}],"why":"A trusted friend knowing your plan is a safety net, not a betrayal."},{"prompt":"On Saturday, you arrive and see your phone is at ten percent. What do you do?","options":[{"text":"Scroll to calm your nerves till he arrives","then":"By the time Imran arrives, you're at three percent."},{"text":"Ask Imran to drop you home if it dies","then":"Imran agrees, and your exit is now in his hands."},{"text":"Switch it off to save it for later","then":"The battery's saved, but nobody knows you've arrived."},{"text":"Send a friend a quick 'I'm here' text","then":"Your friend replies with a thumbs up, and your battery holds.","best":true}],"why":"A quick check-in keeps someone safe in the loop."},{"prompt":"After the date, you're on your way home. What do you do?","options":[{"text":"Text your friend once you're home","then":"Your friend replies: \"Yay. Tell me everything tomorrow.\"","best":true},{"text":"Skip it. Nothing went wrong","then":"Nobody hears from you, and any worry stays unanswered."},{"text":"Post a date photo with the cafe tagged","then":"Your location is public now, while Imran's still nearby."},{"text":"Text Imran instead, since he knows","then":"Imran replies, but nobody who's looking out for you knows."}],"why":"A 'home safe' text closes the loop for whoever's looking out for you."}],"debrief":"Dating may be private from family, but a trusted friend knowing where you are keeps you safer.","relearn":"Even if family can't know, tell a trusted friend where you'll be."},
  {"id":"sr-024","cat":"meeting-safely","type":"sort","hook":"Sort: a good exit plan, or stuck?","items":[{"id":"a","text":"Your own ride booked in advance"},{"id":"b","text":"Relying on them to drop you"},{"id":"c","text":"Enough money or app credit to leave"},{"id":"d","text":"No way home but with them"},{"id":"e","text":"A friend ready to call you"},{"id":"f","text":"Their lift as your only option"}],"bins":[{"id":"exit","label":"Exit plan","valence":"pos"},{"id":"stuck","label":"Stuck","valence":"neg"}],"key":{"a":"exit","b":"stuck","c":"exit","d":"stuck","e":"exit","f":"stuck"},"relearn":"Your own ride, fare to leave and a friend on call make an exit plan; depending on them for the way home leaves you stuck.","persona":"any","source":"exit plan"},
  {"id":"sr-025","cat":"meeting-safely","type":"strike-rewrite","hook":"\"Taking safety precautions means you're paranoid.\"","relearn":"Safety steps aren't fear; they're how you date freely and relax.","persona":"any","source":"safety as freedom","myth":{"un":"Taking safety precautions means you're paranoid.","re":"Safety steps aren't fear; they're simply how you date freely and relax.","why":"Good habits free you up, they don't hold you back."}},
  {"id":"sr-026","cat":"meeting-safely","type":"branch","persona":"any","source":"info boundaries","hook":"Anmol, a match you haven't met, asks for your exact home address on day three.","steps":[{"prompt":"He says he wants to send you a surprise gift. What do you do?","options":[{"text":"Keep it vague and say maybe later","then":"Anmol sends a pouting emoji. \"Okay, mystery person.\"","best":true},{"text":"Send it so you seem trusting","then":"Anmol replies \"Perfect!\", and now knows your home address."},{"text":"Give your college address instead","then":"Anmol now knows where you spend every weekday."},{"text":"Tell him that's a creepy thing to ask","then":"Anmol gets defensive: \"I was being nice!\""}],"why":"Your address is yours to guard. Share it only once real trust is built."},{"prompt":"A few days later, Anmol asks what time you usually get home, 'just roughly'. What do you do?","options":[{"text":"Tell him roughly, since it's only a time","then":"Anmol says he often passes by around then."},{"text":"Keep it general: 'depends on the day'","then":"Anmol writes, \"Fair,\" and moves on for now.","best":true},{"text":"Ask why he keeps asking","then":"\"Just curious,\" he writes, and asks again later."},{"text":"Share your weekly timetable to seem open","then":"Now he knows where you'll be, hour by hour."}],"why":"General is enough for now. Details are earned, not owed."},{"prompt":"Anmol then says he'd like to bring the gift to your place himself. What do you do?","options":[{"text":"Wonder if you're being too guarded","then":"The doubt grows, and his asks keep coming."},{"text":"Promise he can, after a first date","then":"Anmol holds you to it the minute the date ends."},{"text":"Say no, and keep any meet in public","then":"Anmol writes, \"Fine,\" and then, \"You're so guarded.\"","best":true},{"text":"Tell yourself a gift means he's harmless","then":"You relax, and he asks which floor you're on."}],"why":"Guarding your home isn't rude, and his pushing is never your fault."},{"prompt":"Your flatmate Tanvi sees you frowning at Anmol's messages. What do you do?","options":[{"text":"Show her the chat and ask what she thinks","then":"Tanvi reads it. \"That's a lot of pushing. Want to report him?\"","best":true},{"text":"Say it's nothing, and keep it to yourself","then":"Tanvi shrugs, and you're left alone with his messages."},{"text":"Laugh that someone wants to send you gifts","then":"Tanvi laughs along, and the pushing goes unnamed."},{"text":"Ask if you're being too uptight about it","then":"Tanvi says \"maybe\" without seeing the chat, and you feel worse."}],"why":"A friend can spot the pattern with you. Pushing for your address is never your fault."}],"debrief":"Personal details like your address are earned, not given to a stranger to seem nice.","relearn":"Guard your address; share it only when real trust is built."},
  {"id":"sr-027","cat":"meeting-safely","type":"spot","hook":"Spot the two lines that pressure you to drop a safety step.","scene":[{"id":"a","text":"\"Just come over, don't be so uptight\"","trick":true},{"id":"b","text":"\"A public cafe sounds great\"","trick":false},{"id":"c","text":"\"Why tell your friend? Don't you trust me?\"","trick":true},{"id":"d","text":"\"Sure, video-call first, no problem\"","trick":false},{"id":"e","text":"\"Take your own cab, totally fine\"","trick":false}],"why":"Pushing you to skip a public meet or to tell no one are the red flags; respecting your steps is green.","relearn":"Pressure to drop your safety steps is a red flag.","persona":"any","source":"red flag"},
  {"id":"sr-028","cat":"meeting-safely","type":"sort","hook":"Sort: a reassuring sign, or a warning sign, before meeting?","items":[{"id":"a","text":"Happy to video-call and meet in public"},{"id":"b","text":"Always 'too busy' to video-call"},{"id":"c","text":"Relaxed about your pace"},{"id":"d","text":"Pushing to meet privately, fast"},{"id":"e","text":"Fine that you told a friend"},{"id":"f","text":"\"Don't tell anyone about us\""}],"bins":[{"id":"good","label":"Reassuring","valence":"pos"},{"id":"warn","label":"Warning","valence":"neg"}],"key":{"a":"good","b":"warn","c":"good","d":"warn","e":"good","f":"warn"},"relearn":"Happy to video-call, go at your pace and you telling a friend reassure; dodging calls, rushing privacy or 'tell no one' warn.","persona":"any","source":"signs"},
  {"id":"sr-029","cat":"meeting-safely","type":"role-play","persona":"any","source":"leaving","hook":"Your first date with Varun doesn't feel right, and you've decided to leave.","setup":"He's just waved for a second coffee.","steps":[{"prompt":"Varun asks: \"Shall we get dessert too? This place does great brownies.\"","options":[{"text":"\"Sure, one dessert. I don't want to be rude.\"","then":"He orders two brownies and chats on. You watch the clock, still uneasy."},{"text":"\"I'm going to head off now. Take care.\"","then":"Varun blinks. \"Oh. Okay, sure. Get home safe.\"","best":true},{"text":"\"Sorry, my mum just called. Emergency at home.\"","then":"Varun looks worried and offers to come with you. Now the excuse needs more excuses."},{"text":"\"I should explain. It's a few things, really. First...\"","then":"Varun leans in, frowning, and starts arguing each point."}],"why":"A short, polite line is enough. You never owe a reason for leaving."},{"prompt":"Varun says: \"Let me at least drop you home. My bike's right outside.\"","options":[{"text":"\"No thanks. I'll book a cab.\"","then":"\"Okay, cool,\" he says, and you step out to wait for your cab.","best":true},{"text":"\"Okay, since you're going that way anyway.\"","then":"He grabs the keys. Your way home now depends on someone you felt uneasy with."},{"text":"\"Maybe just to the main road?\"","then":"He agrees. You're still getting on his bike, only for a shorter ride."},{"text":"\"No! I don't want you knowing where I live.\"","then":"Varun's face drops. \"Whoa. I was only offering.\""}],"why":"Your own way home keeps your exit yours, and a simple no is enough."},{"prompt":"Later that night, Varun texts: \"Did I do something wrong tonight?\"","options":[{"text":"\"No no, it was great! Let's do it again sometime.\"","then":"\"Yes! Saturday?\" he replies at once. Now you need a way out all over again."},{"text":"\"Sorry, I was just tired.\"","then":"\"Oh okay! Next weekend then?\" The real reason stays unsaid."},{"text":"\"It's complicated. Where do I even start?\"","then":"He replies, \"Go on,\" and you're pulled into a long back-and-forth."},{"text":"\"Not really. I just didn't feel a match. Take care.\"","then":"A pause, then: \"Okay. Thanks for saying it.\"","best":true}],"why":"A brief, honest sign-off closes it kindly without a long explanation."}],"relearn":"You can leave a date politely and promptly; you don't owe a long explanation."},
  {"id":"sr-030","cat":"meeting-safely","type":"branch","persona":"any","source":"consent / pace","hook":"Your first date with Reyansh goes well, and he suggests somewhere private next.","steps":[{"prompt":"You're enjoying yourself but aren't sure you want that. What do you do?","options":[{"text":"Decide a good date means you should go","then":"You agree, and the unease follows you out of the cafe."},{"text":"Say you'd like to keep tonight to just this","then":"Reyansh smiles. \"Sure. This is nice anyway.\"","best":true},{"text":"Make up an early morning to escape","then":"Reyansh says, \"Next time, then,\" and the question waits."},{"text":"Laugh it off and change the subject","then":"Reyansh looks unsure, and asks again ten minutes later."}],"why":"A good date obligates nothing. You can name your pace warmly."},{"prompt":"At the end of the night, Reyansh asks to see you again. What do you do?","options":[{"text":"Say yes to whatever he plans next","then":"Reyansh picks a late movie at his friend's flat."},{"text":"Say maybe, and decide by text later","then":"Reyansh waits for days for that text."},{"text":"Say yes, and suggest another public plan","then":"Reyansh grins. \"Deal. Chai near college?\"","best":true},{"text":"Promise next time you'll go to his place","then":"Reyansh is thrilled, and now it's an expectation."}],"why":"Seeing him again on your terms keeps the pace yours."},{"prompt":"On the second date, he asks how you feel about taking things slow. What do you do?","options":[{"text":"Say whatever pace he likes is fine","then":"He seems pleased, and you've handed him the pace."},{"text":"Joke that you're 'old-fashioned' and move on","then":"He laughs, and the real talk never happens."},{"text":"Say it depends on how each date goes","then":"Now every date feels like a test you're both taking."},{"text":"Tell him honestly where you are with it","then":"Reyansh nods. \"Thanks for telling me. No rush.\"","best":true}],"why":"Consent is an ongoing talk. Naming your pace keeps it real for you both."},{"prompt":"Later, he asks if it's okay to hold your hand. What do you do?","options":[{"text":"Answer honestly, whatever the answer is","then":"Reyansh listens, and the moment feels easy either way.","best":true},{"text":"Tell him he shouldn't have to ask","then":"He laughs, and next time he doesn't ask."},{"text":"Say yes, since that's what a date expects","then":"Reyansh pauses. \"Only if you want to,\" he says, and waits for your real answer."},{"text":"Tease him for being so formal","then":"He goes red and doesn't ask again all night."}],"why":"Being asked is a good sign. An honest answer keeps consent real."}],"debrief":"A good first date obligates nothing. Consent and your own pace still lead.","relearn":"A good date obligates nothing; move on only if you want to."},
  {"id":"sr-031","cat":"fakes-and-ghosts","type":"strike-rewrite","hook":"\"If their photos look real, they're real.\"","myth":{"un":"If their photos look real, they're real.","re":"Photos can be stolen or AI-generated; a live video call is the reliable check.","why":"'Looks real' stopped being proof online."},"relearn":"Photos can be stolen or AI-made; verify with a live video call.","persona":"any","source":"catfishing / verify"},
  {"id":"sr-032","cat":"fakes-and-ghosts","type":"spot","hook":"Spot the two catfish red flags.","scene":[{"id":"a","text":"Always has an excuse not to video-call","trick":true},{"id":"b","text":"Happy to do a quick call","trick":false},{"id":"c","text":"Photos that look like a model shoot, no candid ones","trick":true},{"id":"d","text":"Mentions a cafe near you both","trick":false},{"id":"e","text":"Replies at normal, human hours","trick":false}],"why":"Dodging video and only-perfect photos are catfish red flags; a willing call and normal signs aren't.","relearn":"Never video-calling and only-perfect photos are catfish red flags.","persona":"any","source":"catfish tells"},
  {"id":"sr-033","cat":"fakes-and-ghosts","type":"branch","persona":"any","source":"romance scams","hook":"Dev, a match you've never met, says he loves you after a week of chatting.","steps":[{"prompt":"He calls you his soulmate and wants you to talk only to him. What do you do?","options":[{"text":"Slow down, and ask for a quick video call","then":"Dev says his phone camera is broken, but sends a sweet voice note.","best":true},{"text":"Match his pace, since it feels so real","then":"Dev is overjoyed and starts calling you 'jaan' in every message."},{"text":"Stay warm, and just enjoy the attention","then":"The attention is lovely, and you still don't know who he is."},{"text":"Tell him he's being creepy","then":"Dev apologises with a flood of hearts and even bigger promises."}],"why":"Fast love and 'talk only to me' are tells. A live call checks who's really there."},{"prompt":"A few days on, Dev still hasn't called, but says he's saving up to visit you. What do you do?","options":[{"text":"Start planning where to take him","then":"You spend an evening picking places, and he loves every idea."},{"text":"Say you'd like a live call before any plans","then":"Dev says yes, then misses the time you set.","best":true},{"text":"Ask for more photos to be sure he's real","then":"Three more arrive, all perfect, all a little too polished."},{"text":"Tell your friends he's the one","then":"Your friends cheer, and it all feels even more real."}],"why":"No live call yet means you still haven't met the real person."},{"prompt":"Then Dev says his account is frozen and his rent is due tomorrow. What do you do?","options":[{"text":"Send a small amount, since he's clearly stressed","then":"Dev thanks you warmly. Two days later, the rent is short again."},{"text":"Ask for a bank screenshot as proof","then":"A screenshot arrives within minutes. It looks convincing."},{"text":"Say you don't send money to online-only matches","then":"Dev goes quiet for an hour, then sends a sad voice note.","best":true},{"text":"Lend it if he promises to pay you back","then":"Dev promises, and adds that he'll repay double."}],"why":"Fast love followed by a money ask is the scam pattern. Never send money."},{"prompt":"Soon after, Dev asks again, saying you'd help if you really loved him. What do you do?","options":[{"text":"Believe real love means helping out","then":"The guilt pulls at you, and he asks again that night."},{"text":"Keep it to yourself so nobody judges you","then":"You carry it alone, and his messages keep coming."},{"text":"Argue until he admits it's a scam","then":"Dev acts wounded and sends a longer, sadder story."},{"text":"Tell a friend and show them the chat","then":"Your friend Juhi reads it. \"This is a script,\" she says. \"It's not your fault.\"","best":true}],"why":"Guilt-tripping is part of the script. A friend helps you see it clearly."},{"prompt":"The next morning, Dev has a brand new emergency. What do you do?","options":[{"text":"Report the profile and stop replying","then":"The app removes the profile, and the messages end.","best":true},{"text":"Believe that this time it's real","then":"You reread his story, and it pulls you back in."},{"text":"Block him quietly, but don't report him","then":"He's gone from your phone, but his profile is still up on the app."},{"text":"Wait and see if the story checks out","then":"By evening, the story has grown a new twist."}],"why":"Reporting protects you and the next person. Being targeted is never your fault."}],"debrief":"Fast love followed by a money request is the classic romance scam.","relearn":"Fast love plus a money ask is a romance scam; never send money."},
  {"id":"sr-034","cat":"fakes-and-ghosts","type":"strike-rewrite","hook":"\"Someone who falls for me this fast must be genuine.\"","myth":{"un":"Someone who falls for me this fast must be genuine.","re":"Instant intense love from someone you've never met is a scam tell, not romance.","why":"Scammers rush intimacy on purpose."},"relearn":"Instant intense love from a stranger online is a scam tell, not romance.","persona":"any","source":"love-bombing / scam"},
  {"id":"sr-035","cat":"fakes-and-ghosts","type":"spot","hook":"Spot the two scam tells.","scene":[{"id":"a","text":"Refuses to ever meet or video-call","trick":true},{"id":"b","text":"Asks for money, gift cards or recharges","trick":true},{"id":"c","text":"Happy to meet in public locally","trick":false},{"id":"d","text":"Asks normal getting-to-know-you questions","trick":false},{"id":"e","text":"Is relaxed if you reply late","trick":false}],"why":"Never meeting and any money ask are scam tells; willingness to meet and calm signs aren't.","relearn":"Never meeting plus any money ask are scam tells.","persona":"any","source":"scam tells"},
  {"id":"sr-036","cat":"fakes-and-ghosts","type":"strike-rewrite","hook":"\"Ghosting is fine; you don't owe anyone anything.\"","myth":{"un":"Ghosting is fine; you don't owe anyone anything.","re":"A brief, kind 'this isn't for me' is basic decency; vanishing on someone isn't.","why":"Profiles are people with feelings too."},"relearn":"A brief, kind 'this isn't for me' is basic decency; ghosting isn't.","persona":"any","source":"ghosting"},
  {"id":"sr-037","cat":"fakes-and-ghosts","type":"branch","persona":"Rohan","source":"honesty both ways","hook":"You've been chatting with Priya for three weeks, and you're no longer interested.","steps":[{"prompt":"She messages asking about your weekend. What do you do?","options":[{"text":"Reply with a short, kind message ending it","then":"Priya writes back: \"Oh. Thanks for telling me. Take care.\"","best":true},{"text":"Stop replying and let her figure it out","then":"Priya sends two more messages over the week, then a confused '?'."},{"text":"Reply less and less until it fizzles","then":"Your replies shrink, and Priya keeps asking if something's wrong."},{"text":"Say you're swamped with exams for now","then":"Priya says good luck and asks to catch up after exams."}],"why":"After real chats, a short honest goodbye treats her like a person."},{"prompt":"Your friend Nikhil says ending things by message is 'too much effort'. What do you tell him?","options":[{"text":"True. Ghosting is just how apps work","then":"Nikhil nods, and the idea sticks for the next match."},{"text":"It takes two lines, and she deserves them","then":"Nikhil shrugs. \"Fair. I'd want that too.\"","best":true},{"text":"Only when it's someone I really liked","then":"Nikhil laughs. \"So most people get nothing?\""},{"text":"Everyone prefers ghosting. Less drama","then":"Nikhil agrees, though neither of you has asked anyone."}],"why":"Honesty runs both ways. A brief sign-off is basic decency."},{"prompt":"A month later, you're not feeling it with Sana, a new match who chats daily. What do you do?","options":[{"text":"Keep chatting in case you warm up later","then":"Sana starts planning a date, and you feel stuck."},{"text":"Unmatch without a word","then":"The chat vanishes from her screen mid-conversation."},{"text":"Tell her kindly that you don't feel a match","then":"Sana replies: \"Appreciate the honesty. All the best.\"","best":true},{"text":"Send a long message listing why it won't work","then":"Sana reads it twice and feels judged, not released."}],"why":"Clear and brief is kinder than a fade or a list of reasons."}],"debrief":"Once there's been real conversation, a short honest goodbye beats ghosting.","relearn":"End it with a short, kind message rather than ghosting."},
  {"id":"sr-038","cat":"fakes-and-ghosts","type":"sort","hook":"Sort: honest dating, or not?","items":[{"id":"a","text":"Saying clearly you're not feeling it"},{"id":"b","text":"Leading someone on for attention"},{"id":"c","text":"Being upfront about what you want"},{"id":"d","text":"Keeping someone 'on the hook' just in case"},{"id":"e","text":"A short, kind goodbye after real chats"},{"id":"f","text":"A fake 'maybe someday' you don't mean"}],"bins":[{"id":"honest","label":"Honest","valence":"pos"},{"id":"not","label":"Not","valence":"neg"}],"key":{"a":"honest","b":"not","c":"honest","d":"not","e":"honest","f":"not"},"relearn":"Saying you're not feeling it and being upfront is honest; leading on or hook-keeping isn't.","persona":"any","source":"honesty"},
  {"id":"sr-039","cat":"fakes-and-ghosts","type":"strike-rewrite","hook":"\"Lots of photos and followers means a profile is real.\"","myth":{"un":"Lots of photos and followers means it's real.","re":"Quantity isn't proof; fake and AI profiles can have plenty of both, so verify.","why":"Numbers are easy to fake."},"relearn":"Photo and follower counts aren't proof; verify the person.","persona":"any","source":"verify"},
  {"id":"sr-040","cat":"fakes-and-ghosts","type":"spot","hook":"Spot the two fake 'proofs' of being real.","scene":[{"id":"a","text":"A live video call where they match their photos","trick":false},{"id":"b","text":"A promise that they're definitely real","trick":true},{"id":"c","text":"More glamorous photos as 'proof'","trick":true},{"id":"d","text":"Meeting you in a busy public place","trick":false},{"id":"e","text":"Relaxed about you telling a friend","trick":false}],"why":"A promise and extra photos prove nothing; a live call or public meet is the real verification.","relearn":"A live video call verifies; promises and more photos don't.","persona":"any","source":"verification"},
  {"id":"sr-041","cat":"fakes-and-ghosts","type":"branch","persona":"any","source":"scam setup","hook":"Aisha's profile looks flawless, and on day two she's pushing to move to WhatsApp.","steps":[{"prompt":"She says the app is buggy and sends you her number. What do you do?","options":[{"text":"Keep chatting on the app for now","then":"Aisha sends a sulky emoji and says the app is so annoying.","best":true},{"text":"Move over. Her keenness is flattering","then":"Aisha is thrilled and starts messaging you at all hours."},{"text":"Give her your number, but keep the app too","then":"Now she has your number, and the app chat goes silent."},{"text":"Ask a friend to check her Instagram","then":"Your friend finds an account with the same photos, which proves nothing."}],"why":"Staying on the app keeps your report and block tools while you check."},{"prompt":"Aisha still hasn't video-called, and her photos look like a shoot. What do you do?","options":[{"text":"Reverse-search one photo and leave it there","then":"Nothing turns up. She could still be anyone."},{"text":"Assume she's just very photogenic","then":"You relax, and the chats get more personal."},{"text":"Ask for a quick live video call","then":"Aisha says her camera is broken, but she'll try next week.","best":true},{"text":"Send her more of your photos to build trust","then":"She compliments them and asks where you live."}],"why":"A live call is the check a fake can't pass. Photos alone prove nothing."},{"prompt":"A week later, Aisha still hasn't called, and she asks for a small loan. What do you do?","options":[{"text":"Send a little to show you trust her","then":"The next week she needs more, for a bigger emergency."},{"text":"Keep chatting, but say no to money","then":"Aisha sulks, then tries a new story."},{"text":"Tell her she's a fraud and you'll expose her","then":"She blocks you first, and the profile stays up for others."},{"text":"Report her, and tell a friend what happened","then":"The app takes the profile down, and your friend is glad you said.","best":true}],"why":"Too-perfect, off-app pressure and a money ask add up. Report it. Being targeted is never your fault."}],"debrief":"Too-good-to-be-true plus a rush off the app is a classic fake or scam setup.","relearn":"Too-perfect and rushing off-app is a scam tell; slow down and verify."},
  {"id":"sr-042","cat":"fakes-and-ghosts","type":"role-play","persona":"any","source":"protecting friends","hook":"Your friend Pallavi's new match showers her with love, and now wants money.","setup":"She's showing you the chat over chai.","steps":[{"prompt":"Pallavi asks: \"He wants flight money to meet me. Sweet, no?\"","options":[{"text":"\"Aww. That honestly sounds like true love to me.\"","then":"Pallavi beams. \"I knew you'd get it!\""},{"text":"\"Fast love, then money? That's the scam pattern.\"","then":"Pallavi frowns. \"Scam? He's not like that.\"","best":true},{"text":"\"Seriously? How can you fall for this?\"","then":"Pallavi's face falls. \"Wow. Thanks for the support.\""},{"text":"\"Maybe send half, and he pays the rest?\"","then":"\"Good idea!\" Pallavi says, and opens her banking app."}],"why":"Naming the pattern gently gives her something real to think about."},{"prompt":"Pallavi adds: \"And he sends me good-morning texts every single day.\"","options":[{"text":"\"Then he must really mean it.\"","then":"\"Exactly!\" she says, and shows you his latest."},{"text":"\"Scammers do exactly that on purpose, you know.\"","then":"Pallavi crosses her arms. \"So he's a criminal now?\""},{"text":"\"That's lovely. Has he ever video-called you?\"","then":"Pallavi pauses. \"Not yet. His camera's broken.\"","best":true},{"text":"\"Want me to message him and check?\"","then":"\"No!\" Pallavi says. \"Please don't embarrass me.\""}],"why":"A kind question lets her test it herself, without feeling attacked."},{"prompt":"Pallavi asks: \"So what would you do in my place?\"","options":[{"text":"\"Not send money to someone I've only met online.\"","then":"Pallavi sighs. \"Okay. I'll hold off and ask for a call.\"","best":true},{"text":"\"Honestly? Just follow your heart on this one.\"","then":"\"You're right,\" she says, and taps send."},{"text":"\"Block him right now. Today.\"","then":"\"Easy for you to say,\" Pallavi mutters, and keeps chatting."},{"text":"\"Send it, but screenshot everything first.\"","then":"Pallavi nods, and the money goes."}],"why":"An honest answer, without shaming, helps her keep her money and her pride."},{"prompt":"A week later, Pallavi says: \"He got angry when I asked for a call.\"","options":[{"text":"\"Maybe you pushed him too hard?\"","then":"Pallavi looks down. \"Maybe I did.\""},{"text":"\"See? I was right all along.\"","then":"Pallavi's jaw sets. \"Okay. You win.\""},{"text":"\"Give him a few days. Maybe he was just stressed.\"","then":"\"Yeah, you're right,\" she says, and reopens the chat."},{"text":"\"That's a red flag, and it's not on you. Report him?\"","then":"Pallavi nods slowly. \"Yeah. I think I knew. Will you help me?\"","best":true}],"why":"Backing her instinct, saying it's not on her and offering to report, helps her step away."}],"relearn":"Warn a friend that fast-love-then-money is the classic scam."},
  {"id":"sr-043","cat":"fakes-and-ghosts","type":"strike-rewrite","hook":"\"If someone catfished or scammed me, I was just stupid.\"","myth":{"un":"If I was catfished or scammed, I was stupid.","re":"These are engineered to fool anyone; it's on the person who deceived you, and help exists.","why":"Shame keeps people from reporting."},"relearn":"Being catfished or scammed isn't stupidity; it's on the deceiver, and help exists.","persona":"any","source":"no shame"},
  {"id":"sr-044","cat":"fakes-and-ghosts","type":"sort","hook":"Sort: a real verification step, or a fake reassurance?","items":[{"id":"a","text":"A spontaneous live video call"},{"id":"b","text":"\"Trust me, I'm real\""},{"id":"c","text":"Meeting in a public place"},{"id":"d","text":"Sending one more selfie"},{"id":"e","text":"A short candid clip with background sound"},{"id":"f","text":"\"I promise on my life I'm genuine\""}],"bins":[{"id":"real","label":"Real check","valence":"pos"},{"id":"fake","label":"Not a check","valence":"neg"}],"key":{"a":"real","b":"fake","c":"real","d":"fake","e":"real","f":"fake"},"relearn":"A live call or public meet verifies; 'trust me' and extra selfies don't.","persona":"any","source":"verification"},
  {"id":"sr-045","cat":"fakes-and-ghosts","type":"reflect","hook":"Lensy: honesty runs both ways, don't be the catfish or the ghost either. Fair deal?","prompt":"What do you think?","options":["Yes","Both ways","Be the real one"],"affirm":"Being honest and kind yourself is half of a healthier dating world.","relearn":"Honesty runs both ways: don't be the catfish or the ghost.","persona":"any","source":"honesty both ways"},
  {"id":"sr-046","cat":"fakes-and-ghosts","type":"spot","hook":"Spot the two unkind ways to end a chat.","scene":[{"id":"a","text":"\"I've enjoyed chatting but I'm not feeling a match, take care\"","trick":false},{"id":"b","text":"Going silent forever with no word","trick":true},{"id":"c","text":"Blocking with a cruel parting shot","trick":true},{"id":"d","text":"\"Thanks for the chats, wishing you the best\"","trick":false},{"id":"e","text":"\"I'm stepping back, but it was nice talking\"","trick":false}],"why":"Silent ghosting and a cruel block are the unkind ways; a brief, kind sign-off isn't.","relearn":"A brief, kind sign-off is the decent way to end a chat.","persona":"any","source":"decency"},
  {"id":"sr-047","cat":"date-with-respect","type":"branch","persona":"any","source":"pacing / consent","hook":"Your third date with Tara is going well, and you want to move faster than she seems to.","steps":[{"prompt":"On the walk out, she keeps a little distance between you. What do you do?","options":[{"text":"Match her pace and ask how tonight feels for her","then":"Tara smiles. \"Honestly, I like this slow. I'm having fun.\" She relaxes into the walk.","best":true},{"text":"Take her hand anyway. She'll pull back if she minds","then":"Tara goes stiff for a second, then eases her hand free and checks her phone."},{"text":"Keep it slow tonight, but don't say anything","then":"The walk is pleasant. You still can't tell what she wants, and she can't tell what you do."},{"text":"Suggest going back to your place to just talk","then":"Tara hesitates, says she has an early class, and books her own cab."}],"why":"Matching her pace and asking lets her say what she wants, instead of you guessing."},{"prompt":"Two days later, your friend Nikhil says, \"Three dates in. Make a move already.\" What do you tell him?","options":[{"text":"That the pace is ours to set, not a date count","then":"Nikhil shrugs. \"Fair enough.\" You head into the weekend feeling lighter.","best":true},{"text":"That you'll make a move this weekend for sure","then":"Nikhil cheers. You now have a plan that Tara knows nothing about."},{"text":"That it's going well, and leave it there","then":"Nikhil winks and asks for details later. His question sits with you all week."},{"text":"That maybe she's just not that into you","then":"Nikhil nods too quickly. You start reading her slowness as rejection."}],"why":"Your pace is set by the two of you, not by a friend's idea of what date three means."},{"prompt":"At the weekend, Tara says she likes you but wants to keep things slow for a while. What do you do?","options":[{"text":"Agree, then ask how many dates slow usually means","then":"Tara laughs awkwardly. \"I don't know. Does it need a number?\""},{"text":"Say that works, and ask what feels good to her","then":"Tara lights up and says she loves long walks and slow evenings. You plan one.","best":true},{"text":"Say fine, and go quiet for the rest of the evening","then":"Tara keeps glancing at you. The evening ends earlier than either of you meant."},{"text":"Tell her most people your age move faster","then":"Tara's smile fades. \"Maybe. I'm not most people.\""}],"why":"Welcoming her pace and asking what feels good keeps consent a conversation, not a countdown."}],"debrief":"Pacing to the slower person and checking in keeps a date respectful and consensual.","relearn":"Match the slower pace and check in; don't push."},
  {"id":"sr-048","cat":"date-with-respect","type":"role-play","persona":"any","source":"voicing pace","hook":"You're on a third date with Rohit. You like him, and you want tonight to be just talking.","setup":"The café terrace has emptied out around you.","steps":[{"prompt":"Rohit moves a little closer and asks: \"Can I kiss you?\"","options":[{"text":"\"Sorry, I'm probably being really boring.\"","then":"Rohit looks confused. \"Boring? No. Is that a no, though?\""},{"text":"\"My parents would kill me, haha.\"","then":"Rohit laughs. \"Okay. Is that a no from you, or from them?\""},{"text":"\"I'm really enjoying this. Can we just talk tonight?\"","then":"Rohit smiles and leans back. \"Talking works. I'm having fun too.\"","best":true},{"text":"\"Not tonight. But next time for sure, I promise.\"","then":"Rohit grins. \"I'll hold you to that.\" The promise sits oddly with you."}],"why":"Naming your pace warmly is enough. A good date welcomes it, no excuses needed."},{"prompt":"Rohit asks: \"So what kind of pace feels good to you?\"","options":[{"text":"\"Ugh, do we have to talk about it?\"","then":"Rohit shrugs. \"No. I just didn't want to guess.\""},{"text":"\"Slow. I like getting to know someone first.\"","then":"\"Same, honestly,\" he says. \"So tell me about your family.\"","best":true},{"text":"\"Honestly, I'd rather you just read the signals.\"","then":"Rohit frowns. \"I'd rather hear it from you, if that's okay.\""},{"text":"\"Slow. Don't take it personally. I'm just weird.\"","then":"\"You're not weird,\" Rohit says. \"But okay.\""}],"why":"Saying your pace plainly means he doesn't have to guess, and you don't have to apologise."},{"prompt":"The next day, your friend Simran asks: \"You just talked? Wasn't that a bit boring?\"","options":[{"text":"\"I know. I'll try to loosen up next time.\"","then":"Simran nods. \"Good. Don't overthink it.\" You feel a pressure you didn't before."},{"text":"\"Maybe I'm just not good at dating.\"","then":"\"Don't say that,\" Simran says, but the thought sticks."},{"text":"\"He probably thinks I'm not interested now.\"","then":"Simran shrugs. \"Did you tell him you were?\""},{"text":"\"It wasn't boring. I liked going at my pace.\"","then":"Simran grins. \"Fair. Honestly, that sounds nice.\"","best":true}],"why":"Going at your own pace isn't boring or a flaw. It's yours to set."}],"relearn":"You can name your pace warmly; a good date welcomes it."},
  {"id":"sr-049","cat":"date-with-respect","type":"strike-rewrite","hook":"\"On a date, the consent rules relax.\"","relearn":"Consent and respect apply on every date, app or not.","persona":"any","source":"consent travels","myth":{"un":"On a date, the consent rules relax.","re":"Consent and respect apply on every date, app or not; nothing about a date changes them.","why":"A date is not an exception to consent."}},
  {"id":"sr-050","cat":"date-with-respect","type":"branch","persona":"any","source":"receiving rejection","hook":"After one date, Ishaan texts that he doesn't want to meet again.","steps":[{"prompt":"You'd been looking forward to a second date. How do you reply?","options":[{"text":"Thank him for being honest and wish him well","then":"Ishaan replies with a smiley. \"You too. Good luck out there.\"","best":true},{"text":"Ask what went wrong so you can do better","then":"He takes hours to reply, then sends a vague line about no spark. You feel no clearer."},{"text":"Ask him to give it one more try first","then":"Ishaan says he's sure. The second no lands heavier than the first."},{"text":"Say no worries, but add that he's missing out","then":"He leaves it on read. The last line sitting there bothers you more than him."}],"why":"A no needs no reason. A gracious reply lets you both move on with dignity."},{"prompt":"That evening, you keep rereading his message. What do you do with the feeling?","options":[{"text":"Check his profile to see if he's chatting to others","then":"His profile looks the same. You scroll it for twenty minutes and feel worse."},{"text":"Decide you're just not good at dating","then":"The thought follows you to bed and makes every other match feel pointless."},{"text":"Admit it stings, and call a friend","then":"Your friend Sana listens, then makes you laugh with her worst date story.","best":true},{"text":"Swipe all night to prove you're fine","then":"You match with a few people and reply to none. The sting is still there."}],"why":"A no after one date is normal. Feeling it and talking it through helps it pass."},{"prompt":"A week later, Ishaan likes your story on Instagram. What do you do?","options":[{"text":"Take it as a sign and ask him out again","then":"Ishaan replies politely that he meant what he said. It stings twice."},{"text":"Ask why he's watching if he isn't interested","then":"Ishaan goes quiet, then mutes your stories."},{"text":"Send a friendly hey stranger to keep the door open","then":"He sends a thumbs up. You spend the evening decoding it."},{"text":"Leave it as a like and carry on with your week","then":"The notification fades. By Sunday, you're chatting with someone new.","best":true}],"why":"A friendly like after a no isn't an opening. Letting the no stand keeps things clean."}],"debrief":"Receiving a no without pestering is a core, respectful dating skill.","relearn":"Take a no gracefully; don't push for reasons or a change of mind."},
  {"id":"sr-051","cat":"date-with-respect","type":"role-play","persona":"any","source":"giving rejection","hook":"After one date, you know you don't want a second with Siddharth.","setup":"The next morning, he's already messaging.","steps":[{"prompt":"Siddharth writes: \"Last night was so fun! Free this Saturday?\"","options":[{"text":"\"Saturday's tricky! Let's see.\"","then":"\"No worries! Sunday then?\" he replies instantly."},{"text":"\"So busy this month! I'll let you know.\"","then":"\"Cool, I'll check in next week,\" he replies."},{"text":"\"I had a nice time, but I didn't feel a spark. Take care.\"","then":"A pause, then: \"Ah, okay. Thanks for being honest. Take care too.\"","best":true},{"text":"\"You're great. I just don't deserve someone like you.\"","then":"\"What? Of course you do. Let's talk Saturday.\""}],"why":"Kind, clear and brief lets him move on. Vague maybes keep him waiting."},{"prompt":"That afternoon, your friend Mahi asks: \"So? Are you seeing Siddharth again?\"","options":[{"text":"\"No. It just wasn't a match for me.\"","then":"Mahi nods. \"Fair enough. Not every date clicks.\"","best":true},{"text":"\"Ugh, no. He was so boring, honestly.\"","then":"Mahi laughs. You picture him hearing that, and wince."},{"text":"\"Maybe, if nothing better comes up.\"","then":"Mahi raises an eyebrow. \"Does he know he's the backup?\""},{"text":"\"Please don't tell him, but I'm not keen.\"","then":"Mahi promises. By evening, two more friends know."}],"why":"Being as clear with friends as with him keeps the no clean, and keeps him out of gossip."},{"prompt":"Two days later, Siddharth texts: \"Hey, just checking. Are we good?\"","options":[{"text":"\"Honestly? You talked about yourself a whole lot.\"","then":"\"Oh,\" he writes. \"Okay. Noted.\" He sounds crushed."},{"text":"\"Totally! Let's catch up sometime soon.\"","then":"\"Great!\" he replies. \"Saturday, then?\""},{"text":"\"Sure! Just really busy right now, sorry.\"","then":"\"No problem! I'll wait,\" he replies."},{"text":"\"We're good. Just not a match. Take care.\"","then":"\"Okay,\" he writes. \"Thanks. Take care.\"","best":true}],"why":"A clear, kind answer ends the guessing. Excuses and false promises drag it out."}],"relearn":"Give a no kindly, clearly and briefly; don't false-promise."},
  {"id":"sr-052","cat":"date-with-respect","type":"strike-rewrite","hook":"\"If they rejected me, they owe me an explanation.\"","myth":{"un":"If they rejected me, they owe me an explanation.","re":"A no is complete on its own; no one owes a detailed reason for it.","why":"Demanding reasons turns a no into pressure."},"relearn":"A no is complete; no one owes a detailed reason for it.","persona":"Rohan","source":"rejection"},
  {"id":"sr-053","cat":"date-with-respect","type":"branch","persona":"any","source":"space","hook":"After a lovely first date, you sent Rhea a flirty text. A day later, still no reply.","steps":[{"prompt":"Your thumb hovers over the chat again. What do you do?","options":[{"text":"Leave it and get on with your day","then":"You go to class and forget to check for hours. The chat stays quiet for now.","best":true},{"text":"Send a quick hello with two question marks","then":"The ticks turn blue. Still no reply, and now you both know you're waiting."},{"text":"Check when she was last online","then":"She was online an hour ago. You spend the afternoon building theories."},{"text":"Send a meme so it doesn't look like chasing","then":"The meme sits under your first text. Two unanswered messages now."}],"why":"A day of quiet is usually just life. Giving space keeps it easy for both of you."},{"prompt":"The next evening, Rhea writes, \"Sorry, crazy day! Had fun too.\" What do you send back?","options":[{"text":"Tell her you were worried she'd lost interest","then":"Rhea says she was just swamped. Her next reply takes a little longer."},{"text":"A warm reply, with no mention of the wait","then":"Rhea sends a laughing emoji and asks about your week. The chat picks up easily.","best":true},{"text":"Wait a full day, so she knows how it feels","then":"By the time you reply, her energy has moved on. It feels like a game now."},{"text":"Ask her to reply a bit faster next time","then":"Rhea sends a short \"ok\". The warmth from the date feels further away."}],"why":"Answering warmly, without keeping score of the gap, keeps it about you two."},{"prompt":"A week on, you're still texting, but her replies come hours apart. What do you do?","options":[{"text":"Text more often so the chat doesn't die","then":"Your messages stack up between hers. She answers one in five."},{"text":"Tell her slow replies make you feel unwanted","then":"Rhea apologises and says texting isn't her thing. She sounds tense."},{"text":"Let her texting pace be hers and suggest meeting","then":"Hours later she replies, \"Saturday? I'm better in person anyway.\"","best":true},{"text":"Slow your own replies so you seem less keen","then":"The chat turns into a timing contest neither of you enjoys."}],"why":"Some people just text slowly. Respecting that and meeting up beats chasing replies."}],"debrief":"Respecting space, not flooding someone for a reply, keeps things healthy.","relearn":"Give people space; flooding for a reply reads as pressure."},
  {"id":"sr-054","cat":"date-with-respect","type":"reflect","hook":"Lensy: rejection, given or received, is survivable and part of dating. Take the sting off?","prompt":"What do you think?","options":["Yes","It's survivable","Part of it"],"affirm":"Everyone gets and gives a no; handling it kindly is the real skill.","relearn":"Rejection, given or received, is a survivable, normal part of dating.","persona":"any","source":"rejection is normal"},
  {"id":"sr-055","cat":"date-with-respect","type":"role-play","persona":"any","source":"honesty","hook":"Mid-date, you realise you're not feeling it with Ahana, though she's lovely and clearly having fun.","setup":"The waiter has just cleared your plates.","steps":[{"prompt":"Ahana asks: \"Dessert here, or shall we walk down to the lake?\"","options":[{"text":"\"The lake! Let's make a whole night of it.\"","then":"Ahana lights up and grabs her bag. The date stretches on."},{"text":"\"Actually, I'm feeling a bit unwell. Sorry.\"","then":"Ahana looks worried. \"Oh no! Let me get you a cab.\""},{"text":"\"Dessert here sounds nice. Then I'll head home.\"","then":"\"Perfect,\" Ahana says, and waves the waiter over.","best":true},{"text":"\"Whatever you like. I'm easy either way.\"","then":"Ahana picks the lake. You walk beside her, wishing you'd said more."}],"why":"Not stretching a date you're not feeling spares her a longer hope."},{"prompt":"A little later, Ahana asks: \"So, would you want to do this again?\"","options":[{"text":"\"Totally! Let's plan something for next weekend.\"","then":"Ahana beams and starts suggesting places."},{"text":"\"I've enjoyed this, but I'm not feeling a romantic match.\"","then":"Ahana nods slowly. \"Oh. Okay. Thank you for being honest.\"","best":true},{"text":"\"Let me check my week, and I'll text you.\"","then":"\"Great,\" she says. \"I'll look out for it.\""},{"text":"\"Honestly, no. I felt nothing at all.\"","then":"Ahana's face falls. \"Oh. Right. Okay.\""}],"why":"Honest but kind now beats faking interest and ghosting later."},{"prompt":"The next day, your friend Isha asks: \"So how did it go with Ahana?\"","options":[{"text":"\"Honestly? Total waste of a whole evening.\"","then":"Isha laughs, then asks if Ahana knows that. You go quiet."},{"text":"\"Fine. I'll just stop replying to her.\"","then":"Isha raises an eyebrow. \"The slow ghost? Really?\""},{"text":"\"She's lovely. It just wasn't a romantic match.\"","then":"Isha nods. \"Fair. It happens.\"","best":true},{"text":"\"I'll let her down slowly over a few weeks.\"","then":"Isha winces. \"Weeks of her hoping? Oof.\""}],"why":"Talking about her with respect, even when she isn't there, is part of honesty both ways."}],"relearn":"Honest-but-kind beats faking interest and ghosting later."},
  {"id":"sr-056","cat":"date-with-respect","type":"sort","hook":"Sort each one: respectful on a date, or not?","items":[{"id":"a","text":"Taking no for an answer"},{"id":"b","text":"Pestering after a clear no"},{"id":"c","text":"Being honest about your intentions"},{"id":"d","text":"Sending abuse when rejected"},{"id":"e","text":"Checking in before getting closer"},{"id":"f","text":"Guilt-tripping them into staying"}],"bins":[{"id":"respect","label":"Respectful","valence":"pos"},{"id":"not","label":"Not respectful","valence":"neg"}],"key":{"a":"respect","b":"not","c":"respect","d":"not","e":"respect","f":"not"},"relearn":"Taking no, honesty and checking in are respectful; pestering, abuse or guilt-tripping aren't.","persona":"any","source":"respect"},
  {"id":"sr-057","cat":"date-with-respect","type":"branch","persona":"any","source":"boundary","hook":"You turned down a second date with Varun. Now he's sending angry, guilt-tripping texts.","steps":[{"prompt":"His latest says you wasted his time and money. What do you do?","options":[{"text":"Wonder if you led him on somehow","then":"You replay the date, hunting for your mistake. Another text arrives."},{"text":"Stop replying and block him","then":"His messages stop reaching you. The quiet feels strange, then like relief.","best":true},{"text":"Send a long message explaining your reasons","then":"Varun picks apart every reason and sends three more angry texts."},{"text":"Keep it quiet, since it feels embarrassing","then":"You carry it alone. His texts keep arriving while you sit in class."}],"why":"Anger after a no is pressure. You can stop engaging and block. None of this is your fault."},{"prompt":"The next day, Varun finds you on Instagram and messages there, angrier than before. What do you do?","options":[{"text":"Follow a friend's advice that blocking makes it worse","then":"You leave his Instagram messages open. Each new one is harder to read."},{"text":"Tell yourself it's only words and not a big deal","then":"You mute nothing. By evening there are eleven new messages."},{"text":"Screenshot it, block him there, and tell a friend","then":"Your friend Neha comes over with chai and helps you report both accounts.","best":true},{"text":"Post his messages on your story to shame him","then":"Friends react with shocked emojis. Varun sees it and sends his angriest text yet."}],"why":"Saving proof, blocking and telling a friend means you aren't carrying this alone."},{"prompt":"A mutual friend texts, \"Varun's really upset. Just talk to him once, yaar.\" What do you reply?","options":[{"text":"Reply that maybe you were too harsh on him","then":"Your friend says she'll let Varun know. Your stomach knots."},{"text":"Send a long voice note defending every reason","then":"Your friend replies \"hmm ok\". Now your reasons are up for debate."},{"text":"Ask the friend to go and tell Varun off for you","then":"The friend agrees, and the drama spreads through your whole group."},{"text":"Say your no stands, and ask them not to pass on messages","then":"Your friend pauses, then says, \"Fair. I'll stay out of it.\"","best":true}],"why":"Your no doesn't need defending, to him or anyone passing on his messages."}],"debrief":"A no stands even if they react badly. Block, tell a friend, and if it turns to threats, report to cybercrime 1930 or call 181. It's never your fault.","relearn":"Hold your no even if they react badly; disengage and block if needed."},
  {"id":"sr-058","cat":"date-with-respect","type":"reflect","hook":"Lensy: treating a date like a person you respect makes you someone people feel safe with. Worth it?","prompt":"What do you think?","options":["Yes","Be that person","Safe to date"],"affirm":"Being respectful and safe to date is its own quiet superpower.","relearn":"Treating dates with respect makes you someone people feel safe with.","persona":"any","source":"respect"},
  {"id":"sr-059","cat":"date-with-respect","type":"role-play","persona":"any","source":"support","hook":"Your friend Rukhsar turned someone down on an app. His reply was cruel, and she's shaken.","setup":"In the canteen, she slides her phone across to you.","steps":[{"prompt":"Rukhsar asks: \"Did I bring this on myself?\"","options":[{"text":"\"Maybe you led him on a bit?\"","then":"Rukhsar's face drops. \"I just said I wasn't interested.\""},{"text":"\"No. That's on him, not you. You're allowed to say no.\"","then":"Rukhsar exhales. \"Okay. I keep rereading it and feeling sick.\"","best":true},{"text":"\"Just ignore it. People are weird online.\"","then":"Rukhsar nods slowly. \"Yeah. I guess.\" She doesn't look any better."},{"text":"\"Give me your phone. I'll reply to him.\"","then":"Rukhsar pulls the phone back. \"Please don't. That'll make it worse.\""}],"why":"His cruelty is on him, never on the person who said no. Saying it plainly helps."},{"prompt":"Rukhsar asks: \"What should I even do now?\"","options":[{"text":"\"You have to report him right now.\"","then":"Rukhsar tenses. \"I don't know. Can I just think a second?\""},{"text":"\"Send him something even nastier back.\"","then":"Rukhsar hesitates. \"He'd just come back worse.\""},{"text":"\"Want to block and report him? I can sit with you.\"","then":"\"Yes,\" she says. \"Can you help me find the report button?\"","best":true},{"text":"\"Delete the app. Dating apps are just unsafe.\"","then":"Rukhsar looks deflated. \"I actually liked using it until today.\""}],"why":"Offering options and your company, without pushing, leaves the choices with her."},{"prompt":"Later, Rukhsar says: \"Please don't tell anyone in the group about this.\"","options":[{"text":"\"But everyone should know what he's like!\"","then":"Rukhsar winces. \"Please. Not yet.\""},{"text":"\"Okay, but I'm telling Aman. He'll know what to do.\"","then":"Rukhsar stiffens. \"I asked you not to.\""},{"text":"\"Fine. But you're overreacting a bit.\"","then":"Rukhsar goes quiet and puts her phone away."},{"text":"\"I won't. It's yours to share.\"","then":"\"Thank you,\" she says quietly. \"I can't face questions yet.\"","best":true}],"why":"Keeping her story hers respects her pace. Support means following her lead."},{"prompt":"A week later, Rukhsar texts: \"He's messaging me again. It's worse this time.\"","options":[{"text":"\"Why are you even still replying to him?\"","then":"\"I'm not,\" Rukhsar writes. \"He just keeps going.\""},{"text":"\"That's not okay. Want help blocking and reporting?\"","then":"\"Yes,\" she writes. \"Can you stay on the phone while I do?\"","best":true},{"text":"\"Just stop using apps for a while.\"","then":"\"Maybe,\" she writes. \"That feels like he wins.\""},{"text":"\"Give me his number. I'll sort him out myself.\"","then":"\"No,\" Rukhsar writes. \"Please don't make it bigger.\""}],"why":"It's still not her fault. Believing her and helping her block and report is real support."}],"relearn":"Back a friend's right to say no; an abusive reaction is on the sender."},
  {"id":"sr-060","cat":"date-with-respect","type":"strike-rewrite","hook":"\"Paying for the date means they owe me something.\"","myth":{"un":"Paying for the date means they owe me something.","re":"Buying dinner never buys consent or a second date; nobody owes anything for it.","why":"Generosity isn't a transaction for intimacy."},"relearn":"Paying for a date never means they owe you anything.","persona":"any","source":"no transaction"},
  {"id":"sr-061","cat":"date-with-respect","type":"branch","persona":"any","source":"communication","hook":"You and Aditya are getting closer, and you want to talk about boundaries before things go further.","steps":[{"prompt":"On a quiet walk home tonight, the moment feels right. What do you do?","options":[{"text":"Wait. Talking about it will kill the mood","then":"The walk stays light. The question comes back each time things get closer."},{"text":"Make a joke about it and see how he reacts","then":"Aditya laughs along. You learn nothing about what he actually wants."},{"text":"Say you'd like to talk about what you're each okay with","then":"Aditya looks relieved. \"I've wanted to ask too. I didn't know how.\"","best":true},{"text":"Decide you'll read his signals as you go","then":"It feels easier for now. Later, you both hesitate, unsure what the other wants."}],"why":"Talking about consent openly is a green flag. It means neither of you has to guess."},{"prompt":"A few days later, Aditya asks what you'd want if things get more physical. What do you say?","options":[{"text":"Tell him your limits, but don't ask about his","then":"He listens carefully. You realise you have no idea where his limits are."},{"text":"Say anything is fine with you","then":"Aditya looks unsure. \"Anything? I'd rather know what you actually like.\""},{"text":"Tell him honestly, and ask what he wants too","then":"He answers just as honestly. It turns out you both want a slow start.","best":true},{"text":"Say you'd rather not plan it and just see","then":"He nods, a bit deflated. The talk ends before it starts."}],"why":"Consent runs both ways. Sharing yours and asking his makes it a real conversation."},{"prompt":"The next weekend, while you're kissing, Aditya pauses to ask if you're still okay. What do you do?","options":[{"text":"Tell him checking in is sweet, but he can stop now","then":"Aditya stops asking. You've lost an easy moment to say how you feel."},{"text":"Tell him honestly how you feel right then","then":"He nods and follows your lead. It feels easy, not awkward.","best":true},{"text":"Ask if he's the one having doubts","then":"Aditya blinks. \"No, I just wanted to check.\" The moment turns awkward."},{"text":"Laugh and change the subject","then":"Aditya laughs too, but he still isn't sure where you are."}],"why":"A check-in is a chance to say what's true for you. Answering honestly keeps it working."}],"debrief":"Openly talking about consent and boundaries is mature and attractive, not awkward.","relearn":"Talking openly about consent and boundaries is a green flag."},
  {"id":"sr-062","cat":"date-with-respect","type":"reflect","hook":"Lensy: kindness and consent from the first message is the whole game. Carry it from swipe one?","prompt":"What do you think?","options":["Yes","From swipe one","Kindness first"],"affirm":"Carrying kindness and consent from the first message is what 'date with respect' means.","relearn":"Carry kindness and consent from the very first message.","persona":"any","source":"respect from the start"},
  {"id":"sr-063","cat":"profiles-are-people","type":"reflect","hook":"Lensy: every profile is a real person with feelings, just like you. Keep it in mind?","prompt":"What do you think?","options":["Yes","Real people","Like me"],"affirm":"Remembering there's a person behind every profile changes how you treat them, for the better.","relearn":"Every profile is a real person with feelings, just like you.","persona":"any","source":"profiles are people"},
  {"id":"sr-064","cat":"profiles-are-people","type":"sort","hook":"Sort: treats a match like a person, or like a disposable profile?","items":[{"id":"a","text":"A genuine, kind opening message"},{"id":"b","text":"A copy-pasted crude opener"},{"id":"c","text":"Remembering what they said last time"},{"id":"d","text":"Swiping and discarding on a whim"},{"id":"e","text":"A warm, brief sign-off when it's not a fit"},{"id":"f","text":"Ghosting mid-chat for a newer match"}],"bins":[{"id":"person","label":"Like a person","valence":"pos"},{"id":"disposable","label":"Disposable","valence":"neg"}],"key":{"a":"person","b":"disposable","c":"person","d":"disposable","e":"person","f":"disposable"},"relearn":"Genuine messages, remembering them and a kind sign-off treat a match as a person; crude lines and discarding don't.","persona":"any","source":"decency"},
  {"id":"sr-065","cat":"profiles-are-people","type":"branch","persona":"any","source":"decency","hook":"You've matched with Ayesha, and a crude opener feels tempting because it's just an app.","steps":[{"prompt":"Your thumb hovers over a line about her body. What do you send?","options":[{"text":"The crude line. It's only an app","then":"Ayesha unmatches within a minute. The chat is gone before it started."},{"text":"Something you'd be okay receiving yourself","then":"You ask about the concert in her photos. \"You were there too?!\" she replies.","best":true},{"text":"A cheesy pickup line off the internet","then":"She sends \"lol\" and nothing else. The line said nothing about you or her."},{"text":"Just \"hey,\" then wait for her to do the work","then":"Her reply is a polite \"hey\". The chat stalls at two words."}],"why":"Sending what you'd be glad to get treats a profile as the person it is."},{"prompt":"Your friend Karan says bold lines get more replies than polite ones. What do you do?","options":[{"text":"Write messages you'd be glad to get","then":"Karan shrugs. Your chats are slower, but they're real conversations.","best":true},{"text":"Try his boldest line on your next match","then":"The match reports the message, and the app sends you a warning."},{"text":"Send bold lines, but only to people who seem up for it","then":"You guess wrong on the second try, and the match unmatches, clearly upset."},{"text":"Ask Karan to write your openers for you","then":"His lines get a few replies, none of them about you."}],"why":"Replies to a real message beat replies to a line that treats people as targets."},{"prompt":"A week later, a match sends you a crude opener about your body. What do you do?","options":[{"text":"Send an even cruder one back as a joke","then":"They reply with worse. The chat turns into a contest nobody wins."},{"text":"Take it as a compliment. That's just apps","then":"You shrug it off, and start expecting less from every chat."},{"text":"Wonder if your photos invited it","then":"You start second-guessing your photos. The sender moves on to the next match."},{"text":"Unmatch, and report it","then":"The chat disappears. The app thanks you for the report.","best":true}],"why":"A crude message is on the sender, never you. Unmatch and report are yours to use."}],"debrief":"The screen doesn't cancel basic respect. Profiles are people.","relearn":"Decency doesn't pause for apps; send what you'd be okay to receive."},
  {"id":"sr-066","cat":"profiles-are-people","type":"strike-rewrite","hook":"\"On apps, the normal rules of respect don't apply.\"","myth":{"un":"On apps, the normal rules of respect don't apply.","re":"Profiles are people; consent, honesty and decency carry across every screen.","why":"A screen doesn't switch off respect."},"relearn":"Profiles are people; respect carries across every screen.","persona":"any","source":"respect online"},
  {"id":"sr-067","cat":"profiles-are-people","type":"reflect","hook":"Lensy: the dignity you'd want shown to you is what you give every match. Deal?","prompt":"What do you think?","options":["Yes","Both ways","Golden rule"],"affirm":"Treating others as you'd want to be treated is the simplest dating rule there is.","relearn":"Give every match the dignity you'd want shown to you.","persona":"any","source":"golden rule"},
  {"id":"sr-068","cat":"profiles-are-people","type":"sort","hook":"Sort: inclusive and respectful, or not?","items":[{"id":"a","text":"Respecting someone's stated identity"},{"id":"b","text":"Fetishising or mocking it"},{"id":"c","text":"Being decent across orientations"},{"id":"d","text":"Slurs or 'jokes' in a DM"},{"id":"e","text":"Using the name and pronouns they give"},{"id":"f","text":"Demanding they 'prove' their identity"}],"bins":[{"id":"yes","label":"Respectful","valence":"pos"},{"id":"no","label":"Not","valence":"neg"}],"key":{"a":"yes","b":"no","c":"yes","d":"no","e":"yes","f":"no"},"relearn":"Respecting identity, names and pronouns is decent; fetishising, slurs or demanding 'proof' aren't.","persona":"Zoya","source":"inclusive respect"},
  {"id":"sr-069","cat":"profiles-are-people","type":"role-play","persona":"Rohan","source":"culture","hook":"Your mate Vikram jokes about \"collecting\" matches and leading them on for fun.","setup":"You're both scrolling in the hostel room.","steps":[{"prompt":"Vikram says: \"Forty matches this week. I keep them all hooked with a flirty line.\"","options":[{"text":"\"Ha! Teach me your ways.\"","then":"He grins and shows you his routine. Forty people think he's keen."},{"text":"\"They're people, though. Not a collection.\"","then":"Vikram laughs. \"Okay, okay. They're people. Still, forty!\"","best":true},{"text":"\"Forty? I'm at sixty.\"","then":"\"No way,\" he says, and the count becomes a contest."},{"text":"\"Whatever. It's your phone, your call.\"","then":"Vikram shrugs and keeps swiping. The joke stands."}],"why":"A light reminder that matches are people lands without a lecture."},{"prompt":"Vikram says: \"Honestly, nobody takes a few flirty texts on an app seriously.\"","options":[{"text":"\"Some of them do. I'd hate being strung along.\"","then":"Vikram pauses. \"Yeah. I've been on the other end too.\"","best":true},{"text":"\"True. It's all a game anyway.\"","then":"He nods. Forty people keep hoping for a date that won't come."},{"text":"\"You're a terrible person, you know.\"","then":"His face tightens. \"Wow. Thanks.\" The room goes quiet."},{"text":"\"Fair. Just don't do it to anyone I know.\"","then":"He laughs. \"Deal.\" Everyone else is still fair game."}],"why":"Naming how it feels on the other end makes the person real."},{"prompt":"Later, Vikram asks: \"Okay, what would you do with forty matches, then?\"","options":[{"text":"\"Keep them all. You never know.\"","then":"He grins. \"Exactly.\" The collection keeps growing."},{"text":"\"Ghost the ones you don't like. Easy.\"","then":"\"See, you're just like me,\" he says."},{"text":"\"Reply to all forty, just to be nice.\"","then":"He laughs. \"And say what, to forty people?\""},{"text":"\"Chat with a few I like. Kindly close the rest.\"","then":"Vikram thinks. \"Fewer chats, less guilt. Might try it.\"","best":true}],"why":"A few real chats and kind sign-offs treat people as people."}],"relearn":"Gently remind people that matches are people, not a collection."},
  {"id":"sr-070","cat":"profiles-are-people","type":"branch","persona":"any","source":"kindness","hook":"At the canteen, your friends are passing round a phone, mocking an awkward dating profile.","steps":[{"prompt":"Tanmay turns the screen to you: \"Look at this guy's poses!\" What do you do?","options":[{"text":"Join in with a joke of your own","then":"The table roars. You feel a small twist when the phone moves on."},{"text":"Decline to pile on. There's a real person there","then":"Tanmay shrugs and scrolls on. The laughter dies down a little.","best":true},{"text":"Laugh along, but don't add anything","then":"Nobody notices your silence. The mocking carries on as before."},{"text":"Tell them all they're being cruel, and walk off","then":"The table goes quiet. Tanmay mutters that it's a joke, and they carry on."}],"why":"Simply not joining in reminds a group there's a person on the screen."},{"prompt":"Later, Tanmay says mocking profiles is harmless, since it's just the internet. What do you say?","options":[{"text":"It's the internet, but it's still a real guy","then":"Tanmay rolls his eyes, then goes quiet. \"Fair. I'd hate that too.\"","best":true},{"text":"True. He'll never see it, so it's harmless","then":"Tanmay grins. \"Exactly.\" The guy on the screen is forgotten by dinner."},{"text":"Everyone does it anyway, so whatever","then":"You both move on. The next profile gets the same treatment."},{"text":"You'd cry if someone did it to you","then":"Tanmay bristles. \"I would not.\" The chat gets snippy."}],"why":"A calm reminder of the person behind it lands better than a dig."},{"prompt":"That night you match with someone whose photos are just as awkward. What do you do?","options":[{"text":"Screenshot the profile for the group","then":"The group laughs. The person on the screen never knows, but you do."},{"text":"Chat, but joke about their photos first","then":"They reply with a short \"haha\" and go quiet."},{"text":"Tell them their photos need some work","then":"\"Oh. Thanks, I guess,\" they reply, and the chat fizzles."},{"text":"Chat like you'd chat with anyone","then":"They turn out to be funny and a bit nerdy. You talk for an hour.","best":true}],"why":"Every profile is a person worth meeting on their own terms."}],"debrief":"Not mocking someone's profile is a small, real act of decency.","relearn":"Don't mock someone's profile; there's a real person there."},
  {"id":"sr-071","cat":"profiles-are-people","type":"strike-rewrite","hook":"\"Being too nice online makes you a pushover.\"","relearn":"Being decent online is its own kind of attractive.","persona":"any","source":"decency","myth":{"un":"Being too nice online makes you a pushover.","re":"Being decent online is its own kind of attractive, and a strength, not a weakness.","why":"Kindness reads as confidence, not weakness."}},
  {"id":"sr-072","cat":"profiles-are-people","type":"sort","hook":"Sort: builds your good name, or harms it?","items":[{"id":"a","text":"Honest, kind interactions"},{"id":"b","text":"Sending unsolicited explicit images"},{"id":"c","text":"Respecting a no the first time"},{"id":"d","text":"Bombarding someone who's gone quiet"},{"id":"e","text":"Saying you're not a fit, plainly"},{"id":"f","text":"Screenshotting a chat to mock them"}],"bins":[{"id":"builds","label":"Builds it","valence":"pos"},{"id":"harms","label":"Harms it","valence":"neg"}],"key":{"a":"builds","b":"harms","c":"builds","d":"harms","e":"builds","f":"harms"},"relearn":"Honesty and respecting a no build your name; unsolicited images, bombarding or mocking harm it.","persona":"any","source":"reputation"},
  {"id":"sr-073","cat":"profiles-are-people","type":"spot","hook":"Spot the two openers that don't treat a person with respect.","scene":[{"id":"a","text":"\"Your hiking photos are great, where was that?\"","trick":false},{"id":"b","text":"An unsolicited explicit image","trick":true},{"id":"c","text":"A crude one-liner about their body","trick":true},{"id":"d","text":"\"We both love filter coffee, agree or fight?\"","trick":false},{"id":"e","text":"\"Your bio made me laugh, what's the story?\"","trick":false}],"why":"An explicit image and a crude body line treat a person as an object, not a match.","relearn":"A genuine opener is respectful; explicit images or crude body lines aren't.","persona":"any","source":"openers"},
  {"id":"sr-074","cat":"profiles-are-people","type":"reflect","hook":"Lensy: which 'profiles are people' habit will you carry?","prompt":"Pick one.","options":["Decency doesn't pause for apps","Honesty both ways","Take no gracefully","Respect every identity"],"affirm":"Any of those makes you exactly the kind of person worth matching with.","relearn":"Decency, honesty, grace and respect: that's treating profiles as people.","persona":"any","source":"consolidation"},
  {"id":"sr-075","cat":"tools-and-help","type":"match","persona":"any","source":"help routes","relearn":"1930 for image abuse and blackmail, 181 for harassment, 112 for danger, a friend for your plan, block for contact.","hook":"Match each issue to where help lives (India).","pairs":[{"left":"Blackmail or an intimate image shared","right":"cybercrime.gov.in or 1930"},{"left":"Harassment or threats","right":"Helpline 181 or 1098"},{"left":"Immediate danger","right":"Emergency 112"},{"left":"Where you'll be tonight","right":"A trusted friend"},{"left":"A match who won't stop messaging","right":"Block and report in-app"}]},
  {"id":"sr-076","cat":"tools-and-help","type":"sort","persona":"any","source":"checklist","relearn":"Public, told-a-friend, own transport and clear-headed is the meet-safe checklist; going dark or sharing your address isn't.","hook":"Sort each move: on the meet-safe checklist, or not?","items":[{"id":"a","text":"Public place, told a friend"},{"id":"b","text":"Go alone, tell no one"},{"id":"c","text":"Own transport, stay clear-headed"},{"id":"d","text":"Share your home address first"},{"id":"e","text":"Phone charged before you leave"},{"id":"f","text":"Switch your phone off to be private"}],"bins":[{"id":"yes","label":"On the checklist","valence":"pos"},{"id":"no","label":"Not on it","valence":"neg"}],"key":{"a":"yes","b":"no","c":"yes","d":"no","e":"yes","f":"no"}},
  {"id":"sr-077","cat":"tools-and-help","type":"match","persona":"any","source":"checklist","relearn":"Public, told-a-friend, own-transport, clear-headed and a charged phone each protect a different part of meeting safely.","hook":"Match each safety step to what it protects.","pairs":[{"left":"Meet in public","right":"There are people around"},{"left":"Tell a friend","right":"Someone knows where you are"},{"left":"Your own transport","right":"You can leave any time"},{"left":"Stay clear-headed","right":"You can read the room"},{"left":"Phone charged","right":"You can reach help if needed"}]},
  {"id":"sr-078","cat":"tools-and-help","type":"reflect","hook":"Lensy: report and block aren't 'overreacting', they're tools you're allowed to use. Clear?","prompt":"What do you think?","options":["Yes","Allowed to use them","Not overreacting"],"affirm":"Blocking and reporting are normal tools; using them is sensible, never an overreaction.","relearn":"Report and block are tools you're fully allowed to use.","persona":"any","source":"tools"},
  {"id":"sr-079","cat":"tools-and-help","type":"match","persona":"any","source":"red-flag moves","relearn":"Won't-call means don't meet; money-ask means report; pressure means hold your steps; threats mean 181; leak means 1930.","hook":"Match each red flag to the move.","pairs":[{"left":"Won't ever video-call","right":"Don't meet; likely fake"},{"left":"Asks for money","right":"Stop, never send, report"},{"left":"Pressures you to skip safety","right":"Hold your steps, reconsider"},{"left":"Sends threats after a no","right":"Block and call helpline 181"},{"left":"Threatens to leak a photo","right":"Report to cybercrime 1930"}]},
  {"id":"sr-080","cat":"tools-and-help","type":"match","persona":"Meena","source":"who to tell","relearn":"Friend for whereabouts, 1930 for image abuse, 181 for harassment, 112 for danger, block for unwanted contact.","hook":"Match each thing to who to tell about it.","pairs":[{"left":"Where you'll be tonight","right":"A trusted friend"},{"left":"An intimate image leaked","right":"cybercrime.gov.in or 1930"},{"left":"Ongoing harassment","right":"Helpline 181 or 1098"},{"left":"Immediate danger","right":"Emergency 112"},{"left":"A match who keeps messaging","right":"Block, then report in-app"}]},
  {"id":"sr-081","cat":"tools-and-help","type":"strike-rewrite","hook":"\"If an intimate image of you leaks, it's partly your fault.\"","relearn":"Sharing an intimate image of you is abuse on them, not your fault.","persona":"any","source":"image abuse / no shame","myth":{"un":"If an intimate image of you leaks, it's partly your fault.","re":"Sharing an intimate image of you is abuse and on the person who shared it, never your fault.","why":"The blame sits only with the person who betrayed your trust."}},
  {"id":"sr-082","cat":"tools-and-help","type":"sort","persona":"any","source":"real routes","relearn":"1930, 181 and a trusted person are real routes; hoping it stops or blaming yourself in silence aren't.","hook":"Sort each option: a real help route, or not?","items":[{"id":"a","text":"cybercrime.gov.in or 1930"},{"id":"b","text":"Just hoping it stops"},{"id":"c","text":"A trusted friend or counsellor"},{"id":"d","text":"Blaming yourself in silence"},{"id":"e","text":"Calling helpline 181"},{"id":"f","text":"Replying to keep them calm"}],"bins":[{"id":"real","label":"Real route","valence":"pos"},{"id":"not","label":"Not a route","valence":"neg"}],"key":{"a":"real","b":"not","c":"real","d":"not","e":"real","f":"not"}},
  {"id":"sr-083","cat":"tools-and-help","type":"branch","persona":"any","source":"mutual safety","hook":"Your friend Mitali is meeting an app match this evening and hasn't told anyone.","steps":[{"prompt":"She mentions it while you're both getting chai. What do you do?","options":[{"text":"Say nothing. It's her business","then":"She heads off. Nobody knows where she'll be tonight."},{"text":"Offer to be her check-in and know the plan","then":"Mitali smiles. \"Would you? The cafe by the lake, at 6.\"","best":true},{"text":"Tell her to just stay home instead","then":"Mitali laughs, a bit annoyed. \"I'm going. I'm not a kid.\""},{"text":"Say \"be safe!\" and leave it there","then":"\"I will,\" she says. Nobody knows where or when."}],"why":"Offering to hold the plan is a real kindness, not interfering."},{"prompt":"At 8, you think of Mitali's date and wonder how it's going. What do you do?","options":[{"text":"Text her to ask if all's okay","then":"A minute later: \"All good! Walking to the metro now.\"","best":true},{"text":"Assume she's fine and wait till morning","then":"You go to bed wondering. Nobody checks on her all night."},{"text":"Call her five times in a row","then":"She steps out of the cafe, flustered. \"I'm fine! You scared me.\""},{"text":"Message her match on the app to check","then":"The match is confused, and Mitali is mortified when she finds out."}],"why":"One simple check-in text is how a safety net works."},{"prompt":"Next week, Mitali has another first date. What do you offer?","options":[{"text":"Nothing. She'll ask if she wants it","then":"She doesn't ask. She goes without telling anyone."},{"text":"To come along and sit at the next table","then":"Mitali hesitates. \"That's sweet, but a bit much.\""},{"text":"A warning about everything that could go wrong","then":"Mitali's face falls. \"You're making me scared to go.\""},{"text":"To hold her plan, with a check-in time","then":"\"Yes please,\" she says. \"And I'll do yours.\"","best":true}],"why":"Being the friend who holds the plan makes the habit easy to keep."}],"debrief":"Being a friend's check-in is one of the most useful safety tools there is.","relearn":"Offer to be a friend's check-in when they meet a match."},
  {"id":"sr-084","cat":"tools-and-help","type":"reflect","hook":"Lensy: meet safely, spot the fakes, treat people well, you're set to date the modern world. Ready?","prompt":"What will you carry?","options":["Meet safely","Verify the real ones","Profiles are people","Rejection is survivable"],"affirm":"Carry those and you can date the modern world safely, kindly and on your terms.","relearn":"Meet safely, verify, treat people well, and know rejection is survivable.","persona":"any","source":"carry forward"},
  {"id":"sr-900","cat":"date-with-respect","type":"branch","persona":"Ananya","source":"pacing","hook":"At a café-bar, you suggest another round. Your date Joel goes quiet and looks at his glass.","steps":[{"prompt":"The server is hovering. What do you do?","options":[{"text":"Order two anyway. He'll loosen up","then":"Joel sips slowly and leaves most of it. The chat gets thinner."},{"text":"Ask if he's okay, then order the round anyway","then":"He says he's fine. The drinks arrive and he barely touches his."},{"text":"Say let's skip it, and suggest chai or a walk","then":"Joel exhales and grins. \"A walk sounds perfect, actually.\"","best":true},{"text":"Tease him that one more won't hurt","then":"Joel laughs politely and says sure. His answers get shorter after that."}],"why":"Going quiet is a cue. Easing off and offering another plan lets his comfort steer."},{"prompt":"Later, Joel says he doesn't drink much and felt awkward saying so. What do you say?","options":[{"text":"Tell him he'll get used to it soon enough","then":"Joel's smile tightens. \"I'm not really trying to get used to it.\""},{"text":"Thank him, and say drinks are never a must","then":"Joel relaxes. \"Honestly, that's a relief to hear.\"","best":true},{"text":"Apologise again and again for suggesting it","then":"Joel ends up reassuring you. The moment becomes about your guilt."},{"text":"Laugh and say you'd never have guessed","then":"He shrugs. It's hard to tell whether he feels heard."}],"why":"Thanking him and dropping the drinks pressure makes it easy for him to be honest next time."},{"prompt":"A week later, you're planning your next date. What do you suggest?","options":[{"text":"The same bar. He'll be more relaxed this time","then":"Joel agrees, but goes quiet again at the drinks menu."},{"text":"A house party where everyone will be drinking","then":"Joel says he'll try to come, then cancels on the day."},{"text":"A plan with no drinks at all, without asking him","then":"Joel agrees, then mentions he'd have been fine with one drink."},{"text":"A couple of ideas, and let him pick","then":"Joel picks the rooftop café. \"They do a great masala lemonade.\"","best":true}],"why":"Offering options and letting him pick means the plan fits you both."}],"debrief":"Reading a quiet cue and easing off keeps the night consensual, not pushed.","relearn":"Match the slower pace and check in; don't push."},
  {"id":"sr-901","cat":"date-with-respect","type":"branch","persona":"any","source":"receiving rejection","hook":"After a fun coffee date, Farah messages that she'd rather not meet again.","steps":[{"prompt":"You thought it went really well. What do you reply?","options":[{"text":"Ask her to list what put her off","then":"Farah writes, \"Nothing specific. Just not a match.\" You want more, and there isn't more."},{"text":"Say thanks for being straight, and leave it there","then":"Farah replies, \"Thanks for being so nice about it.\" The chat closes gently.","best":true},{"text":"Say you're confused, since it felt great to you","then":"Farah sends a careful paragraph explaining herself. You both feel worse."},{"text":"Reply ok and unmatch straight away","then":"The chat vanishes. You feel oddly unfinished about it."}],"why":"A no is complete on its own. Thanking her lets it end kindly."},{"prompt":"Your flatmate Mehul says you should just ask her friend what went wrong. What do you do?","options":[{"text":"Ask her friend casually at the next party","then":"Her friend looks uncomfortable. Word gets back to Farah by morning."},{"text":"Ask Mehul to guess what you did wrong","then":"Mehul lists theories for an hour. None help, and all of them sting."},{"text":"Draft a message asking Farah for honest feedback","then":"You rewrite it five times. Sending it would reopen what she closed."},{"text":"Tell him you'll let it go. It was her call","then":"Mehul shrugs and puts on a film. You feel a bit lighter.","best":true}],"why":"Her reasons are hers. Letting the no stand, without digging, respects her and you."},{"prompt":"Next week, you're getting ready for a date with someone new. What do you focus on?","options":[{"text":"Everything Farah might have disliked about you","then":"You spend the date watching yourself instead of listening."},{"text":"Being extra impressive so it doesn't happen again","then":"You talk too much about yourself. The date feels like an interview."},{"text":"Treating it as a fresh start, not a retest","then":"You walk in relaxed and actually enjoy the conversation.","best":true},{"text":"Guarding yourself so a no can't hurt this time","then":"You stay polite and closed. Your date can't tell if you're interested."}],"why":"One no isn't a verdict on you. Showing up fresh gives the next date a real chance."}],"debrief":"A no needs no audit. Thanking them and moving on is the respectful move.","relearn":"Take a no gracefully; don't push for reasons."},
  {"id":"sr-902","cat":"date-with-respect","type":"branch","persona":"any","source":"giving rejection","hook":"You're an hour into a date with Arnav. He's having a great time, but you feel no spark.","steps":[{"prompt":"He says: \"We should do this again soon.\" What do you do?","options":[{"text":"Smile and say maybe, then stop replying later","then":"Arnav leaves beaming. His texts start arriving before you're home."},{"text":"Say sure, and decide over text later","then":"Arnav is thrilled. The honest message now feels harder to send."},{"text":"Make an excuse about being really busy these days","then":"Arnav says he'll wait till things calm down. He means it."},{"text":"Tell him kindly you had fun but felt no spark","then":"Arnav's face falls a little. \"Oh. Okay. Thanks for saying it.\"","best":true}],"why":"Saying it kindly now spares him false hope, and spares you a harder message later."},{"prompt":"That night, Arnav texts a long, warm message about the evening. What do you do?","options":[{"text":"Send a heart so you don't seem rude","then":"Arnav reads the heart as a yes and suggests Friday."},{"text":"Reply kindly, and make sure the no is clear","then":"Arnav replies, \"Got it. Glad we met anyway.\"","best":true},{"text":"Leave it on read and hope he gets it","then":"Arnav sends another message the next day, less sure now."},{"text":"Send a long apology for wasting his evening","then":"Arnav says it wasn't a waste and asks if you're sure. The door creaks open again."}],"why":"A short, clear, kind reply ends it with respect. Mixed signals keep him hoping."},{"prompt":"A week later, your friend Kavya says she'd have just ghosted Arnav. Easier for everyone. What do you say?","options":[{"text":"Agree. Nobody expects a reply after one date","then":"Kavya nods. \"See? Nobody owes anyone anything.\" It sounds simpler than it felt."},{"text":"Say a short, kind no spares him the guessing","then":"Kavya thinks, then shrugs. \"Fair. I'd rather hear it straight too.\"","best":true},{"text":"Say ghosting's fine if you'll never see them again","then":"Kavya laughs. \"Exactly.\" You picture someone checking their phone for a reply."},{"text":"Say it depends on how nice the person was","then":"Kavya raises an eyebrow. \"So rude people just get ghosted?\""}],"why":"A brief, kind no is basic decency. Vanishing leaves the other person guessing."}],"debrief":"A clear, kind no beats faking interest and disappearing on someone.","relearn":"Give a no kindly and clearly; don't string someone along."},
  {"id":"sr-903","cat":"date-with-respect","type":"branch","persona":"any","source":"space","hook":"You sent Kavya a good-night text after your second date. By midnight the next day, no reply.","steps":[{"prompt":"You're awake and restless, phone in hand. What do you do?","options":[{"text":"Send a few \"you up?\" texts in a row","then":"The texts land one after another at 1 a.m. None come back tonight."},{"text":"Ask a friend to check if she's been online","then":"Your friend says she was online at ten. Now you're hurt as well as restless."},{"text":"Put the phone away and sleep on it","then":"You wake up with a clearer head. The chat is still quiet, and that's okay.","best":true},{"text":"Send a joke about being left on read","then":"It's meant to be light, but it reads as a dig. Still no reply."}],"why":"A day's gap is usually just life. Sleeping on it beats a late-night flood."},{"prompt":"The next morning, Kavya replies: \"Sorry! Mad day. Our date was lovely.\" What do you do?","options":[{"text":"Point out that it took her a whole day","then":"Kavya writes back, \"Sorry, I didn't know there was a deadline.\""},{"text":"Reply with a cool \"ok\" to seem unbothered","then":"Kavya reads it twice and can't tell what she did."},{"text":"Say no worries, and ask her to text when she's busy","then":"She agrees, but it sounds like a rule. Her next message is more careful."},{"text":"Reply warmly and pick up where you left off","then":"Kavya sends a voice note about her day. The chat feels easy again.","best":true}],"why":"Picking up warmly shows you trust the connection, not the clock."},{"prompt":"On Friday, you're out with friends and Kavya hasn't replied since lunch. What do you do?","options":[{"text":"Enjoy your night and check your phone later","then":"You get home laughing. Her reply is waiting: \"How was your night?\"","best":true},{"text":"Text her every hour to ask if she's there","then":"Your phone stays out all evening. Her one reply says she was at a family function."},{"text":"Post a story so she sees you're having fun","then":"You check who viewed it more than you talk to your friends."},{"text":"Ask your friends to decode her last message","then":"Three friends give three theories. You feel less sure, not more."}],"why":"Having your own life going is what makes giving space easy."}],"debrief":"Giving someone space instead of flooding them keeps things relaxed and respectful.","relearn":"Give people space; flooding for a reply reads as pressure."},
  {"id":"sr-904","cat":"date-with-respect","type":"branch","persona":"any","source":"ending a date","hook":"An hour into dinner, Sameer says he'd like to head home a bit early.","steps":[{"prompt":"Dessert hasn't arrived yet. What do you do?","options":[{"text":"Ask him to stay just till dessert comes","then":"Sameer sits back down, checking the time every few minutes."},{"text":"Ask what you did to make him want to leave","then":"Sameer says it's nothing. He's just tired. Now he's comforting you."},{"text":"Say of course, and ask how he's getting home","then":"Sameer relaxes. \"Auto's fine. Thanks for being easy about it.\"","best":true},{"text":"Say fine, and go quiet while he packs up","then":"Sameer leaves with an awkward wave. The evening ends on a sour note."},{"text":"Insist on dropping him home on your bike","then":"Sameer says he'd rather take an auto. There's an awkward pause."}],"why":"Anyone can end a date whenever they like. Letting him go warmly is the respect floor."},{"prompt":"Later that night, you're replaying the evening. What do you tell yourself?","options":[{"text":"He was clearly bored of me","then":"The thought stings. You start drafting a text asking him why."},{"text":"People get tired. It was still a nice evening","then":"You sleep fine and wake up curious whether he'll text.","best":true},{"text":"Leaving early means he owes me an explanation","then":"You go to bed annoyed, waiting for a reason he doesn't owe."},{"text":"My friends will know if it's a bad sign","then":"Three friends give three theories. You feel less sure, not more."}],"why":"Leaving early can mean many things. Not making it about you keeps it light."},{"prompt":"Next morning, Sameer texts: \"Sorry about last night. I was wiped.\" What do you reply?","options":[{"text":"Say it's fine, but you did feel a bit ditched","then":"Sameer apologises again. The next plan feels like he's making up for something."},{"text":"Leave him on read for a while to make a point","then":"Sameer checks the chat all morning and decides you're upset."},{"text":"Ask whether it was really just tiredness","then":"Sameer says yes, a little stiffly. It feels like an interrogation."},{"text":"Tell him there's no need to apologise","then":"Sameer sends a sleepy emoji. \"Much better today. Dessert next time?\"","best":true}],"why":"He doesn't owe an apology for leaving. Saying so keeps the door open."}],"debrief":"Someone can end a date whenever they want. Honouring that is the respect floor.","relearn":"A date can end whenever; honour it without guilt-tripping."},
  {"id":"sr-905","cat":"date-with-respect","type":"branch","persona":"any","source":"consent check-in","hook":"Your date with Neha is ending at the metro gate. You'd love a goodbye hug but can't read her.","steps":[{"prompt":"She's smiling and fiddling with her bag strap. What do you do?","options":[{"text":"Go in for it. Asking would kill the moment","then":"Neha stiffens, pats your back once and steps away quickly."},{"text":"Hug her quickly, then ask if that was okay","then":"Neha says it's fine. It's a little late for her to say otherwise."},{"text":"Ask if a hug is okay, and take either answer","then":"Neha laughs. \"Yes, please.\" It's a warm, easy hug.","best":true},{"text":"Just wave goodbye. Asking feels too risky","then":"Neha waves back. You both walk off wondering what the other wanted."}],"why":"A two-second ask lets her choose. Either answer is fine, and she knows it."},{"prompt":"On your next date, Neha says she's more of a high-five person for now. What do you do?","options":[{"text":"Ask her why, and what you did wrong","then":"Neha shrugs. \"Nothing. Just how I feel today.\" It turns into a thing."},{"text":"Say okay, but look visibly disappointed","then":"Neha notices and apologises. The goodbye feels heavy."},{"text":"Joke that you'll win her over by next week","then":"Neha laughs, but her shoulders tense a little."},{"text":"Say sure and go for the high-five","then":"Neha grins and high-fives you hard. \"Ow. Worth it.\"","best":true}],"why":"Comfort can change from date to date. Taking her word, without questions, keeps it easy."},{"prompt":"A friend says asking before a hug is too much. What do you say?","options":[{"text":"Agree and stop asking from now on","then":"On your next date, you go in unasked and your date steps back fast."},{"text":"Say you only ask because Neha is shy","then":"Your friend nods. The idea that everyone deserves the ask slips past you both."},{"text":"Say a quick ask makes things easier","then":"Your friend thinks about it. \"Huh. Nobody's ever minded being asked.\"","best":true},{"text":"Laugh it off and change the subject","then":"The comment stays with you. Next time, you wonder whether to ask."}],"why":"A quick ask is normal for everyone, not a special rule for shy people."}],"debrief":"A two-second consent check beats assuming. Either answer is fine.","relearn":"Check in before you move closer; either answer is fine."},
  {"id":"sr-906","cat":"date-with-respect","type":"branch","persona":"any","source":"pacing","hook":"A few weeks in, Imran tells you he wants to keep things slow for now.","steps":[{"prompt":"You'd hoped things were speeding up. What do you say?","options":[{"text":"Say sure, and plan to change his mind","then":"Imran smiles, unaware you're already planning to test it."},{"text":"Ask him how long slow is going to be","then":"Imran hesitates. \"I don't know. Is there a deadline?\""},{"text":"Say that works for you, and mean it","then":"Imran visibly relaxes. \"Thanks. I really like where this is going.\"","best":true},{"text":"Say fine, then change the subject fast","then":"Imran isn't sure you heard him. He brings it up again later, anxiously."}],"why":"Meaning your yes to his pace, not just saying it, is what makes it real."},{"prompt":"On a movie night at your place, you're sitting close on the sofa. What do you do?","options":[{"text":"Inch a little closer to test the waters","then":"Imran shifts slightly away and gets very interested in the film."},{"text":"Let him set how close you get","then":"Halfway through, Imran leans his head on your shoulder.","best":true},{"text":"Ask if tonight could be an exception","then":"Imran looks torn. \"Can we not do this tonight?\""},{"text":"Sit at the far end so he feels safe","then":"Imran looks puzzled, then asks if you're upset with him."}],"why":"Slow means following his lead, not testing it or making a show of distance."},{"prompt":"Your friend Yash grins: \"Just be patient. He'll give in eventually.\" What do you say?","options":[{"text":"Laugh along. He's probably right","then":"Yash high-fives you. The idea of waiting him out stays with you."},{"text":"Say you're starting to lose patience, honestly","then":"Yash tells you to drop hints. You leave with a plan you don't like."},{"text":"Say nothing and change the subject","then":"Yash keeps joking. You don't correct him, and it bothers you later."},{"text":"Say it isn't about waiting him out","then":"Yash raises his eyebrows, then nods. \"Okay, fair.\"","best":true}],"why":"Slow isn't a hurdle to outlast. It's how he wants to go, and that's the point."},{"prompt":"A month on, Imran says he's ready for more and asks how you feel. What do you say?","options":[{"text":"Tell him you'd been waiting ages for this","then":"Imran's smile slips. \"You were counting?\""},{"text":"Say yes to whatever he's thinking","then":"Imran pauses. \"I'd like to know what you want too.\""},{"text":"Say you're glad, and talk about what more means","then":"Imran laughs. \"Okay, we're doing this properly.\" You talk late into the night.","best":true},{"text":"Suggest going to your place right now","then":"Imran hesitates. \"Maybe not tonight. I meant more generally.\""}],"why":"Ready for more is still a conversation. Talking it through keeps it mutual."}],"debrief":"When someone names a slower pace, matching it honestly is the whole point.","relearn":"Match the slower pace for real; don't keep nudging."},
  {"id":"sr-907","cat":"date-with-respect","type":"branch","persona":"any","source":"holding a no","hook":"You told Rishi you weren't interested after two dates. He keeps asking what he did wrong.","steps":[{"prompt":"His third message today says he just wants to understand. What do you do?","options":[{"text":"Explain every reason until he's satisfied","then":"He answers each reason with a counterpoint. It's a debate now."},{"text":"Tell him maybe you'll feel differently later","then":"Rishi thanks you and says he'll wait. The messages don't stop."},{"text":"Send one kind, final line, then stop replying","then":"You send: \"It's not about anything you did. Take care.\" Then you mute the chat.","best":true},{"text":"Answer his questions, but more briefly each time","then":"Every short answer invites another question. The chat drags on for days."}],"why":"You don't owe an endless debrief. One kind, clear line is enough."},{"prompt":"Two days later, Rishi writes that he can't sleep and just needs closure. What do you do?","options":[{"text":"Decide his sadness is yours to fix","then":"You spend the evening drafting comforting messages. He replies within seconds."},{"text":"Leave it, and talk to a friend instead","then":"Your flatmate Farah listens. \"Your last message was the closure.\"","best":true},{"text":"Tell yourself you must have been cruel somehow","then":"You reread your message ten times. It reads kind, but the doubt stays."},{"text":"Ask a mutual friend to pass on your reasons","then":"The friend comes back with more questions from Rishi. You're still in it."}],"why":"His hurt is real, but it isn't yours to fix. Leaning on a friend helps you hold your no."},{"prompt":"Your friend Pooja says blocking him would be harsh after he's been so sad. What do you do?","options":[{"text":"Agree, and keep reading his messages","then":"His messages keep arriving. Each one pulls you back into the same questions."},{"text":"Reply once more so you don't seem heartless","then":"Rishi reads your reply as a crack in the door and writes back at once."},{"text":"Tell her muting or blocking is your call to make","then":"Pooja thinks it over. \"True. I'd want that option too.\"","best":true},{"text":"Wonder aloud if you really did mislead him","then":"Pooja isn't sure either. You go home doubting a no you were sure of."}],"why":"Muting or blocking is a tool you're allowed to use. His hurt after your no isn't your fault."}],"debrief":"You can be kind and still stop the back-and-forth. A no isn't a negotiation.","relearn":"A no isn't a debate; one kind line, then space, is enough."},
  {"id":"sr-908","cat":"date-with-respect","type":"branch","persona":"Deepak","source":"inclusive pacing","hook":"It's your turn to plan a date with Priya, and you've no idea what she likes to spend.","steps":[{"prompt":"You want it to feel special. What do you suggest?","options":[{"text":"The fancy rooftop place, to impress her","then":"Priya hesitates, then quietly checks the menu prices online."},{"text":"Ask her straight out what her budget is","then":"Priya laughs awkwardly and says anything's fine. You're no wiser."},{"text":"Somewhere cheap, and don't mention why","then":"Priya's fine with it, but wonders if you're not that keen."},{"text":"A couple of low-cost ideas, and let her pick","then":"Priya picks the chaat place near the lake. \"Perfect. I love that spot.\"","best":true}],"why":"Offering options lets her choose what fits, without putting her wallet on the spot."},{"prompt":"At the end of the date, the bill arrives. What do you do?","options":[{"text":"Grab it fast before she can reach","then":"Priya thanks you, but seems put out that she didn't get a say."},{"text":"Wait for her to offer first","then":"The bill sits there for an awkward minute before she reaches for it."},{"text":"Ask how she'd like to handle it","then":"Priya says, \"Split this one, and the next is on me?\" You both like that.","best":true},{"text":"Pay, then mention it was pricey","then":"Priya offers to send you half. The moment feels transactional."}],"why":"Asking how she'd like to split keeps money fair and out in the open."},{"prompt":"Your friend says real dates should cost something, or she'll think you're cheap. What do you do?","options":[{"text":"Borrow money to plan something flashier next","then":"The dinner is lovely. The loan sits in your head all month."},{"text":"Pretend money is never an issue for you","then":"Priya picks a pricier place next. You can't say why it stresses you."},{"text":"Keep planning dates that fit both your budgets","then":"Priya suggests a free concert next. The dates keep being fun.","best":true},{"text":"Plan pricey dates only when she seems keen","then":"You start treating each date like a test she has to pass."}],"why":"Respect isn't measured in rupees. Dates that fit both budgets are the ones that last."}],"debrief":"Picking a date that fits both budgets is respect, not stinginess.","relearn":"Plan dates that fit both budgets; flashy isn't respect."},
  {"id":"sr-909","cat":"date-with-respect","type":"branch","persona":"Zoya","source":"respecting timeline","hook":"Sana isn't out to her family yet, and asks you to keep your relationship low-key.","steps":[{"prompt":"You'd love to post a photo from your weekend trip. What do you do?","options":[{"text":"Post it, but without tagging her","then":"Sana's cousin recognises her jacket in the photo and comments."},{"text":"Ask Sana what she's comfortable with being shared","then":"Sana thinks. \"Scenery is fine. Nothing with me in it for now.\"","best":true},{"text":"Tease her to just be open already","then":"Sana laughs it off, but goes quiet for the rest of the evening."},{"text":"Tell her hiding makes you feel like a secret","then":"Sana apologises and says she's trying. She looks more anxious than before."}],"why":"What's shared about her is hers to decide. Asking lets her set it."},{"prompt":"At a college fest, a friend asks loudly if you two are together, and Sana freezes. What do you do?","options":[{"text":"Say yes proudly. It's time people knew","then":"Heads turn. Sana leaves early, and her phone starts buzzing."},{"text":"Deny it loudly and joke about it","then":"The friend drops it. Sana goes quiet, stung by how fast you laughed."},{"text":"Tell the friend to ask Sana herself","then":"Everyone looks at Sana. She mumbles something and heads for the washroom."},{"text":"Glance at Sana and follow her lead","then":"Sana says you're just friends, and you let it stand. Later, she squeezes your hand.","best":true}],"why":"Her coming out is her call. Following her lead in the moment protects that."},{"prompt":"Weeks later, Sana says she's thinking of telling her sister, and asks what you think. What do you say?","options":[{"text":"Tell her to do it. Waiting only makes it harder","then":"Sana nods, but her face tightens. \"You don't know my sister.\""},{"text":"Say she should wait until she earns her own money","then":"Sana sighs. \"That's years.\" She seems more stuck than before."},{"text":"Ask what she needs, and say you'll back her either way","then":"Sana breathes out. \"Honestly, just help me think it through.\" You do.","best":true},{"text":"Say it's up to her, and leave it there","then":"Sana nods. She wanted to think it through with you, and doesn't."}],"why":"Backing her choice, and asking what support she wants, keeps it her timeline."}],"debrief":"Who to tell, and when, is hers to decide. Following her lead is respect.","relearn":"Coming out is theirs to time; follow their lead."},
  {"id":"sr-910","cat":"date-with-respect","type":"branch","persona":"any","source":"no entitlement","hook":"Two dates in, you've really clicked with Tenzin. Then he mentions he's seeing other people too.","steps":[{"prompt":"Your stomach drops a little. What do you say?","options":[{"text":"Ask him to stop seeing them and pick you","then":"Tenzin looks startled. \"It's been two dates.\""},{"text":"Say it's fine, then sulk for the rest of the evening","then":"Tenzin tries to lift the mood, then gives up and asks for the bill."},{"text":"Thank him for being upfront","then":"Tenzin smiles. \"I'd rather be honest early.\" The date carries on easily.","best":true},{"text":"Ask him for names and how far it's gone","then":"Tenzin shifts in his seat. \"I don't think that's fair to them.\""}],"why":"Early on, nobody owes exclusivity. Thanking him for his honesty keeps things easy."},{"prompt":"A week later, you and Tenzin are still texting, and you still wish he were only seeing you. What do you do?","options":[{"text":"Wait for him to bring it up","then":"A week goes by. You check his app activity until Tenzin brings up where you stand."},{"text":"Give him a deadline to decide","then":"Tenzin goes quiet. \"That feels like pressure. Give me a day.\""},{"text":"Tell him how you feel and ask where he's at","then":"Tenzin looks glad you asked, and takes a moment to answer honestly.","best":true},{"text":"Delete the app loudly, hoping he'll follow","then":"Tenzin notices a day later and asks, a bit uneasy, what it means."}],"why":"Exclusivity is a shared choice. Saying what you want and asking him makes it one."},{"prompt":"Tenzin says he likes you, but he isn't ready to be exclusive yet. What do you do?","options":[{"text":"Keep dating him and check his app activity daily","then":"You know when he's online better than what he's thinking."},{"text":"Try harder to be the obvious choice","then":"You cancel plans to stay free for him. It feels like an audition."},{"text":"Tell him he's wasting your time","then":"Tenzin looks hurt. \"I've been honest from day one.\""},{"text":"Respect it, and think about what works for you","then":"You take a few days, and realise you're happy to keep seeing where it goes.","best":true}],"why":"His pace is his to set. What you do with it is yours to decide, honestly."}],"debrief":"Early on, nobody owes you exclusivity. Respecting that keeps it healthy.","relearn":"Nobody owes exclusivity early on; demanding it is pressure."},
  {"id":"sr-911","cat":"date-with-respect","type":"branch","persona":"any","source":"reading the body","hook":"On your second date, you reach for Mira's hand across the table. She flinches.","steps":[{"prompt":"She pulls her hand into her lap. What do you do?","options":[{"text":"Laugh and joke that she's being very shy","then":"Mira laughs thinly and folds her arms. The conversation stalls."},{"text":"Try again later when she's more relaxed","then":"Later, you reach again. Mira shifts her chair back an inch."},{"text":"Apologise at length for making it weird","then":"Mira ends up reassuring you for five minutes. The moment gets heavier."},{"text":"Pull back easily and say no worries at all","then":"Mira's shoulders drop. \"Sorry. I'm just not a hand-holder yet.\"","best":true}],"why":"A flinch is an answer. Pulling back lightly respects it without making it a thing."},{"prompt":"Later, Mira says she isn't very touchy early on. What do you say?","options":[{"text":"Ask her how long that usually lasts","then":"Mira shrugs. \"Depends on the person.\" She sounds a little guarded."},{"text":"Say thanks for telling you, and that's fine by you","then":"Mira smiles properly for the first time since. \"Thanks. That helps.\"","best":true},{"text":"Say you're very touchy, so she'll get used to it","then":"Mira's eyebrows go up. \"Or not,\" she says, half joking."},{"text":"Ask if someone hurt her before","then":"Mira stiffens. \"That's a lot for a second date.\""}],"why":"Thanking her makes it easy for her to tell you her limits again."},{"prompt":"At the end of the night, you'd like to hug her goodbye. What do you do?","options":[{"text":"Hug her anyway. It's just a goodbye","then":"Mira goes rigid until you let go."},{"text":"Ask, and be fine with a wave instead","then":"Mira grins and offers a fist bump. You take it.","best":true},{"text":"Leave without any goodbye at all","then":"Mira watches you go, unsure whether you're upset."},{"text":"Wait to see if she hugs you first","then":"You both hover by the auto stand. The goodbye ends up awkward."}],"why":"After a flinch, asking again is how you keep her comfort in charge."},{"prompt":"Your friend Harsh says she's just playing hard to get. What do you tell him?","options":[{"text":"Agree, and plan to be bolder next time","then":"You head into the next date planning to push. It sits badly with you."},{"text":"Say maybe, and that you'll wait and see","then":"Harsh takes that as a yes. His advice keeps coming."},{"text":"Say she's probably just not into you","then":"Harsh says you're overthinking. Nobody mentions what she actually said."},{"text":"Say a flinch means no, not a game","then":"Harsh opens his mouth, then shuts it. \"Okay. Fair.\"","best":true}],"why":"Treating a body's no as a game overrides consent. Taking it at face value respects her."}],"debrief":"A body that pulls away is answering. Respecting it on the spot is consent in action.","relearn":"A flinch is a no; pull back without teasing."},
  {"id":"sr-912","cat":"date-with-respect","type":"branch","persona":"any","source":"genuine yes","hook":"You ask Dhruv for a second date. He says he needs to think about it.","steps":[{"prompt":"You're standing by his cab. What do you say?","options":[{"text":"Ask what there is to think about","then":"Dhruv fumbles for an answer. \"I just want to be sure.\""},{"text":"Say take your time, and leave it with him","then":"Dhruv smiles. \"Thanks. I'll message you.\" The cab pulls away.","best":true},{"text":"Ask for an answer before he goes","then":"Dhruv mumbles \"maybe\" and looks relieved when the cab pulls away."},{"text":"Say fine, but the offer won't last forever","then":"Dhruv's smile fades. \"Right. Noted.\""}],"why":"A yes given under pressure isn't a real yes. Giving him time keeps it genuine."},{"prompt":"Two days pass with no word from Dhruv. What do you do?","options":[{"text":"Send a reminder that you're still waiting","then":"Dhruv replies, \"Sorry, still thinking.\" He sounds more tired than before."},{"text":"Ask a mutual friend what he's said about you","then":"Your friend says she'd rather not be in the middle. It's awkward."},{"text":"Leave it with him and get on with your week","then":"It's hard not to check. On day three, he messages.","best":true},{"text":"Say no pressure, then ask again the next day","then":"Dhruv notices that no pressure came with a follow-up."}],"why":"Thinking time means actual time. Letting him use it is part of respecting his answer."},{"prompt":"Dhruv writes that he'd like to meet again, but somewhere low-key. What do you do?","options":[{"text":"Book a fancy dinner anyway to win him over","then":"Dhruv agrees, but spends the evening glancing at the prices."},{"text":"Ask why he took so long to decide","then":"Dhruv hesitates. \"I just needed time. Is that a problem?\""},{"text":"Plan a big group outing so it's less pressure","then":"Dhruv comes, but you barely talk to each other all evening."},{"text":"Ask what low-key looks like for him","then":"Dhruv suggests a bookshop café. \"I talk better with coffee.\"","best":true}],"why":"His yes came with a wish. Asking about it honours the yes he gave."}],"debrief":"A yes that's pressured isn't a yes. Giving someone time keeps it genuine.","relearn":"Let a yes be freely given; don't press for one."},
  {"id":"sr-913","cat":"date-with-respect","type":"branch","persona":"any","source":"reading energy","hook":"On a video date, Ayesha seems tired and a bit flat tonight.","steps":[{"prompt":"She yawns and apologises for the third time. What do you do?","options":[{"text":"Keep her on for another hour to see if she cares","then":"Ayesha stays on, answering in single words. The call drags."},{"text":"Ask her if she's bored of talking to you","then":"Ayesha blinks. \"No, just tired.\" Now she has to reassure you."},{"text":"Offer to keep it short and pick it up another day","then":"Ayesha looks grateful. \"Would you mind? It's been a long week.\"","best":true},{"text":"Tell a long funny story to perk her up","then":"Ayesha laughs politely, then yawns again mid-story."}],"why":"Low energy isn't rejection. Offering an easy out is care."},{"prompt":"The next day, Ayesha texts that she felt bad about the call. What do you reply?","options":[{"text":"Say it's okay, though you did feel a bit ignored","then":"Ayesha apologises again. The chat turns into her making it up to you."},{"text":"Suggest a call tonight to make up for it","then":"Ayesha hesitates. \"Tonight's hard. Maybe the weekend?\""},{"text":"Send a thumbs up and nothing else","then":"Ayesha can't tell if you're annoyed. She doesn't text again that day."},{"text":"Tell her it was fine, and ask about her week","then":"Ayesha sends a long message about her deadline. She sounds lighter.","best":true}],"why":"Letting her off the hook and asking about her week keeps it warm and easy."},{"prompt":"At the weekend, Ayesha suggests another video call. What do you say?","options":[{"text":"Say yes, and ask what time suits her","then":"Ayesha picks Sunday afternoon. \"I'll be human by then.\"","best":true},{"text":"Say yes, if she's properly awake this time","then":"Ayesha laughs, but you can hear she's a bit stung."},{"text":"Say calls don't work for you, so meet tonight","then":"Ayesha says tonight isn't possible. The plan fizzles."},{"text":"Play it cool and say you'll see","then":"Ayesha waits for a real answer that doesn't come."}],"why":"Letting her pick a time that works shows her comfort matters to you."},{"prompt":"A friend says keeping calls short means you're not really trying. What do you tell yourself?","options":[{"text":"I should push for longer calls","then":"You start timing your calls. It makes them feel like work."},{"text":"Maybe she isn't that into me after all","then":"You reread her texts looking for proof. There isn't any."},{"text":"Short and happy beats long and forced","then":"You stop counting minutes and just enjoy the next call.","best":true},{"text":"My friend probably knows how long is right","then":"You ask for a number. Now you have a target you don't need."}],"why":"Reading someone's energy is trying. Care isn't measured in minutes."}],"debrief":"Reading low energy and offering an out is care, not a test.","relearn":"Read their energy and ease off; don't test their interest."},
  {"id":"sr-914","cat":"date-with-respect","type":"branch","persona":"Rohan","source":"no means no","hook":"Meher said a clear no to a second date, but she's still friendly and funny in the chat.","steps":[{"prompt":"She sends a meme about the café you went to. What do you do?","options":[{"text":"Use it to suggest going there again","then":"Meher replies, \"Haha, as friends maybe.\" The chat cools a notch."},{"text":"Read it as a sign she's changing her mind","then":"You spend the evening drafting a second pitch."},{"text":"Laugh at the meme and leave it at that","then":"Meher sends a laughing emoji back. The chat stays light.","best":true},{"text":"Ask why she's messaging if she said no","then":"Meher goes quiet. \"Sorry. I thought we were cool.\""}],"why":"A friendly meme is just friendly. Letting it be keeps her no intact."},{"prompt":"Your friend Kunal says friendly girls are just waiting to be chased. What do you say?","options":[{"text":"Agree it's worth one more try","then":"Kunal helps you draft a message. It reads like a script, not like you."},{"text":"Say she said no, and her no stands","then":"Kunal rolls his eyes, then drops it.","best":true},{"text":"Say you're not sure. Maybe he's right","then":"Kunal takes that as a yes and keeps coaching you all evening."},{"text":"Say friendly people are hard to read anyway","then":"Kunal nods. The fact that she was perfectly clear gets lost."}],"why":"Her no was clear. Friendliness doesn't cancel it, whatever anyone says."},{"prompt":"A month later, Meher invites you to her birthday with a big group. What do you do?","options":[{"text":"Go, and find a quiet moment to ask her out","then":"Meher's smile freezes. She finds a reason to go and check on the cake."},{"text":"Bring an expensive gift to show you care","then":"Meher looks uncomfortable opening it in front of everyone."},{"text":"Go, but drop hints all night","then":"Meher starts talking to everyone except you."},{"text":"Go as a friend and enjoy the party","then":"You meet her friends, laugh a lot, and head home easily.","best":true}],"why":"Showing up as the friend she invited respects the no she already gave."},{"prompt":"Later, one of Meher's friends asks if you two ever dated. What do you say?","options":[{"text":"That she wasn't ready yet, but you're waiting","then":"The friend raises an eyebrow and repeats it to Meher later."},{"text":"That you went on one date and are friends now","then":"The friend nods and moves on to asking about your course.","best":true},{"text":"That she missed out, if you're honest","then":"The friend laughs awkwardly and finds someone else to talk to."},{"text":"Something vague, so they keep wondering","then":"The friend starts guessing out loud. Meher overhears."}],"why":"Describing it the way it was respects her no, even in small talk."}],"debrief":"A no stands even when someone's still warm. Don't read kindness as a maybe.","relearn":"Kindness after a no isn't a maybe; let the no stand."},
  {"id":"sr-915","cat":"date-with-respect","type":"branch","persona":"Deepak","source":"honesty","hook":"You're nervous before a first date with Anjali and tempted to oversell yourself.","steps":[{"prompt":"She asks about your work. You study and do shifts at a phone shop. What do you say?","options":[{"text":"Say you're in tech sales, which sounds bigger","then":"Anjali asks which company. You change the subject fast."},{"text":"Invent a startup job to seem more impressive","then":"Anjali is impressed and asks for details. You make up more."},{"text":"Tell her about your studies and the shop shifts","then":"Anjali lights up. \"My cousin runs a shop! Are weekends chaos?\"","best":true},{"text":"Mention college and skip the shop entirely","then":"The chat moves on. You feel a small tug of having hidden something."}],"why":"Honest and ordinary beats an invented highlight reel. It gives her the real you to like."},{"prompt":"She suggests a pricey café for your next date, and money's tight this month. What do you do?","options":[{"text":"Agree, and skip meals this week to afford it","then":"The coffee is good. You're hungry and a bit resentful all week."},{"text":"Make up an excuse about being busy that day","then":"Anjali suggests another day at the same café. The problem hasn't moved."},{"text":"Agree, and hope she offers to split","then":"She doesn't. You pay, then check your balance in the washroom."},{"text":"Say you'd prefer somewhere cheaper this month","then":"Anjali shrugs. \"Chai stall near my college? It's better anyway.\"","best":true}],"why":"Being honest about money early saves you pretending. Anyone worth dating will adjust."},{"prompt":"Later, Anjali's friend asks where you study, and you feel a flash of shame. What do you do?","options":[{"text":"Name a more famous college nearby","then":"The friend knows someone there and starts asking questions."},{"text":"Laugh and change the subject","then":"The friend notices, and the moment gets a little awkward."},{"text":"Name your college plainly and ask about hers","then":"The friend says her brother studied there. The chat carries on.","best":true},{"text":"Apologise that it's not a big-name place","then":"The friend says it doesn't matter. You feel small all evening anyway."}],"why":"Where you study is part of your story, not something to hide or apologise for."}],"debrief":"Showing up honestly, even nervous, respects them more than a sales pitch.","relearn":"Be honest about who you are; don't sell a fake highlight reel."},
  {"id":"sr-916","cat":"date-with-respect","type":"role-play","persona":"any","source":"voicing pace","hook":"Your date with Karan is lovely, and you like him. You'd just like the physical side to stay slow.","setup":"On the walk back, he takes your hand, then pauses.","steps":[{"prompt":"Karan asks: \"Is this okay? I've wanted to do that all evening.\"","options":[{"text":"\"Ha. Sorry, I'm just not used to this.\"","then":"Karan smiles, unsure. \"Is that a yes, or a not yet?\""},{"text":"\"I like this. Can we keep tonight to just this?\"","then":"Karan smiles. \"Of course. Slow's good. I'm having a great time.\"","best":true},{"text":"\"Totally. I don't want you thinking I'm boring.\"","then":"Karan laughs. \"You're not boring.\" He has no idea you wanted slow."},{"text":"\"Ugh. Do you have to be this clingy?\"","then":"Karan lets go at once. \"Okay. Sorry.\" The walk goes quiet."}],"why":"Naming your pace warmly and plainly is enough. A good date welcomes it."},{"prompt":"Later, Karan asks: \"How do I know what's okay for you, as we go?\"","options":[{"text":"\"Just don't ask. It kind of kills the mood.\"","then":"Karan looks unsure. \"I'd still rather check.\""},{"text":"\"Sorry. I'm weird about all this stuff.\"","then":"\"You're not weird,\" Karan says. You still feel you have to explain yourself."},{"text":"\"Keep asking. I'll tell you honestly.\"","then":"\"Deal,\" Karan says. \"That's easy.\"","best":true},{"text":"\"Can we just not talk about it, okay?\"","then":"Karan nods, and the rest of the walk feels careful."}],"why":"Welcoming his check-ins, and promising to speak up, keeps consent a two-way habit."},{"prompt":"A few days later, Karan texts: \"Want to come over to mine on Friday?\"","options":[{"text":"\"Let me check. I might be busy that day.\"","then":"\"Cool, let me know!\" he replies, and waits all week."},{"text":"\"Only if you swear nothing will happen.\"","then":"\"Uh, okay?\" Karan replies, unsure what he's agreeing to."},{"text":"\"Why? So you can try your luck?\"","then":"\"Wow. Okay,\" he replies, and the chat goes cold."},{"text":"\"I'd love to see you. Maybe a café for now?\"","then":"\"A café works,\" Karan replies. \"I know a place with great cold coffee.\"","best":true}],"why":"Suggesting a plan that fits your pace keeps it honest and keeps the door open."},{"prompt":"Your friend Rhea asks: \"Won't he lose interest if you keep it this slow?\"","options":[{"text":"\"If slow puts him off, I'd rather know now.\"","then":"Rhea nods slowly. \"Yeah. I'd want to know too.\"","best":true},{"text":"\"Maybe. I'll make it up to him next time.\"","then":"Rhea frowns. \"Make up for what, exactly?\""},{"text":"\"Probably. I'm just too uptight.\"","then":"Rhea shakes her head, but the word stays with you."},{"text":"\"I'll drop hints next time, so it's less awkward.\"","then":"Rhea shrugs. \"And if he misses them?\""}],"why":"Your pace is never something you owe anyone. Wanting slow is never a fault."}],"relearn":"You can name your pace warmly; a good date welcomes it."},
  {"id":"sr-917","cat":"date-with-respect","type":"role-play","persona":"any","source":"receiving rejection","hook":"Your first date with Nandini is ending, and she's gone a little quiet.","setup":"You're waiting with her for her auto outside the café.","steps":[{"prompt":"Nandini says: \"You're really nice. I just didn't feel a spark.\"","options":[{"text":"\"Wow, after I paid for everything tonight?\"","then":"Nandini stiffens and pulls out her phone. \"I'll send you my half.\""},{"text":"\"Are you sure? Give it one more date.\"","then":"\"I'm sure,\" she says, more firmly. The auto can't come fast enough."},{"text":"\"Thanks for being straight with me. No hard feelings.\"","then":"Nandini smiles, relieved. \"Thank you. That's really decent of you.\"","best":true},{"text":"\"Okay. Can I ask what I did wrong?\"","then":"\"Nothing,\" she says, a bit uncomfortable. \"It's just a feeling.\""}],"why":"Taking a no graciously respects her honesty and lets you both leave feeling okay."},{"prompt":"Your friend Arjun asks: \"So? When's date two?\"","options":[{"text":"\"She's playing hard to get. Watch.\"","then":"Arjun whoops. You feel a plan forming that ignores what she said."},{"text":"\"She was pretty boring anyway, to be honest.\"","then":"Arjun laughs. You feel a bit smaller for saying it."},{"text":"\"I must have messed it up somehow.\"","then":"Arjun tries to cheer you up, but the doubt stays."},{"text":"\"No date two. Not a match, and that's fine.\"","then":"Arjun shrugs. \"Her loss. Want to get biryani?\"","best":true}],"why":"Saying it plainly, without spin or blame, helps a no settle."},{"prompt":"A week later, Nandini messages: \"Hey! Loved that song you told me about.\"","options":[{"text":"\"Does this mean you changed your mind?\"","then":"\"Oh, no, sorry,\" she replies. \"I just wanted to say thanks.\""},{"text":"\"Glad you liked it! Hope your week's good.\"","then":"\"It is!\" she replies. The chat stays light and ends there.","best":true},{"text":"\"Wow, so now you want to talk?\"","then":"She doesn't reply."},{"text":"\"Thanks. Want to try that date again?\"","then":"\"I meant it as friends,\" she replies gently."}],"why":"A friendly message after a no is just friendly. Keeping it light respects her answer."},{"prompt":"Months later, at a friend's party, Nandini says: \"Hey! Good to see you.\"","options":[{"text":"\"Oh. Hi. I didn't see you there.\"","then":"Nandini's smile falters. She drifts back to her friends."},{"text":"\"Still single, then? Just asking.\"","then":"Nandini laughs awkwardly. \"Wow. Okay.\""},{"text":"\"Ever think about that second date?\"","then":"Nandini smiles politely. \"Not really. But it's nice to see you.\""},{"text":"\"You too! How've you been?\"","then":"Nandini grins. \"Good! New job, new flat. You?\"","best":true}],"why":"Being easy and friendly after a no shows it never stopped you being decent."}],"relearn":"Take a no gracefully; gratitude beats guilt-tripping."},
  {"id":"sr-918","cat":"date-with-respect","type":"role-play","persona":"any","source":"giving rejection","hook":"You enjoyed meeting Yusuf, but you felt no romantic spark.","setup":"Two days later, he calls instead of texting.","steps":[{"prompt":"Yusuf asks: \"So, when can I see you again?\"","options":[{"text":"\"Yeah, let's totally do this again sometime soon!\"","then":"\"Great! Friday?\" Yusuf says, already planning."},{"text":"\"Let me check my calendar and I'll text you.\"","then":"\"Sure,\" he says. \"I'll keep Friday free just in case.\""},{"text":"\"I had a nice time, but I didn't feel a spark.\"","then":"A short pause. \"Ah. Okay. Thanks for telling me straight.\"","best":true},{"text":"\"Honestly? You're just not really my type.\"","then":"A pause. \"Oh. Okay,\" Yusuf says quietly."}],"why":"Kind and clear spares him hope. Vague or blunt makes it harder for both of you."},{"prompt":"That evening, your cousin Zainab says: \"Yusuf sounds so sweet. Don't let him slip away!\"","options":[{"text":"\"Fine. One more date, just to be fair.\"","then":"Zainab cheers. You dread the date already."},{"text":"\"He is sweet. It's just not a romantic match.\"","then":"Zainab sighs. \"Fine. Your call.\"","best":true},{"text":"\"Stay out of my love life, Zainab.\"","then":"Zainab looks hurt. \"I was only saying.\""},{"text":"\"Maybe you're right. Am I too picky?\"","then":"Zainab nods eagerly. The doubt follows you to bed."}],"why":"No spark is reason enough. You don't need to be talked out of it."},{"prompt":"A week later, Yusuf texts: \"No pressure, but would you like to grab coffee?\"","options":[{"text":"\"Maybe! Let's see how this month goes for me.\"","then":"\"Sure!\" Yusuf replies, and marks his calendar."},{"text":"\"Sorry, I'm super busy these days. Next month?\"","then":"\"Next month it is,\" he replies, sounding hopeful."},{"text":"\"Kind of you. But it's not a match for me.\"","then":"\"Understood,\" Yusuf replies. \"Take care.\"","best":true},{"text":"\"Why do you keep on messaging me about this?\"","then":"Yusuf goes quiet. \"Sorry. I just thought I'd ask.\""}],"why":"Saying it clearly, and kindly, is fairer than another maybe."}],"relearn":"Give a no kindly and clearly; don't false-promise."},
  {"id":"sr-919","cat":"date-with-respect","type":"role-play","persona":"any","source":"voicing a boundary","hook":"At the end of a lovely evening, Vikram leans in for a kiss. You're not ready for that yet.","setup":"You're standing by your building gate.","steps":[{"prompt":"Vikram pauses and asks: \"Is this okay?\"","options":[{"text":"\"Sorry. I feel like I've led you on all night.\"","then":"Vikram looks confused. \"Led me on? No. It's fine.\""},{"text":"\"My parents might see us from the balcony.\"","then":"Vikram glances up, then back at you. \"I don't think it's the balcony. That's okay.\""},{"text":"\"I'm really enjoying you. I'm just not there yet.\"","then":"Vikram smiles and steps back. \"That's completely okay. Thanks for telling me.\"","best":true},{"text":"\"Not now. You totally rushed that.\"","then":"Vikram steps back. \"Sorry. I did ask, though.\""}],"why":"Not yet is a full answer. Needing to go slower is never a fault to apologise for."},{"prompt":"Vikram asks: \"How will I know when you're ready?\"","options":[{"text":"\"You'll just know. Read the vibe.\"","then":"Vikram frowns. \"I'm not great at vibes. I'd rather hear it.\""},{"text":"\"I'll tell you. And you can always ask.\"","then":"\"Deal,\" Vikram says. \"I like that.\"","best":true},{"text":"\"Soon, I promise. Just give me a week.\"","then":"\"Okay,\" he says. You feel a clock start ticking."},{"text":"\"Once you've taken me out a few more times.\"","then":"Vikram laughs awkwardly. \"It's not a trade, though.\""}],"why":"Promising to tell him, and inviting him to ask, keeps consent a conversation."},{"prompt":"The next morning, your friend Shreya texts: \"You didn't kiss him? But he's so cute!\"","options":[{"text":"\"I know. I'll make it up to him next time.\"","then":"\"Next time, then!\" Shreya replies. You feel a nudge you didn't ask for."},{"text":"\"Maybe something's wrong with me.\"","then":"\"What? No,\" Shreya replies, but you keep wondering."},{"text":"\"I wasn't ready, and that's enough of a reason.\"","then":"\"Fair,\" Shreya replies. \"Did you have fun, at least?\"","best":true},{"text":"\"He probably thinks I'm not interested now.\"","then":"\"Did you tell him you were?\" Shreya asks."}],"why":"Not being ready is a complete reason. It's never something to fix or make up for."}],"relearn":"You can pause the pace warmly; your 'not yet' is enough."},
  {"id":"sr-920","cat":"date-with-respect","type":"role-play","persona":"any","source":"matching pace","hook":"You've been on two dates with Zeenat, and you really like her.","setup":"You're sharing a plate of momos after class.","steps":[{"prompt":"Zeenat says: \"I'd like to take things slow. I like getting to know someone properly first.\"","options":[{"text":"\"Sure, but you'll come around quite fast, right?\"","then":"Zeenat's smile flickers. \"I don't know. That's kind of the point.\""},{"text":"\"Slow is fine. How slow are we talking?\"","then":"Zeenat laughs uneasily. \"I didn't bring a timetable.\""},{"text":"\"Oh. Did I do something to put you off?\"","then":"\"No,\" she says. \"This isn't about you. It's just me.\""},{"text":"\"That works. Let's go at a pace that suits us both.\"","then":"Zeenat relaxes. \"Really? Thank you. That makes this easier.\"","best":true}],"why":"Welcoming her pace for real, not bargaining it down, makes it safe to say."},{"prompt":"Zeenat asks: \"Is it okay if we just text for a bit before the next date?\"","options":[{"text":"\"Texting's boring, though. Let's just meet.\"","then":"Zeenat hesitates. \"Maybe in a week or so?\""},{"text":"\"Of course. Text me whenever you like.\"","then":"She sends you a meme within the hour.","best":true},{"text":"\"Fine. I'll wait for you to message first.\"","then":"Zeenat messages, then wonders why you're so quiet."},{"text":"\"Sure. But not for too long, okay?\"","then":"\"Okay,\" she says, sounding less sure."}],"why":"Saying yes to her way, with no strings, shows her slow is really okay."},{"prompt":"A week later, Zeenat asks: \"Want to meet for chai on Sunday afternoon?\"","options":[{"text":"\"Chai? Can't we do dinner and a movie?\"","then":"Zeenat pauses. \"Maybe later. Chai's what I'd like for now.\""},{"text":"\"Finally! I thought you'd never ask.\"","then":"Zeenat laughs, but you catch a small wince."},{"text":"\"I'd love that. Sunday works.\"","then":"\"Great,\" she says. \"The place near the library?\"","best":true},{"text":"\"Sure. Should I read anything into it?\"","then":"\"It's just chai,\" she says, a little puzzled."}],"why":"Meeting her plan warmly, without upgrading it, keeps her pace hers."},{"prompt":"Later, your friend Vivek says: \"Slow means she's not that into you, yaar.\"","options":[{"text":"\"You think? Maybe I should push a bit.\"","then":"Vivek nods. \"Show some confidence.\" It doesn't feel like confidence."},{"text":"\"Yeah. Maybe I'll give her a deadline.\"","then":"Vivek laughs. \"Now you're talking.\" You feel uneasy."},{"text":"\"Honestly, I don't know what she wants.\"","then":"Vivek shrugs. The doubt follows you to Sunday."},{"text":"\"Slow means slow. That's her call.\"","then":"Vivek raises his hands. \"Okay, okay. Fair enough.\"","best":true}],"why":"Her pace isn't a signal to decode. Taking her at her word keeps it respectful."}],"relearn":"Welcome a slower pace for real; don't bargain it down."},
  {"id":"sr-921","cat":"date-with-respect","type":"role-play","persona":"any","source":"consent check-in","hook":"On a second date at a bar with Tanya, you're thinking of ordering shots.","setup":"The bartender is looking your way.","steps":[{"prompt":"Tanya asks: \"What are you having?\"","options":[{"text":"\"Shots! Come on, one round won't kill you.\"","then":"Tanya laughs. \"Maybe just one.\" She leaves hers half full."},{"text":"\"I've already ordered us both shots.\"","then":"Tanya blinks. \"Oh. Okay.\" Later, she quietly pushes hers aside."},{"text":"\"Shots, maybe? Or soft drinks. Your call.\"","then":"Tanya smiles. \"Fresh lime soda for me. Early class tomorrow.\"","best":true},{"text":"\"Let's just get shots. You can skip yours.\"","then":"Tanya shrugs and takes one. Saying no now feels awkward to her."}],"why":"Asking, and leaving it to her, makes a no as easy to say as a yes."},{"prompt":"Tanya asks: \"You don't mind if I skip drinks for the rest of tonight?\"","options":[{"text":"\"It's a bit boring, but okay, I guess.\"","then":"Tanya's smile slips. \"Sorry to be boring.\""},{"text":"\"Sure, but you'll have one later, right?\"","then":"\"We'll see,\" she says, a little guarded."},{"text":"\"Not at all. Lime soda sounds good to me too.\"","then":"\"Two, then,\" she says, and the evening relaxes.","best":true},{"text":"\"No, but everyone else here is drinking.\"","then":"Tanya glances around. \"I didn't realise that mattered.\""}],"why":"Backing her choice, with no but attached, keeps the pressure off."},{"prompt":"Later, Tanya asks: \"Bill, or one more round of something?\"","options":[{"text":"\"One more! The night's still young.\"","then":"\"Oh. Okay,\" Tanya says, checking the time."},{"text":"\"Your call. I'm happy either way.\"","then":"\"Bill,\" she says. \"But let's do this again.\"","best":true},{"text":"\"Let's do shots to end it properly.\"","then":"Tanya hesitates. \"I'd rather not, honestly.\""},{"text":"\"Bill, I guess. You're no fun tonight.\"","then":"Tanya laughs it off, but she's quiet on the walk out."}],"why":"Leaving the call to her, and meaning it, is what a check-in looks like."},{"prompt":"Outside, Tanya says: \"I don't really drink, you know. Is that a problem for us?\"","options":[{"text":"\"Ha. You owe me a proper night out, though.\"","then":"Tanya laughs, but it sounds a bit forced."},{"text":"\"Nah. You'd have more fun with a drink, though.\"","then":"Tanya's smile fades. \"I really wouldn't.\""},{"text":"\"No worries. Next time, though, shots!\"","then":"Tanya's smile wavers. \"We'll see.\""},{"text":"\"Not at all. It's always your call.\"","then":"Tanya smiles. \"Good. Same time next week?\"","best":true}],"why":"Saying it's her call, with nothing owed later, is what makes it genuine."}],"relearn":"Check in on drinks and leave it their call; don't push."},
  {"id":"sr-922","cat":"date-with-respect","type":"role-play","persona":"Aarti","source":"support","hook":"Your friend Shruti said no to a guy after one date. His reply was cruel, and she's shaken.","setup":"She calls you near midnight, right after reading his message.","steps":[{"prompt":"Shruti says: \"He called me a tease. Maybe I gave him the wrong idea.\"","options":[{"text":"\"Hmm. Did you flirt with him a lot?\"","then":"Shruti goes quiet. \"I don't know. Maybe?\" She sounds worse."},{"text":"\"Forget him. There are way better guys out there.\"","then":"\"I know,\" she says flatly. \"It's just stuck in my head.\""},{"text":"\"Send me his number. I'll deal with him.\"","then":"\"Please don't,\" Shruti says. \"I don't want it bigger.\""},{"text":"\"That's on him, not you. You're allowed to say no.\"","then":"Shruti breathes out. \"Okay. I needed to hear that.\"","best":true}],"why":"His cruelty is on him, never on her. Saying so clearly is the first help."},{"prompt":"Shruti asks: \"Should I reply and explain myself?\"","options":[{"text":"\"Yes. Tell him exactly what you think.\"","then":"\"He'll just get nastier,\" she says, unsure."},{"text":"\"You don't owe him a reply. Want to block and report?\"","then":"\"Block, yes,\" she says. \"Can you stay on while I report?\"","best":true},{"text":"\"You have to report him to the police tonight, okay?\"","then":"Shruti goes quiet. \"I can't think about that right now.\""},{"text":"\"Maybe just say sorry so he calms down.\"","then":"\"Sorry for what?\" she asks, sounding smaller."}],"why":"She owes him nothing. Offering to block and report, at her pace, keeps her in charge."},{"prompt":"A few days later, Shruti says: \"I still jump every time my phone buzzes. I can't shake it.\"","options":[{"text":"\"Just switch your phone off. It's that simple.\"","then":"\"It's not that simple,\" she says, hurt."},{"text":"\"He's probably forgotten you already.\"","then":"\"Maybe,\" she says. It doesn't seem to help."},{"text":"\"That sounds exhausting. Want me to come over?\"","then":"\"Yes please,\" she says. \"Bring chips.\"","best":true},{"text":"\"This is why I don't trust dating apps.\"","then":"Shruti goes quiet. \"So it's my fault for using one?\""}],"why":"Staying close, without judging or fixing, helps her feel safe again. None of it is her fault."}],"relearn":"An abusive reaction to a no is on the sender, never the person who said no."},
  {"id":"sr-923","cat":"date-with-respect","type":"role-play","persona":"any","source":"honesty","hook":"Halfway through dinner, you realise you're not feeling it with Rahul, though he's genuinely lovely.","setup":"He's just ordered a dessert to share.","steps":[{"prompt":"Rahul asks: \"So, would you want to do this again sometime?\"","options":[{"text":"\"Definitely! Let's plan something for next week.\"","then":"Rahul beams and starts suggesting places."},{"text":"\"Let me check my week and I'll text you.\"","then":"\"Perfect,\" he says. \"I'll wait for your text.\""},{"text":"\"I've enjoyed this, but I'm not feeling a match.\"","then":"Rahul nods slowly. \"Ah. Okay. Thanks for saying it to my face.\"","best":true},{"text":"\"Honestly, I knew in the first ten minutes.\"","then":"Rahul's smile drops. \"Oh. Right. Okay.\""}],"why":"Honest but kind, in the moment, spares him waiting on a text that won't come."},{"prompt":"The next day, Rahul texts: \"Thanks for last night. Hope you got home okay.\"","options":[{"text":"\"Home safe! Let's do it again soon.\"","then":"\"Yes!\" Rahul replies. \"Saturday?\""},{"text":"\"Home safe. Busy week ahead, so I'll be quiet.\"","then":"\"No worries! Ping me when you're free,\" he replies, hopeful."},{"text":"\"Home safe. Not a match for me, but take care.\"","then":"\"Thanks for being clear,\" he replies. \"Take care too.\"","best":true},{"text":"\"Home. You're sweet, but you talk way too much.\"","then":"Rahul replies with a single \"ok\"."}],"why":"A clear, kind line beats a slow fade. It lets him move on."},{"prompt":"A week later, Rahul texts: \"A friend's band is playing Friday. Want to come along?\"","options":[{"text":"\"Maybe! I'll see how the week goes.\"","then":"\"Great!\" he replies, and puts your name on the list."},{"text":"\"Thanks, but I'll pass. Have a great gig!\"","then":"\"No worries,\" he replies. \"Take care.\"","best":true},{"text":"\"Seriously? Can you not take a hint?\"","then":"Rahul goes quiet. \"Sorry. I thought we'd left it friendly.\""},{"text":"\"Sure! I'll try my best to make it there.\"","then":"Rahul tells his friends you're coming. Friday arrives, and you don't."}],"why":"Staying clear and kind, every time, lets the no do its job."}],"relearn":"Honest-but-kind beats faking interest and ghosting later."},
  {"id":"sr-924","cat":"date-with-respect","type":"role-play","persona":"any","source":"reading energy","hook":"It's late in your first date with Anika, and you'd happily stay out longer.","setup":"She glances at the time on her phone.","steps":[{"prompt":"Anika says: \"Sorry, I'm fading. It's been such a long day.\"","options":[{"text":"\"Just stay a bit longer. The night's young!\"","then":"\"Maybe twenty minutes,\" she says, eyes drifting to the door."},{"text":"\"Wow, am I really that boring to you?\"","then":"Anika laughs awkwardly. \"No! Just tired.\" Now she's reassuring you."},{"text":"\"You look wiped. Let's wrap up. I had fun.\"","then":"Anika brightens. \"Thank you. I really did have a good time.\"","best":true},{"text":"\"One more coffee will wake you right up!\"","then":"Anika smiles weakly. \"I'll be up all night if I do.\""}],"why":"Offering the out first means she doesn't have to ask for it."},{"prompt":"Anika asks: \"Can I book my cab from here?\"","options":[{"text":"\"Cancel that. I'll drop you home myself.\"","then":"Anika hesitates. \"I'd rather take the cab, honestly.\""},{"text":"\"Sure. Text me the whole ride so I know.\"","then":"\"Okay,\" she says, a little surprised by the instructions."},{"text":"\"Already? It's barely ten o'clock.\"","then":"Anika shrugs. \"Long day,\" she says, booking it anyway."},{"text":"\"Of course. Want me to wait till it comes?\"","then":"\"That'd be nice,\" she says. The cab arrives in five minutes.","best":true}],"why":"Backing her own way home, and offering company, respects her plan."},{"prompt":"The next day, Anika texts: \"Sorry again for fading out on you last night!\"","options":[{"text":"\"No need to apologise. Hope you slept well!\"","then":"\"So well,\" she replies. \"Round two when I'm awake?\"","best":true},{"text":"\"It's fine. Just don't make it a habit.\"","then":"\"Noted,\" she replies, and the chat cools."},{"text":"\"You owe me a full evening now, you know.\"","then":"\"Haha, okay,\" she replies. It sounds like a debt."},{"text":"\"Honestly, I thought you were bored of me.\"","then":"Anika sends a long reassurance. It's more work than she needed today."}],"why":"She doesn't owe an apology for being tired. Letting it go keeps things warm."},{"prompt":"Your friend Omkar says: \"She left at ten? Sounds like she wasn't into you.\"","options":[{"text":"\"Yeah, maybe I bored her to death.\"","then":"Omkar laughs. You don't."},{"text":"\"Next time I won't let her leave so early.\"","then":"Omkar grins. \"That's the spirit.\" It sits badly with you."},{"text":"\"She was tired. That's all it was.\"","then":"Omkar shrugs. \"Fair. Some weeks are like that.\"","best":true},{"text":"\"I'll ask her straight out if she likes me.\"","then":"Omkar winces. \"After one tired night? Bit much.\""}],"why":"Tiredness is just tiredness. Not reading rejection into it keeps things easy."}],"relearn":"Offer an easy out when they're tired; don't push them to stay."},
  {"id":"sr-925","cat":"date-with-respect","type":"role-play","persona":"any","source":"honest intentions","hook":"You like hanging out with Pranav, but you're not looking for anything serious right now.","setup":"He's walking you to the metro after a movie.","steps":[{"prompt":"Pranav says: \"I'm really starting to like you, you know.\"","options":[{"text":"\"Me too! Let's just see where it all goes, yeah?\"","then":"Pranav grins. \"I was hoping you'd say that.\""},{"text":"\"Let's not put any labels on it, okay?\"","then":"\"Sure,\" he says, clearly picturing something more."},{"text":"\"Whoa. Slow down. It's only been a month.\"","then":"Pranav looks embarrassed. \"Sorry. I just meant I like hanging out.\""},{"text":"\"I like you too. But I'm not after anything serious.\"","then":"Pranav slows down. \"Oh. Okay. I'm glad you told me.\"","best":true}],"why":"Naming what you want early lets him choose with the full picture."},{"prompt":"A few days later, Pranav asks: \"Would you want to meet my friends this weekend?\"","options":[{"text":"\"Of course! Can't wait to meet everyone.\"","then":"Pranav introduces you as someone special. It doesn't feel like you."},{"text":"\"Sure. Just so you know, I'm keeping it casual.\"","then":"\"Got it,\" Pranav says. \"Come anyway. They're fun.\"","best":true},{"text":"\"Maybe. I'll let you know on Friday, okay?\"","then":"Friday comes, and you still don't know what to say."},{"text":"\"Why? Are you trying to make this official?\"","then":"Pranav looks stung. \"No. I just thought you'd like them.\""}],"why":"Being clear, simply and kindly, keeps him from filling in the blanks."},{"prompt":"A month on, Pranav says: \"I think I want more than casual.\"","options":[{"text":"\"Maybe I'll change my mind. Let's see.\"","then":"Pranav lights up. \"Really? Okay.\" You're not sure you meant it."},{"text":"\"You knew exactly what this was from the start.\"","then":"Pranav nods stiffly. \"I did. I'm still allowed to feel things.\""},{"text":"\"Thanks for saying it. I don't want more, though.\"","then":"Pranav is quiet a moment. \"Okay. I needed to hear it straight.\"","best":true},{"text":"\"Let's just not talk about it for now.\"","then":"Pranav agrees, but it hangs over every date after."}],"why":"When you want different things, saying so kindly lets both of you choose what's next."},{"prompt":"Your friend Ria asks: \"Why not just keep it going? He'll stick around anyway.\"","options":[{"text":"\"True. Easier not to rock the boat.\"","then":"Ria nods. The weight of it stays with you all week."},{"text":"\"Not if we want different things.\"","then":"Ria nods slowly. \"Yeah. I'd want to know too.\"","best":true},{"text":"\"I'll let him down slowly over a few months.\"","then":"Ria shrugs. \"Months is a long time to wait for a no.\""},{"text":"\"He'll get over it. People always do.\"","then":"Ria laughs, but you feel uneasy."}],"why":"Keeping someone around on hope isn't fair to him. Letting him choose with the truth is."}],"relearn":"Name what you want kindly and early; don't let them assume."},
  {"id":"sr-926","cat":"date-with-respect","type":"role-play","persona":"Zoya","source":"respecting privacy","hook":"You and your partner Ira just got back from your first trip together.","setup":"You're scrolling through the photos, picking favourites.","steps":[{"prompt":"Ira says: \"Please don't post any of me. Not yet.\"","options":[{"text":"\"But I want everyone to know. Just one post?\"","then":"Ira's jaw tightens. \"I said not yet.\""},{"text":"\"Of course. No posts until you're comfortable.\"","then":"Ira relaxes. \"Thank you. It means a lot.\"","best":true},{"text":"\"Okay. I'll post it to close friends only.\"","then":"Ira goes still. \"Close friends still talk.\""},{"text":"\"Are you embarrassed of me or something?\"","then":"\"No,\" Ira says quietly. \"It's not about you.\""}],"why":"Whether and when to go public is hers to set. Saying yes, fully, respects it."},{"prompt":"A week later, your friend Kabir asks: \"Why don't you ever post Ira? Hiding something?\"","options":[{"text":"\"Her family doesn't know about us yet.\"","then":"Kabir's eyebrows go up. Now he knows something that was Ira's to share."},{"text":"\"Honestly, it's her. She's weird about it.\"","then":"Kabir laughs. You picture Ira hearing that."},{"text":"\"We're just keeping it private for now.\"","then":"Kabir shrugs. \"Fair. Private is good.\"","best":true},{"text":"\"Ugh, don't ask. It's a whole thing.\"","then":"Kabir leans in. \"Now I have to know.\""}],"why":"Her reasons are hers to share. A simple line protects her without telling her story."},{"prompt":"Later, Ira asks: \"Does it bother you that we can't post?\"","options":[{"text":"\"Not at all. It never even crosses my mind.\"","then":"Ira smiles, but you feel the gap between that and the truth."},{"text":"\"Yes, a bit. How much longer do you think it'll be?\"","then":"Ira's face falls. \"I don't know yet.\""},{"text":"\"A little, sometimes. But your comfort comes first.\"","then":"Ira takes your hand. \"Thank you for being honest, and for waiting.\"","best":true},{"text":"\"It's fine. You owe me one big favour, though.\"","then":"Ira laughs uneasily. \"Owe you what?\""}],"why":"Being honest about your feelings while keeping her timeline first is real support."},{"prompt":"Months later, Ira says: \"I think I'm ready to post one photo of us.\"","options":[{"text":"\"Finally! Let me post ten right now.\"","then":"Ira laughs nervously. \"Maybe start with one?\""},{"text":"\"Are you sure? What if your family sees?\"","then":"Ira's confidence wobbles. \"I thought I was sure.\""},{"text":"\"Let's make it a big announcement post!\"","then":"Ira hesitates. \"I meant something small.\""},{"text":"\"Big step. You pick the photo and caption.\"","then":"Ira grins and scrolls for ages. She picks the one from the beach.","best":true}],"why":"When she's ready, letting her lead how it's shared keeps it hers."}],"relearn":"Whether and when to go public is theirs to set; respect the privacy ask."},
  {"id":"sr-927","cat":"date-with-respect","type":"role-play","persona":"Rohan","source":"surviving rejection","hook":"You've been on three dates with Diya, and you were hoping for a fourth.","setup":"You're on the bus home when her message lands.","steps":[{"prompt":"Diya writes: \"I had fun, but I don't think we're a match.\"","options":[{"text":"\"Your loss. You weren't that great anyway.\"","then":"Diya doesn't reply. A minute later, the chat is gone."},{"text":"\"Can I at least know what I did wrong?\"","then":"Diya replies, \"Nothing you did. It's just not there.\""},{"text":"\"All good. Thanks for letting me know.\"","then":"Diya replies with a smiley. \"Thanks for being so decent about it.\"","best":true},{"text":"\"Wow. After three dates? Okay then.\"","then":"The message sits on read. No reply comes."}],"why":"A graceful line is the strong one. A no doesn't earn an insult."},{"prompt":"Your friend Dev texts: \"Bro, just unmatch and roast her in the group chat.\"","options":[{"text":"\"Yeah. She deserves it after that.\"","then":"Dev sends laughing emojis. You feel worse, not better."},{"text":"\"Maybe. Let me write something cutting first.\"","then":"You draft it three times. It keeps you stuck on her all evening."},{"text":"\"Nah. She was honest. That's fair.\"","then":"Dev sends a shrug emoji. \"Your call, man.\"","best":true},{"text":"\"I don't care anyway. Plenty more out there.\"","then":"Dev agrees. The sting you're not admitting stays put."}],"why":"Taking a no without trashing her keeps your dignity and hers."},{"prompt":"That night, your flatmate Joseph asks: \"You okay? You've been quiet all evening.\"","options":[{"text":"\"I'm fine. People on apps are all fake anyway.\"","then":"Joseph frowns. \"All of them?\" You don't have an answer."},{"text":"\"Totally fine. Why wouldn't I be?\"","then":"Joseph shrugs and goes back to his game."},{"text":"\"Not really. Got turned down, and it stings.\"","then":"Joseph sits down. \"Oof. That sucks. Want to get food?\"","best":true},{"text":"\"I'm just not good enough for anyone.\"","then":"\"That's not true,\" he says. You don't believe him yet."}],"why":"Admitting it stings is how it starts to pass. Rejection is normal and survivable."},{"prompt":"A week later, Dev says: \"Saw Diya's story with some guy. She moved on fast.\"","options":[{"text":"\"Show me. I want to see who he is.\"","then":"You stare at the photo far too long."},{"text":"\"Told you. She was never serious.\"","then":"Dev nods. The bitterness grows a little."},{"text":"\"Maybe I should message her again.\"","then":"Dev grins. \"Do it.\" You type and delete three times."},{"text":"\"Good for her. I'm doing fine too.\"","then":"Dev shrugs. \"Fair enough. Cricket tonight?\"","best":true}],"why":"Her life after a no isn't yours to track. Letting it go frees you up."},{"prompt":"A new match, Aisha, asks: \"So, what are you looking for on here?\"","options":[{"text":"\"Honestly, someone less fake than my last match.\"","then":"Aisha raises an eyebrow. \"Yikes. Okay.\""},{"text":"\"Someone fun to get to know. No rush.\"","then":"\"Same,\" Aisha replies. \"Okay, first question: chai or coffee?\"","best":true},{"text":"\"Whatever. Apps are a game anyway.\"","then":"Aisha replies, \"Oh. Not for me.\" The chat stalls."},{"text":"\"Something serious, fast. I'm done wasting time.\"","then":"Aisha hesitates. \"That's a lot for a first chat.\""}],"why":"Starting fresh, without the last no in tow, gives a new match a fair chance."}],"relearn":"A no doesn't earn an insult; the graceful line is the strong one."},
  {"id":"sr-928","cat":"date-with-respect","type":"role-play","persona":"any","source":"planning together","hook":"You're planning tomorrow's date with Mehek and want to be sure it suits her too.","setup":"It's late, and her text lights up your phone.","steps":[{"prompt":"Mehek writes: \"So what's the plan for tomorrow?\"","options":[{"text":"\"I've booked us a fancy dinner. Be there at eight.\"","then":"\"Oh,\" she replies. \"I was hoping for something earlier, but okay.\""},{"text":"\"Daytime coffee? Or would something else suit you?\"","then":"\"Coffee's perfect,\" Mehek replies. \"Afternoon works best for me.\"","best":true},{"text":"\"Surprise! Just come to my place at seven.\"","then":"\"Your place?\" she replies. \"Could we meet somewhere public first?\""},{"text":"\"Anything you want. I'm easy either way.\"","then":"\"Okay,\" she replies. \"I'll figure it out, I guess.\""}],"why":"Offering a plan and asking what she'd prefer makes it a real two-way yes."},{"prompt":"Mehek adds: \"Just so you know, I have a family thing tomorrow evening. I can't stay long.\"","options":[{"text":"\"Can't you skip it? It's only our second date.\"","then":"\"Not really,\" Mehek replies. \"It's my cousin's engagement.\""},{"text":"\"Then what's even the point of meeting?\"","then":"\"Oh,\" she replies. \"Maybe another day is better, then?\""},{"text":"\"No problem. Let's pick a time around it.\"","then":"\"Thank you,\" she replies. \"Afternoon, then? Four o'clock?\"","best":true},{"text":"\"Sure. I'll just drop you there after.\"","then":"\"I'll take a cab. It's fine,\" she replies."}],"why":"Fitting the date around her plans shows you want her there, not just the date."},{"prompt":"After the date, Mehek texts: \"I'd like to see you again. Any ideas for next time?\"","options":[{"text":"\"Sure. I'll book something and surprise you.\"","then":"\"Okay,\" she replies. \"Just tell me the time early?\""},{"text":"\"Next time we do it my way, then.\"","then":"Mehek sends a laughing emoji, unsure what that means."},{"text":"\"Yes! I'll send a couple. You choose.\"","then":"\"Perfect,\" she replies. \"I like having options.\"","best":true},{"text":"\"You decide. I'm terrible at planning.\"","then":"\"Oh,\" she replies. \"I thought it'd be nice to take turns.\""}],"why":"Offering ideas and letting her weigh in keeps planning a two-way thing."}],"relearn":"Plan together and ask; a date isn't an order."},
  {"id":"sr-929","cat":"date-with-respect","type":"strike-rewrite","hook":"\"On a date, the consent rules loosen up.\"","myth":{"un":"On a date, the consent rules loosen up.","re":"Consent and respect apply on every date, app-met or not; nothing about a date changes them.","why":"A date is not an exception to consent."},"relearn":"Consent and respect apply on every date, app or not.","persona":"any","source":"consent travels"},
  {"id":"sr-930","cat":"date-with-respect","type":"strike-rewrite","hook":"\"If they rejected me, they owe me a full explanation.\"","myth":{"un":"If they rejected me, they owe me a full explanation.","re":"A no is complete on its own; no one owes a detailed reason for it.","why":"Demanding reasons turns a no into pressure."},"relearn":"A no is complete; no one owes a detailed reason for it.","persona":"Rohan","source":"rejection"},
  {"id":"sr-931","cat":"date-with-respect","type":"strike-rewrite","hook":"\"Buying the dinner means they owe me something after.\"","myth":{"un":"Buying the dinner means they owe me something after.","re":"Paying for a meal never buys consent or a second date; nobody owes anything for it.","why":"Generosity isn't a transaction for intimacy."},"relearn":"Paying for a date never means they owe you anything.","persona":"any","source":"no transaction"},
  {"id":"sr-932","cat":"date-with-respect","type":"strike-rewrite","hook":"\"Talking about boundaries kills the romance.\"","myth":{"un":"Talking about boundaries kills the romance.","re":"Talking openly about consent and boundaries is a green flag that makes intimacy better.","why":"Knowing what you both want removes guesswork, not romance."},"relearn":"Talking openly about consent and boundaries is a green flag.","persona":"any","source":"communication"},
  {"id":"sr-933","cat":"date-with-respect","type":"strike-rewrite","hook":"\"Playing hard to get and chasing is just how dating works.\"","myth":{"un":"Playing hard to get and chasing is just how dating works.","re":"Clear, mutual interest beats games; chasing someone who's pulling away is pressure, not romance.","why":"A real yes is freely given, not extracted by persistence."},"relearn":"Mutual clear interest beats games; chasing a pull-away is pressure.","persona":"Rohan","source":"no games"},
  {"id":"sr-934","cat":"date-with-respect","type":"strike-rewrite","hook":"\"If they say maybe, keep pushing till it's a yes.\"","myth":{"un":"If they say maybe, keep pushing till it's a yes.","re":"A maybe or a hesitation is not a yes; the respectful move is to ease off and let them decide.","why":"Pushing past hesitation overrides consent."},"relearn":"A maybe isn't a yes; ease off and let them decide.","persona":"any","source":"reading a maybe"},
  {"id":"sr-935","cat":"date-with-respect","type":"strike-rewrite","hook":"\"Ghosting after a meh date is kinder than an awkward message.\"","myth":{"un":"Ghosting after a meh date is kinder than an awkward message.","re":"A brief, kind 'no spark, take care' is basic decency; vanishing leaves someone guessing.","why":"Honesty runs both ways, even when it's a little awkward."},"relearn":"A brief kind sign-off beats ghosting after a date.","persona":"any","source":"no ghosting"},
  {"id":"sr-936","cat":"date-with-respect","type":"strike-rewrite","hook":"\"If I take it slow, they'll think I'm not interested.\"","myth":{"un":"If I take it slow, they'll think I'm not interested.","re":"Naming a slower pace shows respect and interest at once; a good date welcomes it.","why":"Pacing to comfort is a green flag, not a brush-off."},"relearn":"Naming a slower pace is respect; a good date welcomes it.","persona":"any","source":"voicing pace"},
  {"id":"sr-937","cat":"date-with-respect","type":"strike-rewrite","hook":"\"A few drinks in, you don't really need to check in anymore.\"","myth":{"un":"A few drinks in, you don't really need to check in anymore.","re":"Consent matters even more when drinks are involved; checking in and keeping each other clear-headed is the respectful move.","why":"Clouded judgement can't give a clear yes."},"relearn":"Keep checking in; drinks make a clear yes harder, not optional.","persona":"any","source":"consent and drinks"},
  {"id":"sr-938","cat":"date-with-respect","type":"strike-rewrite","hook":"\"Getting rejected means there's something wrong with me.\"","myth":{"un":"Getting rejected means there's something wrong with me.","re":"A no is usually just a mismatch of timing or chemistry, not a verdict on your worth.","why":"Rejection, given or received, is a normal, survivable part of dating."},"relearn":"A no is a mismatch, not a verdict on your worth.","persona":"Deepak","source":"rejection is normal"},
  {"id":"sr-939","cat":"date-with-respect","type":"reflect","hook":"Lensy: rejection, given or received, is survivable and part of dating. Take the sting off?","prompt":"What do you think?","options":["Yes","It's survivable","Part of dating"],"affirm":"Everyone gets and gives a no sometimes; handling it kindly is the real skill.","relearn":"Rejection, given or received, is a survivable, normal part of dating.","persona":"any","source":"rejection is normal"},
  {"id":"sr-940","cat":"date-with-respect","type":"reflect","hook":"Lensy: remembering the small thing they mentioned last time shows you were actually listening. Try it?","prompt":"What do you think?","options":["Yes","I'll remember","Worth doing"],"affirm":"Recalling a small detail tells someone they were heard; that lands more than any line.","relearn":"Remembering small details shows you were really listening.","persona":"any","source":"listening close"},
  {"id":"sr-941","cat":"date-with-respect","type":"reflect","hook":"Lensy: you get to set your own pace on a date, no matter what's 'expected'. Sit with that?","prompt":"What do you think?","options":["Yes","My pace","Good to know"],"affirm":"Your pace is yours to name; the right person moves with it, not against it.","relearn":"You set your own pace; a good date moves with it.","persona":"Ananya","source":"owning your pace"},
  {"id":"sr-942","cat":"date-with-respect","type":"reflect","hook":"Lensy: a no you give doesn't have to come with an essay of reasons. Feel okay about that?","prompt":"What do you think?","options":["Yes","No essay needed","Fair enough"],"affirm":"Your no is complete as it is; kind and brief is plenty.","relearn":"A no you give needs no detailed reasons; kind and brief is enough.","persona":"any","source":"giving a no"},
  {"id":"sr-943","cat":"date-with-respect","type":"reflect","hook":"Lensy: checking in on a date ('this okay?') is attractive, not awkward. Buy that?","prompt":"What do you think?","options":["Yes","It's attractive","I'll try it"],"affirm":"A quick check-in says you see them as a person; that's the good stuff.","relearn":"Checking in on a date is attractive, not awkward.","persona":"any","source":"checking in"},
  {"id":"sr-944","cat":"date-with-respect","type":"reflect","hook":"Lensy: leaving a date that doesn't feel right is always your call. Take that with you?","prompt":"What do you think?","options":["Yes","Always my call","Good to know"],"affirm":"You can end any date whenever you like; you never owe a reason to leave.","relearn":"You can leave a date whenever; you don't owe a reason.","persona":"Meena","source":"your call to leave"},
  {"id":"sr-945","cat":"date-with-respect","type":"reflect","hook":"Lensy: how someone handles your 'no' tells you a lot about them. Notice that?","prompt":"What do you think?","options":["Yes","Tells me a lot","I'll watch for it"],"affirm":"Someone who takes your no with grace is showing you who they are; that's worth knowing.","relearn":"How someone takes your no reveals who they are.","persona":"any","source":"reading a reaction"},
  {"id":"sr-946","cat":"date-with-respect","type":"reflect","hook":"Lensy: matching their energy instead of pushing past it keeps a date comfortable for both of you. See it?","prompt":"What do you think?","options":["Yes","Match the energy","I'll notice"],"affirm":"Reading the room and moving at a shared speed is what makes a date feel easy, not tense.","relearn":"Matching their energy keeps a date comfortable for both of you.","persona":"any","source":"shared pace"},
  {"id":"sr-947","cat":"date-with-respect","type":"reflect","hook":"Lensy: you can want closeness and still wait for a clear yes. Both true at once?","prompt":"What do you think?","options":["Yes","Both true","I can wait"],"affirm":"Wanting someone and waiting for their clear yes go together; that's respect, not rejection.","relearn":"You can want closeness and still wait for a clear yes.","persona":"any","source":"want and wait"},
  {"id":"sr-948","cat":"date-with-respect","type":"reflect","hook":"Lensy: a date that respects your boundaries is the bare minimum, not a bonus. Agree?","prompt":"What do you think?","options":["Yes","Bare minimum","Setting the bar"],"affirm":"Respect for your boundaries is the floor to expect, never a favour to be grateful for.","relearn":"Respect for your boundaries is the floor, not a bonus.","persona":"Aarti","source":"the floor not a favour"},
  {"id":"sr-949","cat":"date-with-respect","type":"sort","hook":"Sort: which moves match a date's pace, which push it?","items":[{"id":"a","text":"\"Want to keep tonight easy?\""},{"id":"b","text":"Ordering shots they didn't ask for"},{"id":"c","text":"Asking before a hug"},{"id":"d","text":"Going in for a kiss without checking"},{"id":"e","text":"Easing off when they go quiet"},{"id":"f","text":"Nudging for more after a slow-pace ask"}],"bins":[{"id":"match","label":"Matches the pace","valence":"pos"},{"id":"push","label":"Pushes the pace","valence":"neg"}],"key":{"a":"match","b":"push","c":"match","d":"push","e":"match","f":"push"},"relearn":"Asking and easing off match the pace; ordering, grabbing or nudging push it.","persona":"any","source":"pacing"},
  {"id":"sr-950","cat":"date-with-respect","type":"sort","hook":"Sort: a graceful way to handle a no, or pressure?","items":[{"id":"a","text":"\"Thanks for telling me, take care\""},{"id":"b","text":"Demanding a list of your flaws"},{"id":"c","text":"Wishing them well and moving on"},{"id":"d","text":"Texting again and again to change their mind"},{"id":"e","text":"Leaving the door friendly, no agenda"},{"id":"f","text":"Guilt-tripping about the money you spent"}],"bins":[{"id":"grace","label":"Graceful","valence":"pos"},{"id":"pressure","label":"Pressure","valence":"neg"}],"key":{"a":"grace","b":"pressure","c":"grace","d":"pressure","e":"grace","f":"pressure"},"relearn":"Thanking, wishing well and leaving it friendly is grace; demanding, chasing or guilt-tripping is pressure.","persona":"any","source":"receiving rejection"},
  {"id":"sr-951","cat":"date-with-respect","type":"sort","hook":"Sort: a kind way to give a no, or unkind?","items":[{"id":"a","text":"\"Nice time, but no romantic spark\""},{"id":"b","text":"Vague-promising a date you won't keep"},{"id":"c","text":"Being clear and brief, soon"},{"id":"d","text":"Ghosting with no word at all"},{"id":"e","text":"Wishing them well honestly"},{"id":"f","text":"Mocking them for being into you"}],"bins":[{"id":"kind","label":"Kind no","valence":"pos"},{"id":"unkind","label":"Unkind","valence":"neg"}],"key":{"a":"kind","b":"unkind","c":"kind","d":"unkind","e":"kind","f":"unkind"},"relearn":"Clear, brief, well-wishing is a kind no; false promises, ghosting or mocking aren't.","persona":"any","source":"giving rejection"},
  {"id":"sr-952","cat":"date-with-respect","type":"sort","hook":"Sort: a green flag on a date, or a red one?","items":[{"id":"a","text":"They check what you're comfortable with"},{"id":"b","text":"They sulk when you say slow down"},{"id":"c","text":"They respect your own way home"},{"id":"d","text":"They keep refilling your glass"},{"id":"e","text":"They take your no without drama"},{"id":"f","text":"They guilt-trip you for leaving early"}],"bins":[{"id":"green","label":"Green flag","valence":"pos"},{"id":"red","label":"Red flag","valence":"neg"}],"key":{"a":"green","b":"red","c":"green","d":"red","e":"green","f":"red"},"relearn":"Checking in and taking a no well are green flags; sulking, over-pouring or guilt-tripping are red.","persona":"any","source":"flag reading"},
  {"id":"sr-953","cat":"date-with-respect","type":"sort","hook":"Sort: who owes whom what, early in dating?","items":[{"id":"a","text":"A clear, kind no if you're not keen"},{"id":"b","text":"A second date because they paid"},{"id":"c","text":"Honesty about what you want"},{"id":"d","text":"Exclusivity after one date"},{"id":"e","text":"Respect for their boundaries"},{"id":"f","text":"A detailed reason for every no"}],"bins":[{"id":"owed","label":"You owe this","valence":"pos"},{"id":"not","label":"You don't owe this","valence":"neg"}],"key":{"a":"owed","b":"not","c":"owed","d":"not","e":"owed","f":"not"},"relearn":"You owe honesty, a kind no and respect; never a date, exclusivity or a reason for every no.","persona":"any","source":"what you owe"},
  {"id":"sr-954","cat":"date-with-respect","type":"sort","hook":"Sort: giving space, or crowding them?","items":[{"id":"a","text":"Letting a slow reply just be slow"},{"id":"b","text":"Sending five 'you up?' texts"},{"id":"c","text":"Waiting for them to plan their day"},{"id":"d","text":"Tracking their last-seen and grilling them"},{"id":"e","text":"One message, then leaving it"},{"id":"f","text":"Showing up uninvited to 'surprise' them"}],"bins":[{"id":"space","label":"Giving space","valence":"pos"},{"id":"crowd","label":"Crowding","valence":"neg"}],"key":{"a":"space","b":"crowd","c":"space","d":"crowd","e":"space","f":"crowd"},"relearn":"Letting replies be slow and sending one message is space; chase-texts, last-seen grilling or surprise visits crowd.","persona":"any","source":"giving space"},
  {"id":"sr-955","cat":"date-with-respect","type":"spot","hook":"Spot the two lines that pressure a date instead of respecting it.","scene":[{"id":"a","text":"\"No rush, we can keep tonight easy.\"","trick":false},{"id":"b","text":"\"I bought dinner, so you owe me a kiss.\"","trick":true},{"id":"c","text":"\"Is a hug okay, or not your thing?\"","trick":false},{"id":"d","text":"\"Don't be uptight, just one more drink.\"","trick":true},{"id":"e","text":"\"Your call, I'm happy either way.\"","trick":false}],"why":"The owe-me-a-kiss and 'don't be uptight' lines both push past consent; the rest leave the choice with them.","relearn":"Lines claiming you're owed something, or pushing past a 'no thanks', are pressure.","persona":"any","source":"spotting pressure"},
  {"id":"sr-956","cat":"date-with-respect","type":"spot","hook":"Spot the two red-flag reactions to being told no.","scene":[{"id":"a","text":"\"Thanks for being honest, take care.\"","trick":false},{"id":"b","text":"\"Tell me exactly what's wrong with me, now.\"","trick":true},{"id":"c","text":"\"No worries at all, wishing you well.\"","trick":false},{"id":"d","text":"\"You'll regret this, you won't do better.\"","trick":true},{"id":"e","text":"\"All good, glad we met.\"","trick":false}],"why":"Demanding a breakdown and threatening 'you'll regret this' turn a no into pressure; the others take it with grace.","relearn":"Demanding reasons or threatening after a no is a red flag, not hurt feelings.","persona":"Rohan","source":"spotting a bad reaction"},
  {"id":"sr-957","cat":"date-with-respect","type":"spot","hook":"Spot the two lines that ignore a slower pace.","scene":[{"id":"a","text":"\"We go as slow as you like.\"","trick":false},{"id":"b","text":"\"You said slow, but you don't really mean it.\"","trick":true},{"id":"c","text":"\"Tell me if anything feels too fast.\"","trick":false},{"id":"d","text":"\"Stop overthinking and just relax with me.\"","trick":true},{"id":"e","text":"\"Happy to just talk all night.\"","trick":false}],"why":"'You don't really mean slow' and 'stop overthinking' both override the pace they set; the rest honour it.","relearn":"Overriding the pace someone sets, even gently, ignores their consent.","persona":"any","source":"spotting pace-pushing"},
  {"id":"sr-958","cat":"date-with-respect","type":"spot","hook":"Spot the two messages that crowd someone after a date.","scene":[{"id":"a","text":"\"Had a lovely time, talk whenever suits you.\"","trick":false},{"id":"b","text":"\"You've been online but not replying. Why?\"","trick":true},{"id":"c","text":"\"No pressure to reply fast at all.\"","trick":false},{"id":"d","text":"\"It's been an hour, are you ignoring me?\"","trick":true},{"id":"e","text":"\"Take your time, I'm around.\"","trick":false}],"why":"Policing their last-seen and 'an hour, are you ignoring me' both flood for a reply; the rest give space.","relearn":"Tracking last-seen or chasing fast replies reads as pressure, not keenness.","persona":"any","source":"spotting crowding"},
  {"id":"sr-959","cat":"date-with-respect","type":"spot","hook":"Spot the two lines that skip a real consent check.","scene":[{"id":"a","text":"\"Is this okay, or would you rather not?\"","trick":false},{"id":"b","text":"\"You didn't say no, so it's fine.\"","trick":true},{"id":"c","text":"\"Tell me to stop anytime.\"","trick":false},{"id":"d","text":"\"You're into it, I can just tell.\"","trick":true},{"id":"e","text":"\"Want to slow down a bit?\"","trick":false}],"why":"'You didn't say no' and 'I can just tell' both assume a yes instead of getting one; the rest actually ask.","relearn":"Assuming a yes from silence or vibes isn't consent; a clear yes is.","persona":"any","source":"spotting assumed-yes"},
  {"id":"sr-960","cat":"date-with-respect","type":"spot","hook":"Spot the two lines that pretend a no is a maybe.","scene":[{"id":"a","text":"\"Got it, no second date. All the best.\"","trick":false},{"id":"b","text":"\"You said no, but I'll win you over.\"","trick":true},{"id":"c","text":"\"Respect that, take care of yourself.\"","trick":false},{"id":"d","text":"\"Give me one more chance to change your mind.\"","trick":true},{"id":"e","text":"\"Thanks for the honesty.\"","trick":false}],"why":"'I'll win you over' and 'one more chance to change your mind' both treat a no as negotiable; the rest accept it.","relearn":"A no isn't a starting offer; trying to 'win them over' ignores it.","persona":"any","source":"spotting no-as-maybe"},
  {"id":"sr-961","cat":"date-with-respect","type":"spot","hook":"Spot the two lines that quietly string someone along.","scene":[{"id":"a","text":"\"No romantic match, but it was nice meeting you.\"","trick":false},{"id":"b","text":"\"Yeah, let's plan something\" (meaning never).","trick":true},{"id":"c","text":"\"I'd rather be honest than vague.\"","trick":false},{"id":"d","text":"\"Maybe, we'll see, keep texting me.\"","trick":true},{"id":"e","text":"\"Wishing you the best, genuinely.\"","trick":false}],"why":"The empty 'let's plan something' and 'maybe, keep texting me' both lead someone on; the rest are honest.","relearn":"False promises and keeping someone hanging are unkind; an honest no is kinder.","persona":"any","source":"spotting stringing-along"},
  {"id":"sr-962","cat":"date-with-respect","type":"spot","hook":"Spot the two lines that don't respect a date's boundary.","scene":[{"id":"a","text":"\"You want to head home? I'll walk you to your cab.\"","trick":false},{"id":"b","text":"\"You can't leave now, the night just started.\"","trick":true},{"id":"c","text":"\"Totally fine, I had a great time.\"","trick":false},{"id":"d","text":"\"Skip the public spot, just come to my place.\"","trick":true},{"id":"e","text":"\"Text me you reached safe?\"","trick":false}],"why":"'You can't leave now' and 'skip the public spot, come to mine' both override a boundary; the rest respect it.","relearn":"Blocking someone from leaving or pushing them somewhere private ignores their boundary.","persona":"any","source":"spotting boundary-pushing"},
  {"id":"sr-963","cat":"date-with-respect","type":"match","hook":"Match each dating situation to the respectful move.","pairs":[{"left":"They want to take it slow","right":"Match their pace, no nudging"},{"left":"They say no to date two","right":"Thank them and move on"},{"left":"You're not feeling it","right":"Tell them kindly and clearly"},{"left":"They reply a day later","right":"Give them space"},{"left":"You want to get closer","right":"Check in before you do"}],"relearn":"Each respectful situation has a calm, consent-first move.","persona":"any","source":"situation to move"},
  {"id":"sr-964","cat":"date-with-respect","type":"match","hook":"Match the pushy line to what it really is.","pairs":[{"left":"\"I bought dinner, so...\"","right":"Treating generosity as a debt"},{"left":"\"You didn't say no\"","right":"Assuming a yes from silence"},{"left":"\"Give me one more chance\"","right":"Treating a no as negotiable"},{"left":"\"Why aren't you replying?\"","right":"Flooding for a fast reply"},{"left":"\"Stop overthinking it\"","right":"Overriding their pace"}],"relearn":"Naming what a pushy line really is makes it easy to spot.","persona":"any","source":"line to label"},
  {"id":"sr-965","cat":"date-with-respect","type":"match","hook":"Match each line to whether it's a green or red flag.","pairs":[{"left":"\"Is this okay with you?\"","right":"Green: checks consent"},{"left":"\"You owe me for tonight\"","right":"Red: treats you as a debt"},{"left":"\"Take your time replying\"","right":"Green: gives space"},{"left":"\"You can't leave yet\"","right":"Red: blocks your exit"},{"left":"\"We go at your pace\"","right":"Green: respects pacing"}],"relearn":"Consent, space and pacing are green; debts, blocked exits are red.","persona":"any","source":"flag reading"},
  {"id":"sr-966","cat":"date-with-respect","type":"match","hook":"Match the feeling to a respectful thing to say.","pairs":[{"left":"Want to slow the night down","right":"\"Can we keep tonight easy?\""},{"left":"Not interested in date two","right":"\"No spark, but nice meeting you\""},{"left":"Got turned down yourself","right":"\"Thanks for the honesty, take care\""},{"left":"Unsure if a hug's welcome","right":"\"Is a hug okay?\""},{"left":"They seem tired tonight","right":"\"Let's wrap up, I had fun\""}],"relearn":"Every feeling on a date has a kind, clear line to match it.","persona":"any","source":"feeling to line"},
  {"id":"sr-967","cat":"date-with-respect","type":"match","hook":"Match each truth about rejection to why it holds.","pairs":[{"left":"A no is complete on its own","right":"No reasons are owed"},{"left":"Rejection is part of dating","right":"It's normal and survivable"},{"left":"Give a no kindly and briefly","right":"Honesty beats false promises"},{"left":"Take a no without pushing","right":"Pushing turns it to pressure"},{"left":"A no isn't about your worth","right":"It's usually just a mismatch"}],"relearn":"Rejection, given or received, is normal and needs no audit.","persona":"any","source":"rejection truths"},
  {"id":"sr-968","cat":"date-with-respect","type":"match","hook":"Match the date moment to what consent looks like there.","pairs":[{"left":"Before holding hands","right":"A reached-for hand they meet"},{"left":"When they go quiet","right":"Easing off and asking"},{"left":"They named a boundary","right":"Following it without sulking"},{"left":"Ordering more drinks","right":"Checking it's their call"},{"left":"They want to leave","right":"Walking them out warmly"}],"relearn":"Consent on a date is small check-ins, not assumptions.","persona":"any","source":"consent moments"},
  {"id":"sr-969","cat":"date-with-respect","type":"match","hook":"Match each thing to whether you owe it on a date.","pairs":[{"left":"Honesty about your intentions","right":"Yes, you owe this"},{"left":"A second date for being paid for","right":"No, never owed"},{"left":"Respect for their boundaries","right":"Yes, the basic floor"},{"left":"Exclusivity after one meet","right":"No, not owed early on"},{"left":"A kind, brief no if you're out","right":"Yes, decency both ways"}],"relearn":"You owe honesty, respect and a kind no; never a date or exclusivity for being paid for.","persona":"any","source":"what you owe"},
  {"id":"sr-970","cat":"date-with-respect","type":"match","hook":"Match the red-flag reaction to the calmer move that beats it.","pairs":[{"left":"Demanding reasons for a no","right":"Accepting it with thanks"},{"left":"Chasing with rapid texts","right":"Sending one, then space"},{"left":"Guilt-tripping them to stay","right":"Walking them to their cab"},{"left":"Insulting them when rejected","right":"Wishing them well"},{"left":"Nudging past a slow pace","right":"Matching the pace they set"}],"relearn":"Every pushy reaction has a calmer, respectful move that beats it.","persona":"any","source":"swap the reaction"},
  {"id":"sr-990","cat":"dating-now","type":"strike-rewrite","hook":"\"If they don't reply fast, they're just not interested.\"","myth":{"un":"A slow reply means they're not interested.","re":"People have jobs, family and bad-signal days; a slow reply is usually just life, not a verdict.","why":"Reading silence as rejection makes you chase or spiral for no reason."},"relearn":"A slow reply is usually life, not rejection; don't read a verdict into a quiet day.","persona":"any","source":"reply pace"},
  {"id":"sr-991","cat":"dating-now","type":"strike-rewrite","hook":"\"Delete the app the moment you start talking to someone you like.\"","myth":{"un":"Once you like someone, you must delete the app to prove it.","re":"You set the pace; staying on or logging off early are both fine until you've agreed to be exclusive.","why":"Forced proof early on builds pressure, not trust."},"relearn":"There's no rule to delete the app on cue; exclusivity is a choice you make together, not a loyalty test.","persona":"any","source":"pacing"},
  {"id":"sr-992","cat":"dating-now","type":"strike-rewrite","hook":"\"A premium subscription means you'll finally find someone.\"","myth":{"un":"Paying for premium is what finally gets you matches that matter.","re":"Premium buys features, not connection; a real click depends on people, not your plan tier.","why":"Apps sell urgency; paying more doesn't make a stranger right for you."},"relearn":"Premium buys features, not love; connection comes from people, not your subscription tier.","persona":"Deepak","source":"app design"},
  {"id":"sr-993","cat":"dating-now","type":"strike-rewrite","hook":"\"If you're single at your age, you've fallen behind.\"","myth":{"un":"Being single at your age means you've fallen behind everyone.","re":"There's no shared dating timetable; people pair up, split and start over at every age.","why":"The 'behind' feeling comes from comparison, not from any real clock."},"relearn":"There's no dating timetable; single at any age is a fine place to be, not 'behind'.","persona":"Aarti","source":"comparison"},
  {"id":"sr-994","cat":"dating-now","type":"strike-rewrite","hook":"\"More swiping means you'll match faster.\"","myth":{"un":"The more you swipe, the faster you'll find someone.","re":"Swiping on everyone numbs your judgement; a few thoughtful matches beat a feed of fast right-swipes.","why":"Volume turns dating into a slot machine, not a way to meet a person."},"relearn":"Swiping on everyone numbs judgement; a few thoughtful matches beat chasing volume.","persona":"any","source":"healthy use"},
  {"id":"sr-995","cat":"dating-now","type":"strike-rewrite","hook":"\"An empty match list means something's wrong with you.\"","myth":{"un":"A quiet match list proves something's wrong with you.","re":"Match counts swing with photos, timing, area and luck; they measure an algorithm, not your worth.","why":"Tying self-worth to a number hands your mood to an app."},"relearn":"A quiet match list reflects the algorithm and timing, not your worth.","persona":"any","source":"self-worth"},
  {"id":"sr-996","cat":"dating-now","type":"strike-rewrite","hook":"\"You should hide the boring parts of your life on your profile.\"","myth":{"un":"A profile should hide the ordinary parts of your life.","re":"A profile is a highlight reel, but honest highlights help the right person recognise you.","why":"Pretending to be someone else just attracts matches for a person who isn't you."},"relearn":"A profile is a highlight reel of the real you; honest highlights help the right people find you.","persona":"any","source":"realistic expectations"},
  {"id":"sr-997","cat":"dating-now","type":"strike-rewrite","hook":"\"Take a break from apps and you'll miss the one good match.\"","myth":{"un":"Step away from apps and you'll miss your one chance.","re":"There is no single missable person; stepping back when you're drained is a healthy reset, not a loss.","why":"The 'you'll miss out' nudge is the app's design talking, not reality."},"relearn":"Taking a break is a healthy reset; there's no one missable match you'll lose by logging off.","persona":"Zoya","source":"your pace"},
  {"id":"sr-998","cat":"dating-now","type":"strike-rewrite","hook":"\"If a chat goes nowhere, you wasted your time.\"","myth":{"un":"A chat that goes nowhere was wasted time.","re":"Most chats fizzle and that's normal; a pleasant talk that ends is dating working, not failing.","why":"Calling every fade a 'waste' makes a normal thing feel like loss."},"relearn":"Most chats fizzle and that's normal; a chat that ends isn't time wasted.","persona":"any","source":"expectations"},
  {"id":"sr-999","cat":"dating-now","type":"strike-rewrite","hook":"\"Everyone on apps is just there to hook up.\"","myth":{"un":"Everyone on dating apps only wants to hook up.","re":"People are on apps for all sorts: friendship, something serious, casual, or just curiosity.","why":"One blanket assumption flattens a lot of different, valid reasons."},"relearn":"People use apps for many reasons; it's fine to ask early what someone's looking for.","persona":"any","source":"realistic expectations"},
  {"id":"sr-1000","cat":"dating-now","type":"strike-rewrite","hook":"\"You have to reply to every match or you're rude.\"","myth":{"un":"Not replying to a match makes you a rude person.","re":"You can let a match you're not feeling go without a reply; a match is an opening, not a debt.","why":"Owing a reply to everyone turns dating into an obligation list."},"relearn":"A match is an opening, not a debt; you don't owe everyone a reply.","persona":"any","source":"no obligation"},
  {"id":"sr-1001","cat":"dating-now","type":"reflect","hook":"Lensy: your photos can be ordinary and honest, not a fashion shoot. Sit right with you?","prompt":"What do you think?","options":["Yes","Honest is enough","I don't need a shoot"],"affirm":"Real, everyday photos help the right person recognise the actual you; you don't owe anyone a perfect feed.","relearn":"Honest, everyday photos are enough; you don't owe anyone a flawless profile.","persona":"any","source":"realistic expectations"},
  {"id":"sr-1002","cat":"dating-now","type":"reflect","hook":"Lensy: you're allowed to want something casual, or something serious, with no apology. Agree?","prompt":"What do you think?","options":["Yes","My call","Either is fine"],"affirm":"What you want from dating is yours to name; casual or serious, neither needs defending to anyone.","relearn":"Wanting casual or serious is your call; you don't owe anyone an apology for either.","persona":"any","source":"your pace"},
  {"id":"sr-1003","cat":"dating-now","type":"reflect","hook":"Lensy: deleting the apps for a while can be a kindness to yourself. How's that land?","prompt":"What do you think?","options":["Yes","I can step back","Rest is allowed"],"affirm":"Stepping back when apps drain you is self-respect, not giving up; they'll be there when you're ready.","relearn":"Taking a break from apps when they drain you is self-respect, not giving up.","persona":"Meena","source":"your pace"},
  {"id":"sr-1004","cat":"dating-now","type":"reflect","hook":"Lensy: your worth isn't decided by how many people swipe right. True for you?","prompt":"What do you think?","options":["Yes","I'm not a number","Worth isn't a count"],"affirm":"You were a whole, worthwhile person before any app and you stay one no matter the match count.","relearn":"Your worth was never a match count; it doesn't move with the app.","persona":"any","source":"self-worth"},
  {"id":"sr-1005","cat":"dating-now","type":"reflect","hook":"Lensy: it's fine to date quietly without telling everyone at home. Does that fit your life?","prompt":"What do you think?","options":["Yes","My pace","I choose who knows"],"affirm":"Who you tell about your dating life is yours to decide; privacy at home isn't dishonesty.","relearn":"Who you tell about dating is your choice; keeping it private isn't dishonesty.","persona":"Aarti","source":"privacy"},
  {"id":"sr-1006","cat":"dating-now","type":"reflect","hook":"Lensy: comparing your week to a friend's highlight stories is a losing game. Recognise it?","prompt":"What do you think?","options":["Yes","I'll stop comparing","It's a highlight reel"],"affirm":"Their feed is the edited best bits; your real, messy week is not behind anyone's curated one.","relearn":"A friend's feed is the edited best bits; your real week isn't behind their highlight reel.","persona":"any","source":"comparison"},
  {"id":"sr-1007","cat":"dating-now","type":"reflect","hook":"Lensy: you can log off the second dating stops being fun. Permission you'll take?","prompt":"What do you think?","options":["Yes","Fun is the point","I'll log off"],"affirm":"Dating is meant to add to your life, not become a chore; closing the app when it sours is wise.","relearn":"When dating stops being fun you can log off; it's meant to add to your life, not drain it.","persona":"any","source":"healthy use"},
  {"id":"sr-1008","cat":"dating-now","type":"reflect","hook":"Lensy: you can be new to all this with zero experience, and that's completely okay. Land alright?","prompt":"What do you think?","options":["Yes","Beginners welcome","No shame in new"],"affirm":"Everyone starts somewhere; being new to dating apps is a fine, ordinary place to begin.","relearn":"Being new to dating with no experience is completely okay; everyone starts somewhere.","persona":"Ananya","source":"beginners"},
  {"id":"sr-1009","cat":"dating-now","type":"reflect","hook":"Lensy: you get to take a profile down, take a break, then come back whenever. Yours to choose?","prompt":"What do you think?","options":["Yes","On and off is fine","My timing"],"affirm":"Dating isn't a streak to maintain; on, off and back again on your own timing is perfectly normal.","relearn":"On, off and back again is normal; dating isn't a streak you have to keep alive.","persona":"any","source":"your pace"},
  {"id":"sr-1010","cat":"dating-now","type":"reflect","hook":"Lensy: you can decide a person, not an algorithm, is who you're trying to meet. Sound right?","prompt":"What do you think?","options":["Yes","A person, not a score","Real connection"],"affirm":"Keeping your eyes on meeting an actual human keeps the app a tool instead of a scoreboard.","relearn":"You're trying to meet a person, not beat an algorithm; that keeps the app a tool.","persona":"any","source":"the goal"},
  {"id":"sr-1011","cat":"dating-now","type":"reflect","hook":"Lensy: wanting a partner doesn't make you needy or 'too much'. Does that sit okay?","prompt":"What do you think?","options":["Yes","Wanting is human","Not too much"],"affirm":"Wanting closeness is a normal human pull, not a flaw; you're allowed to want and to wait for the right fit.","relearn":"Wanting a partner is human, not needy; you can want closeness without shame.","persona":"any","source":"self-worth"},
  {"id":"sr-1012","cat":"dating-now","type":"reflect","hook":"Lensy: you can date openly across orientations and still keep parts of your life private. Fit you?","prompt":"What do you think?","options":["Yes","On my terms","Privacy is mine"],"affirm":"You decide who you date and what you share; living openly and keeping a private corner can both be true.","relearn":"You choose who you date and what you share; being open and keeping privacy can coexist.","persona":"Zoya","source":"identity"},
  {"id":"sr-1013","cat":"dating-now","type":"reflect","hook":"Lensy: a fizzled chat says nothing bad about you. Can you let that one go?","prompt":"What do you think?","options":["Yes","Not about me","I'll let it go"],"affirm":"Chats fade for a hundred small reasons that aren't a referendum on you; you can release it lightly.","relearn":"A fizzled chat isn't about you; it fades for small reasons you can release lightly.","persona":"any","source":"self-worth"},
  {"id":"sr-1014","cat":"dating-now","type":"reflect","hook":"Lensy: it's fine to read a profile slowly and message only when you actually feel a spark. Yours?","prompt":"What do you think?","options":["Yes","No rush","Only when I feel it"],"affirm":"There's no quota of messages to send; reaching out only when you genuinely feel a pull is honest.","relearn":"There's no message quota; reaching out only when you feel a spark is honest, not lazy.","persona":"any","source":"healthy use"},
  {"id":"sr-1015","cat":"dating-now","type":"reflect","hook":"Lensy: you can want company and still enjoy being single right now. Both true at once?","prompt":"What do you think?","options":["Yes","Both can be true","Happy either way"],"affirm":"Liking your single life and being open to someone aren't a contradiction; you can hold both.","relearn":"Enjoying single life and being open to dating can both be true at once.","persona":"any","source":"your pace"},
  {"id":"sr-1016","cat":"dating-now","type":"sort","hook":"Sort: a sign of healthy app habits, or that your use has gone sour?","items":[{"id":"a","text":"You close the app feeling fine"},{"id":"b","text":"You check for matches the moment you wake"},{"id":"c","text":"You message when you've got energy"},{"id":"d","text":"A quiet day leaves you anxious"},{"id":"e","text":"You can put the phone down mid-swipe"},{"id":"f","text":"You keep swiping when it's stopped being fun"}],"bins":[{"id":"ok","label":"Healthy","valence":"pos"},{"id":"sour","label":"Gone sour","valence":"uhoh"}],"key":{"a":"ok","b":"sour","c":"ok","d":"sour","e":"ok","f":"sour"},"relearn":"Closing fine and stopping with ease are healthy; wake-up checking and anxious, joyless swiping mean it's sour.","persona":"any","source":"healthy use"},
  {"id":"sr-1017","cat":"dating-now","type":"sort","hook":"Sort: a fair thing to expect from a match, or an unfair one?","items":[{"id":"a","text":"That they reply in their own time"},{"id":"b","text":"That they answer the instant you text"},{"id":"c","text":"That they can change their mind"},{"id":"d","text":"That they owe you a date for matching"},{"id":"e","text":"That a fade-out can happen, no big reason"},{"id":"f","text":"That they share their whole life by day two"}],"bins":[{"id":"fair","label":"Fair","valence":"pos"},{"id":"unfair","label":"Unfair","valence":"neg"}],"key":{"a":"fair","b":"unfair","c":"fair","d":"unfair","e":"fair","f":"unfair"},"relearn":"Their own pace, changing their mind and quiet fade-outs are fair; instant replies, owed dates and on-demand oversharing aren't.","persona":"any","source":"no obligation"},
  {"id":"sr-1018","cat":"dating-now","type":"sort","hook":"Sort: a green-flag opener, or a flat one likely to fizzle?","items":[{"id":"a","text":"A question about something in their profile"},{"id":"b","text":"A plain 'hi' and nothing else"},{"id":"c","text":"A warm note on a shared interest"},{"id":"d","text":"A copy-paste line sent to everyone"},{"id":"e","text":"A genuine, easy question to reply to"},{"id":"f","text":"'You're the only normal one on here'"}],"bins":[{"id":"green","label":"Green opener","valence":"pos"},{"id":"flat","label":"Flat opener","valence":"neg"}],"key":{"a":"green","b":"flat","c":"green","d":"flat","e":"green","f":"flat"},"relearn":"A real question, a shared-interest note and an easy ask land; a bare 'hi', a copy-paste and flattery-bait fizzle.","persona":"any","source":"openers"},
  {"id":"sr-1019","cat":"dating-now","type":"sort","hook":"Sort: a realistic read of dating now, or a movie myth?","items":[{"id":"a","text":"You build trust slowly, in small steps"},{"id":"b","text":"You'll just 'know' the second you meet"},{"id":"c","text":"Most matches won't become anything"},{"id":"d","text":"One perfect person is out there waiting"},{"id":"e","text":"Good people exist; fit is what's rare"},{"id":"f","text":"The right one will complete you"}],"bins":[{"id":"real","label":"Realistic","valence":"pos"},{"id":"myth","label":"Movie myth","valence":"neg"}],"key":{"a":"real","b":"myth","c":"real","d":"myth","e":"real","f":"myth"},"relearn":"Slow trust, fizzling matches and rare-fit are real; 'just knowing', 'one perfect person' and 'completing you' are myths.","persona":"any","source":"expectations"},
  {"id":"sr-1020","cat":"dating-now","type":"sort","hook":"Sort: dating for yourself, or to please someone else?","items":[{"id":"a","text":"You date when you feel like it"},{"id":"b","text":"You date to stop relatives asking"},{"id":"c","text":"You pick people you actually like"},{"id":"d","text":"You pick people who'll impress others"},{"id":"e","text":"You set the pace that suits you"},{"id":"f","text":"You rush to match a friend's timeline"}],"bins":[{"id":"self","label":"For yourself","valence":"pos"},{"id":"others","label":"To please others","valence":"uhoh"}],"key":{"a":"self","b":"others","c":"self","d":"others","e":"self","f":"others"},"relearn":"When you feel like it, who you like and your own pace is for you; to stop questions, impress others or match a friend isn't.","persona":"Aarti","source":"motivation"},
  {"id":"sr-1021","cat":"dating-now","type":"sort","hook":"Sort: a kind way to handle a fading chat, or a careless one?","items":[{"id":"a","text":"A brief 'lovely talking, take care'"},{"id":"b","text":"Vanishing mid-chat with no word"},{"id":"c","text":"Saying you're not feeling a spark, gently"},{"id":"d","text":"Leaving them on read for weeks on purpose"},{"id":"e","text":"Being honest you've met someone else"},{"id":"f","text":"Stringing them along with maybe-laters"}],"bins":[{"id":"kind","label":"Kind close","valence":"pos"},{"id":"careless","label":"Careless","valence":"neg"}],"key":{"a":"kind","b":"careless","c":"kind","d":"careless","e":"kind","f":"careless"},"relearn":"A brief sign-off, a gentle 'no spark' and honesty are kind; vanishing, read-leaving and stringing along are careless.","persona":"Rohan","source":"honesty both ways"},
  {"id":"sr-1022","cat":"dating-now","type":"sort","hook":"Sort: a profile detail worth its space, or filler that says nothing?","items":[{"id":"a","text":"A real hobby with a specific detail"},{"id":"b","text":"'I love to laugh and have fun'"},{"id":"c","text":"A photo of you doing something you enjoy"},{"id":"d","text":"'Ask me anything' and nothing else"},{"id":"e","text":"One honest line about what you want"},{"id":"f","text":"A wall of copied cliches"}],"bins":[{"id":"worth","label":"Worth it","valence":"pos"},{"id":"filler","label":"Filler","valence":"neutral"}],"key":{"a":"worth","b":"filler","c":"worth","d":"filler","e":"worth","f":"filler"},"relearn":"A specific hobby, a real photo and an honest want earn space; 'love to laugh', 'ask me anything' and cliches are filler.","persona":"any","source":"realistic expectations"},
  {"id":"sr-1023","cat":"dating-now","type":"sort","hook":"Sort: a steady thought after a no-reply, or one to let go?","items":[{"id":"a","text":"'Maybe they're just busy or off the app'"},{"id":"b","text":"'I must be unlovable'"},{"id":"c","text":"'It's one match among many'"},{"id":"d","text":"'Everyone can tell I'm a failure'"},{"id":"e","text":"'The reasons aren't about me'"},{"id":"f","text":"'I should change everything about myself'"}],"bins":[{"id":"steady","label":"Steady","valence":"pos"},{"id":"spiral","label":"Let it go","valence":"uhoh"}],"key":{"a":"steady","b":"spiral","c":"steady","d":"spiral","e":"steady","f":"spiral"},"relearn":"'They're busy', 'one of many' and 'not about me' are steady; 'unlovable', 'everyone can tell' and 'change everything' are spirals.","persona":"Deepak","source":"self-worth"},
  {"id":"sr-1024","cat":"dating-now","type":"sort","hook":"Sort: a healthy boundary with apps, or a habit that runs you?","items":[{"id":"a","text":"No apps for the first hour after waking"},{"id":"b","text":"Swiping in bed till 2am most nights"},{"id":"c","text":"Replying when free, not on alert"},{"id":"d","text":"Carrying every chat's mood into your day"},{"id":"e","text":"Closing the app once you feel restless"},{"id":"f","text":"Opening it out of pure boredom, again"}],"bins":[{"id":"boundary","label":"Boundary","valence":"pos"},{"id":"runs-you","label":"Runs you","valence":"uhoh"}],"key":{"a":"boundary","b":"runs-you","c":"boundary","d":"runs-you","e":"boundary","f":"runs-you"},"relearn":"App-free mornings and closing on restlessness are boundaries; late-night and boredom-swiping run you.","persona":"any","source":"healthy use"},
  {"id":"sr-1025","cat":"dating-now","type":"sort","hook":"Sort: a fair thing to share early in chat, or too much too soon?","items":[{"id":"a","text":"What you generally enjoy doing"},{"id":"b","text":"Your home address on day one"},{"id":"c","text":"The kind of relationship you want"},{"id":"d","text":"Detailed daily routines and timings"},{"id":"e","text":"A bit about your work or studies"},{"id":"f","text":"Where you'll be alone and when"}],"bins":[{"id":"fine","label":"Fine to share","valence":"pos"},{"id":"hold","label":"Hold back","valence":"uhoh"}],"key":{"a":"fine","b":"hold","c":"fine","d":"hold","e":"fine","f":"hold"},"relearn":"Interests, what you want and broad work or study are fine early; your address, exact routines and when you're alone are best held back.","persona":"Ananya","source":"healthy use"},
  {"id":"sr-1026","cat":"dating-now","type":"branch","persona":"any","source":"reply pace","hook":"After three days of great chat, Kiran has gone quiet for two days.","steps":[{"prompt":"You're tempted to send something. What do you do?","options":[{"text":"Ask her why she's ignoring you","then":"The message sits unread. When she opens it, the tone of the chat changes."},{"text":"Give it space and carry on with your day","then":"You meet friends for momos and forget your phone for a while.","best":true},{"text":"Check her stories to see what she's up to","then":"She's posted from a family wedding. You still feel ignored."},{"text":"Assume she's lost interest and sulk","then":"You snap at a friend over nothing. The phone stays face down, and so do you."}],"why":"Quiet stretches happen for lots of reasons. Space keeps your dignity and your options open."},{"prompt":"On day four, Kiran's back: \"Sorry, family wedding chaos!\" What do you do?","options":[{"text":"Send a sarcastic \"Oh, you're alive\"","then":"Kiran sends a flat \"yes\". The warmth from last week is gone."},{"text":"Wait two days to reply, so she knows how it felt","then":"By the time you reply, she's busy chatting with someone else."},{"text":"Tell her you were worried she'd ghosted you","then":"Kiran apologises. The chat feels a bit careful now."},{"text":"Reply warmly and ask how the wedding was","then":"Kiran sends mehendi photos and a long voice note. The chat's back.","best":true}],"why":"Meeting her return warmly, with no scorekeeping, lets the chat pick up again."},{"prompt":"A week later, you realise you check her last-seen every hour. What do you do?","options":[{"text":"Mention you saw she was online and didn't reply","then":"Kiran goes quiet. \"Are you tracking me?\""},{"text":"Notice the habit and put the phone down","then":"The urge fades by evening. You get back to your assignments.","best":true},{"text":"Time your messages to catch her online","then":"You stay up late waiting for a green dot."},{"text":"Decide it's fine, since you don't say anything","then":"You say nothing, but the checking eats half your day."}],"why":"Tracking someone's online status breeds worry, not closeness. Stepping back helps you both."}],"debrief":"Quiet stretches happen for many reasons. Space keeps your dignity and options open.","relearn":"Give a quiet match space; silence is usually life, not rejection."},
  {"id":"sr-1027","cat":"dating-now","type":"branch","persona":"any","source":"healthy use","hook":"It's 1 a.m. and you've been swiping for an hour. Your mood keeps sinking, but you keep going.","steps":[{"prompt":"Your thumb is on autopilot. What do you do?","options":[{"text":"Keep going till a like makes you feel better","then":"A like arrives at 2 a.m. The lift lasts about a minute."},{"text":"Switch to scrolling reels instead","then":"You've stopped swiping, but you're still scrolling at 2 a.m., still low."},{"text":"Close the app and put the phone across the room","then":"It feels abrupt. Five minutes later, you're already calmer.","best":true},{"text":"Message an old match just to get a reply","then":"They don't reply. Now you're waiting on that too."}],"why":"When swiping drains you, logging off is the win. Pushing through for a hit rarely helps."},{"prompt":"The next evening, you feel the pull to open the app again. What do you do?","options":[{"text":"Open it and see where the night goes","then":"The night goes on past midnight. The same slump creeps back."},{"text":"Open it with a limit, and stop when it's not fun","then":"You chat with two people for twenty minutes, then close it feeling fine.","best":true},{"text":"Swipe right on everyone to get it over with","then":"You get matches you don't care about and feel emptier."},{"text":"Open it only when you're feeling low","then":"The app becomes where you go to feel better. It rarely works."}],"why":"Using the app on your terms, with a limit, keeps it a doorway, not a drain."},{"prompt":"On Sunday, you notice you've spent the whole day indoors checking matches. What do you do?","options":[{"text":"Stay in and wait for someone to message","then":"Nobody does. The day slips by on your phone."},{"text":"Update your profile photos again","then":"You spend an hour on angles. The mood stays the same."},{"text":"Post a story so matches see you're fun","then":"You check who viewed it every ten minutes."},{"text":"Call a friend and go out for chai","then":"You laugh for an hour and forget to check the app till you're home.","best":true}],"why":"A life full of people and plans is what makes the app matter less."}],"debrief":"When swiping drains you, the win is logging off, not pushing through for a hit.","relearn":"When the app drains you, close it; a break beats chasing a 'like'."},
  {"id":"sr-1028","cat":"dating-now","type":"branch","persona":"Aarti","source":"agency","hook":"At a family lunch, Chitra Masi asks why you're still single. Everyone turns to look.","steps":[{"prompt":"You feel the heat rise in your face. What do you say?","options":[{"text":"Promise you'll settle down soon to end it","then":"Masi beams. \"I know just the family,\" she says, already reaching for her phone."},{"text":"Snap that it's none of her business","then":"The table goes silent. Your mother gives you a look across the dal."},{"text":"Say lightly that you're happy and in no rush","then":"Masi raises an eyebrow, then laughs. \"Okay, okay.\" The table moves on.","best":true},{"text":"Laugh and say nobody would have you anyway","then":"Everyone laughs. Masi says she'll find someone who will."}],"why":"Saying you're happy, lightly, answers her honestly without promising anything or starting a fight."},{"prompt":"After lunch, your mother says quietly that Masi means well. What do you do?","options":[{"text":"Promise to consider Masi's picks, just to end the talk","then":"Your mother looks relieved. A biodata lands in your inbox that night."},{"text":"Tell her you're sick of the whole family","then":"Your mother goes quiet. The talk ends with both of you hurt."},{"text":"Say you know, and ask her to back your pace","then":"Your mother hesitates, then nods. \"I'll talk to Masi.\"","best":true},{"text":"Wonder if Masi's right that you're running late","then":"Your mother pats your hand. That night, you scroll old classmates' wedding photos."}],"why":"Asking your mother to back you, calmly, turns her from a messenger into an ally."},{"prompt":"A week later, a cousin adds you to a family group where proposals are shared. What do you do?","options":[{"text":"Leave the group without a word","then":"Three aunts message to ask if you're upset. Now it's a bigger thing."},{"text":"Post a sharp reply telling the whole group to back off","then":"The group goes quiet, then fills with aunties' comments."},{"text":"Mute it and like a few profiles to keep the peace","then":"Your likes get noticed. By Sunday, a family wants to meet."},{"text":"Message your cousin privately that you're not looking","then":"Your cousin replies, \"Oh! Sorry. I'll take you off the list.\"","best":true}],"why":"A quiet word with the right person holds your line without a public fight."},{"prompt":"At the next function, Masi asks again, louder this time. What do you say?","options":[{"text":"Make up a secret partner to shut it down","then":"Masi wants a name and a photo by next week."},{"text":"Explain your career plans in detail to justify waiting","then":"Masi finds a hole in every plan. The talk goes on for an hour."},{"text":"Say warmly that you're happy and in no rush","then":"Masi sighs dramatically, then turns to someone else's news.","best":true},{"text":"Walk away in the middle of her sentence","then":"Masi tells everyone you've become rude since college."}],"why":"You don't owe a reason for your pace. A warm, simple line holds."}],"debrief":"Your timeline is yours. A calm, warm line protects it without a scene.","relearn":"Your dating timeline is yours; a calm 'happy, no rush' holds it."},
  {"id":"sr-1029","cat":"dating-now","type":"branch","persona":"any","source":"pacing","hook":"You really like one match, Aman, but you're still chatting with two others. You feel guilty.","steps":[{"prompt":"Aman asks if you're talking to anyone else on the app. What do you say?","options":[{"text":"Tell him he's the only one","then":"Aman looks pleased. You now have a lie to keep straight."},{"text":"Say honestly that you're chatting to a few","then":"Aman nods. \"Same here, to be fair. Good to know.\"","best":true},{"text":"Dodge with a joke and change the subject","then":"Aman laughs, but asks again a few days later."},{"text":"Ask if he's talking to others first","then":"Aman laughs. \"I asked first.\" The question hangs there."}],"why":"Chatting with a few early is normal. Being honest about it keeps it fair."},{"prompt":"Another match, Neil, asks to meet, but you realise you only want to see Aman. What do you do?","options":[{"text":"Stop replying and let it fade","then":"Neil sends two more messages, then a confused \"all good?\""},{"text":"Tell Neil kindly that you're not feeling it","then":"Neil replies, \"Thanks for being straight with me. Good luck.\"","best":true},{"text":"Say you're busy this weekend, and next","then":"Neil suggests the weekend after. The excuse needs another excuse."},{"text":"Say yes, to keep him as a backup","then":"You meet, distracted. Neil can tell something's off."}],"why":"A short, kind no is fairer than a fade or a backup plan."},{"prompt":"A week later, Aman asks if you'd like to be exclusive. What do you do?","options":[{"text":"Say yes straight away so you don't lose him","then":"It feels sweet, but you're not sure you meant it yet."},{"text":"Say you need to check with your friends first","then":"Aman laughs uneasily. \"Okay. Let me know what they decide.\""},{"text":"Keep it vague so your options stay open","then":"Aman takes the hint and starts chatting with others again."},{"text":"Tell him how you actually feel about it","then":"You talk it through over chai and both leave knowing what you want.","best":true}],"why":"Exclusivity is a choice you make together. Saying honestly how you feel is the start."}],"debrief":"Chatting with a few early is normal. Exclusivity is a choice you make together.","relearn":"Chatting with a few early is normal; exclusivity is a shared choice."},
  {"id":"sr-1031","cat":"dating-now","type":"branch","persona":"Rohan","source":"honesty both ways","hook":"You matched with Leela, but after a day of chat you realise you're not interested.","steps":[{"prompt":"She's just sent a long message about her weekend. What do you do?","options":[{"text":"Just stop replying and let it die","then":"Leela sends a follow-up the next day, then a confused emoji."},{"text":"Reply to be polite, then fade out slowly","then":"The chat limps on for a week. Leela keeps putting in effort."},{"text":"Unmatch so the chat just disappears","then":"Her message vanishes with the chat. You feel oddly guilty all evening."},{"text":"Send a short, kind note that you're not feeling it","then":"Leela replies, \"Ah, fair enough. Thanks for saying so!\"","best":true}],"why":"A brief, kind close respects her time. Vanishing leaves her guessing."},{"prompt":"Your friend Sahil says sign-offs are pointless and ghosting is just how apps work. What do you say?","options":[{"text":"Agree that apps have their own rules","then":"Sahil nods. Your next fade feels easier, and a bit worse."},{"text":"Say it only matters with people you've met","then":"Sahil agrees. Most of your matches now fall below the line."},{"text":"Say a one-line sign-off costs nothing","then":"Sahil shrugs. \"I guess I'd want one too.\"","best":true},{"text":"Laugh along so you don't seem soft","then":"Sahil keeps talking. You don't say what you think."}],"why":"Decency doesn't pause for apps. A one-line sign-off is how you'd want to be treated."},{"prompt":"A week later, a match you liked stops replying with no word. What do you do?","options":[{"text":"Send a long message asking what you did","then":"It sits unread. You check it all day."},{"text":"Feel the sting, then let it go","then":"It bugs you for an evening. By morning, it's smaller.","best":true},{"text":"Decide ghosting is fair game from now on","then":"You start fading on people too. It doesn't feel as easy as Sahil said."},{"text":"Post a story about people who ghost","then":"A few friends react. The match never sees it."}],"why":"Being ghosted stings. Letting it go, without passing it on, keeps your own standard."},{"prompt":"Then you go on a date with Noor and aren't sure you want a second. What do you do?","options":[{"text":"Fade slowly so she gets the hint","then":"Noor keeps making plans. The hint never lands."},{"text":"Say yes to a second date to avoid saying no","then":"You spend the second date wishing you'd been honest."},{"text":"Take a day to think, then tell her kindly","then":"You message Noor the next evening. She thanks you for being clear.","best":true},{"text":"Tell her it was nice, then never reply again","then":"Noor waits for a plan that never comes."}],"why":"Taking time is fine. Closing kindly once you know is honesty both ways."}],"debrief":"A brief, warm sign-off respects you both. You owe no interest, but you owe honesty.","relearn":"When you're not interested, a brief kind close beats ghosting."},
  {"id":"sr-1032","cat":"dating-now","type":"branch","persona":"Deepak","source":"app design","hook":"An app pings: \"Upgrade now or miss 12 people who liked you!\" Money is already tight this month.","steps":[{"prompt":"The upgrade costs more than your week's chai money. What do you do?","options":[{"text":"Pay now so you don't miss anyone","then":"You see who liked you. Most live far away, and none message."},{"text":"Treat it as a sales nudge and close it","then":"The ping fades. Whoever those twelve are, they're still there tomorrow.","best":true},{"text":"Borrow from a friend to pay for a month","then":"Your friend sends the money. Now you owe them, and the likes look the same."},{"text":"Sign up for the free trial, just to peek","then":"You peek at the likes. In a week, the trial turns into a paid plan."}],"why":"Manufactured urgency is a sales tactic. Nobody real is lost by waiting."},{"prompt":"The next day, a pop-up offers a profile boost at half price, for one hour only. What do you do?","options":[{"text":"Grab it. Half price won't come again","then":"The next week, the same half-price offer pops up again."},{"text":"Ask the group chat if it's worth it","then":"The group argues for an hour. The timer runs out mid-debate."},{"text":"Buy it and cut back on data for the month","then":"The boost works, but your data runs out by the twentieth."},{"text":"Spot the same trick, and decide calmly later","then":"The hour passes. You don't miss it.","best":true}],"why":"Countdown discounts are built to rush you. A calm decision later is still yours to make."},{"prompt":"A friend says the free version works fine if you actually message people. What do you do?","options":[{"text":"Swipe on everyone to beat the algorithm","then":"You get lots of matches and have time for none of them."},{"text":"Save up for premium, since free users lose out","then":"You skip a movie with friends to save. The app feels like a bill now."},{"text":"Put your energy into real chats, not boosts","then":"You send three thoughtful messages. One turns into a great conversation.","best":true},{"text":"Give up on apps, since dating costs money anyway","then":"You delete the apps, sure that dating is only for people with money."}],"why":"What makes a chat work is what you put into it, not what you pay the app."}],"debrief":"'You'll miss out' is design, not reality.","relearn":"App 'upgrade or miss out' urgency is a sales nudge; date on your own terms."},
  {"id":"sr-1033","cat":"dating-now","type":"branch","persona":"Ananya","source":"expectations","hook":"You're new to dating apps, and your first three chats all fizzled out on day one.","steps":[{"prompt":"You're ready to delete the app tonight. What do you tell yourself?","options":[{"text":"I'm clearly bad at this","then":"You go to bed sure it's about you. You dread opening the app."},{"text":"My profile must be all wrong","then":"You rewrite your bio four times. It doesn't change how you feel."},{"text":"Fizzles are the normal start for everyone","then":"You leave the app for tomorrow. It feels less like a test now.","best":true},{"text":"Apps are only for confident people","then":"You feel like an outsider to something everyone else gets."}],"why":"Most early chats fade for everyone. Three fizzles is a normal start, not a verdict."},{"prompt":"Your roommate Leena asks how the apps are going. What do you say?","options":[{"text":"Pretend it's going great","then":"Leena is impressed. You feel lonelier keeping up the act."},{"text":"Tell her honestly that it's been a slow start","then":"Leena laughs. \"Mine too. My first ten were duds.\" You feel less alone.","best":true},{"text":"Say apps are stupid anyway","then":"Leena shrugs and drops it. The sting stays private."},{"text":"Ask her to write your openers from now on","then":"Her openers get replies, but the chats don't sound like you."}],"why":"Saying it honestly to a friend shows you how normal it is."},{"prompt":"The next day, a match called Kabir sends a friendly hello. What do you do?","options":[{"text":"Reply fast with ten questions so it doesn't die","then":"Kabir answers two, then goes quiet."},{"text":"Wait a day so you don't seem too keen","then":"By the time you reply, the chat has cooled."},{"text":"Reply with something genuine, and see where it goes","then":"Kabir asks about your favourite street food. You chat for an hour.","best":true},{"text":"Tell him about your three fizzles upfront","then":"Kabir sends a sympathetic emoji. The chat starts on a heavy note."}],"why":"A genuine reply, without pressure to make it work, gives a chat its best chance."},{"prompt":"A week later, Kabir's chat fades too. What do you do?","options":[{"text":"Decide it proves you can't do this","then":"You quit the app, sure it was about you."},{"text":"Keep dating at your own pace","then":"It stings a little. By the weekend, you're chatting with someone new.","best":true},{"text":"Message Kabir to ask what went wrong","then":"He replies, \"Nothing! Just got busy.\" You're no clearer."},{"text":"Swipe right on everyone to make up for it","then":"You get matches you don't care about, and the fizzles keep coming."}],"why":"A fizzle isn't about you. Keeping your own pace is how you stay in the game."}],"debrief":"Beginnings are mostly fizzles. That's the app working, not you.","relearn":"Most early chats fizzle for everyone; a few fizzles is a normal start."},
  {"id":"sr-1034","cat":"dating-now","type":"branch","persona":"Zoya","source":"identity","hook":"You came out at college but not at home. Your match Ritika asks to meet your family soon.","steps":[{"prompt":"She says it would mean a lot to her. What do you say?","options":[{"text":"Agree, and hope it somehow works out","then":"Ritika is thrilled. You lie awake working out what to tell your parents."},{"text":"Stop replying so you don't have to explain","then":"The next day, Ritika sends a worried message asking if you're okay."},{"text":"Ask a friend to explain it to Ritika for you","then":"Ritika hears it second-hand, confused, and you still haven't talked."},{"text":"Say warmly that you keep home private for now","then":"Ritika pauses. \"Okay. Can you tell me a bit about why?\"","best":true}],"why":"Your home life and your timeline are yours. Naming the boundary warmly keeps it honest."},{"prompt":"Later, Ritika notices you tense up whenever family comes up, and gently asks why. What do you say?","options":[{"text":"Say you're not out at home yet","then":"Ritika goes quiet, then says, \"Thank you for telling me. No rush.\"","best":true},{"text":"Tell her everything, past what you're ready to share","then":"Ritika listens closely. Afterwards, you feel exposed and wish you'd gone slower."},{"text":"Say your parents are just old-fashioned","then":"Ritika grins and offers to win them over. Now she's keener than ever to meet them."},{"text":"Tell her she's pushing too hard","then":"Ritika backs off, hurt. \"I was only asking.\""}],"why":"How much to share is your call. Sharing what feels safe helps her understand you."},{"prompt":"Next weekend, Ritika talks about coming out to her own family, and how light she felt after. What do you do?","options":[{"text":"Tell her you'll come out soon too, just like she did","then":"Ritika lights up. You go home with a deadline that feels like hers, not yours."},{"text":"Apologise for still being closeted","then":"Ritika says you've nothing to apologise for. You feel smaller anyway."},{"text":"Say her family is just more modern than yours","then":"Ritika shrugs. The talk slides into comparing families."},{"text":"Say you're happy for her, and your path is yours","then":"Ritika nods slowly. \"Fair. I'd hate for you to feel rushed.\"","best":true}],"why":"Everyone's coming-out path is different. Yours doesn't have to match hers."},{"prompt":"A month later, Ritika asks what she can do to make family stuff easier for you. What do you say?","options":[{"text":"Tell her it's your problem to deal with","then":"Ritika backs off. You carry it alone."},{"text":"Tell her what support would actually help you","then":"You ask her to keep photos off social media for now. She says done.","best":true},{"text":"Let Ritika choose the plan and the timing","then":"She picks the next family function to meet your parents. The timing is hers, not yours."},{"text":"Say she deserves someone who's already out","then":"Ritika looks stung. \"I chose you. Not a timeline.\""}],"why":"Telling her what support you need lets her back your timeline, not set it."}],"debrief":"Who knows what about your life is your call. A good match respects that.","relearn":"Your coming-out timeline is yours; name a private boundary warmly, no need to ghost."},
  {"id":"sr-1035","cat":"dating-now","type":"spot","hook":"Spot the two app nudges designed to rush you, not help you.","scene":[{"id":"a","text":"\"Take your time getting to know each match\"","trick":false},{"id":"b","text":"\"3 people are about to expire, act now!\"","trick":true},{"id":"c","text":"\"You can pause your profile anytime\"","trick":false},{"id":"d","text":"\"Upgrade in 5 minutes for a discount\"","trick":true},{"id":"e","text":"\"Fine to message only when you're free\"","trick":false}],"why":"'About to expire' and a 5-minute deadline are urgency dark patterns; the rest let you set your own pace.","relearn":"App countdowns and 'act now' deadlines are nudges to rush you, not real scarcity.","persona":"any","source":"app design"},
  {"id":"sr-1036","cat":"dating-now","type":"spot","hook":"Spot the two unrealistic expectations someone's carrying into dating.","scene":[{"id":"a","text":"\"We might not click, and that's okay\"","trick":false},{"id":"b","text":"\"If they're right, I'll feel zero nerves\"","trick":true},{"id":"c","text":"\"I'll learn who they are slowly\"","trick":false},{"id":"d","text":"\"A good match should need no effort at all\"","trick":true},{"id":"e","text":"\"Most chats fade and that's normal\"","trick":false}],"why":"'Zero nerves' and 'no effort at all' are myths; new connections bring some nerves and take real, ordinary effort.","relearn":"Real connection brings some nerves and takes effort; 'zero nerves, zero effort' is a myth.","persona":"any","source":"expectations"},
  {"id":"sr-1037","cat":"dating-now","type":"spot","hook":"Spot the two thoughts that tie your worth to the app.","scene":[{"id":"a","text":"\"A quiet week says nothing about me\"","trick":false},{"id":"b","text":"\"No matches today means I'm unlovable\"","trick":true},{"id":"c","text":"\"My value isn't a number on a screen\"","trick":false},{"id":"d","text":"\"Fewer likes than my friend means I'm worse\"","trick":true},{"id":"e","text":"\"Counts swing with luck and timing\"","trick":false}],"why":"'No matches means unlovable' and 'fewer likes means worse' hand your worth to an app; counts measure timing and luck, not you.","relearn":"Match counts measure an algorithm; your worth isn't decided by likes or a friend's count.","persona":"any","source":"self-worth"},
  {"id":"sr-1038","cat":"dating-now","type":"spot","hook":"Spot the two openers that treat a match as disposable, not a person.","scene":[{"id":"a","text":"\"Loved your hiking photo, which trail?\"","trick":false},{"id":"b","text":"\"Hey gorgeous, sending this to all my matches\"","trick":true},{"id":"c","text":"\"Your bio about old films made me smile\"","trick":false},{"id":"d","text":"\"You free tonight? Skip the chat\"","trick":true},{"id":"e","text":"\"We both love street food, best place?\"","trick":false}],"why":"The copy-paste-to-all line and 'skip the chat' rush treat a match as disposable; the rest as a person.","relearn":"A specific opener treats a match as a person; copy-pastes treat them as disposable.","persona":"any","source":"openers"},
  {"id":"sr-1039","cat":"dating-now","type":"spot","hook":"Spot the two habits that mean the app is running you.","scene":[{"id":"a","text":"\"I check it when I have a free moment\"","trick":false},{"id":"b","text":"\"I reopen it every few minutes for a hit\"","trick":true},{"id":"c","text":"\"I log off easily when it's not fun\"","trick":false},{"id":"d","text":"\"A bad swipe-session ruins my whole day\"","trick":true},{"id":"e","text":"\"I can go days without opening it\"","trick":false}],"why":"Reopening for a hit and a session ruining your day mean the app runs you; the rest keep you in charge.","relearn":"Compulsive reopening and mood-by-app mean it runs you; being able to log off keeps you in charge.","persona":"any","source":"healthy use"},
  {"id":"sr-1040","cat":"dating-now","type":"spot","hook":"Spot the two 'reasons to date' that come from pressure, not you.","scene":[{"id":"a","text":"\"I'm curious and open to meeting someone\"","trick":false},{"id":"b","text":"\"Everyone my age is paired up, so I must\"","trick":true},{"id":"c","text":"\"I'd genuinely enjoy some company\"","trick":false},{"id":"d","text":"\"It'll get my relatives off my back\"","trick":true},{"id":"e","text":"\"I like getting to know new people\"","trick":false}],"why":"'Everyone's paired so I must' and 'get relatives off my back' are pressure, not your own pull.","relearn":"Dating from FOMO or family pressure isn't for you; curiosity and wanting company are your own reasons.","persona":"Aarti","source":"motivation"},
  {"id":"sr-1041","cat":"dating-now","type":"spot","hook":"Spot the two profile lines that are red flags, not green ones.","scene":[{"id":"a","text":"\"Looking for something real, taking it slow\"","trick":false},{"id":"b","text":"\"No drama, no feelings, don't catch any\"","trick":true},{"id":"c","text":"\"Ask me about my terrible cooking\"","trick":false},{"id":"d","text":"\"Prove you're not like the others\"","trick":true},{"id":"e","text":"\"Big on long walks and bad puns\"","trick":false}],"why":"'Don't catch feelings' and 'prove you're not like the others' set a testing, contemptuous tone.","relearn":"Bios that ban feelings or set 'prove yourself' tests are red flags; warm, open lines are green.","persona":"any","source":"openers"},
  {"id":"sr-1042","cat":"dating-now","type":"match","hook":"Match the app feeling to the realistic reframe.","pairs":[{"left":"They replied slowly","right":"Probably life, not a verdict"},{"left":"My match list is quiet","right":"That's timing, not my worth"},{"left":"The chat fizzled out","right":"Normal, and not about me"},{"left":"I want a break","right":"A healthy reset, not quitting"},{"left":"Everyone seems paired up","right":"That's a highlight reel"}],"relearn":"Slow replies are life, quiet lists are timing, fizzles are normal, breaks are resets, and 'everyone's paired' is a highlight reel.","persona":"any","source":"reframes"},
  {"id":"sr-1043","cat":"dating-now","type":"match","hook":"Match the dating myth to the truth that replaces it.","pairs":[{"left":"Premium guarantees love","right":"It buys features, not connection"},{"left":"Single means behind","right":"There's no shared timetable"},{"left":"More swipes, faster luck","right":"A few thoughtful beats volume"},{"left":"A great profile, a great person","right":"You learn that over time"},{"left":"You owe every match a reply","right":"A match is an opening, not a debt"}],"relearn":"Premium buys features, single isn't behind, thoughtful beats volume, profiles aren't proof, and matches aren't debts.","persona":"any","source":"myth busting"},
  {"id":"sr-1044","cat":"dating-now","type":"match","hook":"Match the healthy app habit to why it helps.","pairs":[{"left":"Logging off when it's not fun","right":"Keeps dating a joy, not a chore"},{"left":"Messaging only when you feel it","right":"Honest, not a quota to hit"},{"left":"Taking breaks","right":"Resets you, nobody real is lost"},{"left":"A few genuine chats","right":"Beats a blast of copy-pastes"},{"left":"Closing the app calm","right":"You stayed in charge of it"}],"relearn":"Logging off, messaging when you feel it, breaks, a few genuine chats and calm closing keep the app a tool, not your boss.","persona":"any","source":"healthy use"},
  {"id":"sr-1045","cat":"dating-now","type":"match","hook":"Match what you want from dating to a clear way to say it.","pairs":[{"left":"You want something serious","right":"\"I'm looking for something real\""},{"left":"You want it casual","right":"\"I'm keeping things light right now\""},{"left":"You need to go slow","right":"\"I like taking my time getting to know people\""},{"left":"You're just curious","right":"\"I'm new to this and seeing how it feels\""},{"left":"You want a break","right":"\"I'm stepping back from apps for a bit\""}],"relearn":"Naming what you want in a plain line, whether serious, casual, slow, curious or a break, saves guessing.","persona":"any","source":"naming wants"},
  {"id":"sr-1046","cat":"dating-now","type":"match","hook":"Match the unhealthy app pull to the steadier move.","pairs":[{"left":"Checking for matches on waking","right":"Give yourself an app-free first hour"},{"left":"Mood riding on each reply","right":"Reply when free, not on alert"},{"left":"Swiping till 2am","right":"Set a stop time and keep it"},{"left":"Chasing a 'like' to feel okay","right":"Do something off-app that fills you"},{"left":"Comparing counts with friends","right":"Remember counts aren't a ranking"}],"relearn":"App-free mornings, replying when free, a stop time, off-app refills and ignoring counts steady the pull.","persona":"any","source":"healthy use"},
  {"id":"sr-1047","cat":"dating-now","type":"match","hook":"Match the kind sign-off to the situation it fits.","pairs":[{"left":"Not feeling a spark","right":"\"Lovely to match, but I'm not feeling it\""},{"left":"You've met someone else","right":"\"I've started seeing someone, take care\""},{"left":"Too busy to date now","right":"\"My plate's full right now, all the best\""},{"left":"Slowing a fast-moving chat","right":"\"Can we keep it light for a bit?\""},{"left":"Closing a faded chat","right":"\"It was nice chatting, wishing you well\""}],"relearn":"A brief, warm line fits every exit; honesty both ways beats vanishing or stringing someone along.","persona":"Rohan","source":"honesty both ways"},
  {"id":"sr-1048","cat":"dating-now","type":"role-play","persona":"Aarti","source":"agency","hook":"Bua is visiting for the week, and she has opinions about your love life.","setup":"At dinner, she turns to you, and the whole table goes quiet.","steps":[{"prompt":"Bua asks: \"Beta, all your cousins are settled. What are you waiting for?\"","options":[{"text":"\"Fine, Bua. I'll just marry whoever you pick.\"","then":"Bua's eyes light up. \"Finally! But why did you wait so long?\""},{"text":"\"That's honestly none of your business, Bua.\"","then":"Bua's face falls. The table goes stiff."},{"text":"\"I'm happy as I am. I'll know when it's right.\"","then":"Bua sniffs. \"Hmph. Okay.\" She reaches for the pickle.","best":true},{"text":"\"Soon, Bua, very soon. Please don't worry.\"","then":"Bua beams. \"I'll start looking, then!\""}],"why":"A calm, warm line holds your timeline without a fight."},{"prompt":"Bua adds: \"At your age, I already had two children.\"","options":[{"text":"\"And look how that turned out for you.\"","then":"Someone gasps. Bua sets down her spoon."},{"text":"\"That was your path, Bua. I'm happy with mine.\"","then":"Bua shakes her head, half smiling. \"Always an answer, this one.\"","best":true},{"text":"\"I know. I feel terrible about it.\"","then":"Bua nods, satisfied. \"Then let's fix it!\""},{"text":"\"Let me explain my whole five-year plan first.\"","then":"Bua finds a hole in every year of it, and she's off."}],"why":"You don't need to defend your choices. A warm, simple line is enough."},{"prompt":"Your mother says quietly: \"She means well. Just humour her a little.\"","options":[{"text":"\"Why do you always take her side, Mummy?\"","then":"Your mother sighs. \"I'm not taking sides.\""},{"text":"\"Okay. I'll say I'm meeting people.\"","then":"Your mother looks relieved. Bua asks for names by next week."},{"text":"\"I know. Can you back me when she asks?\"","then":"Your mother hesitates, then nods. \"I'll have a word with her.\"","best":true},{"text":"\"Fine. I'll just skip family dinners.\"","then":"Your mother looks hurt. \"That's not what I meant.\""}],"why":"Asking your mother for support turns her into an ally, not a messenger."},{"prompt":"Later, your cousin Nisha whispers: \"Just say you're seeing someone. It'll shut them up.\"","options":[{"text":"\"Good idea. I'll make someone up.\"","then":"Nisha grins. You start inventing a name, and it already feels heavy."},{"text":"\"Easy for you. You're already engaged.\"","then":"Nisha's smile fades. \"I was trying to help.\""},{"text":"\"Maybe something's wrong with me for not wanting it yet.\"","then":"Nisha squeezes your arm, but the thought comes home with you."},{"text":"\"I'd rather be honest. I'm just not in a rush.\"","then":"Nisha shrugs. \"Fair. I'll back you if they start again.\"","best":true}],"why":"Honesty holds up better than a made-up partner, and your pace stays yours."},{"prompt":"As you leave, Bua says: \"I'm only asking because I care about you.\"","options":[{"text":"\"Then stop asking me every single time.\"","then":"Bua looks wounded. The goodbye is stiff."},{"text":"\"If you cared, you'd let it go.\"","then":"Bua's eyes fill. Your mother gives you a look."},{"text":"\"I know, Bua. And I'm happy. Trust me on this.\"","then":"Bua pats your cheek. \"Okay, okay. Eat properly, at least.\"","best":true},{"text":"\"I know. Let's talk about it next time.\"","then":"Bua nods. \"Next time, then.\" You know she means it."}],"why":"Taking her care kindly while holding your line is what lasts."}],"relearn":"A calm, warm line holds your own timeline without a fight; your pace is yours to keep."},
  {"id":"sr-1049","cat":"dating-now","type":"role-play","persona":"any","source":"pacing","hook":"It's only day two of chatting with your match Rehaan, and he messages nonstop.","setup":"His latest message comes with three heart emojis.","steps":[{"prompt":"Rehaan writes: \"I feel like we're meant to be. Are we exclusive now?\"","options":[{"text":"\"Aww, me too! This must be fate.\"","then":"Rehaan sends ten hearts. \"I knew it!\" The pace picks up again."},{"text":"\"Why are you being so desperate about this?\"","then":"Rehaan goes quiet, then sends a stiff \"sorry\"."},{"text":"\"Maybe! Let me think about it for a bit.\"","then":"\"Take your time,\" Rehaan replies. An hour later, he asks again."},{"text":"\"I'm enjoying this. I just like taking my time.\"","then":"\"Oh. Okay,\" Rehaan writes. \"I just get excited, I guess.\"","best":true}],"why":"You can name your pace warmly. A good match welcomes 'let's take our time'."},{"prompt":"The next day, Rehaan writes: \"My friends want to know when they'll meet you.\"","options":[{"text":"\"Tell them tonight! Let's all meet up.\"","then":"Rehaan is thrilled, then asks you to say you're exclusive. You hesitate."},{"text":"\"You told your friends? Already? About me?\"","then":"\"Is that bad?\" he asks. The chat gets tense."},{"text":"\"Ha. Let's video-call first, then plan a coffee.\"","then":"\"Okay,\" Rehaan writes. \"Video call tonight, then.\"","best":true},{"text":"\"Soon! Whenever you want, honestly.\"","then":"Rehaan picks tomorrow. You haven't video-called, and you pause before saying yes."}],"why":"A video call first, and more chatting, keeps the pace yours, not his friends'."},{"prompt":"Later, Rehaan writes: \"If you really liked me, you wouldn't need time.\"","options":[{"text":"\"Maybe you're right. Maybe I'm just a cold person.\"","then":"\"You're not cold,\" he writes. \"So just say yes.\" The push continues."},{"text":"\"My friend says I'm too picky, so maybe.\"","then":"\"See? Your friend gets it,\" Rehaan writes."},{"text":"\"That feels like pressure. I'm going at my pace.\"","then":"A long pause. \"Fair. Sorry. I'll back off a bit.\"","best":true},{"text":"\"Okay. I guess that's what real love looks like.\"","then":"Rehaan sends a string of hearts. \"So we're exclusive now?\""}],"why":"Guilt-tripping your pace is pressure, not romance. Needing time is never your fault."},{"prompt":"Your friend Sneha asks: \"He's so into you. Isn't that romantic?\"","options":[{"text":"\"I guess. Maybe I'm the problem here.\"","then":"Sneha shrugs. The doubt goes home with you."},{"text":"\"It's sweet. He just really, really likes me.\"","then":"Sneha sighs happily. You push your unease away."},{"text":"\"Rushing me isn't romantic. It's pressure.\"","then":"Sneha pauses. \"Hm. When you put it like that.\"","best":true},{"text":"\"I'll give him one week to prove it's real.\"","then":"Sneha laughs. \"A trial period? Brutal.\" The pressure hasn't gone anywhere."}],"why":"Real interest can wait for your pace. Rushed intensity is worth noticing, not rewarding."}],"relearn":"You can name your own pace warmly; a good match welcomes 'let's take our time'."},
  {"id":"sr-1050","cat":"dating-now","type":"role-play","persona":"any","source":"self-worth","hook":"Tanvi laughs that your quiet match list means you're 'failing at dating'.","setup":"It's a group dinner, and it stings.","steps":[{"prompt":"Tanvi asks: \"Seriously, how many matches this week? Two?\"","options":[{"text":"\"Match counts measure the app, not me. I'm good.\"","then":"Tanvi shrugs. \"Fair. I check mine way too much anyway.\"","best":true},{"text":"\"Yeah. I'm probably just not app material.\"","then":"Tanvi pats your arm. \"Aww, don't say that.\" The table goes quiet."},{"text":"\"At least I'm not glued to my phone like you.\"","then":"\"Okay, ouch,\" Tanvi says, and the joke turns into a standoff."},{"text":"\"Two good ones. Quality over quantity, obviously.\"","then":"\"Sure, sure,\" Tanvi grins, and starts comparing numbers round the table."}],"why":"It keeps your worth off the scoreboard without starting a fight."},{"prompt":"Later, Tanvi says: \"Just swipe right on everyone. It's a numbers game.\"","options":[{"text":"\"Maybe you're right. I'll swipe on everyone tonight.\"","then":"She grins. \"That's the spirit. Send me screenshots.\""},{"text":"\"I'd rather chat with a few people I actually like.\"","then":"Tanvi thinks. \"Honestly, that sounds less tiring than my way.\"","best":true},{"text":"\"I'll just delete the app. Clearly it hates me.\"","then":"\"So dramatic,\" Tanvi laughs, not noticing that part of you means it."},{"text":"\"Numbers game? Says the one who got ghosted twice.\"","then":"Tanvi's smile drops. \"Wow. Okay.\""}],"why":"Apps are a doorway to real connection, not a count to win."},{"prompt":"On the walk home, Tanvi asks: \"Does it actually bother you, though?\"","options":[{"text":"\"A bit. Then I remember feeds are highlight reels.\"","then":"Tanvi nods. \"Same. Everyone's feed looks busier than their life.\"","best":true},{"text":"\"Not at all. Nothing like that bothers me.\"","then":"\"Okay,\" Tanvi says, not quite believing it, and you both go quiet."},{"text":"\"Only because you keep bringing it up.\"","then":"Tanvi flushes. \"Sorry. I thought we were joking around.\""},{"text":"\"Yes. Maybe something's actually wrong with me.\"","then":"Tanvi stops walking. \"Hey. Nothing's wrong with you. Stop that.\""}],"why":"Naming the sting honestly, then letting the comparison go, keeps it small."}],"relearn":"Your worth isn't a match count; you can name that lightly and let a comparison go."},
  {"id":"sr-1051","cat":"dating-now","type":"role-play","persona":"Rohan","source":"honesty both ways","hook":"After a day of chatting with Ishita, you know you're not interested.","setup":"A new message from her pops up tonight.","steps":[{"prompt":"Ishita writes: \"So, free for chai this weekend?\"","options":[{"text":"\"I've liked chatting, but I don't feel a spark.\"","then":"A pause, then: \"Oh. Okay. Thanks for being straight with me.\"","best":true},{"text":"\"Maybe! Let me check my week and tell you.\"","then":"\"Cool, tell me by Friday!\" she replies."},{"text":"\"This weekend's packed, sorry! Another time?\"","then":"\"Sure! Next weekend, then?\" Ishita asks brightly."},{"text":"\"Honestly, you're just not my type.\"","then":"\"Wow. Okay,\" she writes, and you can tell it stung."}],"why":"A brief, kind 'not feeling it' is honest without stinging more than it has to."},{"prompt":"Ishita adds: \"I'll be honest. I really liked talking to you.\"","options":[{"text":"\"That's kind. I liked it too, just not as a match.\"","then":"\"Got it,\" she writes. \"Thanks for not just vanishing.\"","best":true},{"text":"\"Aww. Let's see where it goes from here, then.\"","then":"She sends a hopeful smiley. \"Yay, okay!\""},{"text":"\"Same! We should definitely talk more.\"","then":"\"Yay!\" she replies, and starts suggesting plans."},{"text":"\"Sorry, gotta go. Busy day.\"","then":"\"Oh. Okay,\" she writes, then nothing more all evening."}],"why":"Being clear now saves her days of guessing and hoping."},{"prompt":"Your friend Kunal says: \"Just ghost next time. Way less awkward.\"","options":[{"text":"\"Less awkward for me. More hurtful for them.\"","then":"Kunal shrugs. \"Fair. I'd want a message too, honestly.\"","best":true},{"text":"\"True. Next time I'll just go quiet on them.\"","then":"Kunal nods. \"See? Easy. Nobody's owed an essay.\""},{"text":"\"Depends how many days we'd chatted.\"","then":"\"Exactly. Rules are flexible,\" Kunal says, pleased."},{"text":"\"Only if they're boring, obviously.\"","then":"Kunal laughs and starts ranking his own matches."}],"why":"A few kind words cost you a moment and spare someone days of guessing."}],"relearn":"A brief, kind 'not feeling it' beats ghosting; honesty both ways is the standard."},
  {"id":"sr-1052","cat":"dating-now","type":"role-play","persona":"Ananya","source":"beginners","hook":"New to dating apps, you match with Vivaan, who gets straight to the point.","setup":"His message arrives within minutes.","steps":[{"prompt":"Vivaan asks: \"So what are you really here for? Be honest.\"","options":[{"text":"\"I'm new to this. Just seeing how it feels.\"","then":"\"Fair enough,\" he replies. \"No fixed plan, then.\"","best":true},{"text":"\"Um, whatever you're here for, I guess.\"","then":"\"Oh, nice,\" he writes, clearly assuming you want what he wants."},{"text":"\"Why does that matter? Let's just chat.\"","then":"\"Okay, touchy,\" he writes, and the chat cools."},{"text":"\"Something serious. Definitely serious.\"","then":"\"Great, me too,\" he writes, and you feel signed up for something."}],"why":"Saying you're new and undecided is honest, and it's enough."},{"prompt":"The next day, Vivaan writes: \"Chatting is boring. Let's just meet this week.\"","options":[{"text":"\"Maybe later. I'd like to chat a bit first.\"","then":"\"Okay, your call,\" he replies, a little slower now.","best":true},{"text":"\"Sure, if that's how apps work.\"","then":"\"That's how it works,\" he writes. \"Friday?\""},{"text":"\"You're really pushy, you know that?\"","then":"\"Wow, just asking,\" he writes, and goes quiet for a while."},{"text":"\"I guess I should, or you'll lose interest.\"","then":"\"Smart,\" he writes, and sends a time and place."}],"why":"You set the pace. Chatting first is yours to choose."},{"prompt":"Two days later, Vivaan writes: \"So what's your actual plan here? Spell it out.\"","options":[{"text":"\"No plan yet, and that's okay with me.\"","then":"A pause. \"Fair. I guess we'll see.\"","best":true},{"text":"\"Something serious, I guess, if you want that.\"","then":"\"Great,\" he writes, and starts planning like it's settled."},{"text":"\"Sorry. I'm just really bad at this stuff.\"","then":"\"It's fine,\" he writes. \"I'll plan it, then.\""},{"text":"\"What do you think my plan should be?\"","then":"\"Meet me Friday,\" he replies at once, as if it's decided."}],"why":"You don't have to perform a plan you don't have. 'No plan yet' is honest."}],"relearn":"You can name being new and undecided plainly; you don't have to perform a plan you don't have."},
  {"id":"sr-1053","cat":"dating-now","type":"role-play","persona":"any","source":"naming wants","hook":"Kabir assumes from your profile that you want something casual, like him.","setup":"You're chatting late, wanting something serious.","steps":[{"prompt":"Kabir writes: \"So, keeping it chill and casual, yeah?\"","options":[{"text":"\"Actually, I want something serious.\"","then":"\"Oh,\" Kabir writes. \"Good to know. That's not really me.\"","best":true},{"text":"\"Yeah, sure. Casual's fine, I suppose.\"","then":"\"Perfect,\" he replies. \"Knew we'd vibe.\""},{"text":"\"Let's just see where it goes, yeah?\"","then":"\"Cool,\" he writes, clearly reading it as a yes."},{"text":"\"Ugh. Why does everyone want casual?\"","then":"\"Whoa, just asking,\" Kabir writes, a bit stung."}],"why":"Naming what you want early saves you both time and guesswork."},{"prompt":"Your friend Meher says: \"Go along with it. He might change his mind.\"","options":[{"text":"\"Maybe. People change once they catch feelings.\"","then":"Meher nods. \"Exactly. Give it time.\""},{"text":"\"I'd rather match with someone who wants it too.\"","then":"Meher smiles. \"Fair. Why start off pretending?\"","best":true},{"text":"\"Maybe I should delete the app. Nobody wants serious.\"","then":"Meher rolls her eyes. \"Plenty do. You just met one who doesn't.\""},{"text":"\"I'll act casual till he's hooked on me.\"","then":"Meher winces. \"That sounds exhausting for you both.\""}],"why":"You don't have to mirror a match's wants or hope they'll change."},{"prompt":"A week later, a new match, Anu, asks: \"What are you looking for here?\"","options":[{"text":"\"Something serious, at my own pace. You?\"","then":"\"Same, actually,\" Anu writes. \"Nice to hear it upfront.\"","best":true},{"text":"\"Oh, anything really. I'm easy.\"","then":"\"Very chill,\" Anu replies, and you're back to guessing."},{"text":"\"Serious. If you're not, unmatch now, please.\"","then":"Anu pauses. \"Okay, bit intense for hello, but sure.\""},{"text":"\"Let's not put labels on it so early.\"","then":"\"Sure,\" Anu writes, and the question stays unanswered."}],"why":"Saying it plainly, and asking back, starts things honestly."}],"relearn":"You don't have to mirror a match's assumption; naming what you actually want early saves both of you time."},
  {"id":"sr-1054","cat":"dating-now","type":"role-play","persona":"Meena","source":"your pace","hook":"The app is draining you, and your match Suresh keeps asking why you've gone quiet.","setup":"After your shift, his message is waiting.","steps":[{"prompt":"Suresh writes: \"Hello? Did I do something wrong?\"","options":[{"text":"\"I'm taking a break from apps. It's not about you.\"","then":"\"Oh, okay,\" he writes. \"Thanks for telling me. Look after yourself.\"","best":true},{"text":"\"Sorry! I'll try to reply more often. Promise.\"","then":"\"Good,\" he writes. \"Talk tonight, then?\""},{"text":"\"No reason. Work's just been busy lately.\"","then":"\"Busy till when?\" he asks at once."},{"text":"\"Why do you keep checking on me?\"","then":"\"I was just worried,\" Suresh writes, a little hurt."}],"why":"Naming a break plainly is honest, and stepping back is self-respect."},{"prompt":"Your roommate Lata says: \"Everyone's on the apps. You'll fall behind.\"","options":[{"text":"\"Maybe. I'll push through, even if I'm tired.\"","then":"Lata nods. \"That's the way. Keep swiping.\""},{"text":"\"There's no timetable. I'll go at my own pace.\"","then":"Lata thinks. \"True. I only swipe because everyone does.\"","best":true},{"text":"\"Easy for you. You get way more matches.\"","then":"Lata looks away. \"That's not what I meant.\""},{"text":"\"Maybe I'm just not made for dating.\"","then":"\"Don't say that,\" Lata says softly."}],"why":"There's no dating timetable. A break is a healthy choice, not a failure."},{"prompt":"A month later, Lata asks: \"So what's your plan with the apps now?\"","options":[{"text":"\"A few chats at a time, and only when I want.\"","then":"\"Sounds calmer,\" Lata says. \"Teach me that.\"","best":true},{"text":"\"Swipe every night till something works out.\"","then":"Lata laughs. \"Full power, then. Don't burn out.\""},{"text":"\"No plan. Everyone on there is fake anyway.\"","then":"\"Harsh,\" Lata says. \"Didn't you like some chats?\""},{"text":"\"Whatever you think I should do.\"","then":"Lata shrugs. \"It's your call, not mine.\""}],"why":"Using apps at your own pace, a few chats at a time, keeps it enjoyable."}],"relearn":"You can name a break plainly; stepping back when you're drained is self-respect, not rudeness."},
  {"id":"sr-1055","cat":"dating-now","type":"role-play","persona":"any","source":"reply pace","hook":"You didn't reply to Aryan for a few hours, and he sent five messages in a row.","setup":"You open the chat after class.","steps":[{"prompt":"Aryan writes: \"Hello?? Are you ignoring me?\"","options":[{"text":"\"Not ignoring you. I just don't always reply fast.\"","then":"\"Oh. Okay,\" Aryan writes. \"Sorry, I got anxious.\"","best":true},{"text":"\"Sorry sorry! I'll reply instantly from now on.\"","then":"\"Great!\" he writes, and your phone buzzes all evening."},{"text":"\"Five texts? That's a lot, honestly.\"","then":"\"Sorry for caring,\" Aryan writes, stung."},{"text":"\"I was busy. Anyway, what's up?\"","then":"\"Nothing. Just missed you,\" he writes, and sends three more."}],"why":"Naming your pace kindly sets the boundary without a fight."},{"prompt":"The next day, Aryan writes: \"You were online an hour ago. Why no reply?\"","options":[{"text":"\"I reply when I can. Tracking me isn't okay.\"","then":"\"Okay, fair,\" Aryan writes. \"I'll stop checking.\"","best":true},{"text":"\"Sorry! I'll reply the second I'm online.\"","then":"\"Deal!\" he replies. You start checking your phone in class."},{"text":"\"Aww, you noticed? That's kind of sweet.\"","then":"\"Of course I notice,\" he writes. \"I always check.\""},{"text":"\"I was in class, then lunch, then the library.\"","then":"\"Okay,\" he writes. \"Just tell me next time.\""}],"why":"Checking when you're online is pressure, not care. Your reply pace is yours."},{"prompt":"A week later, Aryan writes: \"Sorry. I get anxious when chats go quiet.\"","options":[{"text":"\"Thanks for telling me. Quiet isn't goodbye.\"","then":"\"That helps,\" he writes. \"I'll breathe more.\"","best":true},{"text":"\"That's your problem to fix, not mine.\"","then":"\"Okay,\" he writes, and the chat goes cold."},{"text":"\"Then I'll reply faster so you don't worry.\"","then":"\"You're sweet,\" he says, and the pings start again."},{"text":"\"Don't worry about it. It's totally fine.\"","then":"\"Cool,\" he writes. The next day, the texts pile up again."}],"why":"You can be kind about his worry and still keep your own pace."},{"prompt":"Later, Aryan asks: \"Is it okay if I send good-night texts?\"","options":[{"text":"\"Why ask? You'll send them anyway.\"","then":"\"Ouch,\" he writes. \"I was asking nicely.\""},{"text":"\"Of course! I'll reply to every single one.\"","then":"\"Promise?\" he writes, with three hearts."},{"text":"\"Sure. Just don't expect a reply every time.\"","then":"\"Deal,\" Aryan writes. \"Good night, then.\"","best":true},{"text":"\"Whatever you want is fine by me.\"","then":"He sends good-nights, good-mornings and a lot in between."}],"why":"A warm yes with a clear limit keeps it easy for you both."}],"relearn":"You can name your reply pace kindly; you don't owe anyone instant, on-demand replies."},
  {"id":"sr-1056","cat":"dating-now","type":"sort","hook":"Sort: a realistic thing to look for in a match, or a fantasy?","items":[{"id":"a","text":"Someone whose values mostly line up"},{"id":"b","text":"Someone who reads your mind"},{"id":"c","text":"Someone you can talk to easily"},{"id":"d","text":"Someone with zero flaws at all"},{"id":"e","text":"Someone willing to grow together"},{"id":"f","text":"Someone who fixes your whole life"}],"bins":[{"id":"real","label":"Realistic","valence":"pos"},{"id":"fantasy","label":"Fantasy","valence":"neg"}],"key":{"a":"real","b":"fantasy","c":"real","d":"fantasy","e":"real","f":"fantasy"},"relearn":"Shared values, easy talk and willingness to grow are realistic; mind-reading, zero flaws and life-fixing are fantasy.","persona":"any","source":"expectations"},
  {"id":"sr-1057","cat":"dating-now","type":"match","hook":"Match the app moment to the realistic expectation that fits it.","pairs":[{"left":"A new match","right":"A doorway, not a promise"},{"left":"A first message","right":"An opening, owed nothing"},{"left":"A few good chats","right":"Still early; let it unfold"},{"left":"A long quiet patch","right":"Often life, not a verdict"},{"left":"A profile you love","right":"Learn the real person slowly"}],"relearn":"Matches are doorways, messages owe nothing, early chats unfold, quiet is usually life, and profiles are learned slowly.","persona":"any","source":"expectations"},
  {"id":"sr-1080","cat":"fakes-and-ghosts","type":"strike-rewrite","hook":"\"If they sound exactly like my type, it's meant to be.\"","myth":{"un":"If they sound exactly like my type, it's meant to be.","re":"A stranger who mirrors your every wish may be reading you, not matching you; a live call grounds it.","why":"Scammers study a profile to become your dream."},"relearn":"A stranger who fits perfectly on day one is a tell, not fate; verify on a live call.","persona":"any","source":"too-perfect mirror"},
  {"id":"sr-1081","cat":"fakes-and-ghosts","type":"strike-rewrite","hook":"\"They sent a selfie holding a sign with my name, so they're real.\"","myth":{"un":"A selfie holding my name means they're real.","re":"Images like that can be edited or AI-made; only a live, two-way video call really verifies.","why":"A still photo proves nothing live."},"relearn":"A name-card selfie can be faked; a live two-way video call is the real check.","persona":"any","source":"fake proof"},
  {"id":"sr-1082","cat":"fakes-and-ghosts","type":"strike-rewrite","hook":"\"Their camera is 'always broken', but the chat feels so real.\"","myth":{"un":"Their camera is always broken, but the chat feels real.","re":"A camera that never works once you ask is a catfish dodge; a real match will call to reassure you.","why":"Dodging video is the core catfish tell."},"relearn":"A camera that's 'always broken' the moment you ask to call is a catfish dodge.","persona":"any","source":"video dodge"},
  {"id":"sr-1083","cat":"fakes-and-ghosts","type":"strike-rewrite","hook":"\"They're abroad on a contract, so meeting or calling is impossible.\"","myth":{"un":"They're abroad on a job, so meeting or calling is impossible.","re":"Real people abroad can still video-call; a story that rules out all verification is a scam script.","why":"The 'far-away job' is a classic scam backdrop."},"relearn":"A far-away job that conveniently blocks every video call is a scam script.","persona":"any","source":"far-away job"},
  {"id":"sr-1084","cat":"fakes-and-ghosts","type":"strike-rewrite","hook":"\"They want to move us to a private chat app right away, that's just easier.\"","myth":{"un":"Moving us off the app to a private chat right away is just easier.","re":"Rushing you off the app where there's no report button, on day one, is a common scam move.","why":"Off-app means no safety tools and no trace."},"relearn":"Being rushed off the app on day one removes your report tools; slow down.","persona":"any","source":"off-app rush"},
  {"id":"sr-1085","cat":"fakes-and-ghosts","type":"strike-rewrite","hook":"\"It's a tiny loan for their visa, and they'll pay me back.\"","myth":{"un":"It's a tiny loan for their visa, they'll pay me back.","re":"Any money ask from a match you've only met online is a scam tell, however small or urgent it sounds.","why":"Small asks test you before the big one."},"relearn":"Never send money to an online-only match, however small or urgent the ask.","persona":"any","source":"money ask"},
  {"id":"sr-1086","cat":"fakes-and-ghosts","type":"strike-rewrite","hook":"\"They cried on the call, so the emergency is obviously real.\"","myth":{"un":"They cried on the call, so the emergency is obviously real.","re":"A sudden tearful crisis that ends in a money request is the romance-scam pattern; don't pay.","why":"Pressure and emotion are the scam's tools."},"relearn":"A tearful crisis that ends in a money ask is the scam pattern; don't pay.","persona":"any","source":"crisis ask"},
  {"id":"sr-1087","cat":"fakes-and-ghosts","type":"strike-rewrite","hook":"\"They asked for a spicy photo as 'proof I trust them'. Feels romantic.\"","myth":{"un":"Sending a spicy photo to 'prove I trust them' feels romantic.","re":"An online-only match pushing for an intimate photo can be setting up blackmail; you owe no such proof.","why":"That image becomes leverage, not love."},"relearn":"An online stranger pushing for an intimate 'proof' photo can be setting up blackmail.","persona":"any","source":"sextortion bait"},
  {"id":"sr-1088","cat":"fakes-and-ghosts","type":"strike-rewrite","hook":"\"I went quiet for two weeks, better to just never reply now.\"","myth":{"un":"I went quiet for two weeks, so better to never reply now.","re":"A late, honest 'sorry, I'm not feeling a match' still beats vanishing; it's never too late to be kind.","why":"A short message respects the person."},"relearn":"It's never too late for a brief, kind sign-off instead of vanishing.","persona":"Rohan","source":"late ghost"},
  {"id":"sr-1089","cat":"fakes-and-ghosts","type":"strike-rewrite","hook":"\"Slow-fading, replying less and less, isn't really ghosting.\"","myth":{"un":"Slow-fading by replying less and less isn't really ghosting.","re":"Quietly trailing off leaves someone guessing; one honest line is kinder than a slow fade.","why":"Clarity is a kindness, not a confrontation."},"relearn":"A slow fade still leaves someone guessing; one honest line is kinder.","persona":"any","source":"slow fade"},
  {"id":"sr-1090","cat":"fakes-and-ghosts","type":"strike-rewrite","hook":"\"They blue-ticked and didn't reply, so I'll spam until they do.\"","myth":{"un":"They read it and didn't reply, so I'll keep messaging until they do.","re":"Silence after a clear message is its own answer; flooding their inbox reads as pressure, not interest.","why":"A non-reply can be a quiet no."},"relearn":"Silence after your message can be a quiet no; flooding them reads as pressure.","persona":"Rohan","source":"silence is a no"},
  {"id":"sr-1091","cat":"fakes-and-ghosts","type":"strike-rewrite","hook":"\"I got catfished, so I clearly can't trust my own judgement at all.\"","myth":{"un":"I got catfished, so I can't trust my own judgement at all.","re":"A good con is built to fool careful people; being deceived is on the deceiver, not a flaw in you.","why":"Shame is what keeps people from reporting."},"relearn":"Being catfished is on the deceiver, not a flaw in your judgement.","persona":"any","source":"no self-blame"},
  {"id":"sr-1092","cat":"fakes-and-ghosts","type":"strike-rewrite","hook":"\"They've video-called once, so now I can wire them money safely.\"","myth":{"un":"They video-called once, so now I can wire them money safely.","re":"A call verifies a face, not their honesty; an online-only match asking for money is still a scam tell.","why":"Scammers will video-call too, then ask."},"relearn":"A video call proves a face, not honesty; a money ask is still a scam tell.","persona":"any","source":"verified-then-asks"},
  {"id":"sr-1093","cat":"fakes-and-ghosts","type":"strike-rewrite","hook":"\"My new match is suspiciously like my ex. Must be a coincidence.\"","myth":{"un":"A new match weirdly like my ex must be a coincidence.","re":"A match echoing your old posts and details may be someone studying you; verify before you open up.","why":"Recycled details are a grooming tell."},"relearn":"A match echoing details from your old posts is a tell; verify before opening up.","persona":"any","source":"studied profile"},
  {"id":"sr-1094","cat":"fakes-and-ghosts","type":"strike-rewrite","hook":"\"They begged me not to tell anyone about us. That's just being private.\"","myth":{"un":"Begging me to keep us totally secret is just being private.","re":"A push to hide an online romance from every friend is how a scam avoids a reality check; tell a trusted friend.","why":"Secrecy keeps the con from being spotted."},"relearn":"A push to hide the romance from everyone is a scam move; tell a trusted friend.","persona":"any","source":"forced secrecy"},
  {"id":"sr-1095","cat":"fakes-and-ghosts","type":"strike-rewrite","hook":"\"They block the call the second I pick up, bad network, surely.\"","myth":{"un":"They drop the call the second I pick up, must be bad network.","re":"A call that fails only at the moment of seeing a face, every single time, is a catfish pattern.","why":"Consistent 'failures' aren't bad luck."},"relearn":"A call that fails only at the face-to-face moment, every time, is a catfish pattern.","persona":"any","source":"call drops"},
  {"id":"sr-1096","cat":"fakes-and-ghosts","type":"spot","hook":"Spot the two catfish red flags.","scene":[{"id":"a","text":"Happy to do a quick video call tonight","trick":false},{"id":"b","text":"Every photo looks like a glossy magazine shoot","trick":true},{"id":"c","text":"Mentions a local cafe you both know","trick":false},{"id":"d","text":"Has an excuse to dodge calls every single time","trick":true},{"id":"e","text":"Replies at normal, human hours","trick":false}],"why":"Only-perfect photos and always dodging a call are catfish tells; the rest are ordinary and fine.","relearn":"Only-glossy photos and always dodging a call are the catfish red flags.","persona":"any","source":"catfish tells"},
  {"id":"sr-1097","cat":"fakes-and-ghosts","type":"spot","hook":"Spot the two romance-scam tells.","scene":[{"id":"a","text":"Declares deep love within days of matching","trick":true},{"id":"b","text":"Suggests meeting in a public place locally","trick":false},{"id":"c","text":"Soon mentions an urgent money problem","trick":true},{"id":"d","text":"Asks normal getting-to-know-you questions","trick":false},{"id":"e","text":"Shares their actual weekend plans","trick":false}],"why":"Lightning-fast love and an early money problem are the scam pattern; the rest are normal dating.","relearn":"Fast intense love plus an early money problem are the romance-scam tells.","persona":"any","source":"scam pattern"},
  {"id":"sr-1098","cat":"fakes-and-ghosts","type":"spot","hook":"Spot the two lines that mean 'don't send money'.","scene":[{"id":"a","text":"\"Send a small recharge and I'll repay tomorrow\"","trick":true},{"id":"b","text":"\"No rush, let's just keep chatting\"","trick":false},{"id":"c","text":"\"Wire it fast or I'll be in real trouble\"","trick":true},{"id":"d","text":"\"Happy to video-call whenever you like\"","trick":false},{"id":"e","text":"\"Tell your friend we're meeting, that's smart\"","trick":false}],"why":"Any push to send money, small or urgent, is the line to catch; the calm, open lines are fine.","relearn":"Any push to send money, small or urgent, is the scam line to catch.","persona":"any","source":"money lines"},
  {"id":"sr-1099","cat":"fakes-and-ghosts","type":"spot","hook":"Spot the two fake 'proofs' of being real.","scene":[{"id":"a","text":"A live two-way video call where they match their photos","trick":false},{"id":"b","text":"\"I swear on my life I'm completely real\"","trick":true},{"id":"c","text":"Meeting you in a busy public cafe","trick":false},{"id":"d","text":"Sending five more glamour photos as 'proof'","trick":true},{"id":"e","text":"Being relaxed about you telling a friend","trick":false}],"why":"A solemn promise and extra photos prove nothing; a live call or public meet is the real check.","relearn":"A 'I swear I'm real' and more photos aren't proof; a live call or meet is.","persona":"any","source":"fake proofs"},
  {"id":"sr-1100","cat":"fakes-and-ghosts","type":"spot","hook":"Spot the two lines that are really blackmail bait.","scene":[{"id":"a","text":"\"Send me a spicy pic to prove you trust me\"","trick":true},{"id":"b","text":"\"Let's keep tonight to just chatting\"","trick":false},{"id":"c","text":"\"If you loved me you'd send one private photo\"","trick":true},{"id":"d","text":"\"A public first meet sounds great to me\"","trick":false},{"id":"e","text":"\"Your pace is fine, no pressure at all\"","trick":false}],"why":"Pressuring you for an intimate 'proof' photo is blackmail bait; you owe no such proof.","relearn":"Pressuring you for an intimate 'proof' photo is blackmail bait, not love.","persona":"any","source":"sextortion bait"},
  {"id":"sr-1101","cat":"fakes-and-ghosts","type":"spot","hook":"Spot the two ghosting moves to avoid being.","scene":[{"id":"a","text":"\"I've enjoyed this but I'm not feeling a match\"","trick":false},{"id":"b","text":"Going totally silent after weeks of real chats","trick":true},{"id":"c","text":"\"Take care, wishing you the best\"","trick":false},{"id":"d","text":"Blocking with no word after planning to meet","trick":true},{"id":"e","text":"\"Thanks for the chats, I'm stepping back\"","trick":false}],"why":"Vanishing after real chats and blocking with no word are the ghosting moves; the kind sign-offs aren't.","relearn":"Silent vanishing and a wordless block are the ghosting moves to avoid.","persona":"Rohan","source":"don't ghost"},
  {"id":"sr-1102","cat":"fakes-and-ghosts","type":"spot","hook":"Spot the two profile details that should make you pause.","scene":[{"id":"a","text":"Only one photo, no candid or everyday shots","trick":true},{"id":"b","text":"A few casual photos from different days","trick":false},{"id":"c","text":"Bio is blank but quick to ask for your number","trick":true},{"id":"d","text":"Mentions a hobby with some real detail","trick":false},{"id":"e","text":"Links to a normal, lived-in social account","trick":false}],"why":"One staged photo and an empty bio in a rush for your number are pause tells; the rest read genuine.","relearn":"One staged photo plus a blank bio rushing for your number are pause tells.","persona":"any","source":"thin profile"},
  {"id":"sr-1103","cat":"fakes-and-ghosts","type":"spot","hook":"Spot the two scam pressure tactics.","scene":[{"id":"a","text":"\"Don't tell your friends, they won't understand us\"","trick":true},{"id":"b","text":"\"Tell a friend where you'll be, that's wise\"","trick":false},{"id":"c","text":"\"Decide right now or you'll lose me forever\"","trick":true},{"id":"d","text":"\"No hurry, take all the time you need\"","trick":false},{"id":"e","text":"\"Happy to call whenever suits you\"","trick":false}],"why":"Isolating you from friends and a now-or-never ultimatum are pressure tactics; calm patience isn't.","relearn":"Isolating you from friends and now-or-never ultimatums are scam pressure tactics.","persona":"any","source":"pressure tactics"},
  {"id":"sr-1104","cat":"fakes-and-ghosts","type":"spot","hook":"Spot the two lines that lead someone on dishonestly.","scene":[{"id":"a","text":"\"Maybe someday\" when you mean never","trick":true},{"id":"b","text":"\"I'm not looking for the same thing, sorry\"","trick":false},{"id":"c","text":"Keeping them 'on hold' just for attention","trick":true},{"id":"d","text":"\"I had fun but I don't see a match\"","trick":false},{"id":"e","text":"\"Let's be honest about what we each want\"","trick":false}],"why":"A fake 'someday' and stringing someone along for attention are leading-on; the honest lines aren't.","relearn":"A false 'maybe someday' and stringing someone along are leading-on, not kindness.","persona":"any","source":"leading on"},
  {"id":"sr-1105","cat":"fakes-and-ghosts","type":"spot","hook":"Spot the two AI-fake giveaways.","scene":[{"id":"a","text":"Photos look flawless but the hands look odd","trick":true},{"id":"b","text":"A short, ordinary video clip of them talking","trick":false},{"id":"c","text":"Won't ever appear live, only sends stills","trick":true},{"id":"d","text":"Casual photos with friends tagged in them","trick":false},{"id":"e","text":"A profile that's been active for a while","trick":false}],"why":"Flawless-but-glitchy images and never appearing live point to AI fakes; the live, tagged signs don't.","relearn":"Flawless-but-glitchy photos and never appearing live point to an AI fake.","persona":"any","source":"AI fakes"},
  {"id":"sr-1106","cat":"fakes-and-ghosts","type":"spot","hook":"Spot the two reasons to report and block, not pay.","scene":[{"id":"a","text":"An online-only match demands money to 'unlock' a visit","trick":true},{"id":"b","text":"A match who's fine meeting in public soon","trick":false},{"id":"c","text":"Threats to share a private photo unless you pay","trick":true},{"id":"d","text":"Someone who video-calls without a fuss","trick":false},{"id":"e","text":"A match who respects your slower pace","trick":false}],"why":"A money demand and a threat to leak an image are report-and-block moments; the calm signs aren't.","relearn":"A money demand or a threat to leak an image means report and block, never pay.","persona":"any","source":"report not pay"},
  {"id":"sr-1107","cat":"fakes-and-ghosts","type":"spot","hook":"Spot the two fast-love-bombing tells.","scene":[{"id":"a","text":"Calls you their soulmate within the first day","trick":true},{"id":"b","text":"Asks light questions and listens to answers","trick":false},{"id":"c","text":"Plans your whole future together by week one","trick":true},{"id":"d","text":"Lets the chat build at an easy pace","trick":false},{"id":"e","text":"Is fine if you take a day to reply","trick":false}],"why":"Instant 'soulmate' talk and racing to plan a future are love-bombing tells; an easy pace isn't.","relearn":"Instant 'soulmate' talk and racing to plan a future are love-bombing tells.","persona":"any","source":"love-bombing"},
  {"id":"sr-1108","cat":"fakes-and-ghosts","type":"spot","hook":"Spot the two cruel ways to end things.","scene":[{"id":"a","text":"A short, honest \"this isn't a match for me\"","trick":false},{"id":"b","text":"A mocking screenshot shared with friends","trick":true},{"id":"c","text":"\"All the best, take care\" and then space","trick":false},{"id":"d","text":"A nasty insult on the way out the door","trick":true},{"id":"e","text":"\"I enjoyed chatting, but I'm stepping back\"","trick":false}],"why":"Mocking them publicly and a parting insult are cruel; a brief, kind sign-off never is.","relearn":"Public mockery and a parting insult are cruel; a brief, kind sign-off is decent.","persona":"any","source":"end with decency"},
  {"id":"sr-1109","cat":"fakes-and-ghosts","type":"branch","persona":"any","source":"deepfake check","hook":"Neel sends a romantic video that looks oddly smooth, then says no to a live call.","steps":[{"prompt":"He says the clip should be proof enough. What do you do?","options":[{"text":"Accept the clip as proof and open up","then":"Neel starts asking about your family and where you live."},{"text":"Say you'd still like a quick live call","then":"Neel says his network is bad tonight and sends another clip.","best":true},{"text":"Send a video of your own to match it","then":"Neel replies with hearts and asks for a more private one."},{"text":"Tell him the clip is obviously fake","then":"Neel acts wounded and says you've hurt him deeply."}],"why":"A recorded clip can be faked. A live two-way call is the check that works."},{"prompt":"Two days later, Neel says real love doesn't need a video call. What do you do?","options":[{"text":"Agree, since he sounds so sincere","then":"The chats get deeper, still without ever seeing him live."},{"text":"Apologise for being so suspicious","then":"Neel forgives you warmly, and the call never happens."},{"text":"Ask a friend to check his clip for glitches","then":"Your friend can't tell either way. The clip settles nothing."},{"text":"Say a live call is simply your rule","then":"Neel goes quiet, then sends a long paragraph about being hurt.","best":true}],"why":"Wanting a live call isn't distrust. It's a normal check, and yours to keep."},{"prompt":"Neel still won't call, but sends another perfect clip. What do you do?","options":[{"text":"Report the profile and stop sharing details","then":"The app reviews the profile, and your chat goes quiet.","best":true},{"text":"Keep chatting, since the clips feel real","then":"Neel starts hinting he needs help with a visa fee."},{"text":"Give him one more week to call","then":"The week passes with more clips and no call."},{"text":"Post his clip in a group chat as a warning","then":"The group chat blows up, and his profile stays live."}],"why":"A polished clip plus a refused call points to a fake. Report and step back."}],"debrief":"A polished clip plus a refused call points to a fake.","relearn":"A refused live call after a too-smooth video points to a fake; insist on the call."},
  {"id":"sr-1110","cat":"fakes-and-ghosts","type":"branch","persona":"any","source":"crisis money","hook":"Your online-only match Rhea says her mother is in hospital and needs money tonight.","steps":[{"prompt":"She's crying in voice notes and asks for ₹5,000. What do you do?","options":[{"text":"Send a small amount, just this once","then":"Rhea thanks you. By morning there's a new bill."},{"text":"Say you won't send money, and suggest local help","then":"Rhea sobs that you don't care, then goes quiet for hours.","best":true},{"text":"Send it, and ask her to repay next week","then":"Rhea promises. Her next message asks for more."},{"text":"Ask for a photo of the hospital bill as proof","then":"A photo of a bill arrives in minutes, looking official."}],"why":"A crisis that ends in a money ask from a stranger is the scam."},{"prompt":"The next day, Rhea's 'cousin' messages you, begging for help. What do you do?","options":[{"text":"Send a little to the cousin instead","then":"The cousin thanks you and says the doctor needs more."},{"text":"Reply to explain why you can't help","then":"The cousin argues back with a longer, sadder story."},{"text":"Don't engage, and report both profiles","then":"The cousin's account disappears within the day.","best":true},{"text":"Wonder if you're being heartless","then":"You replay the voice notes, and the guilt pulls you back."}],"why":"A second person joining the ask is part of the script. Report it and don't pay."},{"prompt":"Your roommate Farah asks why you look so upset. What do you do?","options":[{"text":"Tell her what happened and show her the chats","then":"Farah reads them. \"This is a scam,\" she says. \"Not your fault.\"","best":true},{"text":"Say nothing. It's too embarrassing","then":"Farah drops it, and you carry it alone all night."},{"text":"Ask her to lend you money for Rhea","then":"Farah frowns and asks who Rhea is."},{"text":"Say a friend is in trouble and ask for advice","then":"Farah gives general advice that doesn't quite fit."}],"why":"Telling someone you trust breaks the scam's grip. Being targeted isn't your fault."},{"prompt":"That night, Rhea messages: 'I thought you were different.' What do you do?","options":[{"text":"Apologise and promise to help next month","then":"Rhea replies at once with a date for next month."},{"text":"Reply with a long message explaining yourself","then":"Rhea picks apart every line and asks again."},{"text":"Believe a scammer wouldn't sound this hurt","then":"Her hurt feels real, and you reopen the chat."},{"text":"Block the profile without replying","then":"Her message sits unread in a blocked chat.","best":true}],"why":"Guilt is the scam's last lever. You don't owe it a reply."}],"debrief":"A crisis ending in a money ask from a stranger is the scam.","relearn":"An urgent crisis ending in a money ask online is the scam pattern; don't pay."},
  {"id":"sr-1111","cat":"fakes-and-ghosts","type":"branch","persona":"any","source":"catfish call","hook":"Arjun is lovely in chat, but his photos look like a shoot and he dodges every call.","steps":[{"prompt":"He suggests meeting next week instead of a call. What do you do?","options":[{"text":"Agree to meet. A call can come later","then":"Arjun picks a place, and still hasn't shown his face live."},{"text":"Assume he's shy, and pour your heart out","then":"You share a lot, and he mirrors it back perfectly."},{"text":"Keep it light, and ask for a live call first","then":"Arjun says maybe, then changes the subject.","best":true},{"text":"Ask him for more photos to be sure","then":"He sends three more, just as polished."}],"why":"Verify before investing. A live call is the check that counts."},{"prompt":"Arjun says his data has run out and asks you to recharge it so he can call. What do you do?","options":[{"text":"Recharge it. It's only a little","then":"The call never comes. Next, he needs a phone repair."},{"text":"Say no to money, and let him call when he can","then":"Arjun sends a sad face and says he understands.","best":true},{"text":"Send it, but make him promise to repay you","then":"He promises, and the promise is all you get."},{"text":"Tell him to stop lying to you","then":"Arjun acts hurt and goes silent for two days."}],"why":"A money ask to enable a call is a scam loop. A real call costs you nothing."},{"prompt":"A week on, Arjun still hasn't called. What do you do?","options":[{"text":"Give him one more chance to call","then":"He has a new excuse ready within the hour."},{"text":"Tell yourself real people are just busy","then":"The chats go on, and you still don't know who he is."},{"text":"Keep chatting, but share nothing personal","then":"It feels safer, but you're still investing in someone unseen."},{"text":"Step back, report, and tell a friend","then":"The app logs your report. Your friend Tanvi says: \"I'm glad you told me. I'm here if he tries again.\"","best":true}],"why":"Perfect photos plus dodged calls is the catfish pattern. Walk away, and let a friend in."},{"prompt":"Days later, his photos turn up on a model's page. Your friend Mansi says she'd have 'known straight away'. What do you say?","options":[{"text":"It's on the person faking it, not me","then":"Mansi pauses. \"Fair. They're good at it.\"","best":true},{"text":"You're right. I'm so gullible","then":"Mansi nods, and the shame follows you home."},{"text":"Laugh along so it seems like no big deal","then":"Mansi laughs too, and the sting stays with you."},{"text":"You'd have fallen for it too, trust me","then":"Mansi bristles. \"I really wouldn't have.\""}],"why":"Being catfished is on the deceiver, never your fault."}],"debrief":"Perfect photos plus dodged calls is the catfish pattern.","relearn":"Only-perfect photos plus dodged calls is the catfish pattern; verify with a call."},
  {"id":"sr-1112","cat":"fakes-and-ghosts","type":"branch","persona":"Rohan","source":"don't fade","hook":"You've chatted warmly with Tara for two weeks, but you're just not feeling it.","steps":[{"prompt":"She sends a funny meme and asks about your day. What do you do?","options":[{"text":"Let your replies get shorter until it fades","then":"Tara keeps sending memes, and asks if you're okay."},{"text":"Reply, then say kindly it's not a match for you","then":"Tara replies: \"Oh. Thanks for saying it. Good luck!\"","best":true},{"text":"Leave her on read, in case you change your mind","then":"Tara checks the chat, waits, and checks again."},{"text":"Say you're busy this month and will write later","then":"Tara says no worries, and waits for 'later'."}],"why":"After real chats, a short kind message beats a slow fade."},{"prompt":"Your friend Varun says keeping a few chats warm 'as backup' is smart. What do you say?","options":[{"text":"Makes sense. Options are good","then":"You leave three chats half-open, and the guilt builds."},{"text":"Only if they never find out","then":"Varun laughs, but you both know people notice."},{"text":"It's leading people on. I'd rather be honest","then":"Varun shrugs. \"Fine, fine.\" But he looks thoughtful.","best":true},{"text":"Backup's fine if you're polite about it","then":"Polite or not, someone is still waiting on you."}],"why":"Keeping someone on hold is leading on. Honesty lets them move on."},{"prompt":"A new match, Pooja, asks for a second date, and you're not keen. What do you do?","options":[{"text":"Say yes to be polite, then cancel later","then":"Pooja books a table and tells her friends."},{"text":"Go quiet and hope she gets the hint","then":"Pooja messages twice more, puzzled."},{"text":"Say you're not ready for anything right now","then":"Pooja says she'll wait, and checks in a month later."},{"text":"Thank her and say you don't feel a match","then":"Pooja replies: \"Appreciate it. All the best.\"","best":true}],"why":"A clear, kind no lets her move on. A white lie keeps her waiting."}],"debrief":"After real conversation, a brief honest goodbye beats a silent fade.","relearn":"After real chats, end it with a short kind message, not a silent fade."},
  {"id":"sr-1113","cat":"fakes-and-ghosts","type":"branch","persona":"any","source":"blackmail","hook":"Someone you've never met threatens to leak your private chat unless you pay by tonight.","steps":[{"prompt":"Your hands are shaking as you read it. What do you do first?","options":[{"text":"Believe them that one payment ends it","then":"You reply asking how much, and they raise the amount."},{"text":"Screenshot the threat, then block them","then":"The account can't reach you now, and your screenshots are saved.","best":true},{"text":"Tell yourself it's your fault for chatting","then":"The shame makes you want to hide, and the deadline creeps closer."},{"text":"Delete the whole chat so there's no trace","then":"The chat is gone, and so is your proof."}],"why":"Paying invites more demands. Saving proof and blocking cuts their leverage."},{"prompt":"An hour later, a new account messages you with the same threat. What do you do?","options":[{"text":"Follow a friend's advice to just pay quickly","then":"Paying brings a thank-you and a second, larger demand."},{"text":"Decide it's not serious enough to report","then":"The new account keeps messaging, and you face it alone."},{"text":"Report it to cybercrime 1930 with screenshots","then":"The helpline takes your details and tells you what to do next.","best":true},{"text":"Keep it secret so nobody ever finds out","then":"You check your phone every minute, alone with it."}],"why":"Cybercrime 1930 is there for exactly this. Reporting puts it on them."},{"prompt":"That night you can't sleep, wondering if it's your fault. What do you do?","options":[{"text":"Tell a trusted friend what's happening","then":"Your friend Noor comes over. \"This is on them,\" she says. \"Not you.\"","best":true},{"text":"Decide you deserve it for trusting someone","then":"The shame sits heavy, and you stay up alone."},{"text":"Keep checking their profiles for a post","then":"Hours pass on their pages, and the fear only grows."},{"text":"Believe any friend would judge you for this","then":"You keep it to yourself, and the night drags on alone."}],"why":"Blackmail is on the blackmailer, never your fault. Support helps you carry it."},{"prompt":"Next morning, one more message arrives: 'Last chance.' What do you do?","options":[{"text":"Think paying now is the only way out","then":"You start typing to ask how much, and the fear doesn't ease."},{"text":"Reply once to tell them off","then":"They answer instantly, and now they know you're reading."},{"text":"Hide your phone and tell nobody","then":"The morning passes with the fear all yours."},{"text":"Save it and report to cybercrime 1930","then":"The helpline logs it, and you put the phone down.","best":true}],"why":"Threats are how blackmail works. Proof and a report keep it on them, not you."}],"debrief":"A pay-or-I-leak threat is blackmail, and it's on them, never your fault.","relearn":"A pay-or-I-leak threat is blackmail; don't pay, block, report to cybercrime 1930."},
  {"id":"sr-1114","cat":"fakes-and-ghosts","type":"branch","persona":"any","source":"off-app pressure","hook":"On day one, Samar insists you leave the app and chat only on his private number.","steps":[{"prompt":"He says the app is unreliable and he hates it. What do you do?","options":[{"text":"Stay on the app until you've video-called","then":"Samar grumbles, but keeps chatting on the app for now.","best":true},{"text":"Switch over. The app is glitchy anyway","then":"Samar now has your number, and the app's report button is gone."},{"text":"Switch, and share your area so he trusts you","then":"Samar now knows your number and your area after one day."},{"text":"Give him a spare number you rarely use","then":"It feels safer, but you've still left the app's tools behind."}],"why":"The app's tools protect you while you check someone out."},{"prompt":"The next day, Samar sends new selfies but says video calls are 'too much' this early. What do you do?","options":[{"text":"Agree. Maybe a call is too much to ask","then":"Samar relaxes, and you still haven't seen him live."},{"text":"Say a short call is your rule, and hold it","then":"Samar sighs, then says fine, maybe this weekend.","best":true},{"text":"Drop the call, but ask for a few more selfies","then":"Two new selfies arrive, and they prove nothing."},{"text":"Call him a fake and tell him off","then":"Samar floods the chat with angry messages."}],"why":"A short live call is a fair ask. A real match doesn't mind it."},{"prompt":"By the weekend, Samar is pushing to meet and says you're 'wasting his time'. What do you do?","options":[{"text":"Wonder if you're being too fussy","then":"The doubt grows, and his messages keep coming."},{"text":"Argue back until he admits he's being rude","then":"The argument drags on for an hour and settles nothing."},{"text":"Take a friend's advice to give him a chance","then":"You give it a day, and the pushing only gets louder."},{"text":"Block him, report him, and tell a friend","then":"His messages stop. Your friend Tara says: \"That was pressure. None of it was on you.\"","best":true}],"why":"Pushing and guilt-trips are a scam move, never your fault. Block, report and let a friend in."}],"debrief":"Day-one pressure to go off-app is a common scam move.","relearn":"Day-one pressure to go off-app removes your safety tools; verify before you move."},
  {"id":"sr-1115","cat":"fakes-and-ghosts","type":"branch","persona":"any","source":"warn a friend","hook":"Ritika glows about Sameer, her online-only love, who now wants a 'small loan'.","steps":[{"prompt":"She asks if she should send it. What do you say?","options":[{"text":"Gently name the fast-love-then-money pattern","then":"Ritika goes quiet, then says, \"He's not like that, though.\"","best":true},{"text":"Stay out of it so you don't upset her","then":"Ritika takes your silence as a yes and opens her banking app."},{"text":"Tell her she's being naive","then":"Ritika's face closes. \"You just don't get it.\""},{"text":"Say send it only if he promises to repay","then":"Ritika brightens. \"He will. He always keeps his word.\""}],"why":"A gentle heads-up gives her room to step back without shame."},{"prompt":"The next day, Ritika says Sameer has promised to visit soon. What do you say?","options":[{"text":"That's great. I'm really happy for you both","then":"Ritika beams and tells him you approve."},{"text":"He'll never visit. It's a scam","then":"Ritika snaps that you're jealous and walks off."},{"text":"Ask if they've ever had a live video call","then":"Ritika hesitates. \"His camera's broken,\" she says slowly.","best":true},{"text":"Offer to check his profile for her","then":"The photos look real to you both, which settles nothing."}],"why":"A gentle question helps her see it herself, which lasts longer than a warning."},{"prompt":"A week later, Ritika calls, upset: Sameer has asked for more. What do you say?","options":[{"text":"I told you so","then":"Ritika hangs up, and you don't hear from her for days."},{"text":"Not your fault. Want to report him together?","then":"Ritika exhales. \"Okay. Sit with me while I do it?\"","best":true},{"text":"Send it one last time, then stop","then":"Ritika sends it. Two days later, the next ask comes."},{"text":"Give me his number. I'll sort him out myself","then":"Sameer blocks you and tells Ritika you're jealous."}],"why":"Scams are on the scammer. Support and a report help more than blame."},{"prompt":"Days later, Ritika messages that she feels too stupid to tell anyone else. What do you say?","options":[{"text":"You should tell your parents right now","then":"Ritika tenses. \"No way. Not yet.\""},{"text":"It's their trick, not your failing. I'm here","then":"Ritika nods. \"Maybe I'll tell my sister too.\"","best":true},{"text":"Okay. We'll keep it between us forever","then":"Ritika agrees, and carries the shame quietly."},{"text":"Honestly, you should have seen it coming","then":"Ritika's eyes fill, and she goes quiet."}],"why":"Believing her and letting her set the pace helps her heal and speak up."}],"debrief":"Fast love then a money ask is the classic scam, and it's never the target's fault.","relearn":"Warn a friend kindly that fast-love-then-money is the classic scam pattern."},
  {"id":"sr-1116","cat":"fakes-and-ghosts","type":"branch","persona":"any","source":"shifting story","hook":"Your match Karan was a doctor abroad, then a soldier, and now says he's an engineer.","steps":[{"prompt":"He says you must have misremembered. What do you do?","options":[{"text":"Assume you mixed it up, and carry on","then":"Karan's story gains a new detail every day."},{"text":"Note the contradictions and pause the chat","then":"Karan sends a long, charming message explaining it all away.","best":true},{"text":"Call out the lies and demand the truth","then":"Karan turns it round and says you're paranoid."},{"text":"Ask for his work profile to check","then":"A polished profile arrives, and it proves nothing either way."}],"why":"Shifting stories are a scam tell, not a problem with your memory."},{"prompt":"Karan now says he's stuck at a port and needs customs fees paid. What do you do?","options":[{"text":"Pay half, just to show you really care","then":"Karan thanks you, and the fees somehow double."},{"text":"Ask for the customs papers before you pay","then":"Official-looking papers arrive within minutes."},{"text":"Feel bad for doubting him earlier","then":"The guilt softens you, and the fee question hangs."},{"text":"Say no. You don't send money to matches","then":"Karan sends crying emojis, then asks again an hour later.","best":true}],"why":"Never send money to someone you've only met online. A shifting story, then a money ask, is the scam pattern."},{"prompt":"Karan says you're the only one who understands him. What do you do?","options":[{"text":"Give him a chance to explain properly","then":"Another long story arrives, different again."},{"text":"Step back, report, and tell a friend","then":"The app reviews the profile. Your friend Nisha says: \"Classic scam. Glad you told me.\"","best":true},{"text":"Tell him you're done and he's a liar","then":"Karan sends angry messages for an hour."},{"text":"Keep chatting, but only as friends","then":"Karan agrees, and the money hints continue."}],"why":"You can step back without a row, and a friend helps. Being targeted is never your fault."},{"prompt":"A week later, a new match's story sounds a lot like Karan's. What do you do?","options":[{"text":"Assume every match is a scammer now","then":"You unmatch everyone, and the app starts to feel like enemy ground."},{"text":"Ignore it. Lightning doesn't strike twice","then":"The chat speeds up, and the questions stay unasked."},{"text":"Ask them outright if they're a scammer","then":"They laugh it off, and you learn nothing."},{"text":"Slow down, and ask for a live call early","then":"The match agrees to a call on Sunday, and you'll see for yourself.","best":true}],"why":"Spotting the pattern early, then verifying, lets you keep dating freely."}],"debrief":"A backstory that keeps changing is a scam tell.","relearn":"A backstory that keeps changing is a scam tell; slow down before trusting."},
  {"id":"sr-1117","cat":"fakes-and-ghosts","type":"branch","persona":"Rohan","source":"late closure","hook":"Weeks after you ghosted Neha, she messages asking why you vanished.","steps":[{"prompt":"She says she thought something had happened to you. What do you do?","options":[{"text":"Apologise briefly and say it wasn't a match","then":"Neha replies: \"Okay. That hurt, but thanks for saying it.\"","best":true},{"text":"Block her so you needn't deal with it","then":"Neha sees the chat vanish and feels it all over again."},{"text":"Make up a family emergency as the reason","then":"Neha is sympathetic and asks when you can talk."},{"text":"Explain every reason you lost interest","then":"Neha reads the list and feels picked apart."}],"why":"Owning it briefly gives her closure without new hurt."},{"prompt":"Your friend Karthik says apologising just 'shows weakness'. What do you say?","options":[{"text":"Maybe. I won't do it again","then":"Karthik nods, and you feel a little smaller."},{"text":"People like it when you stay a bit mysterious","then":"Karthik agrees, and you both drop the subject."},{"text":"Owning a mistake takes more nerve than hiding","then":"Karthik thinks, then admits he's ghosted people and felt bad.","best":true},{"text":"I only replied so she'd stop messaging","then":"Karthik laughs, and the point gets lost."}],"why":"Taking responsibility is a strength. Honesty runs both ways."},{"prompt":"A month later, you lose interest in a new match, Ria. What do you do?","options":[{"text":"Ghost her. It worked out last time","then":"Ria's messages go unanswered, and the pattern repeats."},{"text":"Keep chatting till she loses interest","then":"Weeks pass, and she's still planning to meet."},{"text":"Ask a mutual friend to tell her for you","then":"Ria hears it second-hand and feels even more dismissed."},{"text":"Send a short, kind message ending it","then":"Ria replies: \"Thanks for telling me. Take care.\"","best":true}],"why":"A kind sign-off at the start saves a late apology later."}],"debrief":"Even late, a short honest apology beats blocking or a fake excuse.","relearn":"Even late, a short honest 'it wasn't a match' beats blocking or a fake excuse."},
  {"id":"sr-1118","cat":"fakes-and-ghosts","type":"branch","persona":"any","source":"trust unease","hook":"Mahir's new selfie looks subtly off, and he gets defensive when you ask to call.","steps":[{"prompt":"He writes that asking for a call means you don't trust him. What do you do?","options":[{"text":"Apologise for doubting him and drop it","then":"Mahir forgives you, and the call is never mentioned again."},{"text":"Trust the unease and still ask for a call","then":"Mahir sends an annoyed 'fine, later' and changes the topic.","best":true},{"text":"Decide it's fine, since he seems upset","then":"You feel bad for him, and your unease goes quiet."},{"text":"Zoom into the selfie hunting for flaws","then":"You stare for ages and can't prove anything either way."}],"why":"Your unease is information. A basic call is a fair check."},{"prompt":"The next day, Mahir sends a sweet voice note and asks to meet. What do you do?","options":[{"text":"Meet him in public. That's safe enough","then":"You pick a cafe, still unsure who will walk in."},{"text":"Say yes. The voice note sounds real","then":"Mahir picks the place and time himself."},{"text":"Say a live call comes before any meet","then":"Mahir sighs. \"Okay, okay,\" he writes, but doesn't set a time.","best":true},{"text":"Ignore the invite and hope he stops","then":"Mahir asks again, a little impatient."}],"why":"A live call first means you know who you're meeting."},{"prompt":"Mahir writes that he never video-calls before a first meet, and anyone who asks is paranoid. What do you do?","options":[{"text":"Hold out for a call, and pass if he won't","then":"Mahir goes quiet. You feel lighter than you expected.","best":true},{"text":"Wonder if you really are paranoid","then":"You second-guess yourself, and his messages keep coming."},{"text":"Ask him to prove he's not a fake","then":"Mahir sends a new selfie. It looks off too."},{"text":"Screenshot his selfie to roast in the group","then":"The group laughs, and you still don't know who he is."}],"why":"Defensiveness about a basic call is itself a tell. Your check stands."}],"debrief":"An off selfie plus call-dodging is a fake tell.","relearn":"An off-looking selfie plus defensiveness about a call is a fake tell; keep asking."},
  {"id":"sr-1119","cat":"fakes-and-ghosts","type":"sort","hook":"Sort: a real way to verify a match, or a fake reassurance?","items":[{"id":"a","text":"A live two-way video call"},{"id":"b","text":"\"I promise I'm real, trust me\""},{"id":"c","text":"Meeting in a busy public place"},{"id":"d","text":"Sending one more posed selfie"},{"id":"e","text":"A short candid clip with background sound"},{"id":"f","text":"A name-card photo that could be edited"}],"bins":[{"id":"real","label":"Real check","valence":"pos"},{"id":"fake","label":"Not a check","valence":"neg"}],"key":{"a":"real","b":"fake","c":"real","d":"fake","e":"real","f":"fake"},"relearn":"Live calls, public meets and candid clips verify; promises and posed photos don't.","persona":"any","source":"verify vs reassure"},
  {"id":"sr-1120","cat":"fakes-and-ghosts","type":"sort","hook":"Sort: ordinary match, or romance-scam tell?","items":[{"id":"a","text":"Declares true love within days"},{"id":"b","text":"Suggests a public local first meet"},{"id":"c","text":"Soon needs urgent money"},{"id":"d","text":"Asks normal getting-to-know-you stuff"},{"id":"e","text":"Refuses every video call"},{"id":"f","text":"Is relaxed if you reply late"}],"bins":[{"id":"ok","label":"Ordinary","valence":"pos"},{"id":"tell","label":"Scam tell","valence":"neg"}],"key":{"a":"tell","b":"ok","c":"tell","d":"ok","e":"tell","f":"ok"},"relearn":"Fast love, a money need and dodged calls are scam tells; the calm, open signs aren't.","persona":"any","source":"scam tells sort"},
  {"id":"sr-1121","cat":"fakes-and-ghosts","type":"sort","hook":"Sort: honest dating, or leading someone on?","items":[{"id":"a","text":"Saying clearly you're not feeling it"},{"id":"b","text":"A fake \"maybe someday\" you don't mean"},{"id":"c","text":"Being upfront about what you want"},{"id":"d","text":"Keeping someone on hold for attention"},{"id":"e","text":"A short, kind goodbye after real chats"},{"id":"f","text":"Slow-fading so they have to guess"}],"bins":[{"id":"honest","label":"Honest","valence":"pos"},{"id":"not","label":"Leading on","valence":"neg"}],"key":{"a":"honest","b":"not","c":"honest","d":"not","e":"honest","f":"not"},"relearn":"Clear nos and upfront goodbyes are honest; fake maybes and slow fades lead people on.","persona":"any","source":"honesty sort"},
  {"id":"sr-1122","cat":"fakes-and-ghosts","type":"sort","hook":"Sort: which red-flag move calls for which response?","items":[{"id":"a","text":"They refuse to ever video-call"},{"id":"b","text":"They demand money to visit you"},{"id":"c","text":"They threaten to leak a private image"},{"id":"d","text":"They keep pushing past your slower pace"},{"id":"e","text":"They want you off-app on day one"},{"id":"f","text":"They never appear live, only stills"}],"bins":[{"id":"dontmeet","label":"Don't meet, verify","valence":"uhoh"},{"id":"report","label":"Report it","valence":"tell"}],"key":{"a":"dontmeet","b":"report","c":"report","d":"dontmeet","e":"dontmeet","f":"dontmeet"},"relearn":"Won't-call and pushy moves mean don't meet yet; money demands and leak threats mean report.","persona":"any","source":"flag to move"},
  {"id":"sr-1123","cat":"fakes-and-ghosts","type":"sort","hook":"Sort: what a real person does, or what a fake profile does?","items":[{"id":"a","text":"Has casual photos from different days"},{"id":"b","text":"Only one flawless, posed image"},{"id":"c","text":"Happy to video-call this week"},{"id":"d","text":"Avoids calls with a new excuse each time"},{"id":"e","text":"Shares small, real everyday details"},{"id":"f","text":"Rushes to declare love and ask for money"}],"bins":[{"id":"real","label":"Real person","valence":"pos"},{"id":"fake","label":"Fake profile","valence":"neg"}],"key":{"a":"real","b":"fake","c":"real","d":"fake","e":"real","f":"fake"},"relearn":"Casual photos, easy calls and real details read genuine; flawless stills and rush-then-ask don't.","persona":"any","source":"real vs fake"},
  {"id":"sr-1124","cat":"fakes-and-ghosts","type":"role-play","persona":"any","source":"hold the check","hook":"Your match Zain keeps dodging video calls with a new excuse each time.","setup":"Tonight he wants to plan a meet.","steps":[{"prompt":"Zain writes: \"Calls are awkward. Let's just meet Saturday?\"","options":[{"text":"\"Okay, forget the call. I'll just trust you.\"","then":"\"Great!\" Zain replies, and names a place you don't know."},{"text":"\"No worries, but I like a quick live call first.\"","then":"\"Ugh, fine,\" Zain writes. \"Maybe tomorrow.\"","best":true},{"text":"\"Why are you always making excuses?\"","then":"\"Relax,\" Zain writes. \"Not everyone likes calls.\""},{"text":"\"Sure, as long as we meet somewhere public.\"","then":"\"Deal,\" Zain writes, still without a single call."}],"why":"A live call before meeting is a normal check. A real match won't mind."},{"prompt":"The next day, Zain writes: \"By the way, my camera's broken. Just so you know.\"","options":[{"text":"\"No problem. We don't need a call anyway.\"","then":"\"Perfect,\" he writes, and the topic closes."},{"text":"\"Then use your laptop. Right now.\"","then":"\"Whoa, bossy,\" Zain writes, and goes offline."},{"text":"\"Sure. We can call once it's fixed.\"","then":"A pause. \"Yeah... could be a while.\"","best":true},{"text":"\"Just send me a voice note instead.\"","then":"A smooth voice note arrives. It proves very little."}],"why":"Kindness and your check can go together. The call stays on the list."},{"prompt":"On Friday, Zain writes: \"So, tomorrow? Or are you backing out on me?\"","options":[{"text":"\"Sorry. Maybe I'm just too suspicious.\"","then":"\"You are,\" Zain writes. \"So, tomorrow at six?\""},{"text":"\"Fine. Unmatching you now, liar.\"","then":"\"Wow,\" Zain writes, and the chat ends in a row."},{"text":"\"Let's chat another month and then see.\"","then":"\"Sure,\" he writes, and the excuses keep coming."},{"text":"\"No call, no meet. That's my rule.\"","then":"Zain stops replying. You feel a flicker of relief.","best":true}],"why":"Pressure to drop your check is on him, never your fault. No call yet means no meet yet."},{"prompt":"Later, your friend Riya asks: \"Why not just meet matches and see? Calls are so awkward.\"","options":[{"text":"\"Zain dodged calls, then pushed me. That's why.\"","then":"Riya frowns. \"That sounds off. Tell me if he messages again.\"","best":true},{"text":"\"Maybe you're right. Photos look real enough.\"","then":"Riya shrugs. \"Just be careful, yaar.\""},{"text":"\"Because meeting strangers is always risky.\"","then":"Riya laughs. \"Then why be on the app at all?\""},{"text":"\"I might, if it's somewhere public.\"","then":"\"That's something,\" Riya says. \"You still won't know who they are.\""}],"why":"Telling a friend about Zain gets you backup. A call before meeting keeps dating free and safe."}],"relearn":"It's fair to keep asking for a live call before meeting; a real match won't mind."},
  {"id":"sr-1125","cat":"fakes-and-ghosts","type":"role-play","persona":"any","source":"no-money line","hook":"Mehul, an online-only match you really like, keeps hinting that he's broke.","setup":"His message lands late at night.","steps":[{"prompt":"Mehul writes: \"Rent's due and I'm short. Life is so unfair.\"","options":[{"text":"\"How much do you need? I'll figure something out.\"","then":"\"Just ₹8,000,\" he writes instantly."},{"text":"\"That sounds stressful. I'm happy to listen.\"","then":"\"Thanks,\" Mehul writes. \"Wish you could do more, though.\"","best":true},{"text":"\"Sounds like a you problem, honestly.\"","then":"\"Wow. Cold,\" Mehul writes, and goes quiet."},{"text":"\"Maybe I can help out a little this month?\"","then":"\"Would you? You're an angel,\" he replies."}],"why":"You can be warm without stepping into his money problems."},{"prompt":"The next day, Mehul writes: \"Could you send ₹8,000 today? I'll pay you back.\"","options":[{"text":"\"Okay. Let me see what I can manage.\"","then":"\"Knew it,\" Mehul writes, and sends his UPI ID."},{"text":"\"I don't send money to online-only matches.\"","then":"\"Wow. Okay,\" Mehul writes, and goes quiet for a day.","best":true},{"text":"\"So is it just my money you like?\"","then":"\"How could you say that?\" he writes, with sad emojis."},{"text":"\"Let's talk about the money after we meet.\"","then":"\"We can't meet till I sort this,\" he replies."}],"why":"A money ask from an online-only match is a scam tell. A no-money line protects you."},{"prompt":"Later, Mehul writes: \"If you really cared, you'd have sent it by now.\"","options":[{"text":"\"I do care! I'm sorry. Please don't be upset.\"","then":"\"Then prove it,\" he writes, and the ask returns."},{"text":"\"You're clearly a scammer. Bye.\"","then":"Mehul sends an angry voice note and blocks you."},{"text":"\"Maybe we can work out a smaller amount?\"","then":"\"Even ₹2,000 would help,\" he replies at once."},{"text":"\"I liked chatting. My no-money line stays.\"","then":"No reply comes. The chat quietly ends there.","best":true}],"why":"Keeping your line, warmly, is enough. Being targeted like this is never your fault."},{"prompt":"Your roommate Kabir asks: \"You've been frowning at your phone all night. What's up?\"","options":[{"text":"\"A match keeps asking me for money. Look.\"","then":"Kabir reads it. \"Classic scam. Not your fault. Want to report him?\"","best":true},{"text":"\"Nothing. Just tired, that's all.\"","then":"\"Okay,\" Kabir says, and goes back to his phone."},{"text":"\"I think I was too cold to someone.\"","then":"\"Who?\" Kabir asks, and you find yourself defending Mehul."},{"text":"\"Help me write a nicer reply to someone?\"","then":"\"Sure,\" Kabir says, and helps you soften it without asking why."}],"why":"Talking it through with a friend helps you see the scam. Being targeted is never your fault."}],"relearn":"You can keep a no-money boundary and still be warm; a real match respects it."},
  {"id":"sr-1126","cat":"fakes-and-ghosts","type":"role-play","persona":"Rohan","source":"kind sign-off","hook":"You've decided your chat with Simran isn't going anywhere.","setup":"She messages while you're on the metro.","steps":[{"prompt":"Simran writes: \"Haven't heard from you in a bit. All good?\"","options":[{"text":"\"All good! Work has been super busy lately.\"","then":"\"Phew, okay! Talk tonight, then?\" she asks."},{"text":"\"I've liked chatting, but I don't feel a match.\"","then":"\"Ah, okay,\" Simran replies. \"Thanks for saying it. Take care.\"","best":true},{"text":"\"Yeah. Sorry, I'm bad at texting.\"","then":"\"No worries!\" Simran writes, and keeps the chat going."},{"text":"\"Honestly, you're not really my type.\"","then":"\"Oh,\" Simran writes. \"Okay. That's blunt.\""}],"why":"A brief, kind sign-off treats her like a person."},{"prompt":"Your friend Manoj says: \"Why even reply? Just leave her on read.\"","options":[{"text":"\"True. Replying just drags it out.\"","then":"Manoj nods. \"Exactly. Clean break.\""},{"text":"\"Because she's a person, not a profile.\"","then":"Manoj shrugs. \"Fair. I'd hate being left hanging.\"","best":true},{"text":"\"I'll reply, but only if she asks again.\"","then":"Manoj laughs. \"So she has to chase you first?\""},{"text":"\"Replying just makes me look desperate.\"","then":"Manoj grins. \"Now you're getting it.\""}],"why":"A kind sign-off is basic decency, whoever the match is."},{"prompt":"A week later, a new match, Aditi, asks: \"Is it just me, or has this chat gone flat?\"","options":[{"text":"\"No, no! I'm just really tired lately.\"","then":"\"Oh, okay!\" she replies, and the chat drags on."},{"text":"\"Yeah. You've been kind of boring.\"","then":"\"Wow,\" Aditi writes, and unmatches."},{"text":"\"Let's give it another week and see.\"","then":"\"Okay,\" she writes. Neither of you enjoys the week."},{"text":"\"Not just you. I don't feel a match, sadly.\"","then":"\"Ha, same,\" Aditi writes. \"Nice chatting, though!\"","best":true}],"why":"Saying it early and warmly saves you both a slow fade."}],"relearn":"A brief, kind sign-off beats vanishing; it treats them like a person."},
  {"id":"sr-1127","cat":"fakes-and-ghosts","type":"role-play","persona":"any","source":"decline proof","hook":"Your match Rishi keeps asking for an intimate photo as 'proof you trust him'.","setup":"It's late, and he's pushing again.","steps":[{"prompt":"Rishi writes: \"If you really liked me, you'd send one.\"","options":[{"text":"\"I'm not sending photos like that. Ever.\"","then":"\"Wow, okay,\" Rishi writes. \"Didn't know you were so cold.\"","best":true},{"text":"\"My friend says everyone sends them now.\"","then":"\"Your friend's right,\" Rishi writes. \"So send one.\""},{"text":"\"Sorry. I don't want you to think I'm cold.\"","then":"\"Then prove it,\" Rishi writes at once."},{"text":"\"Is that normal? Does everyone do this?\"","then":"\"Totally normal,\" Rishi writes. \"Everyone does it.\""}],"why":"You owe no one an intimate photo. A clear no is complete."},{"prompt":"Your friend Nidhi asks: \"You've been quiet all evening. What's up?\"","options":[{"text":"\"Nothing. It's embarrassing. Forget it.\"","then":"Nidhi lets it go. \"Okay. I'm here if you want.\""},{"text":"\"Rishi keeps pushing me for a photo.\"","then":"Nidhi sits up. \"That's not okay. I'm glad you told me.\"","best":true},{"text":"\"Rishi's great. I'm just overthinking stuff.\"","then":"\"Okay,\" Nidhi says, unsure, and changes the topic."},{"text":"\"Do you think I'm being a prude?\"","then":"Nidhi laughs. \"A prude? About what?\" You shrug it off."}],"why":"Telling someone you trust means you don't carry the pressure alone."},{"prompt":"The next day, Rishi writes: \"Send it, or I'll tell people you led me on.\"","options":[{"text":"\"Did I lead you on? I'm sorry if I did.\"","then":"\"You did,\" Rishi writes. \"So make it up to me.\""},{"text":"\"Go ahead and tell people. See if I care.\"","then":"Rishi sends a string of angry messages."},{"text":"\"That's a threat. I'm blocking and reporting.\"","then":"The chat closes before he can reply, and the report is logged.","best":true},{"text":"\"You wouldn't really do that, would you?\"","then":"\"Try me,\" Rishi writes."}],"why":"A threat for a photo is pressure, and it's never your fault. Block and report it."},{"prompt":"Later, Nidhi messages: \"Hey, you okay? You seemed off earlier.\"","options":[{"text":"\"I'm fine. I handled it all myself.\"","then":"\"Okay,\" Nidhi writes. \"Just checking.\""},{"text":"\"I think it was my fault, honestly.\"","then":"\"Why would it be?\" Nidhi asks, worried."},{"text":"\"Not really. Can I show you what he sent?\"","then":"\"Of course. Show me, and we'll sort it together.\"","best":true},{"text":"\"Everyone gets these. It's just dating.\"","then":"\"Is it, though?\" Nidhi writes."}],"why":"You don't have to carry it alone. A friend can help you report and feel safe."}],"relearn":"You owe no intimate 'proof' photo; a push for one is a red flag, not romance."},
  {"id":"sr-1128","cat":"fakes-and-ghosts","type":"role-play","persona":"any","source":"gentle doubt","hook":"Harsh is sure his online-only 'soulmate', Nina, is real, and bristles at any doubt.","setup":"You're walking back from class together.","steps":[{"prompt":"Harsh says: \"Don't start. Nina's real. I just know it.\"","options":[{"text":"\"You're being silly. It's obviously a scam.\"","then":"\"Wow,\" Harsh says, and walks faster."},{"text":"\"Okay, okay. If you know, you know.\"","then":"Harsh relaxes. \"Finally, someone gets it.\""},{"text":"\"I hope she is. Have you two ever video-called?\"","then":"Harsh hesitates. \"Not yet. Her camera's always off.\"","best":true},{"text":"\"Show me her photos. I'll tell you if she's real.\"","then":"Harsh shows you. They look real, which settles nothing."}],"why":"A gentle question lets him check it himself, without being shamed."},{"prompt":"The next day, Harsh says: \"Nina says calls make her anxious, so we never call. Fair, right?\"","options":[{"text":"\"Totally fair. Don't push her on it.\"","then":"Harsh nods, relieved. \"That's what I thought.\""},{"text":"\"Maybe. A short call could ease it, though.\"","then":"\"Hmm,\" Harsh says. \"I could ask for just a minute.\"","best":true},{"text":"\"Anxious? That's the oldest excuse there is.\"","then":"Harsh bristles. \"You don't even know her.\""},{"text":"\"Ask her for a selfie holding today's paper.\"","then":"\"She'd find that weird,\" Harsh says, and drops it."}],"why":"A live call is the reliable check. Keeping it gentle keeps him listening."},{"prompt":"A week later, Harsh says: \"She asked me for money. Just a bit.\"","options":[{"text":"\"I told you. You never listen to me.\"","then":"Harsh looks away. \"Forget I said anything.\""},{"text":"\"A bit is fine, if you can spare it.\"","then":"Harsh nods and opens his UPI app."},{"text":"\"That worries me. Please don't send any.\"","then":"Harsh goes quiet. \"Yeah. That's what I was scared of.\"","best":true},{"text":"\"Want me to message her and sort it out?\"","then":"\"No way,\" Harsh says. \"Stay out of it.\""}],"why":"Honest worry without 'I told you so' keeps a friend talking to you."},{"prompt":"Days later, Nina's profile vanishes, and Harsh says quietly: \"I feel like such an idiot.\"","options":[{"text":"\"Honestly, the signs were all there.\"","then":"Harsh winces and stops talking."},{"text":"\"You're not. They're good at this. I'm here.\"","then":"Harsh exhales. \"Thanks. Help me report it?\"","best":true},{"text":"\"Just forget her and move on already.\"","then":"\"Easy for you to say,\" Harsh mutters."},{"text":"\"Don't tell anyone else. It's embarrassing.\"","then":"Harsh nods, and the shame stays his secret."}],"why":"Scams are on the scammer, never the target. Support beats blame."}],"relearn":"A gentle question about a live call helps a friend more than shaming them."},
  {"id":"sr-1129","cat":"fakes-and-ghosts","type":"role-play","persona":"any","source":"calm exit","hook":"Your match Aman's backstory keeps changing, and you've decided to step back.","setup":"He messages just as you sit down to eat.","steps":[{"prompt":"Aman writes: \"Why so quiet? Did I say something?\"","options":[{"text":"\"Whatever. You're clearly a liar.\"","then":"\"Excuse me?\" Aman fires back, and a long row starts."},{"text":"\"Nothing! Just a busy week at work, that's all.\"","then":"\"Phew,\" he writes. \"Talk later, then?\""},{"text":"\"So which version of your story is true?\"","then":"\"Both, sort of,\" Aman writes, with a new long story."},{"text":"\"It's not feeling right for me. I'm stepping back.\"","then":"\"Oh. Okay,\" Aman writes. \"Can we at least talk about it?\"","best":true}],"why":"A calm exit is enough. You don't owe a confrontation."},{"prompt":"The next day, Aman writes: \"You've gone distant. Can we just talk it out?\"","options":[{"text":"\"I'd rather keep this short. I wish you well.\"","then":"\"Fine,\" Aman writes. \"Your loss.\"","best":true},{"text":"\"Sorry. I'm just overthinking things.\"","then":"\"It's okay,\" he writes, and a new story arrives."},{"text":"\"Talk about what? Your story keeps changing!\"","then":"Aman sends five long messages defending himself."},{"text":"\"Let me think about it and get back to you.\"","then":"\"Take your time,\" he writes, and checks in every hour."}],"why":"You don't owe reasons or a debate. A short, kind line is enough."},{"prompt":"Later, Aman writes: \"Can I have your number? The app is so glitchy.\"","options":[{"text":"\"Sure, here it is.\"","then":"Now he has your number, and the stories move to your phone."},{"text":"\"Only if you tell me the truth first.\"","then":"\"Deal,\" Aman writes, and yet another version arrives."},{"text":"\"I'd rather not. Take care, Aman.\"","then":"No reply comes. The chat stays quiet.","best":true},{"text":"\"Why would I? You're a total fraud.\"","then":"Aman fires back angrily, and it drags on."}],"why":"Keeping your details private is a fair boundary with a shaky story."}],"relearn":"You can step back from a shaky story calmly; you don't owe a confrontation."},
  {"id":"sr-1130","cat":"fakes-and-ghosts","type":"role-play","persona":"any","source":"normal ask","hook":"When you asked Yash for a quick video call, he went cold and defensive.","setup":"He brings it up again tonight.","steps":[{"prompt":"Yash writes: \"Why do you even need a call? Don't you trust me?\"","options":[{"text":"\"Sorry, sorry. Forget I asked anything.\"","then":"\"Good,\" Yash writes. \"Let's keep it fun.\""},{"text":"\"A quick call is just a normal ask for me.\"","then":"\"Hmm,\" Yash writes. \"I just hate calls. Maybe.\"","best":true},{"text":"\"Trust has to be earned, you know.\"","then":"\"Wow, harsh,\" Yash writes."},{"text":"\"Fine. Then send me ten selfies instead.\"","then":"A stream of polished photos arrives, and nothing is settled."}],"why":"Naming a call as your normal ask keeps it simple, not personal."},{"prompt":"The next day, Yash writes: \"My other matches never needed a call. Just saying.\"","options":[{"text":"\"Maybe I'm being too much about it.\"","then":"\"You are a bit,\" Yash agrees."},{"text":"\"Well, maybe they should have!\"","then":"\"Okay, attitude,\" Yash writes."},{"text":"\"Then just send a voice note instead.\"","then":"A voice note arrives. It sounds fine and proves little."},{"text":"\"That's okay. It's still what I need.\"","then":"A pause. \"Fine. Maybe Sunday,\" Yash writes.","best":true}],"why":"Your ask doesn't need anyone else's approval. It's a fair, basic check."},{"prompt":"On Sunday, Yash writes: \"Let's skip the call and just meet. Deal?\"","options":[{"text":"\"A call first. If that's a problem, I'll pass.\"","then":"\"Whatever,\" Yash writes, and goes quiet. You feel oddly calm.","best":true},{"text":"\"Sure. Meeting is basically the same thing.\"","then":"\"Now you're talking,\" Yash writes at once."},{"text":"\"You're a fake, aren't you?\"","then":"Yash sends an angry paragraph and blocks you."},{"text":"\"Maybe. Let's keep chatting and see.\"","then":"\"Sure,\" Yash writes, and the call never comes up again."}],"why":"Defensiveness about a basic call is a tell. Passing is yours to choose."}],"relearn":"Defensiveness about a basic call is a tell; a normal ask is yours to make."},
  {"id":"sr-1131","cat":"fakes-and-ghosts","type":"reflect","hook":"Lensy: a profile is a highlight reel: a live call is what tells you who's actually there. Worth it?","prompt":"What feels right to you?","options":["Yes, I'll call first","Verify before I invest","Sounds fair"],"affirm":"Asking for a live call before you open up is calm, normal self-respect.","relearn":"A live call before you invest is calm self-respect, not paranoia.","persona":"any","source":"verify first"},
  {"id":"sr-1132","cat":"fakes-and-ghosts","type":"reflect","hook":"Lensy: being fooled by a good con is on the con artist, never on you. Sit with that?","prompt":"How does that land?","options":["It wasn't my fault","On the deceiver","I can be kinder to myself"],"affirm":"A con built to fool careful people fooling you says nothing bad about you.","relearn":"Being deceived is on the deceiver; it's not a verdict on you.","persona":"any","source":"no self-blame"},
  {"id":"sr-1133","cat":"fakes-and-ghosts","type":"reflect","hook":"Lensy: a brief, kind 'this isn't for me' is a small thing that spares someone a lot. Deal?","prompt":"What do you think?","options":["I'll send the line","No more ghosting","People over profiles"],"affirm":"Choosing a short kind sign-off over silence is the decency you'd want shown to you.","relearn":"A short kind sign-off over silence is everyday decency, both ways.","persona":"Rohan","source":"honesty both ways"},
  {"id":"sr-1134","cat":"fakes-and-ghosts","type":"reflect","hook":"Lensy: your gut catching that something's 'off' is data, not rudeness. Trust it?","prompt":"Does that sit right?","options":["I'll trust my gut","Off means pause","I can step back"],"affirm":"If something feels off, you're allowed to slow down or step away, no reason owed.","relearn":"A gut 'this is off' is reason enough to pause or step back.","persona":"any","source":"trust your gut"},
  {"id":"sr-1135","cat":"fakes-and-ghosts","type":"reflect","hook":"Lensy: 'never send money to someone you've only met online' is a clean rule to keep. Keep it?","prompt":"What feels true for you?","options":["I'll keep the rule","No online money","Easy line to hold"],"affirm":"Holding a no-money line with online matches keeps the warmth and drops the risk.","relearn":"Never sending money to an online-only match is a clean line to keep.","persona":"any","source":"money rule"},
  {"id":"sr-1136","cat":"fakes-and-ghosts","type":"reflect","hook":"Lensy: report and block are tools you're fully allowed to use, not 'overreacting'. Agree?","prompt":"How do you feel about that?","options":["I can report","Block is fine","Tools, not drama"],"affirm":"Using block or report when something's wrong is sensible, never an overreaction.","relearn":"Block and report are tools you're allowed to use, not an overreaction.","persona":"any","source":"tools not drama"},
  {"id":"sr-1137","cat":"fakes-and-ghosts","type":"reflect","hook":"Lensy: telling a trusted friend about an online romance gives it a reality check. Worth doing?","prompt":"What do you think?","options":["I'll tell a friend","A reality check helps","Not betrayal"],"affirm":"Letting one trusted friend in on it is a safety net, not a betrayal of the romance.","relearn":"Telling a trusted friend gives a romance a healthy reality check.","persona":"any","source":"reality check"},
  {"id":"sr-1138","cat":"fakes-and-ghosts","type":"match","hook":"Match each fake-or-ghost red flag to the smart response.","pairs":[{"left":"Refuses to ever video-call","right":"Don't meet until verified live"},{"left":"Online match asks you for money","right":"Hold your no-money line"},{"left":"Threatens to leak a private image","right":"Don't pay; report to 1930"},{"left":"You've gone off someone after real chats","right":"Send a short, kind sign-off"},{"left":"Their backstory keeps changing","right":"Step back calmly"}],"relearn":"Each red flag has a calm move: verify, hold the line, report, sign off, or step back.","persona":"any","source":"flag to move"},
  {"id":"sr-1139","cat":"fakes-and-ghosts","type":"match","hook":"Match each catfish line to what it really is.","pairs":[{"left":"\"My camera's broken again\"","right":"A dodge to avoid being seen live"},{"left":"\"I swear on my life I'm real\"","right":"A promise that proves nothing"},{"left":"\"Send a tiny recharge, I'll repay\"","right":"A small ask that tests you first"},{"left":"\"Don't tell your friends about us\"","right":"Isolation so no one spots the con"},{"left":"\"You're my soulmate already\"","right":"Day-one love-bombing"}],"relearn":"Broken cameras, big promises, small asks, secrecy and instant love are the catfish kit.","persona":"any","source":"catfish lines"},
  {"id":"sr-1140","cat":"fakes-and-ghosts","type":"match","hook":"Match each verification idea to whether it's real proof.","pairs":[{"left":"A live two-way video call","right":"A real check of who's there"},{"left":"One more posed selfie","right":"Not proof of anything"},{"left":"Meeting in a busy public place","right":"A genuine way to verify"},{"left":"\"Trust me, I'm definitely real\"","right":"A reassurance, not a check"},{"left":"A short candid clip with sound","right":"Harder for a fake to produce"}],"relearn":"Live calls, public meets and candid clips check; selfies and 'trust me' only reassure.","persona":"any","source":"proof or not"},
  {"id":"sr-1141","cat":"fakes-and-ghosts","type":"match","hook":"Match the kind move to the messy dating moment.","pairs":[{"left":"You're not feeling a match anymore","right":"A brief, honest goodbye"},{"left":"They said no to a second date","right":"Take it gracefully, no pushing"},{"left":"You went quiet for weeks","right":"A late but honest apology"},{"left":"They keep messaging after your no","right":"Restate once, then give space"},{"left":"You ended things abruptly before","right":"Own it kindly if they reach out"}],"relearn":"Honesty, grace, a late apology, space and owning it are the kind moves both ways.","persona":"Rohan","source":"kind moves"},
  {"id":"sr-1142","cat":"fakes-and-ghosts","type":"match","hook":"Match each India report route to the right situation.","pairs":[{"left":"A leaked or threatened intimate image","right":"Cybercrime 1930"},{"left":"Online harassment or threats","right":"Helpline 181"},{"left":"You're in immediate danger now","right":"Emergency 112"},{"left":"You want a safety net for a meet","right":"Tell a trusted friend"},{"left":"A creepy match on the app","right":"Block and report in-app"}],"relearn":"1930 for image abuse, 181 for harassment, 112 for danger, a friend for your plan.","persona":"any","source":"report routes"},
  {"id":"sr-1143","cat":"fakes-and-ghosts","type":"match","hook":"Match each scam tactic to the calm counter-move.","pairs":[{"left":"\"Decide right now or lose me\"","right":"Slow down; pressure is a tell"},{"left":"\"Let's leave the app, chat privately\"","right":"Stay on-app until you've verified"},{"left":"\"Only you can save me tonight\"","right":"Don't send money; suggest local help"},{"left":"\"Keep us a total secret\"","right":"Tell one trusted friend anyway"},{"left":"\"Here's a photo as proof\"","right":"Ask for a live call instead"}],"relearn":"Pressure, off-app rush, crisis asks and secrecy each meet a calm, steady counter.","persona":"any","source":"counter-moves"},
  {"id":"sr-1144","cat":"fakes-and-ghosts","type":"match","hook":"Match each true statement about fakes and ghosts to its point.","pairs":[{"left":"A profile is a highlight reel","right":"You learn someone over time, not from photos"},{"left":"Looks-real isn't proof","right":"A live video call is the reliable check"},{"left":"Fast love plus money","right":"That's a scam pattern, not romance"},{"left":"Being deceived","right":"It's on the deceiver, never your fault"},{"left":"A kind sign-off","right":"It beats vanishing on someone"}],"relearn":"Profiles aren't proof, fast-love-money is a scam, deceit isn't your fault, don't ghost.","persona":"any","source":"core truths"},
  {"id":"sr-1145","cat":"fakes-and-ghosts","type":"match","hook":"Match each ghosting habit to the honest alternative.","pairs":[{"left":"Going silent after real chats","right":"A short \"this isn't a match\""},{"left":"Slow-fading replies to nothing","right":"One clear, kind goodbye"},{"left":"A fake \"maybe someday\"","right":"An honest \"I don't see this working\""},{"left":"Blocking with no word","right":"A brief sign-off, then space"},{"left":"Leaving them on read for weeks","right":"A late but honest reply"}],"relearn":"Every ghosting habit has a short honest alternative that treats them like a person.","persona":"Rohan","source":"ghost to honest"},
  {"id":"sr-1146","cat":"fakes-and-ghosts","type":"sort","hook":"Sort: a green move on apps, or a fake/ghost red flag?","items":[{"id":"a","text":"Asking for a live call before meeting"},{"id":"b","text":"Sending money to an online-only match"},{"id":"c","text":"A short, kind goodbye when it's not a match"},{"id":"d","text":"Vanishing after weeks of real chats"},{"id":"e","text":"Telling a trusted friend your meet plan"},{"id":"f","text":"Keeping someone on hold for attention"}],"bins":[{"id":"green","label":"Green move","valence":"pos"},{"id":"flag","label":"Red flag","valence":"neg"}],"key":{"a":"green","b":"flag","c":"green","d":"flag","e":"green","f":"flag"},"relearn":"Verify, sign off kindly and tell a friend are green; money, vanishing and on-hold aren't.","persona":"any","source":"green vs flag"},
  {"id":"sr-1170","cat":"meeting-safely","type":"branch","persona":"Ananya","source":"public first meet","hook":"It's your first-ever app date, and your match Siddharth asks you to pick the place.","steps":[{"prompt":"He says he's free on Saturday afternoon. What do you do?","options":[{"text":"Let him pick somewhere new to you","then":"He picks a place across town you've never heard of."},{"text":"Pick a busy cafe near you that you know","then":"Siddharth says \"Perfect,\" and you already know the way home.","best":true},{"text":"Pick a quiet rooftop you saw online","then":"It looks lovely in photos, but you've no idea who else will be there."},{"text":"Say 'anywhere is fine' so you seem easygoing","then":"He picks his favourite spot, far from your side of town."}],"why":"Naming a public spot you know puts the first meet on your ground."},{"prompt":"The day before, you feel nervous about the plan. What do you do?","options":[{"text":"Keep the nerves to yourself","then":"You carry the jitters alone all night."},{"text":"Look up his socials for reassurance","then":"His photos look fine, but you're no calmer."},{"text":"Tell a friend the place and time","then":"Your friend replies: \"Noted. Text me when you're out.\"","best":true},{"text":"Plan a drink first to calm down","then":"It's a plan, but not one that keeps your head clear."}],"why":"A friend in the loop makes nerves easier and the plan safer."},{"prompt":"Midway through the date, Siddharth suggests moving to his friend's place nearby. What do you do?","options":[{"text":"Say you'd rather stay here today","then":"He shrugs. \"Sure. Another chai, then.\"","best":true},{"text":"Assume it's fine, since the date's going well","then":"You follow him out, away from the busy street."},{"text":"Go, but text your friend the new address","then":"Your friend knows, but you're now somewhere private with a near-stranger."},{"text":"Worry that saying no will spoil the mood","then":"You hesitate, and the question hangs over the table."}],"why":"Staying in public keeps a first meet easy to leave, and you never owe a reason."}],"debrief":"Choosing the public spot yourself starts the meet on ground you already trust.","relearn":"Pick the public spot yourself so the first meet is on ground you know."},
  {"id":"sr-1171","cat":"meeting-safely","type":"branch","persona":"any","source":"own way home","hook":"Before your first date, Ishaan offers to drive you there and back.","steps":[{"prompt":"He says it's no trouble at all. What do you do?","options":[{"text":"Accept so you don't seem distrustful","then":"Ishaan will pick you up, so he asks for your address."},{"text":"Accept the ride there, and plan your own way back","then":"Getting there is easy, and he still learns where you live."},{"text":"Thank him, but say you'll sort your own travel","then":"Ishaan replies: \"Sure, see you there!\"","best":true},{"text":"Ask him why he wants to drive you","then":"Ishaan sounds hurt: \"Just being nice!\""}],"why":"Your own ride means you decide when the date ends."},{"prompt":"On the day, the metro's down, and every way home except Ishaan's car costs a lot. What do you do?","options":[{"text":"Let Ishaan handle the ride home","then":"He's glad to, and your exit is now his to give."},{"text":"Spend freely now, and sort home later","then":"The evening's fun, and there's little left for home."},{"text":"Plan to borrow cab money from a friend later","then":"Your friend says maybe, and you head out unsure."},{"text":"Keep fare aside for an auto home","then":"It pinches a little, but your way home is sorted.","best":true}],"why":"Keeping fare for home means leaving is always up to you."},{"prompt":"The date ends, and Ishaan says, 'Let me drop you. It's late.' What do you do?","options":[{"text":"Accept, since it's late and he's been nice","then":"He drives you home, and now knows your gate."},{"text":"Thank him, and sort your own ride home","then":"You're home in twenty minutes, on your own schedule.","best":true},{"text":"Accept, but get dropped at the corner","then":"He still knows your street, and you walk the last bit."},{"text":"Say no sharply, as if he's a threat","then":"Ishaan looks stung, and a warm evening ends awkwardly."}],"why":"Your own way home keeps the ending in your hands."}],"debrief":"Your own transport means you decide when the date ends, not them.","relearn":"Book your own ride so leaving is always in your hands."},
  {"id":"sr-1172","cat":"meeting-safely","type":"branch","persona":"any","source":"stay clear-headed","hook":"On your first date, Akhil keeps topping up your drink, round after round.","steps":[{"prompt":"You're already feeling it. What do you do?","options":[{"text":"Keep pace, since a fun date means drinking","then":"The room gets fuzzy, and it's harder to read how you feel."},{"text":"Slow down and switch to water","then":"Akhil raises an eyebrow and orders himself another round.","best":true},{"text":"Tell yourself you can handle a few more","then":"Your glass fills again, and the room starts to blur."},{"text":"Tell him off loudly for pushing drinks","then":"Nearby tables look over, and Akhil gets defensive."}],"why":"A clear head keeps your instincts loud and your judgement your own."},{"prompt":"Akhil says, 'Come on, one more. Don't be boring.' What do you do?","options":[{"text":"Believe that saying no makes you boring","then":"The word 'boring' stays with you, and so does the full glass."},{"text":"Decide it's rude to refuse what he's paying for","then":"The glass stays full, and so does the pressure."},{"text":"Say 'I'm good,' and stick to water","then":"Akhil shrugs. \"Suit yourself.\"","best":true},{"text":"Tell yourself one more won't matter","then":"One more becomes two, and your head gets foggier."}],"why":"No is a complete answer, for drinks too. Someone pushing is on them, not you."},{"prompt":"It's getting late, and Akhil offers to take you home. What do you do?","options":[{"text":"Accept, since he's been generous all evening","then":"You get in his car, feeling you owe him something."},{"text":"Stay for one more round to be polite","then":"Another round arrives, and the night stretches on."},{"text":"Head home the way you planned, and text a friend","then":"You're home soon, and your friend replies with a heart.","best":true},{"text":"Tell yourself you're overreacting about him","then":"You second-guess yourself as he reaches for his car keys."}],"why":"Your own way home and a friend in the loop keep the night yours."},{"prompt":"Next day, a friend says first dates are more fun with a few drinks. What do you say?","options":[{"text":"Say you like a clear head on first dates","then":"Your friend nods. \"Fair. Keeps things easy to read.\"","best":true},{"text":"Agree. A few drinks break the ice","then":"Next time, you plan to match your date's pace from the start."},{"text":"Decide you're just bad at dating","then":"The doubt sticks around for your next date."},{"text":"Laugh and change the subject","then":"The question hangs, and so does the doubt."}],"why":"Staying clear-headed isn't boring. It's how you keep your read on things."}],"debrief":"A clear head on a first meet keeps your read on things, and on them, sharp.","relearn":"Keep a clear head on a first meet so your gut can speak."},
  {"id":"sr-1173","cat":"meeting-safely","type":"branch","persona":"any","source":"video-verify","hook":"You've chatted with Ruhi for two weeks but never seen her move or talk live.","steps":[{"prompt":"She suggests meeting this weekend. What do you do?","options":[{"text":"Meet anyway. The photos look genuine enough","then":"You say yes, still not sure who'll walk in."},{"text":"Ask for a few more selfies first","then":"Three new selfies arrive, each as perfect as the last."},{"text":"Suggest a short video call before you meet","then":"Ruhi replies: \"Sure, maybe. I'm a bit shy on camera, though.\"","best":true},{"text":"Stall until you somehow feel sure","then":"Ruhi waits, and the question doesn't get answered."}],"why":"Photos can be stolen or generated. A live call shows a real person."},{"prompt":"Before the weekend, Ruhi says video calls make her nervous, and suggests a phone call. What do you do?","options":[{"text":"Say even a thirty-second video call works","then":"Ruhi laughs. \"Okay. Thirty seconds, camera on.\"","best":true},{"text":"Accept the phone call. A voice is proof","then":"She sounds lovely, but a voice can't show a face."},{"text":"Drop it. She's clearly nervous","then":"You let it go, and you still haven't seen her."},{"text":"Tell her shyness sounds like an excuse","then":"Ruhi goes quiet. \"That's kind of harsh.\""}],"why":"A short live video call is the check, and you can make it easy for her."},{"prompt":"By Friday, Ruhi asks where you'd like to meet. What do you do?","options":[{"text":"Invite her over to yours to keep it simple","then":"Ruhi agrees, and now she knows your address."},{"text":"Suggest a busy cafe and tell a friend","then":"Ruhi agrees, and your friend has the time and place.","best":true},{"text":"Let her choose anywhere she likes","then":"She picks a spot you've never been to."},{"text":"Suggest a late-night drive for fun","then":"Ruhi's keen, but you'd be alone in a car at night."}],"why":"A public first meet, with a friend in the loop, is how you date freely."}],"debrief":"A quick live call before meeting turns a profile into a verified person.","relearn":"A live video call before meeting is the simplest real-or-not check."},
  {"id":"sr-1174","cat":"meeting-safely","type":"branch","persona":"Aarti","source":"told a friend","hook":"Family can't know about Friday's date with Rahul, so you feel you must tell nobody.","steps":[{"prompt":"Your friend Pooja asks what you're up to on Friday. What do you do?","options":[{"text":"Say 'nothing much' to keep it secret","then":"Pooja shrugs, and nobody knows where you'll be."},{"text":"Tell her the place and time","then":"Pooja grins. \"Got it. Text me when you're home.\"","best":true},{"text":"Tell her it's a date, but not where","then":"Pooja's excited, but can't help if plans change."},{"text":"Say you'll tell her after, if it goes well","then":"Pooja waits, knowing nothing about Friday."}],"why":"One trusted friend knowing your plan is a safety net, not a betrayal."},{"prompt":"On Friday, Rahul suggests moving from the cafe to somewhere else. What do you do?","options":[{"text":"Go, and update her later","then":"For an hour, nobody knows where you are."},{"text":"Go, since telling her means explaining","then":"The new place is somewhere only Rahul knows you are."},{"text":"Text Pooja the new place before you go","then":"Pooja replies: \"Noted! Have fun.\"","best":true},{"text":"Assume Pooja only needed the first place","then":"You go, and Pooja's info is now an hour out of date."}],"why":"Keeping your friend updated keeps your net in place."},{"prompt":"Walking home, you worry your family will find out. What do you do?","options":[{"text":"Promise yourself you'll never tell anyone again","then":"Next time, you'll be on your own with it."},{"text":"Stay out late so nobody asks questions","then":"You wander longer than planned, with your phone on five percent."},{"text":"Decide dating in secret makes you a bad person","then":"The guilt sits heavy all night."},{"text":"Text Pooja that you're almost home","then":"Pooja replies with a heart, and your nerves settle.","best":true}],"why":"Privacy from family is your call. Closing the loop with a friend keeps you safe."}],"debrief":"Even when family is out of the loop, one trusted friend knowing your plan is your net.","relearn":"Tell a trusted friend your plan, even when family can't know."},
  {"id":"sr-1175","cat":"meeting-safely","type":"branch","persona":"any","source":"trust your gut","hook":"Ten minutes into meeting Manav, something feels off and you can't name why.","steps":[{"prompt":"He's chatting away, and you want to go. What do you do?","options":[{"text":"Stay, so you don't seem rude","then":"Every minute feels longer, and the unease stays."},{"text":"Stay till you can name a clear reason","then":"An hour passes, and you still can't put words to it."},{"text":"Ask him lots of questions to test him","then":"Manav answers easily, and your gut still says go."},{"text":"Head off, and text a friend you're leaving","then":"Manav blinks. \"Oh. Okay, sure.\" Your friend replies: \"Text me when home.\"","best":true}],"why":"Your gut needs no reason. If it says leave, leaving is allowed."},{"prompt":"Later, Manav texts to ask if he did something wrong. What do you do?","options":[{"text":"Explain in detail why you felt uneasy","then":"Manav argues with each point, and it drags on."},{"text":"Reply briefly that it wasn't a match","then":"Manav writes: \"Okay. Thanks for replying.\"","best":true},{"text":"Apologise and offer a second date","then":"Manav books a table for Saturday."},{"text":"Say you felt ill, so he doesn't feel bad","then":"Manav offers to check on you tomorrow."}],"why":"You don't owe a reason. A brief, honest reply is enough."},{"prompt":"A friend says a bad feeling on a date is 'just nerves'. What do you think?","options":[{"text":"My gut is reason enough to leave","then":"Your friend nods. \"Fair. You know how it felt.\"","best":true},{"text":"Maybe I'm too picky to date at all","then":"The doubt sticks, and you second-guess your next date."},{"text":"Next time I'll push through the feeling","then":"You plan to ignore the very thing that protects you."},{"text":"I'll only leave if something actually happens","then":"It sounds reasonable, but it means waiting for trouble."}],"why":"Trusting an uneasy gut is always allowed. You never owe an explanation."}],"debrief":"An uneasy gut is a complete reason to leave. You never owe an explanation.","relearn":"If your gut says go, you can leave any time, no reason owed."},
  {"id":"sr-1176","cat":"meeting-safely","type":"branch","persona":"any","source":"pressure red flag","hook":"Gaurav keeps pushing to skip the cafe and have you come straight to his flat.","steps":[{"prompt":"He's asked three times now. What do you do?","options":[{"text":"Hold the cafe plan and say it plainly","then":"Gaurav replies: \"Ugh, fine. Cafe.\" An hour later, he asks again.","best":true},{"text":"Believe he'll lose interest if you say no","then":"The worry softens your reply, and he pushes harder."},{"text":"Tell yourself cafes are old-fashioned now","then":"You start rethinking your own plan to suit him."},{"text":"Take a friend's advice that it's no big deal","then":"You start to waver, and Gaurav sends his address."}],"why":"A public first meet is a normal boundary. Saying it plainly is enough."},{"prompt":"Gaurav texts: \"Only people who think I'm a criminal insist on a cafe.\" What do you do?","options":[{"text":"Apologise for making him feel bad","then":"Gaurav accepts, and asks about the flat again."},{"text":"Say it's your rule for every first meet","then":"Gaurav sighs. \"Okay. Whatever you're comfortable with.\"","best":true},{"text":"Argue with him until he admits he's pushy","then":"The chat turns into a long fight."},{"text":"Wonder if you're being paranoid","then":"The doubt grows, and your plan starts to wobble."}],"why":"It's not personal. A public first meet is a rule for everyone."},{"prompt":"Your roommate Anjali notices you frowning at your phone. What do you do?","options":[{"text":"Say it's nothing and put the phone away","then":"The pressure stays in your head all night."},{"text":"Laugh that you're probably overreacting","then":"She laughs along, and the flag goes unspoken."},{"text":"Show her the chat and talk it through","then":"Anjali reads it. \"The push is the red flag,\" she says. \"Not you.\"","best":true},{"text":"Ask her to message him and tell him off","then":"She hesitates, and it starts to become her fight, not yours."}],"why":"Pressure to skip a public meet is the flag, never your fault. A friend helps."},{"prompt":"The next day, Gaurav writes: 'My place or nothing.' What do you do?","options":[{"text":"Believe that's just how dating works now","then":"The idea sits with you, and his message stays open."},{"text":"Reply with a long lecture on red flags","then":"Gaurav leaves you on read, and you feel drained."},{"text":"Keep chatting in case he changes his mind","then":"He keeps pushing, and you keep bracing for the next message."},{"text":"Choose nothing, and unmatch","then":"The chat closes, and so does the pressure.","best":true}],"why":"An ultimatum makes it clear. Walking away is yours to do."}],"debrief":"Pushing past your public-meet plan is the red flag. A real match holds to it.","relearn":"Pressure to skip the public meet is a red flag, not romance."},
  {"id":"sr-1177","cat":"meeting-safely","type":"branch","persona":"Deepak","source":"low-cost safety","hook":"You're on one phone and a tight budget, and safe dating feels like a luxury.","steps":[{"prompt":"You're meeting Kavya on Sunday. What do you plan?","options":[{"text":"Skip the steps. You can't afford extras","then":"The plan is just you, Kavya and a place nobody knows."},{"text":"Meet in a free park and text a friend","then":"Kavya loves the idea, and your friend has the plan.","best":true},{"text":"Meet at her place, since it's free","then":"Kavya sends her address, and nobody knows where you'll be."},{"text":"Borrow money for a fancy cafe","then":"It's public, but you'll be paying it back for weeks."}],"why":"The core safety steps are free: a public place and a friend told."},{"prompt":"On Sunday, your data is nearly gone. What do you do?","options":[{"text":"Go anyway. Nobody needs to know","then":"You head out, with no way to check in if plans change."},{"text":"Spend the last data scrolling her profile","then":"Now you're out of data, and can't message anyone later."},{"text":"Ask Kavya to keep track of time for you","then":"Kavya says sure, but she's not your safety net."},{"text":"Tell a friend in person when you'll be back","then":"Your friend nods. \"Six o'clock. Got it.\"","best":true}],"why":"Telling someone face to face works just as well, with zero data."},{"prompt":"The date is ending. How do you get home?","options":[{"text":"Take the bus with the fare you kept aside","then":"You're home on time, just as you planned.","best":true},{"text":"Hope Kavya offers to pay your fare","then":"She doesn't, and you're stuck working it out."},{"text":"Spend the fare on snacks, then figure it out","then":"The snacks are great, and you're left counting coins for the bus."},{"text":"Stay out longer so you look less broke","then":"It gets late, and the last bus goes."}],"why":"Your own way home, planned ahead, costs little and keeps you free to leave."}],"debrief":"Meeting safely is free: a public place, a friend told, your own way back.","relearn":"Safety steps cost nothing; a public spot and a friend's text are free."},
  {"id":"sr-1178","cat":"meeting-safely","type":"branch","persona":"any","source":"day vs night","hook":"Your match Sahil suggests a late-night drive as your very first meeting.","steps":[{"prompt":"He says it'll be 'way more fun than a boring cafe'. What do you do?","options":[{"text":"Agree to the drive so you seem fun","then":"Sahil says he'll pick you up and text you the time."},{"text":"Suggest a daytime coffee for the first one","then":"Sahil sends an eye-roll emoji and says he'll think about it.","best":true},{"text":"Agree, but ride your own scooty there","then":"Sahil says he'll text the time and a spot outside the city."},{"text":"Say 'maybe' and see how you feel","then":"Sahil keeps asking, pushing for a yes."}],"why":"A daytime public first meet keeps it low-pressure and easy to leave."},{"prompt":"Later that week, Sahil texts: \"Saturday, ten at night. Can't wait.\" What do you do?","options":[{"text":"Worry that saying no makes you seem dull","then":"You start rewriting your plan to seem fun."},{"text":"Tell him he sounds like a creep","then":"Sahil goes cold. \"Wow. Just a suggestion.\""},{"text":"Say you'd like the first meet in daylight","then":"Sahil writes: \"Okay, okay. Daylight it is.\"","best":true},{"text":"Offer a late-night cafe as a middle ground","then":"It's public, but late, and getting home is harder."}],"why":"His pushing is on him, never your fault. Daylight keeps a first meet easy to leave."},{"prompt":"Your friend Zara asks about your weekend plan. What do you do?","options":[{"text":"Keep it vague. It's just a date","then":"Zara shrugs, knowing nothing."},{"text":"Say you'll share details if it goes badly","then":"Zara agrees, but she'd have nothing to go on."},{"text":"Post a countdown on your story","then":"Lots of reactions, but nobody knows where you'll be."},{"text":"Tell her the time and place","then":"Zara says: \"Nice. Text me after!\"","best":true}],"why":"A friend who knows your plan is the easiest safety step."},{"prompt":"As your first meet winds down, Sahil suggests 'one more stop' at a spot he knows. What do you do?","options":[{"text":"Say no thanks, and head home your own way","then":"Sahil shrugs. \"Next time, then.\"","best":true},{"text":"Go, since it's only one more stop","then":"The stop is farther than he said, and far from other people."},{"text":"Go, but share your location first","then":"Your friend can see where you are, but you're still on his route."},{"text":"Accuse him of trying to trap you","then":"Sahil looks shocked, and the date ends in a sour mood."}],"why":"A good date can end where it started. Your own way home keeps it easy."}],"debrief":"A daytime, public first meet keeps a first date light and easy to leave.","relearn":"A daytime, public first meet is an easy way to keep things light."},
  {"id":"sr-1179","cat":"meeting-safely","type":"branch","persona":"Zoya","source":"inclusive safety","hook":"You're meeting Mira, a woman from the app, and wonder if the safety steps still apply.","steps":[{"prompt":"A friend says, 'Relax. It's a girl. Skip the steps.' What do you do?","options":[{"text":"Drop them, since it feels lower-risk","then":"You tell nobody, and let Mira pick where to meet."},{"text":"Use the same steps as with anyone","then":"Your friend shrugs, and your plan is set.","best":true},{"text":"Keep one step, and skip the rest","then":"You've picked a cafe, but no one knows you're there."},{"text":"Worry that the steps mean you distrust her","then":"You start second-guessing the whole plan."}],"why":"Meet-safe steps fit every match. They aren't tied to anyone's gender."},{"prompt":"Mira asks if she can pick you up from home. What do you do?","options":[{"text":"Say yes. It's sweet of her","then":"Mira now knows your address before your first meet."},{"text":"Say yes, but meet at the end of your lane","then":"She still learns your street."},{"text":"Thank her, and say you'll meet her there","then":"Mira writes: \"Cool, see you at five!\"","best":true},{"text":"Tell her you don't trust anyone yet","then":"Mira writes: \"Oh. Okay, fair.\" She sounds a little hurt."}],"why":"Your own way there and back keeps your exit yours, whoever you're meeting."},{"prompt":"Mid-date, Mira suggests heading back to hers. What do you do?","options":[{"text":"Go, since it's 'different' with a woman","then":"You follow her out, having dropped your own plan."},{"text":"Go, but text your friend the address","then":"Your friend knows, but you've left your plan behind."},{"text":"Feel you owe it since it's going well","then":"You say yes, with a knot in your stomach."},{"text":"Say you'd like to keep today to this","then":"Mira smiles. \"Sure. Another round of chai?\"","best":true}],"why":"A good date doesn't mean you owe more time or a new place. Your plan holds with every match."}],"debrief":"The meet-safe checklist is the same for every match, whatever their gender.","relearn":"The same meet-safe steps fit every match, every orientation."},
  {"id":"sr-1180","cat":"meeting-safely","type":"branch","persona":"any","source":"check-in plan","hook":"Your friend Ayesha asks how she'll know your first date with Dhruv went fine.","steps":[{"prompt":"She wants a plan before Saturday. What do you do?","options":[{"text":"Agree you'll text her once you're home","then":"Ayesha says: \"Deal. If I don't hear by ten, I'll call.\"","best":true},{"text":"Say you'll call only if it goes wrong","then":"Ayesha frowns. \"And if you can't call?\""},{"text":"Say she'll see it on your story","then":"Ayesha laughs, unsure whether that counts as a plan."},{"text":"Tell her not to worry so much","then":"Ayesha lets it go, still uneasy."}],"why":"A planned 'home safe' text is easier than calling only in a crisis."},{"prompt":"On Saturday, the date runs late and it's fun. What do you do?","options":[{"text":"Ignore your phone. You're having fun","then":"Ayesha's messages start piling up."},{"text":"Send Ayesha a quick 'running late' text","then":"Ayesha replies: \"Enjoy! Text when home.\"","best":true},{"text":"Ask Dhruv to text her for you","then":"Dhruv looks puzzled. \"Who's Ayesha?\""},{"text":"Wait and text only once you're home","then":"Ten o'clock passes, and Ayesha starts to worry."}],"why":"A tiny update keeps the net working, even on a good night."},{"prompt":"Dhruv offers to drop you home since it's late. What do you do?","options":[{"text":"Accept, and just tell Ayesha about it after","then":"He drives you, and your plan quietly changes."},{"text":"Accept, so the fun doesn't end yet","then":"He drives you home, and now knows your gate."},{"text":"Thank him, and take the ride you planned","then":"Dhruv nods. \"Cool. Get home safe.\"","best":true},{"text":"Snap that you don't need his help","then":"Dhruv looks stung, and the night ends awkwardly."}],"why":"Your own way home keeps the plan you told Ayesha true."},{"prompt":"You get home at eleven, exhausted. What do you do?","options":[{"text":"Sleep. She'll assume you're fine","then":"Ayesha lies awake, checking her phone."},{"text":"Post a story and let her see it","then":"Ayesha sees it at midnight, after an hour of worry."},{"text":"Text her tomorrow with the full story","then":"Ayesha wakes up to no message and panics a little."},{"text":"Text Ayesha that you're home safe","then":"Ayesha replies with a sleepy thumbs up.","best":true}],"why":"The 'home safe' text closes the loop. It takes ten seconds."}],"debrief":"A planned 'text me when you're home' is a tiny step that closes the loop.","relearn":"A simple 'text me when home' check-in is an easy safety net."},
  {"id":"sr-1181","cat":"meeting-safely","type":"branch","persona":"any","source":"location share","hook":"You want someone to know where you are during your date with Tejas tonight.","steps":[{"prompt":"You're getting ready to leave. What do you do?","options":[{"text":"Send Tejas your home address to be safe","then":"Tejas now knows where you live, not where you'll be."},{"text":"Post your location on your story","then":"Lots of people can see it, but nobody's watching."},{"text":"Share live location with a trusted friend","then":"Your friend Leela replies: \"Got you. Have fun!\"","best":true},{"text":"Tell a friend you'll share if it gets weird","then":"Your friend waits, with nothing to go on."}],"why":"Live location goes to a friend you trust, never your address to a stranger."},{"prompt":"At the cafe, Tejas asks why you keep checking your phone. What do you do?","options":[{"text":"Say you like a friend to know where you are","then":"Tejas nods. \"Makes sense. My sister does the same.\"","best":true},{"text":"Say it's nothing, and stop checking in","then":"Tejas relaxes, and nobody hears from you for hours."},{"text":"Hand him your phone to prove it's innocent","then":"Tejas scrolls, and now he's seen your chats."},{"text":"Say it's work, so he doesn't feel judged","then":"Tejas shrugs, and you feel oddly guilty."}],"why":"Wanting a friend to know where you are is normal, not rude."},{"prompt":"Tejas suggests a second spot across town. What do you do?","options":[{"text":"Go, and tell your friend about it tomorrow","then":"For the evening, nobody knows where you are."},{"text":"Go, since a second cafe is basically the same","then":"You're across town, somewhere nobody expects you to be."},{"text":"Let Tejas decide, and don't mention it","then":"You're off across town, and only he knows the plan."},{"text":"Check in with your friend before you go","then":"Your friend replies: \"Noted. Enjoy!\"","best":true}],"why":"Plans can change. A quick check-in keeps your net up to date."},{"prompt":"The date ends, and you're heading home. What do you do?","options":[{"text":"Get home, and tell your friend tomorrow","then":"Your friend spends the evening wondering if you're okay."},{"text":"Text your friend once you're home safe","then":"Your friend replies with a heart, and the loop is closed.","best":true},{"text":"Post 'home safe!' on your story instead","then":"Lots of likes, but your friend never sees it."},{"text":"Let Tejas drop you and send him your pin","then":"Tejas now has your home pin."}],"why":"A quick 'home safe' closes the loop, so your friend can stop watching out."}],"debrief":"Live location goes to a friend you trust, never your address to a stranger.","relearn":"Share live location with a friend, not your address with a match."},
  {"id":"sr-1182","cat":"meeting-safely","type":"branch","persona":"any","source":"changed mind","hook":"Your date with Om is tomorrow, but your gut now says you don't want to go.","steps":[{"prompt":"You've already said yes. What do you do?","options":[{"text":"Go anyway. You already said yes","then":"You go, smile through it, and feel drained after."},{"text":"Send a brief, kind message cancelling","then":"Om replies: \"Oh, okay. Thanks for letting me know.\"","best":true},{"text":"Cancel an hour before with a vague excuse","then":"Om is already on his way when he sees it."},{"text":"Make up a family emergency","then":"Om sends kind wishes and asks if everything's okay."}],"why":"A plan isn't a contract. You can change your mind and cancel kindly."},{"prompt":"Later, your roommate Juhi asks why you seem off. What do you say?","options":[{"text":"Say you're fine, and keep it in","then":"Juhi lets it go, and the feeling stays."},{"text":"Ask her to decide for you next time","then":"Juhi hesitates. \"It's not really up to me.\""},{"text":"Tell her your gut said no to this date","then":"Juhi nods. \"Your gut's worth listening to.\"","best":true},{"text":"Say changing your mind makes you flaky","then":"The guilt grows louder than your gut."}],"why":"Your gut's no is valid. Saying it out loud helps you trust it."},{"prompt":"A few days later, Om asks if you'd like to meet another time. What do you do?","options":[{"text":"Say yes to make up for it","then":"A new date is set that you don't want either."},{"text":"Leave him on read","then":"Om sends a '?' and waits."},{"text":"Say 'maybe' to keep it open","then":"Om checks in again next week, hopeful."},{"text":"Say thanks, but you'd rather not","then":"Om writes: \"Fair enough. Take care.\"","best":true}],"why":"A clear, kind no is kinder than a maybe. You never owe a date."}],"debrief":"Changing your mind before a date is fine. A short, kind cancel is all it takes.","relearn":"You can cancel a planned meet any time; a no is always allowed."},
  {"id":"sr-1183","cat":"meeting-safely","type":"branch","persona":"Meena","source":"offline safety","hook":"Your data's nearly gone, and you worry safe dating means constant check-ins.","steps":[{"prompt":"You're meeting Ravi on your day off. What do you plan?","options":[{"text":"Skip telling anyone. You can't text much","then":"Only you and Ravi know the plan."},{"text":"Meet wherever he picks, since he knows the area","then":"Ravi picks a spot you've never been to."},{"text":"Tell a workmate, and meet at the market","then":"Your workmate Shanti says: \"Market at four. I'll look out for you.\"","best":true},{"text":"Ask Ravi to message your friend for you","then":"Ravi says sure, but now your net runs through him."}],"why":"Telling someone face to face counts. The net needs no data."},{"prompt":"On your day off, Ravi suggests going somewhere quieter. What do you do?","options":[{"text":"Stay where people are, at a tea stall nearby","then":"Ravi shrugs. \"Okay, tea it is.\"","best":true},{"text":"Go, since quiet means you can talk","then":"You follow him away from the crowd."},{"text":"Go, but ask him to let your workmate know","then":"He says he will, and doesn't."},{"text":"Worry that saying no will offend him","then":"You hesitate, and the quiet spot is still on the table."}],"why":"Busy public places are free safety. You can stay where people are."},{"prompt":"Ravi asks for your address so he can visit next week. What do you do?","options":[{"text":"Give it. He's been nice today","then":"Ravi now knows where you live and when you're off."},{"text":"Suggest meeting at the market instead","then":"Ravi nods. \"Market it is, then.\"","best":true},{"text":"Give him your workplace instead","then":"Now he knows where to find you every day."},{"text":"Give just your lane, not your house number","then":"Ravi now knows your area, if not your door."}],"why":"Your address is earned. Public places work until you trust someone."},{"prompt":"It's time to head back to your room. What do you do?","options":[{"text":"Let Ravi walk you right to your door","then":"Ravi now knows exactly where you live."},{"text":"Stay out late, and sort the way back later","then":"The last bus has gone, and you're working it out alone."},{"text":"Get back, and skip telling anyone","then":"Nobody knows the day ended fine."},{"text":"Take the bus, then tell your workmate","then":"Your workmate waves, and your day off ends easy.","best":true}],"why":"Your own way back and a word to someone close the loop, offline."}],"debrief":"Safety works offline: a person told in advance and a busy, public place.","relearn":"Meet-safe steps work offline: tell a friend in person, meet where people are."},
  {"id":"sr-1184","cat":"meeting-safely","type":"branch","persona":"any","source":"watch your drink","hook":"At a bar on your first date, Rohit offers to fetch your drink while you wait.","steps":[{"prompt":"The bar's crowded and he's already standing up. What do you do?","options":[{"text":"Let him bring it and don't think about it","then":"He comes back with two drinks you didn't see made."},{"text":"Go up with him and order your own","then":"Rohit shrugs. \"Sure, come on.\" You order together.","best":true},{"text":"Ask him to bring a sealed bottle instead","then":"He comes back with a bottle, already opened."},{"text":"Tell him you don't trust him with it","then":"Rohit sits back down, stung."}],"why":"Ordering your own is a quiet, easy habit, not an accusation."},{"prompt":"Later, you need the washroom and your drink is half full. What do you do?","options":[{"text":"Ask Rohit to watch it for you","then":"Rohit nods, then gets busy on his phone."},{"text":"Leave it, and finish it when you're back","then":"It sits alone for five minutes in a crowded bar."},{"text":"Leave it, and order a fresh one after","then":"You come back and order a new one, no fuss.","best":true},{"text":"Skip the washroom so you don't leave it","then":"You spend the next hour uncomfortable."}],"why":"A drink that's been out of your sight is easy to replace. Order fresh."},{"prompt":"At the end of the night, Rohit offers one last drink. What do you do?","options":[{"text":"Accept so the night ends on a high","then":"You feel foggier, and getting home feels harder."},{"text":"Accept, but let him order it","then":"A drink arrives that you didn't see made."},{"text":"Accept, and just leave it untouched","then":"It sits there, and he asks why you're not drinking."},{"text":"Say you're done for tonight","then":"Rohit nods. \"Fair. Let's get the bill.\"","best":true}],"why":"Ending the night clear-headed keeps your way home easy."}],"debrief":"Order your own drink and keep it in view. Tampering is always on the person who does it, never you.","relearn":"Keep your drink with you and order it yourself on a first meet."},
  {"id":"sr-1185","cat":"meeting-safely","type":"branch","persona":"Ananya","source":"first-time nerves","hook":"It's your first date ever, and nerves make you want to skip the safety 'rules'.","steps":[{"prompt":"You worry the steps will make you look uncool. What do you do?","options":[{"text":"Drop them all to seem casual","then":"You head out with no plan, and the nerves get louder."},{"text":"Keep one, and skip the ones that feel 'extra'","then":"You've picked a cafe, but no one knows you're there."},{"text":"Keep the simple steps. They let you relax","then":"You text a friend the plan and feel a little calmer.","best":true},{"text":"Ask your match which rules they follow","then":"They say 'none, relax', and you feel sillier."}],"why":"The steps aren't fear. With them in place, your nerves can settle."},{"prompt":"At the cafe, Rudra arrives and your hands are shaking. What do you do?","options":[{"text":"Order something strong to calm down","then":"Your head gets fuzzy, and the nerves just move around."},{"text":"Admit, lightly, that you're nervous","then":"Rudra laughs. \"Same! First time for me too.\"","best":true},{"text":"Pretend you date all the time","then":"Rudra asks about your best date ever, and you scramble for a story."},{"text":"Text a friend under the table all date","then":"Your friend replies, but Rudra notices you're elsewhere."}],"why":"Nerves are normal on a first date. Naming them lightly often helps you both."},{"prompt":"It's going okay, and Rudra offers you a lift home. What do you do?","options":[{"text":"Thank him and take your own way home","then":"Rudra smiles. \"Text me when you're back?\"","best":true},{"text":"Accept. Refusing would feel awkward","then":"He drops you, and now knows your gate."},{"text":"Accept, but get out at the corner","then":"He still learns your street."},{"text":"Say you'll 'see how you feel' later","then":"The question hangs over the rest of the date."}],"why":"Your own ride home keeps the ending yours, which makes relaxing easier."}],"debrief":"The safety steps aren't the scary part. They're what make a first date easy.","relearn":"First-meet nerves are normal; the safety steps are what let you relax."},
  {"id":"sr-1186","cat":"meeting-safely","type":"branch","persona":"any","source":"early leave kit","hook":"Halfway through your date with Aditya, you want to go, but you've no fare home.","steps":[{"prompt":"He's busy chatting and hasn't noticed. What do you do?","options":[{"text":"Hope he offers to drop you, so you needn't ask","then":"You wait for the offer, and time drags on."},{"text":"Stay till he leaves so you can share his cab","then":"The date drags on, and your exit is tied to his."},{"text":"Ask a friend to send you fare by UPI","then":"Your friend sends it in a minute, no questions asked.","best":true},{"text":"Ask him to lend you the fare","then":"Aditya agrees, a little surprised, and asks when you'll pay him back."}],"why":"Your way home shouldn't hang on your date. A friend's help keeps it yours."},{"prompt":"A few minutes later, Aditya suggests another place nearby. What do you do?","options":[{"text":"Say you're calling it a night","then":"Aditya nods. \"Okay. This was nice.\"","best":true},{"text":"Go, since you've no easy way home anyway","then":"The night goes on, on his plan."},{"text":"Go, and slip away when you can","then":"You spend the next hour planning an escape."},{"text":"Say you feel sick so he doesn't mind","then":"Aditya offers to take you home himself."}],"why":"You can end a date whenever you want. A short line is enough."},{"prompt":"Before your next date, you're packing your bag. What do you do?","options":[{"text":"Rely on your date to cover travel","then":"Your way home depends on how the date goes."},{"text":"Take just enough to get there","then":"Getting there is sorted. Getting back isn't."},{"text":"Keep fare, but spend it if the date runs long","then":"It's gone by dessert, and you're back where you started."},{"text":"Keep fare aside that you won't touch","then":"It sits in your wallet, ready if you want to leave.","best":true}],"why":"A bit of fare set aside means leaving is always your call."}],"debrief":"A bit of fare set aside means you can end the date whenever you want.","relearn":"Carry enough fare or credit to leave on your own at any point."},
  {"id":"sr-1187","cat":"meeting-safely","type":"branch","persona":"any","source":"pacing the meet","hook":"Kabir, a match you haven't met yet, has planned your first meeting as a whole day out.","steps":[{"prompt":"He sends the plan: brunch, a museum, then dinner. What do you reply?","options":[{"text":"Say yes to the whole day so he isn't let down","then":"He's thrilled. You're now set for ten hours with someone you've only texted."},{"text":"Say yes, and plan a fake excuse to leave by lunch","then":"He's happy. You spend the week rehearsing an emergency that isn't real."},{"text":"Agree to brunch and the museum, but not dinner","then":"Kabir drops dinner. You're still set for five hours with a near-stranger."},{"text":"Suggest a coffee first and see how it feels","then":"Kabir writes, \"Oh, sure. Coffee on Saturday?\" The first meet is now an hour you can end easily.","best":true}],"why":"A short first meet is easy to enjoy and easy to end, and you don't owe anyone a whole day."},{"prompt":"On Saturday, an hour in, it's pleasant, but you're ready to head home. What do you do?","options":[{"text":"Stay for hours more so it isn't awkward","then":"By evening you're drained and quiet, and Kabir wonders what he did wrong."},{"text":"Fake a call from home to get away","then":"It works, but Kabir texts later to ask if everything's okay at home."},{"text":"Thank him, say you enjoyed it, and head off","then":"Kabir smiles. \"This was nice. Again sometime?\" You get home with energy to spare.","best":true},{"text":"Hint that you're tired and wait for him to end it","then":"Kabir misses the hint and suggests one more stop. You go along, wishing you'd said so."}],"why":"You can end a meet whenever you like, and saying so plainly beats an excuse."},{"prompt":"That night Kabir asks for a full day out next time. You'd rather go slower. What do you reply?","options":[{"text":"Say yes, or he'll think you're not interested","then":"He books the whole day at once. You feel the knot in your stomach again."},{"text":"Tell him you'd like a few shorter meets first","then":"\"Fair enough,\" Kabir replies. \"Chai and a walk on Thursday?\"","best":true},{"text":"Reply \"maybe\" and hope he forgets","then":"He doesn't forget. He sends three day-out ideas by morning."},{"text":"Say you're busy for the next month","then":"Kabir goes quiet, unsure whether you want to see him at all."}],"why":"Naming your pace early lets a good match meet you there."}],"debrief":"A short first meet is plenty. You never owe a near-stranger a whole day.","relearn":"A short first meet is fine; you don't owe them a whole evening."},
  {"id":"sr-1188","cat":"meeting-safely","type":"branch","persona":"any","source":"won't-video-call","hook":"Your match Ishaan has skipped every video call you've suggested.","steps":[{"prompt":"He texts: \"Camera's broken again. Let's just meet Friday!\" What do you do?","options":[{"text":"Say you'd like a quick video call before meeting","then":"Ishaan sends a laughing emoji. \"You're so formal. Fine, I'll see.\"","best":true},{"text":"Agree to Friday, since his photos look real","then":"He's delighted and names a place. You still don't know if the face is his."},{"text":"Ask him for more photos instead of a call","then":"Three new photos arrive within minutes, all perfectly lit, all a little too polished."},{"text":"Tell yourself you're being too cautious","then":"You don't raise the call again. Ishaan starts planning Friday."}],"why":"A live call is the one check that shows who you're really talking to."},{"prompt":"The next day Ishaan sends a sweet voice note, asking to meet on Saturday instead. What do you do?","options":[{"text":"Take the voice note as proof and say yes","then":"He sends a heart and a cafe name. A voice tells you little about the face in the photos."},{"text":"Say yes, and plan to leave if he doesn't match his photos","then":"He agrees happily. You'd only find out who he is once you're already there."},{"text":"Tell him you're too busy this weekend","then":"He says he'll wait and asks about next week instead."},{"text":"Reply that a short video call comes first","then":"He goes quiet for an hour, then says his camera is still broken.","best":true}],"why":"A voice note is nice, but only a live call shows the face matches the photos."},{"prompt":"Your friend Farah hears about Ishaan and says calls before meeting are overkill. What do you do?","options":[{"text":"Decide Farah's right and tell Ishaan the call can wait","then":"He replies instantly: \"Great. So we just meet, no call?\""},{"text":"Ask Farah to come along on the meet","then":"Farah agrees, a bit bored of the topic. Nobody has seen Ishaan's face live yet."},{"text":"Tell Farah you'll meet once he's done a call","then":"Farah shrugs. \"Fair. Your rules.\" You feel steadier about it.","best":true},{"text":"Drop the subject and stay unsure","then":"You change the topic, and the question sits with you all evening."}],"why":"Friends can mean well. Your own safety step still stands."},{"prompt":"Ishaan says video calls make him anxious, and asks you to just trust him. What do you do?","options":[{"text":"Decide he's right that trust means skipping the call","then":"He's sweet again at once. The meet is set, and his face is still unconfirmed."},{"text":"Say the call isn't about trust, and hold off meeting","then":"He sends a long, sulky message. Days pass and the call never happens.","best":true},{"text":"Send him a selfie to show that you're real","then":"He sends hearts, and still no call. Now he has your photo, and you have none of him."},{"text":"Tell him he must be a fake until he proves otherwise","then":"He calls you paranoid, and the chat turns into a fight."}],"why":"Pressure to skip a safety step is his, never your fault. Waiting is fair."}],"debrief":"A match who'll never video-call but rushes to meet is a reason to wait.","relearn":"Won't ever video-call before meeting is a sign to wait, not rush."},
  {"id":"sr-1189","cat":"meeting-safely","type":"sort","persona":"any","source":"meet-safe basics","relearn":"Public spot, friend told, own transport and a clear head are meet-safe; their flat, no one told, and getting drunk are risks.","hook":"Sort each first-meet choice: meet-safe, or a risk?","items":[{"id":"a","text":"A busy public cafe"},{"id":"b","text":"Going straight to their flat"},{"id":"c","text":"Telling a friend your plan"},{"id":"d","text":"Telling absolutely no one"},{"id":"e","text":"Your own ride home"},{"id":"f","text":"Getting too drunk to think"}],"bins":[{"id":"safe","label":"Meet-safe","valence":"pos"},{"id":"risk","label":"Risk","valence":"neg"}],"key":{"a":"safe","b":"risk","c":"safe","d":"risk","e":"safe","f":"risk"}},
  {"id":"sr-1190","cat":"meeting-safely","type":"sort","persona":"any","source":"reassure vs warn","relearn":"Happy to video-call, relaxed about pace and a public meet reassure; dodging calls, rushing privacy and 'tell no one' warn.","hook":"Sort each pre-meet sign: reassuring, or a warning?","items":[{"id":"a","text":"Happy to video-call first"},{"id":"b","text":"Always too busy to call"},{"id":"c","text":"Relaxed about your pace"},{"id":"d","text":"Pushing to meet privately, fast"},{"id":"e","text":"Fine with a public cafe"},{"id":"f","text":"\"Don't tell your friends about us\""}],"bins":[{"id":"good","label":"Reassuring","valence":"pos"},{"id":"warn","label":"Warning","valence":"neg"}],"key":{"a":"good","b":"warn","c":"good","d":"warn","e":"good","f":"warn"}},
  {"id":"sr-1191","cat":"meeting-safely","type":"sort","persona":"any","source":"exit plan","relearn":"Your own booked ride, fare in hand and a friend on standby make an exit plan; relying on them or having no way back leaves you stuck.","hook":"Sort each: a solid exit plan, or leaves you stuck?","items":[{"id":"a","text":"Your own ride booked ahead"},{"id":"b","text":"Relying on them to drop you"},{"id":"c","text":"Fare or app credit in hand"},{"id":"d","text":"No way home but with them"},{"id":"e","text":"A friend ready to call you"},{"id":"f","text":"Their lift as your only option"}],"bins":[{"id":"exit","label":"Exit plan","valence":"pos"},{"id":"stuck","label":"Stuck","valence":"neg"}],"key":{"a":"exit","b":"stuck","c":"exit","d":"stuck","e":"exit","f":"stuck"}},
  {"id":"sr-1192","cat":"meeting-safely","type":"sort","persona":"any","source":"share with whom","relearn":"Your plan and live location go to a trusted friend; your home address, OTP and bank details stay private from a new match.","hook":"Sort each: share with a friend, or keep private from a match?","items":[{"id":"a","text":"Your plan, with a trusted friend"},{"id":"b","text":"Your home address, with a match"},{"id":"c","text":"Live location, with a friend"},{"id":"d","text":"Your OTP, with a match"},{"id":"e","text":"Tonight's venue, with a friend"},{"id":"f","text":"Your bank details, with a match"}],"bins":[{"id":"share","label":"Tell a friend","valence":"pos"},{"id":"keep","label":"Keep private","valence":"neg"}],"key":{"a":"share","b":"keep","c":"share","d":"keep","e":"share","f":"keep"}},
  {"id":"sr-1193","cat":"meeting-safely","type":"sort","persona":"any","source":"on the checklist","relearn":"Public, friend-told, own-transport and clear-headed are on the meet-safe checklist; sharing your address, going dark and getting drunk are not.","hook":"Sort each: on the meet-safe checklist, or not on it?","items":[{"id":"a","text":"Meet in a public place"},{"id":"b","text":"Share your home address first"},{"id":"c","text":"Tell a trusted friend"},{"id":"d","text":"Go dark, reply to no one"},{"id":"e","text":"Keep your own transport"},{"id":"f","text":"Get drunk to relax"}],"bins":[{"id":"on","label":"On checklist","valence":"pos"},{"id":"off","label":"Not on it","valence":"neg"}],"key":{"a":"on","b":"off","c":"on","d":"off","e":"on","f":"off"}},
  {"id":"sr-1194","cat":"meeting-safely","type":"sort","persona":"any","source":"calm vs fear","relearn":"Safety steps are calm, free habits that let you date freely; treating them as proof the world is terrifying is the fear-framing to drop.","hook":"Sort each thought: a calm safety habit, or fear-talk to drop?","items":[{"id":"a","text":"\"I'll meet in public, simple\""},{"id":"b","text":"\"Everyone out there is dangerous\""},{"id":"c","text":"\"A friend knows where I am\""},{"id":"d","text":"\"Dating is just too risky to try\""},{"id":"e","text":"\"I've got my own ride sorted\""},{"id":"f","text":"\"One date and I'll be a headline\""}],"bins":[{"id":"calm","label":"Calm habit","valence":"pos"},{"id":"fear","label":"Fear-talk","valence":"neg"}],"key":{"a":"calm","b":"fear","c":"calm","d":"fear","e":"calm","f":"fear"}},
  {"id":"sr-1195","cat":"meeting-safely","type":"sort","persona":"any","source":"green vs red moves","relearn":"Suggesting a call, a public spot and going at your pace are green moves; refusing to call, pushing privacy and rushing you are red ones.","hook":"Sort each move they make: green, or red?","items":[{"id":"a","text":"\"Sure, let's video-call first\""},{"id":"b","text":"\"Why bother with a call?\""},{"id":"c","text":"\"A public cafe works for me\""},{"id":"d","text":"\"Skip the cafe, come over\""},{"id":"e","text":"\"No rush, your pace is fine\""},{"id":"f","text":"\"Don't be uptight, just trust me\""}],"bins":[{"id":"green","label":"Green move","valence":"pos"},{"id":"red","label":"Red move","valence":"neg"}],"key":{"a":"green","b":"red","c":"green","d":"red","e":"green","f":"red"}},
  {"id":"sr-1196","cat":"meeting-safely","type":"sort","persona":"any","source":"who to tell","relearn":"A trusted friend, flatmate or sibling are safe people to tell; the new match and a public post are not your safety net.","hook":"Sort each: a safe person to tell, or not your safety net?","items":[{"id":"a","text":"A trusted close friend"},{"id":"b","text":"The match you've not met"},{"id":"c","text":"A flatmate you trust"},{"id":"d","text":"A public Instagram story"},{"id":"e","text":"A sibling you trust"},{"id":"f","text":"Nobody at all"}],"bins":[{"id":"tell","label":"Safe to tell","valence":"pos"},{"id":"no","label":"Not your net","valence":"neg"}],"key":{"a":"tell","b":"no","c":"tell","d":"no","e":"tell","f":"no"}},
  {"id":"sr-1236","cat":"meeting-safely","type":"sort","persona":"any","source":"first vs later","relearn":"A public spot, a clear head and your own ride suit a first meet; a private place and overnight plans belong much later, once trust is built.","hook":"Sort each: fits a first meet, or belongs much later?","items":[{"id":"a","text":"A busy public cafe"},{"id":"b","text":"Going to their flat"},{"id":"c","text":"Keeping a clear head"},{"id":"d","text":"An overnight trip together"},{"id":"e","text":"Your own ride home"},{"id":"f","text":"Sharing your house keys"}],"bins":[{"id":"first","label":"First meet","valence":"pos"},{"id":"later","label":"Much later","valence":"neg"}],"key":{"a":"first","b":"later","c":"first","d":"later","e":"first","f":"later"}},
  {"id":"sr-1237","cat":"meeting-safely","type":"sort","persona":"any","source":"do vs skip","relearn":"Telling a friend, meeting in public and booking your own ride are do-it steps; getting drunk, going silent and sharing your address are ones to skip.","hook":"Sort each first-meet move: do it, or skip it?","items":[{"id":"a","text":"Tell a friend your plan"},{"id":"b","text":"Get drunk to relax"},{"id":"c","text":"Meet somewhere public"},{"id":"d","text":"Go silent, reply to no one"},{"id":"e","text":"Book your own ride"},{"id":"f","text":"Share your home address"}],"bins":[{"id":"do","label":"Do it","valence":"pos"},{"id":"skip","label":"Skip it","valence":"neg"}],"key":{"a":"do","b":"skip","c":"do","d":"skip","e":"do","f":"skip"}},
  {"id":"sr-1238","cat":"meeting-safely","type":"sort","persona":"any","source":"their reply reads","relearn":"\"Public works\", \"let's call\" and \"no rush\" reassure; \"tell no one\", \"why so careful\" and \"just trust me\" pressure you to drop your steps.","hook":"Sort each reply they give: reassuring, or pressure?","items":[{"id":"a","text":"\"A public cafe works for me\""},{"id":"b","text":"\"Don't tell anyone about us\""},{"id":"c","text":"\"Sure, let's video-call first\""},{"id":"d","text":"\"Why are you so careful?\""},{"id":"e","text":"\"No rush, your pace is fine\""},{"id":"f","text":"\"Just trust me, come over\""}],"bins":[{"id":"ok","label":"Reassuring","valence":"pos"},{"id":"push","label":"Pressure","valence":"neg"}],"key":{"a":"ok","b":"push","c":"ok","d":"push","e":"ok","f":"push"}},
  {"id":"sr-1239","cat":"meeting-safely","type":"sort","persona":"any","source":"empowering vs scary","relearn":"\"My steps let me date freely\" framings empower; \"the world is too dangerous\" framings are the fear-talk to drop, not the steps.","hook":"Sort each thought: empowering, or fear-talk?","items":[{"id":"a","text":"\"My steps let me date freely\""},{"id":"b","text":"\"The world's too dangerous out there\""},{"id":"c","text":"\"I've got a friend in the loop\""},{"id":"d","text":"\"Something bad will surely happen\""},{"id":"e","text":"\"I can leave whenever I want\""},{"id":"f","text":"\"Meeting anyone is a huge gamble\""}],"bins":[{"id":"free","label":"Empowering","valence":"pos"},{"id":"scary","label":"Fear-talk","valence":"neg"}],"key":{"a":"free","b":"scary","c":"free","d":"scary","e":"free","f":"scary"}},
  {"id":"sr-1240","cat":"meeting-safely","type":"sort","persona":"any","source":"true vs false","relearn":"You can leave any time, a friend told keeps you safer, a public meet is normal: true. Needing an excuse, drinking for nerves, address-sharing: false.","hook":"Sort each meet-safe belief: true, or false?","items":[{"id":"a","text":"You can leave a date any time"},{"id":"b","text":"You need an excuse to leave"},{"id":"c","text":"A friend told keeps you safer"},{"id":"d","text":"Drink lots to calm nerves"},{"id":"e","text":"A public first meet is normal"},{"id":"f","text":"Sharing your address is polite"}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"false","label":"False","valence":"neg"}],"key":{"a":"true","b":"false","c":"true","d":"false","e":"true","f":"false"}},
  {"id":"sr-1197","cat":"meeting-safely","type":"role-play","persona":"any","source":"set up check-in","hook":"You have a first date tonight and want your friend Imran to hold the plan.","setup":"You call him while you're getting ready.","steps":[{"prompt":"Imran asks: \"Tonight's the date, right? What's the plan?\"","options":[{"text":"\"Brew Cafe, 7pm. I'll text you when I'm home.\"","then":"\"Got it,\" Imran says. \"No text by 11 and I'm calling.\"","best":true},{"text":"\"Out tonight. Might be back late, who knows.\"","then":"\"Okay, have fun,\" he says. He couldn't find you if he needed to."},{"text":"\"I'll send you their profile, just in case.\"","then":"A screenshot lands. Imran knows who, but not where or when."},{"text":"\"You'll judge me. I'd rather not say.\"","then":"\"I won't,\" he says, a bit hurt. The plan stays with you alone."}],"why":"A place, a time and a check-in give your friend what they need."},{"prompt":"At 10:30, Imran texts: \"Hey. Haven't heard from you. All good?\"","options":[{"text":"\"Relax. Why are you checking on me?\"","then":"He sends an eye-roll emoji and says nothing more."},{"text":"\"Fine. Will text tomorrow.\"","then":"\"Okay,\" he replies. Now he won't know if you get home tonight."},{"text":"\"Can't talk. I'm still on the date!\"","then":"He waits. You forget to text again, and he stays up wondering."},{"text":"\"All good! Leaving now. Home in 20.\"","then":"\"Great,\" Imran replies. \"Text me once you're in.\"","best":true}],"why":"A quick reply with a new time keeps the net working till you're home."},{"prompt":"The next day, Imran asks: \"I've got a date next week. Will you be my check-in?\"","options":[{"text":"\"Sure, but you're a guy. You'll be fine.\"","then":"Imran frowns. \"Anyone can have a bad date, you know.\""},{"text":"\"Sure. Just message me if anything goes wrong.\"","then":"\"Okay,\" he says. Without the plan, you wouldn't know where to look."},{"text":"\"Yes. Send me where and when, and text when you're home.\"","then":"\"Deal,\" he says, and shares a cafe name and time on the spot.","best":true},{"text":"\"You don't need one. You know how to handle yourself.\"","then":"He shrugs. \"I guess.\" He goes without telling anyone."}],"why":"Holding the plan for each other makes the habit normal for everyone."}],"relearn":"Telling a friend the plan and a check-in time is a simple safety net."},
  {"id":"sr-1198","cat":"meeting-safely","type":"role-play","persona":"any","source":"suggest video call","hook":"You'd like to video-call Joel before your first meet. He's been lovely in chat.","setup":"He's messaging you late one evening.","steps":[{"prompt":"Joel asks: \"When can I finally see you in person?\"","options":[{"text":"\"Never mind a call. Photos look fine. Saturday?\"","then":"\"Saturday's perfect!\" he replies. The face in the photos is still unconfirmed."},{"text":"\"Soon! Fancy a quick video call first?\"","then":"\"Sure,\" Joel says, then adds a nervous emoji.","best":true},{"text":"\"When you've sent a few more selfies.\"","then":"Three selfies arrive, all lovely. Photos can still be old, borrowed or edited."},{"text":"\"Sorry, it's silly, but could we maybe video-call?\"","then":"\"Uh, sure?\" Joel says. \"You sound worried. Is everything okay?\""}],"why":"Suggesting a call as a normal, fun step makes it easy to say yes to."},{"prompt":"Joel says: \"My sister says we should video-call first. I'm so awkward on live video, though.\"","options":[{"text":"\"Same here! Five minutes, no pressure to look good.\"","then":"Joel laughs. \"Okay. Five minutes, sometime this week.\"","best":true},{"text":"\"Then no call. Let's just meet Saturday.\"","then":"\"Really? Great!\" he says. You're set to meet someone you've never seen live."},{"text":"\"A voice call works too, then.\"","then":"He calls within minutes. He sounds nice, and you still haven't seen his face."},{"text":"\"Everyone says that. Makes me wonder, honestly.\"","then":"\"Wonder what?\" Joel asks, a little stung."}],"why":"Keeping the call short and low-stakes holds your step without pushing him."},{"prompt":"The next day, Joel says: \"Saturday, then? I'll book us somewhere.\"","options":[{"text":"\"Book wherever you like. I'll trust you.\"","then":"He books a place you've never heard of, across town."},{"text":"\"Sure. Pick me up from my hostel?\"","then":"\"Of course,\" he says. Now he knows where you live, and you haven't met."},{"text":"\"Saturday! Let's skip the call. Too much fuss.\"","then":"\"Yay,\" he says. The one check you wanted has quietly dropped away."},{"text":"\"Saturday's good, after a quick call.\"","then":"\"Deal,\" Joel says. \"Call first, then chai.\"","best":true}],"why":"Keeping the call as the step before the meet is a simple rule you can hold."},{"prompt":"Joel asks: \"Do you usually video-call people before meeting them?\"","options":[{"text":"\"Only with people who seem a bit too good to be true.\"","then":"Joel pauses. \"Is that what you think of me?\""},{"text":"\"Not really. I'm probably being paranoid.\"","then":"\"Ha, maybe,\" he says, and the call slips down the list."},{"text":"\"Yes. It's just how I start, with anyone.\"","then":"\"Makes sense,\" Joel says. \"I might start doing that too.\"","best":true},{"text":"\"My friends make me. It's not my idea.\"","then":"\"Oh, your friends,\" he says. \"So you don't really need it?\""}],"why":"Owning the call as your normal step makes it easy to keep with anyone."}],"relearn":"Suggesting a quick video call before meeting is easy and normal to say."},
  {"id":"sr-1199","cat":"meeting-safely","type":"role-play","persona":"any","source":"name the public spot","hook":"You're meeting Sana from the app for the first time next week.","setup":"She messages while you're on the bus.","steps":[{"prompt":"Sana asks: \"Where would you like to meet? I'm easy.\"","options":[{"text":"\"Wherever you want is fine. You decide.\"","then":"Sana suggests a quiet place near her flat. You don't know the area at all."},{"text":"\"My place is free on Saturday. Just come over.\"","then":"\"Oh,\" she types. \"Your place? For a first meet?\""},{"text":"\"The cafe on MG Road? I love their chai.\"","then":"\"Oh, I know it!\" Sana says. \"Chai it is.\"","best":true},{"text":"\"Somewhere quiet where we can really talk?\"","then":"Sana suggests a tiny rooftop place she knows. It's usually empty at night."}],"why":"Naming a busy public spot you know keeps the first meet easy and on open ground."},{"prompt":"Your friend Ritika asks: \"So where are you meeting this Sana person?\"","options":[{"text":"\"Not sure yet. She's sorting it.\"","then":"Ritika frowns. \"Tell me once you know?\" You forget to."},{"text":"\"I'll send you the place and time now, and text after.\"","then":"\"Perfect,\" Ritika says. \"And call me if you want an exit.\"","best":true},{"text":"\"Somewhere near her place. It'll be fine.\"","then":"\"Near her place?\" Ritika asks. \"Not somewhere you know?\""},{"text":"\"I'll tell you all about it after!\"","then":"Ritika laughs. \"Okay.\" She has no idea where you'll be till then."}],"why":"Sharing the place and time with a friend backs up your public-meet plan."},{"prompt":"On Saturday, Sana texts: \"Change of plan? My flat's closer. We can order in.\"","options":[{"text":"\"First meets are in public for me. MG Road cafe?\"","then":"\"Fair enough,\" Sana replies. \"Cafe it is.\"","best":true},{"text":"\"Sure. You seem lovely, so it's fine.\"","then":"She sends a building name. The first meet is now in a private flat."},{"text":"\"How about my place instead?\"","then":"\"Even better,\" she says. The first meet is still somewhere private."},{"text":"\"Okay, but I'll share my live location with Ritika.\"","then":"Ritika gets the pin. The first meet is still in a flat, with someone you've just met."}],"why":"A public place for a first meet is a fair line, and a warm no keeps it easy."}],"relearn":"Naming a public place warmly keeps the first meet on safe, open ground."},
  {"id":"sr-1200","cat":"meeting-safely","type":"role-play","persona":"any","source":"decline the lift","hook":"Your first date with Nikhil is on Friday, and he's keen to handle the travel.","setup":"You're on a video call, sorting out the plan.","steps":[{"prompt":"Nikhil says: \"Just send me your address. I'll come get you at 6.\"","options":[{"text":"\"Okay, sure. You can pick me up, I guess.\"","then":"He asks for your address. Someone you haven't met now knows where you live."},{"text":"\"Thanks, but I'll make my own way. See you there!\"","then":"\"Oh, sure,\" Nikhil says. \"Meet you at the gate at 6.\"","best":true},{"text":"\"Could you pick me up from the metro instead of home?\"","then":"\"Done,\" he says. You'd still need him to get home."},{"text":"\"I don't get into cars with strangers.\"","then":"Nikhil's smile drops. \"Right. Okay. Stranger.\""}],"why":"Your own ride keeps your arrival and your exit in your hands."},{"prompt":"On Friday, as the date ends, Nikhil says: \"It's late. Let me drop you home.\"","options":[{"text":"\"No need. My cab's two minutes away. This was fun!\"","then":"\"Okay,\" Nikhil says. \"Text me when you're in?\"","best":true},{"text":"\"Oh, okay. It would save me the fare.\"","then":"You get in. The ride home now runs on his plans, not yours."},{"text":"\"Just drop me at the corner, not at my building.\"","then":"He agrees. He still learns your street, and you're still in his car."},{"text":"\"I'll wait here a while and figure it out.\"","then":"Nikhil offers to wait with you. The evening stretches on without a plan."}],"why":"Having your ride sorted means you leave when you choose."},{"prompt":"The next day, Nikhil texts: \"Did I overstep with the lift thing?\"","options":[{"text":"\"Bit much, yeah. Don't do that again.\"","then":"\"Oh. Sorry,\" he replies, and the chat goes cold."},{"text":"\"No, no! I'll take the lift next time, promise.\"","then":"\"Great!\" he says. You've traded your own ride away for next time."},{"text":"\"It's fine. My parents are just strict.\"","then":"\"Ah, okay,\" he says. Next time, he'll offer to drop you round the corner."},{"text":"\"Not at all. Next time I'd like my own ride, though.\"","then":"\"Got it,\" he says. \"Makes sense. Same again next week?\"","best":true}],"why":"Owning your own-ride habit warmly lets a good match respect it."}],"relearn":"Declining a lift warmly keeps your own way home without awkwardness."},
  {"id":"sr-1201","cat":"meeting-safely","type":"role-play","persona":"any","source":"leave when uneasy","hook":"Your date with Siddharth feels off, and you've decided to head home now.","setup":"You catch the waiter's eye for the bill.","steps":[{"prompt":"Siddharth asks: \"Leaving already? We've only just got here.\"","options":[{"text":"\"Sorry, I'm being silly. Let me stay a bit.\"","then":"He waves for menus. Twenty minutes on, still uneasy, you get up to go."},{"text":"\"My friend just texted. She needs me urgently.\"","then":"\"Oh no, I'll come with you,\" he says, already standing."},{"text":"\"Yes. I'm going to head off now. Take care.\"","then":"He shrugs. \"Okay then.\" You pay for your coffee and get up.","best":true},{"text":"\"Honestly, you've made me uncomfortable all night.\"","then":"His face hardens. \"Wow. Okay. What did I even do?\""}],"why":"A brief, polite line is all it takes. You don't owe a reason for leaving."},{"prompt":"Siddharth follows you to the door and says: \"At least let me walk you to your stop.\"","options":[{"text":"\"Okay. Saying no again feels rude.\"","then":"He walks you to the stop, talking the whole way. You don't relax until the bus comes."},{"text":"\"No thanks. I'm fine on my own. Bye!\"","then":"\"Suit yourself,\" he says, and heads back to the table.","best":true},{"text":"\"Only to the end of the road, then.\"","then":"He walks with you and asks which bus you take."},{"text":"\"Why would I want that?\"","then":"He stiffens. \"Just being nice. Relax.\""}],"why":"You can turn down company plainly. His pushing is on him, never your fault."},{"prompt":"On the bus, your friend Priya texts: \"How's the date going?\"","options":[{"text":"\"It felt off, so I'm heading home. Back in 20.\"","then":"\"Glad you're out,\" Priya replies. \"Text me when you're in.\"","best":true},{"text":"\"Fine! Tell you all about it tomorrow.\"","then":"\"Okay!\" she replies, with no idea how uneasy you felt."},{"text":"\"Ugh, I think I overreacted and left.\"","then":"\"Did you?\" Priya asks. You start doubting a feeling that was real."},{"text":"\"Can't talk. Nothing happened. Don't worry.\"","then":"Priya reads it twice and starts to worry anyway."}],"why":"Telling a friend you've left and when you'll be home closes the loop."},{"prompt":"Later, Siddharth texts: \"That was weird. Why did you leave?\"","options":[{"text":"\"Sorry! My fault. Can we try again?\"","then":"\"Sure,\" he says at once. Now there's a second date you didn't want."},{"text":"\"It's complicated. Let me explain everything.\"","then":"He replies, \"Go on,\" and argues with every reason you give."},{"text":"\"Something came up. Maybe another time!\"","then":"\"Next week?\" he asks at once. The door you meant to close is open again."},{"text":"\"I wasn't feeling it. Take care.\"","then":"\"Fine,\" he replies. Nothing more comes.","best":true}],"why":"A short, honest line ends it. You never owe a detailed reason."}],"relearn":"You can end a date briefly and politely; you don't owe a long reason."},
  {"id":"sr-1202","cat":"meeting-safely","type":"role-play","persona":"any","source":"hold the public plan","hook":"Your first meet with Aditya is at a cafe, but he keeps pushing to change it.","setup":"It's the evening before.","steps":[{"prompt":"Aditya says: \"Cafes are so loud. Come to mine instead. I'll cook.\"","options":[{"text":"\"You're right. I'm overthinking the cafe thing.\"","then":"He sends his address at once. The first meet is now in a private flat."},{"text":"\"Maybe. Let me think and tell you tomorrow.\"","then":"\"Sure,\" he says. \"But you'll love my cooking.\" The question hangs over the night."},{"text":"\"Your place, if you send me your full address now.\"","then":"He sends it right away. You're still meeting someone new, alone, in his flat."},{"text":"\"I'd like our first one at the cafe. See you there!\"","then":"\"Hm, okay,\" Aditya replies. \"Cafe, then.\"","best":true}],"why":"A first meet in public is a fair line, and saying it warmly keeps it simple."},{"prompt":"Your friend Rhea says: \"Just go to his. Being too careful is why nobody asks you out.\"","options":[{"text":"\"Maybe you're right. I'm too uptight about this stuff.\"","then":"Rhea nods, pleased. You start treating your own safety step as a flaw."},{"text":"\"Don't tell anyone about this, okay?\"","then":"\"Whatever,\" Rhea says. Now nobody knows where you'll be tomorrow."},{"text":"\"Public first meets are my rule. Can I send you the plan?\"","then":"Rhea rolls her eyes, then smiles. \"Fine. Send it. I'll hold it.\"","best":true},{"text":"\"I'll go to his, but share my location with you.\"","then":"Rhea agrees. She'll see a dot on a map inside a flat you've never been to."}],"why":"Friends can mean well and still be wrong. Your safety steps stay yours."},{"prompt":"On the day, Aditya texts: \"See you at mine at 5, yeah?\"","options":[{"text":"\"Sorry. I didn't mean to make this weird.\"","then":"\"It's okay,\" he says. \"So, mine at 5?\" The pressure hasn't moved."},{"text":"\"The cafe, or another day. Your pick.\"","then":"A long pause. \"Fine. Cafe at 5.\"","best":true},{"text":"\"Let me see how I feel in a bit.\"","then":"\"Cool,\" he replies. \"I'll get the food ready just in case.\""},{"text":"\"I guess after a month of chatting, it's not really a first meet.\"","then":"\"Exactly!\" he says. The first meet is now in his flat."}],"why":"Pushing past your plan is his pressure, never your fault. The public meet stands."}],"relearn":"You can hold the public-meet plan warmly when they push to skip it."},
  {"id":"sr-1203","cat":"meeting-safely","type":"role-play","persona":"Aarti","source":"tell a friend not family","hook":"Your family can't know you date, and you're meeting a match at 6 today.","setup":"Your college friend Meher is packing up after class.","steps":[{"prompt":"Meher asks: \"You look nervous. Everything okay?\"","options":[{"text":"\"Keep this between us? Meeting someone at 6. Will ping after.\"","then":"Meher's eyes widen. Then she nods. \"Our secret. Send me the place.\"","best":true},{"text":"\"It's nothing. Don't worry about me.\"","then":"Meher smiles. \"It's that app match, isn't it? I won't tell.\""},{"text":"\"I'm meeting someone, but please don't ask me anything more.\"","then":"Meher nods slowly. \"Okay. Is it the match you mentioned?\""},{"text":"\"Can you tell my mum I'm at yours tonight?\"","then":"\"I can,\" Meher says slowly. \"But where will you really be?\""}],"why":"A trusted friend can hold your plan even when family can't know."},{"prompt":"Meher asks: \"And what if something goes wrong tonight?\"","options":[{"text":"\"Nothing will. They seem really nice.\"","then":"Meher bites her lip. \"Okay. Just be careful?\""},{"text":"\"Then I'll handle it. I don't want to drag you into this.\"","then":"\"You wouldn't be dragging me,\" she says, but you leave it there."},{"text":"\"I'll text you if anything feels off, promise.\"","then":"\"Okay,\" she says. Without a time, she won't know when to worry."},{"text":"\"Here's the cafe and time. If I don't ping by 8, call me.\"","then":"Meher saves it in her notes. \"Done. And I'll call with an exit if you want one.\"","best":true}],"why":"A place, a time and a ping-by give your friend something real to hold."},{"prompt":"At 7:50, Meher texts: \"Just checking. How's it going?\"","options":[{"text":"\"Fine, stop worrying!\"","then":"She sends a sad face. She has no idea when you'll head back."},{"text":"\"All good! Might go somewhere else after, not sure where.\"","then":"\"Where?\" Meher asks. You don't answer, and the next place stays unknown."},{"text":"\"Going well! Leaving at 8:30. Will ping from the bus.\"","then":"\"Yay! Okay,\" Meher replies. \"Waiting for that ping.\"","best":true},{"text":"\"Don't text me here. They'll think it's weird.\"","then":"Meher goes quiet, unsure whether to keep checking."}],"why":"A quick update with your next move keeps your check-in working."},{"prompt":"The next day, Meher asks: \"Want me to be your person for these from now on?\"","options":[{"text":"\"No need. It went fine, so I'll manage.\"","then":"\"Okay,\" she says. Next time nobody will know where you are."},{"text":"\"Yes please. And I'll be yours too.\"","then":"Meher grins. \"Deal. Our own little safety club.\"","best":true},{"text":"\"Sure, but I won't always remember to ping.\"","then":"\"Then I'll ping you,\" she says, though you both know that's easy to miss."},{"text":"\"I'd rather not risk anyone finding out.\"","then":"Meher nods. The secret stays safe, and so does the gap in your safety net."}],"why":"One trusted friend holding the plan each time is a safety net that fits your life."}],"relearn":"Asking a trusted friend to hold your plan works even when family can't know."},
  {"id":"sr-1204","cat":"meeting-safely","type":"role-play","persona":"any","source":"keep a clear head","hook":"On your date, Faizan keeps ordering rounds, and you'd rather stay clear-headed.","setup":"The waiter has just brought two more drinks.","steps":[{"prompt":"Faizan says: \"Come on, one more! It's Friday.\"","options":[{"text":"\"Fine, one more. Don't want to seem boring.\"","then":"He cheers and orders another. Your head's fuzzier than you'd like."},{"text":"\"I'm good with water for now. Clear head tonight.\"","then":"\"Fair enough,\" Faizan says, and pushes the extra glass aside.","best":true},{"text":"\"I'll hold it and just not drink it.\"","then":"He keeps topping it up. The glass becomes a running joke all night."},{"text":"\"Sorry, I'm such a lightweight. It's so embarrassing.\"","then":"Faizan laughs. \"Then one more won't hurt!\""}],"why":"A clear, easy line keeps your own pace without making it a big deal."},{"prompt":"A bit later, Faizan says: \"Another round? Come on, everyone drinks on dates.\"","options":[{"text":"\"I'm having fun. I just like a clear head.\"","then":"He shrugs, smiling. \"Okay, okay. Fair.\"","best":true},{"text":"\"Maybe you're right. Everyone does.\"","then":"He grins and waves the waiter over. Your clear-head plan slips away."},{"text":"\"I can't. I'm on medicine this week, sadly.\"","then":"\"Ah, okay,\" he says. Next date, you'll need another excuse."},{"text":"\"Everyone? Where did you even get that idea from?\"","then":"He starts arguing the point, and the evening turns into a debate."}],"why":"Your pace is yours. A clear head doesn't need an excuse."},{"prompt":"As you're leaving, Faizan says: \"Next time, let's do a proper night out.\"","options":[{"text":"\"Sure! I'll keep up next time, promise.\"","then":"\"That's the spirit!\" he says. You've promised to drink past your own pace."},{"text":"\"Let's see. I'll text you.\"","then":"\"Cool,\" he says. What bothered you tonight goes unsaid."},{"text":"\"Sorry I was so dull tonight.\"","then":"\"You were fine!\" he says. You head home apologising for a choice that was yours to make."},{"text":"\"Maybe. Easy on the drinks next time, though.\"","then":"Faizan pauses. \"Fair. Your pace, if there's a next time.\"","best":true}],"why":"Pushing drinks is on the one pushing, never your fault. Naming your pace keeps it clear."},{"prompt":"On your way home, your friend Kavya texts: \"How did the date go?\"","options":[{"text":"\"Heading home. He kept pushing drinks all night.\"","then":"\"Ugh, that's a lot,\" Kavya replies. \"Text me when you're in?\"","best":true},{"text":"\"All good. He's fun, just drinks a lot.\"","then":"\"Ha, okay!\" Kavya replies. The pushing never comes up."},{"text":"\"Honestly? Probably my fault for being so boring.\"","then":"\"Boring?\" Kavya asks. You start blaming yourself for his pushing."},{"text":"\"Can't talk. Tell you some other time.\"","then":"Kavya sends a thumbs up. Nobody knows how pushy the evening got."}],"why":"Telling a friend how it went, and when you're home, means someone has your back."}],"relearn":"You can ask to slow the drinks and keep a clear head without it being a thing."},
  {"id":"sr-1205","cat":"meeting-safely","type":"role-play","persona":"any","source":"book own ride home","hook":"Your date with Manav is winding down, and he offers again to drop you home.","setup":"You're both standing outside the cafe.","steps":[{"prompt":"Manav says: \"Come on, hop on. It's on my way, really.\"","options":[{"text":"\"Oh... I suppose a lift would save me the fare.\"","then":"You get on. Now your ride home runs on his plans, not yours."},{"text":"\"Okay, but drop me at the corner, not at home.\"","then":"He agrees. You're still on his bike, and he'll know your street."},{"text":"\"All sorted. My cab's two minutes away. Thanks though!\"","then":"\"Ah, okay,\" Manav says. \"Text me when you're home?\"","best":true},{"text":"\"I'll decide in a bit. Let's chat some more first.\"","then":"You linger. It's late, and your own ride still isn't booked."}],"why":"Having your ride sorted keeps your exit firmly yours."},{"prompt":"Your friend Joel texts: \"Heading home yet? Share your ride?\"","options":[{"text":"\"Don't worry about me. I've got it.\"","then":"Joel sends a thumbs up, with no idea how you're getting home."},{"text":"\"Sharing my live location now, till I'm home.\"","then":"\"Got it,\" Joel replies. \"Watching the little dot.\"","best":true},{"text":"\"Will text when I'm back, if I remember.\"","then":"\"Please remember,\" Joel says. There's no trip link, just a hope."},{"text":"\"Leave me alone. I'm having a nice time.\"","then":"Joel goes quiet. He stops asking."}],"why":"Sharing your live location with a friend means someone knows you're on your way."},{"prompt":"Manav texts later: \"Fun night! Next time, let me take you both ways.\"","options":[{"text":"\"Me too! I'll get myself there, though. Chai again?\"","then":"\"Sure,\" Manav replies. \"Your way, your ride.\"","best":true},{"text":"\"Okay, next time you can pick me up.\"","then":"\"Great,\" he says. \"Send me your address.\" Your own ride is gone for next time."},{"text":"\"Maybe. We'll see how it goes, I suppose.\"","then":"\"Cool,\" he says. The lift question will come up again next time."},{"text":"\"Stop offering. It's getting really annoying.\"","then":"\"Oh. Sorry,\" he replies, and the chat goes cold."}],"why":"Saying you like your own ride makes it a habit, not a one-off."}],"relearn":"Saying you've got your own ride sorted keeps your exit firmly yours."},
  {"id":"sr-1206","cat":"meeting-safely","type":"role-play","persona":"any","source":"ask to video before meet","hook":"Harpreet, your match, has found a reason to skip every video call so far.","setup":"She's texted again this morning.","steps":[{"prompt":"Harpreet says: \"Let's stop chatting and just meet. Tomorrow?\"","options":[{"text":"\"Okay, forget the call. Tomorrow works.\"","then":"\"Yay!\" she says. You'll meet someone you've never seen live."},{"text":"\"Why do you keep dodging calls? What are you hiding?\"","then":"\"Hiding?\" she replies. \"Wow. Nothing.\" The chat turns tense."},{"text":"\"Tomorrow, but somewhere really busy.\"","then":"\"Sure,\" she says. You'll be in a crowd, still unsure who's coming."},{"text":"\"We keep missing a call. I'd like one before we meet.\"","then":"\"Ugh, calls are awkward,\" Harpreet replies. \"But fine, maybe.\"","best":true}],"why":"Naming it kindly and holding out for the call keeps your check without a fight."},{"prompt":"An hour later, Harpreet sends a voice note: \"Hi! Just so you know I'm real.\"","options":[{"text":"\"Okay, that's proof enough for me.\"","then":"She sends a heart. A voice still doesn't show you a face."},{"text":"\"Cute! Send a new photo too, just to be sure.\"","then":"A perfect photo arrives in seconds. Photos can be stolen or made by AI."},{"text":"\"Lovely! A quick video call still first?\"","then":"A long pause. \"Calls are awkward,\" she writes. \"I'll see.\"","best":true},{"text":"\"Sweet. Let's just meet and see how it goes.\"","then":"\"Finally!\" she writes. The one check you wanted is off the table."}],"why":"Only a live call shows the face matches. Waiting for one is fair."},{"prompt":"The next day, Harpreet writes: \"My friend says we should video-call first. Honestly, calls feel like an interview.\"","options":[{"text":"\"Fair. Let's skip it, then.\"","then":"\"Yay,\" she writes. \"Tomorrow at 7?\" You're meeting someone unverified."},{"text":"\"Five minutes, no questions. Then we plan the meet.\"","then":"Harpreet sends an eye-roll emoji. The call hasn't happened, and neither has the meet.","best":true},{"text":"\"Sorry. I'm probably being paranoid about it.\"","then":"\"See?\" she says. \"Tomorrow at 7, then.\" The call is off the table."},{"text":"\"Maybe I'll just bring a friend along instead.\"","then":"\"Sure,\" she says. Your friend will meet an unverified stranger too."}],"why":"Pressure to skip a check is on them, never your fault. Holding it calmly is fair."},{"prompt":"That evening, your friend Divya asks: \"So, are you meeting Harpreet this week?\"","options":[{"text":"\"Not till we've video-called. Hold me to that?\"","then":"\"Deal,\" Divya replies. \"And send me the plan once there is one.\"","best":true},{"text":"\"Maybe. Her voice note sounded real enough.\"","then":"\"Oh, nice,\" Divya says. A voice still hasn't shown you a face."},{"text":"\"Yes, but keep it quiet. The call thing is awkward.\"","then":"\"Okay,\" Divya says. Nobody else knows the call never happened."},{"text":"\"Yes. She says calls are awkward, and I get that.\"","then":"\"Fair enough,\" Divya says. The meet goes ahead with no call."}],"why":"Telling a friend your plan gives you backup when the pushing starts again."}],"relearn":"You can name that they keep dodging a call and wait for one before meeting."},
  {"id":"sr-1207","cat":"meeting-safely","type":"strike-rewrite","persona":"any","source":"safety isn't distrust","relearn":"Meet-safe steps aren't an insult; a good match keeps them with you.","hook":"\"Asking to meet in public means you don't trust them.\"","myth":{"un":"Asking to meet in public means you don't trust them.","re":"A public first meet is a normal, sensible step, not an accusation about them.","why":"A match worth meeting expects and respects the public-meet step."}},
  {"id":"sr-1208","cat":"meeting-safely","type":"strike-rewrite","persona":"any","source":"verify isn't rude","relearn":"A pre-meet video call is normal verification, not an insult.","hook":"\"Wanting a video call first is rude, like you're checking up on them.\"","myth":{"un":"Wanting a video call first is rude, like you're checking up on them.","re":"A quick video call before meeting is normal; it confirms a real person is there.","why":"Photos can be stolen or generated, so a live call is the reliable check."}},
  {"id":"sr-1209","cat":"meeting-safely","type":"strike-rewrite","persona":"any","source":"own way home","relearn":"Keeping your own way home is independence, not coldness.","hook":"\"Sorting your own ride home means you're being cold and standoffish.\"","myth":{"un":"Sorting your own ride home means you're being cold and standoffish.","re":"Keeping your own way home just means leaving stays your choice, not theirs.","why":"Your own transport means you can end the date whenever you want to."}},
  {"id":"sr-1210","cat":"meeting-safely","type":"strike-rewrite","persona":"any","source":"no reason to leave","relearn":"You can leave a date at any point without owing a reason.","hook":"\"You can't just leave a date, you'd need a proper excuse first.\"","myth":{"un":"You can't just leave a date, you'd need a proper excuse first.","re":"You can leave any date whenever you want, and you don't owe a reason.","why":"Your safety and comfort outrank politeness; an uneasy gut is reason enough."}},
  {"id":"sr-1211","cat":"meeting-safely","type":"strike-rewrite","persona":"Aarti","source":"told a friend","relearn":"Telling a trusted friend your plan is a safety move, not betrayal.","hook":"\"If family can't know you're dating, you must tell nobody at all.\"","myth":{"un":"If family can't know you're dating, you must tell nobody at all.","re":"Even when family can't know, telling one trusted friend keeps you safer.","why":"A friend knowing your plan is a safety net, not a betrayal of your privacy."}},
  {"id":"sr-1212","cat":"meeting-safely","type":"strike-rewrite","persona":"any","source":"sober first meet","relearn":"Staying clear-headed on a first meet keeps your judgement working.","hook":"\"You should drink plenty on a first date to take the edge off nerves.\"","myth":{"un":"You should drink plenty on a first date to take the edge off nerves.","re":"Staying mostly clear-headed on a first meet keeps your read on things sharp.","why":"A clear head lets your instincts speak and your judgement stay yours."}},
  {"id":"sr-1213","cat":"meeting-safely","type":"strike-rewrite","persona":"any","source":"steps are freedom","relearn":"Safety steps are how you date freely, not a sign to be afraid.","hook":"\"All these safety steps just prove dating is too scary to bother with.\"","myth":{"un":"All these safety steps just prove dating is too scary to bother with.","re":"The steps aren't fear; they're the simple habits that let you date freely.","why":"A public spot, a friend told and your own ride free you up to relax."}},
  {"id":"sr-1214","cat":"meeting-safely","type":"spot","persona":"any","source":"red-flag lines","relearn":"Pressure to skip a public meet or to tell no one are the red flags to catch.","hook":"Spot the two lines that pressure you to drop a safety step.","scene":[{"id":"a","text":"\"A public cafe sounds perfect.\"","trick":false},{"id":"b","text":"\"Just come to mine, don't be so uptight.\"","trick":true},{"id":"c","text":"\"Sure, video-call first, no problem.\"","trick":false},{"id":"d","text":"\"Why tell your friend? Don't you trust me?\"","trick":true},{"id":"e","text":"\"Take your own cab, that's totally fine.\"","trick":false}],"why":"Pushing you to skip the public meet or to tell no one are the red flags; the rest respect your steps."},
  {"id":"sr-1215","cat":"meeting-safely","type":"spot","persona":"any","source":"unsafe plan items","relearn":"Going to their flat unannounced and telling no one are the unsafe choices to catch.","hook":"Spot the two choices in this first-meet plan that are unsafe.","scene":[{"id":"a","text":"Busy cafe, daytime","trick":false},{"id":"b","text":"Straight to their flat instead","trick":true},{"id":"c","text":"A friend knows the plan","trick":false},{"id":"d","text":"Tell absolutely no one","trick":true},{"id":"e","text":"Own cab booked home","trick":false}],"why":"Going to a private flat and telling no one drop the safety; public, friend-told and own-ride keep it."},
  {"id":"sr-1216","cat":"meeting-safely","type":"spot","persona":"any","source":"pre-meet warning signs","relearn":"Always dodging calls and rushing to meet privately are the warning signs to catch.","hook":"Spot the two pre-meet warning signs here.","scene":[{"id":"a","text":"Happy to video-call first","trick":false},{"id":"b","text":"Always 'too busy' to call","trick":true},{"id":"c","text":"Relaxed about your pace","trick":false},{"id":"d","text":"Pushing to meet privately, fast","trick":true},{"id":"e","text":"Fine with a public spot","trick":false}],"why":"Dodging every call and rushing a private meet are the warnings; the rest are reassuring."},
  {"id":"sr-1217","cat":"meeting-safely","type":"spot","persona":"any","source":"info to guard","relearn":"Sending your home address and your OTP to a new match are the risky moves to catch.","hook":"Spot the two things you should not send a match you've never met.","scene":[{"id":"a","text":"\"Let's meet at the public library\"","trick":false},{"id":"b","text":"Your exact home address","trick":true},{"id":"c","text":"\"I'll be in a blue kurta\"","trick":false},{"id":"d","text":"Your banking OTP","trick":true},{"id":"e","text":"\"See you at 5 by the gate\"","trick":false}],"why":"Your home address and your OTP are private; meeting details and what you're wearing are fine to share."},
  {"id":"sr-1218","cat":"meeting-safely","type":"spot","persona":"any","source":"fear-talk lines","relearn":"\"Everyone is dangerous\" and \"dating is too risky to try\" are the fear-talk lines to catch.","hook":"Spot the two fear-talk lines that go too far.","scene":[{"id":"a","text":"\"I'll just meet in public, simple.\"","trick":false},{"id":"b","text":"\"Everyone out there is dangerous.\"","trick":true},{"id":"c","text":"\"A friend knows where I'll be.\"","trick":false},{"id":"d","text":"\"Dating is too risky to even try.\"","trick":true},{"id":"e","text":"\"My own ride is sorted, easy.\"","trick":false}],"why":"\"Everyone is dangerous\" and \"too risky to try\" are fear-talk; the rest are calm, doable habits."},
  {"id":"sr-1219","cat":"meeting-safely","type":"spot","persona":"any","source":"rushed-meet red flags","relearn":"A late-night private drive and refusing to ever video-call are the rush red flags to catch.","hook":"Spot the two red flags in how they're rushing the first meet.","scene":[{"id":"a","text":"Suggests a daytime coffee","trick":false},{"id":"b","text":"Wants a late-night drive, just you two","trick":true},{"id":"c","text":"Fine to meet near your area","trick":false},{"id":"d","text":"Refuses to ever video-call","trick":true},{"id":"e","text":"Okay with a short first meet","trick":false}],"why":"A late-night private drive and never video-calling are the red flags; the rest keep things open and easy."},
  {"id":"sr-1220","cat":"meeting-safely","type":"match","persona":"any","source":"red flag to move","relearn":"Each first-meet red flag has a clear safe move: won't-call -> wait, money-ask -> report, pressure -> hold your steps.","hook":"Match each red flag to the safe move.","pairs":[{"left":"Won't ever video-call","right":"Wait, don't meet yet"},{"left":"Pushes to skip the public meet","right":"Hold your public-spot plan"},{"left":"Asks an online-only match for money","right":"Don't pay, report it"},{"left":"Your gut feels off on the date","right":"Leave, no reason owed"},{"left":"Wants your home address early","right":"Keep it private for now"}]},
  {"id":"sr-1221","cat":"meeting-safely","type":"match","persona":"any","source":"step to why","relearn":"Each meet-safe step has a plain reason: public for openness, friend told for a net, own ride to leave, clear head to judge.","hook":"Match each safety step to why it helps.","pairs":[{"left":"Meet in a public place","right":"You're around other people"},{"left":"Tell a trusted friend","right":"Someone safe knows your plan"},{"left":"Keep your own transport","right":"You can leave any time"},{"left":"Stay clear-headed","right":"Your judgement stays sharp"},{"left":"Video-call before meeting","right":"You confirm they're real"}]},
  {"id":"sr-1222","cat":"meeting-safely","type":"match","persona":"any","source":"share with whom","relearn":"Match each detail to where it belongs: plans to a trusted friend, private info kept from a new match.","hook":"Match each detail to the right home.","pairs":[{"left":"Your live location tonight","right":"A trusted friend"},{"left":"Your home address","right":"Keep private for now"},{"left":"The venue and time","right":"A friend who'll check in"},{"left":"Your banking OTP","right":"Nobody, ever"},{"left":"The 'I'm home' message","right":"Send when you're back"}]},
  {"id":"sr-1223","cat":"meeting-safely","type":"match","persona":"any","source":"helpline routes","relearn":"Match each situation to its India route: image abuse to cybercrime 1930, harassment to 181, immediate danger to 112.","hook":"Match each situation to the right route.","pairs":[{"left":"An intimate image is shared","right":"Cybercrime 1930"},{"left":"Harassment or threats","right":"Helpline 181"},{"left":"Immediate danger right now","right":"Emergency 112"},{"left":"Knowing your date plan","right":"A trusted friend"},{"left":"A creepy profile to stop","right":"Report and block"}]},
  {"id":"sr-1224","cat":"meeting-safely","type":"match","persona":"any","source":"reassure vs warn","relearn":"Match each pre-meet sign to its read: open steps reassure, dodging and rushing and secrecy warn.","hook":"Match each sign to how it reads.","pairs":[{"left":"Happy to meet in public","right":"Reassuring and open"},{"left":"Dodges every video call","right":"A warning to slow down"},{"left":"Relaxed about your pace","right":"A good, easy sign"},{"left":"Rushes to a private place","right":"A red flag to hold steps"},{"left":"Fine you told a friend","right":"Respects your safety net"}]},
  {"id":"sr-1225","cat":"meeting-safely","type":"match","persona":"any","source":"plan to person","relearn":"Match each part of a meet-safe plan to who holds it: you, your friend, your own ride.","hook":"Match each plan part to who handles it.","pairs":[{"left":"Picking the public venue","right":"You decide it"},{"left":"Knowing when you're home","right":"Your friend tracks it"},{"left":"Your way back","right":"Your own booked ride"},{"left":"Calling to check you're ok","right":"Your friend on standby"},{"left":"Choosing to leave early","right":"Your call alone"}]},
  {"id":"sr-1226","cat":"meeting-safely","type":"match","persona":"any","source":"myth to truth","relearn":"Match each meet-safe myth to the truth that replaces it.","hook":"Match each myth to its truth.","pairs":[{"left":"Public meets mean distrust","right":"They're just sensible"},{"left":"Drinking calms first-date nerves","right":"A clear head helps more"},{"left":"You need an excuse to leave","right":"An uneasy gut is enough"},{"left":"Telling a friend is betrayal","right":"It's a safety net"},{"left":"Safety steps mean fear","right":"They let you date freely"}]},
  {"id":"sr-1227","cat":"meeting-safely","type":"match","persona":"any","source":"safe vs risky home","relearn":"Match each first-meet choice to its read: safe habits versus risky ones.","hook":"Match each choice to safe or risky.","pairs":[{"left":"Busy public cafe","right":"Safe and open"},{"left":"Straight to their flat","right":"Risky, too private"},{"left":"Own cab booked home","right":"Safe, you can leave"},{"left":"Getting very drunk","right":"Risky, dulls judgement"},{"left":"A friend told the plan","right":"Safe, a net in place"}]},
  {"id":"sr-1228","cat":"meeting-safely","type":"reflect","persona":"any","source":"your own pace","relearn":"How fast you move to meeting someone is your call; there's no timetable.","hook":"How soon do you like to meet a match in person?","prompt":"Your call:","options":["After a good few chats","Once we've video-called","Pretty quickly if it clicks","I take my time, no rush"],"affirm":"There's no right speed; meeting when it feels right to you is exactly the point."},
  {"id":"sr-1229","cat":"meeting-safely","type":"reflect","persona":"any","source":"what reassures you","relearn":"What makes a first meet feel safe enough is personal; your own steps are valid.","hook":"What helps a first date feel safe enough for you?","prompt":"Pick what fits:","options":["A friend knowing my plan","Meeting somewhere I know well","Having my own way home","A video call beforehand"],"affirm":"Whatever lets you relax and be yourself on a date is a step worth keeping."},
  {"id":"sr-1230","cat":"meeting-safely","type":"reflect","persona":"any","source":"who you'd tell","relearn":"Who you trust with your plan is yours to choose: a friend, a sibling, a flatmate.","hook":"Who would you tell about a first date?","prompt":"Your pick:","options":["A close friend","A sibling I trust","A flatmate","Whoever feels safest that day"],"affirm":"There's no single right person; the one you trust to have your back is the right call."},
  {"id":"sr-1231","cat":"meeting-safely","type":"reflect","persona":"Ananya","source":"first-date nerves","relearn":"Nerves before a first date are normal; how you steady yourself is your own.","hook":"What would help you feel steadier before a first date?","prompt":"What fits you:","options":["Telling a friend my plan","Picking a place I know","Reminding myself I can leave","Keeping the meet short"],"affirm":"First-date nerves are completely normal; whatever steadies you is good to lean on."},
  {"id":"sr-1232","cat":"meeting-safely","type":"reflect","persona":"any","source":"comfort to leave","relearn":"What makes leaving easier is yours to set up; you can always go.","hook":"What makes it easier for you to leave a date that's not working?","prompt":"Your call:","options":["Having my own ride ready","A friend on call","Knowing I owe no reason","A short meet planned anyway"],"affirm":"You can leave any date, any time; setting up what makes that easy is smart, not rude."},
  {"id":"sr-1233","cat":"meeting-safely","type":"reflect","persona":"Zoya","source":"your own way","relearn":"Your safety steps fit your life and who you meet; there's no one template.","hook":"Which safety steps feel most 'you' before meeting someone?","prompt":"Pick yours:","options":["A video call first","A public, lively spot","A friend in the loop","My own way home"],"affirm":"Dating safely looks a little different for everyone; the steps that fit your life are right."},
  {"id":"sr-1234","cat":"meeting-safely","type":"reflect","persona":"any","source":"trusting your gut","relearn":"You're allowed to act on a gut feeling; no proof needed to leave.","hook":"When your gut feels off on a date, what helps you act on it?","prompt":"What helps you:","options":["Remembering I owe no reason","Having my exit ready","A friend I can text","Just trusting the feeling"],"affirm":"An uneasy gut is reason enough; trusting it and leaving is always allowed."},
  {"id":"sr-1235","cat":"meeting-safely","type":"reflect","persona":"Deepak","source":"free safety","relearn":"The core meet-safe steps cost nothing; safety isn't about money.","hook":"Which free safety step would you reach for first?","prompt":"Your pick:","options":["A public, busy place","Texting a friend my plan","Meeting in daytime","Keeping my own way back"],"affirm":"The steps that matter most are free; dating safely was never about what you can spend."},
  {"id":"sr-1260","cat":"profiles-are-people","type":"reflect","hook":"Lensy: behind the photos is someone who, like you, just wants to be seen kindly.","prompt":"Sit with that?","options":["Yeah","A real person","Like me"],"affirm":"Once a profile stops being a card and becomes a person, the cruelty just falls away.","relearn":"Every profile is a real person with feelings, just like you.","persona":"any","source":"profiles are people"},
  {"id":"sr-1261","cat":"profiles-are-people","type":"reflect","hook":"Lensy: would you send that opener if they were standing right in front of you?","prompt":"Honestly?","options":["Probably not","Same words either way","Good check"],"affirm":"The 'would I say this to their face' test is the whole etiquette of apps in one line.","relearn":"Send only what you'd be okay saying to someone's face; decency doesn't pause for a screen.","persona":"any","source":"decency"},
  {"id":"sr-1262","cat":"profiles-are-people","type":"reflect","hook":"Lensy: a match isn't a trophy you won, it's a person who chose to say hi.","prompt":"Reframe it?","options":["Not a trophy","A person","Noted"],"affirm":"Matches as people, not points, is the difference between a hobby and a habit you'd be proud of.","relearn":"Matches are people, not a collection to be scored or led on.","persona":"any","source":"golden rule"},
  {"id":"sr-1263","cat":"profiles-are-people","type":"reflect","hook":"Lensy: which decency are you proudest to carry across every screen?","prompt":"Pick the one that's yours.","options":["I send what I'd want to get","I never pile on","I respect every identity"],"affirm":"Whichever you picked, that's exactly the kind of person worth matching with.","relearn":"On apps the normal rules of respect still apply, every screen.","persona":"any","source":"consolidation"},
  {"id":"sr-1264","cat":"profiles-are-people","type":"reflect","hook":"Lensy: Zoya keeps her profile soft on her orientation. That's her call, not yours to test.","prompt":"Respect her timeline?","options":["Her call","Her timeline","Of course"],"affirm":"Letting people share at their own pace is decency; never make them 'prove' or out themselves to you.","relearn":"Respect someone's pace on identity; never push them to prove or come out.","persona":"Zoya","source":"inclusive respect"},
  {"id":"sr-1265","cat":"profiles-are-people","type":"reflect","hook":"Lensy: someone screenshots a match's awkward bio to the group chat for laughs.","prompt":"Want to be in that chat?","options":["Not really","There's a person there","I'd leave it"],"affirm":"The instinct to not turn a real person into group-chat content is quietly a big deal.","relearn":"There's a real person behind every profile; don't turn them into a joke.","persona":"any","source":"kindness"},
  {"id":"sr-1266","cat":"profiles-are-people","type":"reflect","hook":"Lensy: Rohan used to rate matches out of ten with his mates. Lately it feels hollow.","prompt":"What changed?","options":["They're people","It got old","I grew up"],"affirm":"Noticing the hollowness is the whole shift, from scoring people to actually meeting them.","relearn":"Rating people like a leaderboard treats matches as objects, not people.","persona":"Rohan","source":"culture"},
  {"id":"sr-1267","cat":"profiles-are-people","type":"reflect","hook":"Lensy: the kindest thing on an app is often just a clear, warm 'not for me'.","prompt":"Worth doing?","options":["Worth it","Kinder than silence","Yeah"],"affirm":"A two-line kind sign-off costs you nothing and treats them like the person they are.","relearn":"A brief, kind 'this isn't for me' beats vanishing; honesty runs both ways.","persona":"any","source":"decency"},
  {"id":"sr-1268","cat":"profiles-are-people","type":"reflect","hook":"Lensy: Deepak feels his plain bio can't compete with the gym-and-travel feed.","prompt":"What would you tell him?","options":["Be himself","Real beats curated","His story counts"],"affirm":"A genuine, ordinary profile that's actually him will out-charm any highlight reel that isn't.","relearn":"You bring your whole self to dating; a real you beats a curated illusion.","persona":"Deepak","source":"realism"},
  {"id":"sr-1269","cat":"profiles-are-people","type":"reflect","hook":"Lensy: a match shares they're nervous about meeting. You could tease, or be gentle.","prompt":"Which feels like you?","options":["Be gentle","Reassure them","Both kind"],"affirm":"Meeting someone's nerves with softness is the golden rule, just on a smaller, kinder scale.","relearn":"Give every match the dignity and gentleness you'd want shown to you.","persona":"any","source":"golden rule"},
  {"id":"sr-1270","cat":"profiles-are-people","type":"reflect","hook":"Lensy: you can be warm, decent and kind online and still be nobody's pushover.","prompt":"True for you?","options":["Both at once","Kind isn't weak","Agreed"],"affirm":"Decency and a backbone live happily together; kindness reads as confidence, never weakness.","relearn":"Being decent online is a strength, not weakness; kindness reads as confidence.","persona":"any","source":"decency"},
  {"id":"sr-1271","cat":"profiles-are-people","type":"reflect","hook":"Lensy: Aarti worries dating apps make people 'replaceable'. Only if we let them.","prompt":"Your take?","options":["We choose","Not replaceable","People, not cards"],"affirm":"The app doesn't decide whether people are disposable, the way you treat them does.","relearn":"People aren't replaceable cards; how you treat a match is your choice, not the app's.","persona":"Aarti","source":"realism"},
  {"id":"sr-1272","cat":"profiles-are-people","type":"reflect","hook":"Lensy: imagine your own profile in a stranger's hands. How would you want it held?","prompt":"Picture it.","options":["With care","Read kindly","Like a person"],"affirm":"That feeling you just had is the exact care every profile in your hands deserves too.","relearn":"Hold every profile with the care you'd want yours held with.","persona":"any","source":"golden rule"},
  {"id":"sr-1273","cat":"profiles-are-people","type":"reflect","hook":"Lensy: it's just as kind to be decent to someone you'll never match with.","prompt":"Worth it anyway?","options":["Always","No audience needed","Yeah"],"affirm":"Decency that isn't for show, even to a no, is the realest kind there is.","relearn":"Be decent even to a match you'll pass on; respect isn't only for people you want.","persona":"any","source":"kindness"},
  {"id":"sr-1274","cat":"profiles-are-people","type":"sort","hook":"Sort: an opener that treats them as a person, or as an object?","items":[{"id":"a","text":"\"Your travel pics are class, where next?\""},{"id":"b","text":"\"Send a body pic.\""},{"id":"c","text":"\"Your bio made me grin.\""},{"id":"d","text":"A rating of their looks out of ten"},{"id":"e","text":"\"What's the band in your photo?\""},{"id":"f","text":"A crude line about what you'd 'do' to them"}],"bins":[{"id":"person","label":"As a person","valence":"pos"},{"id":"object","label":"As an object","valence":"neg"}],"key":{"a":"person","b":"object","c":"person","d":"object","e":"person","f":"object"},"relearn":"Curious, specific openers treat a match as a person; body demands, ratings and crude lines treat them as an object.","persona":"any","source":"openers"},
  {"id":"sr-1275","cat":"profiles-are-people","type":"sort","hook":"Sort: carries respect across the screen, or drops it because 'it's just an app'?","items":[{"id":"a","text":"Asking before sending a flirty pic"},{"id":"b","text":"\"It's only an app, who cares\""},{"id":"c","text":"Taking a no without an argument"},{"id":"d","text":"Pushing for a reason after a no"},{"id":"e","text":"Replying like they're a real person"},{"id":"f","text":"Copy-pasting the same crude line to ten people"}],"bins":[{"id":"carries","label":"Respect carries","valence":"pos"},{"id":"drops","label":"Respect dropped","valence":"neg"}],"key":{"a":"carries","b":"drops","c":"carries","d":"drops","e":"carries","f":"drops"},"relearn":"Consent, taking a no and treating them as real carry respect across the screen; 'it's just an app' drops it.","persona":"any","source":"respect online"},
  {"id":"sr-1276","cat":"profiles-are-people","type":"sort","hook":"Sort: treats them like a whole person, or like a stereotype?","items":[{"id":"a","text":"Asking what someone actually enjoys"},{"id":"b","text":"\"You're [city], so you must be...\""},{"id":"c","text":"Reading their bio before messaging"},{"id":"d","text":"Fetishising their background or accent"},{"id":"e","text":"Letting them tell you who they are"},{"id":"f","text":"Assuming their 'type' from one photo"}],"bins":[{"id":"whole","label":"Whole person","valence":"pos"},{"id":"box","label":"A stereotype","valence":"neg"}],"key":{"a":"whole","b":"box","c":"whole","d":"box","e":"whole","f":"box"},"relearn":"Asking and letting people define themselves treats them as whole; fetishising or assuming a 'type' boxes them.","persona":"any","source":"inclusive respect"},
  {"id":"sr-1277","cat":"profiles-are-people","type":"sort","hook":"Sort: how you end a chat, kindly or carelessly?","items":[{"id":"a","text":"\"You're lovely, but I'm not feeling a match.\""},{"id":"b","text":"Vanishing mid-conversation"},{"id":"c","text":"\"Take care, all the best.\""},{"id":"d","text":"Leaving them on read for weeks"},{"id":"e","text":"A short, honest 'not for me'"},{"id":"f","text":"Blocking with no word after a nice chat"}],"bins":[{"id":"kind","label":"Kindly","valence":"pos"},{"id":"careless","label":"Carelessly","valence":"neg"}],"key":{"a":"kind","b":"careless","c":"kind","d":"careless","e":"kind","f":"careless"},"relearn":"A brief honest sign-off ends a chat kindly; ghosting, leaving on read or a silent block is careless.","persona":"any","source":"decency"},
  {"id":"sr-1278","cat":"profiles-are-people","type":"sort","hook":"Sort: builds someone up, or chips at their dignity?","items":[{"id":"a","text":"A genuine compliment about their work"},{"id":"b","text":"Mocking their English in a DM"},{"id":"c","text":"Being curious about their world"},{"id":"d","text":"Negging to 'lower their guard'"},{"id":"e","text":"Letting them share at their pace"},{"id":"f","text":"Pressuring for photos they didn't offer"}],"bins":[{"id":"up","label":"Builds dignity","valence":"pos"},{"id":"chip","label":"Chips at it","valence":"neg"}],"key":{"a":"up","b":"chip","c":"up","d":"chip","e":"up","f":"chip"},"relearn":"Genuine interest and patience build dignity; mocking, negging or pressure chip away at it.","persona":"Deepak","source":"kindness"},
  {"id":"sr-1279","cat":"profiles-are-people","type":"sort","hook":"Sort: would you be okay to receive it, or not?","items":[{"id":"a","text":"\"Loved your book photo, what's it about?\""},{"id":"b","text":"An unsolicited explicit image"},{"id":"c","text":"A warm, normal hello"},{"id":"d","text":"Twenty 'why aren't you replying' texts"},{"id":"e","text":"\"No worries if not, just thought I'd say hi.\""},{"id":"f","text":"A demand to 'prove' you're really single"}],"bins":[{"id":"okay","label":"Okay to receive","valence":"pos"},{"id":"not","label":"Not okay","valence":"neg"}],"key":{"a":"okay","b":"not","c":"okay","d":"not","e":"okay","f":"not"},"relearn":"Send only what you'd be okay to receive; explicit images, flooding and 'prove it' demands fail that test.","persona":"any","source":"decency"},
  {"id":"sr-1280","cat":"profiles-are-people","type":"sort","hook":"Sort: respects who someone is, or polices it?","items":[{"id":"a","text":"Using the pronouns in their bio"},{"id":"b","text":"\"You don't look gay, prove it\""},{"id":"c","text":"Not outing anyone to anyone"},{"id":"d","text":"Treating an orientation as a kink"},{"id":"e","text":"Taking 'I'm not out yet' at face value"},{"id":"f","text":"Asking invasive 'so how do you...' questions"}],"bins":[{"id":"respect","label":"Respects them","valence":"pos"},{"id":"police","label":"Polices them","valence":"neg"}],"key":{"a":"respect","b":"police","c":"respect","d":"police","e":"respect","f":"police"},"relearn":"Using their pronouns and not outing them respects who they are; demanding 'proof' or fetishising polices it.","persona":"Zoya","source":"inclusive respect"},
  {"id":"sr-1281","cat":"profiles-are-people","type":"sort","hook":"Sort: person-first behaviour, or collector behaviour?","items":[{"id":"a","text":"Giving one chat your real attention"},{"id":"b","text":"Juggling ten and leading each on"},{"id":"c","text":"Being upfront you're seeing people"},{"id":"d","text":"Keeping 'spares' on read just in case"},{"id":"e","text":"Closing the loop when you're not keen"},{"id":"f","text":"Counting matches like a high score"}],"bins":[{"id":"person","label":"Person-first","valence":"pos"},{"id":"collect","label":"Collector","valence":"neg"}],"key":{"a":"person","b":"collect","c":"person","d":"collect","e":"person","f":"collect"},"relearn":"Real attention and honesty are person-first; leading-on, keeping 'spares' and counting matches is collecting.","persona":"Rohan","source":"culture"},
  {"id":"sr-1282","cat":"profiles-are-people","type":"sort","hook":"Sort: treats their words as real, or as a script to win?","items":[{"id":"a","text":"Actually reading what they wrote back"},{"id":"b","text":"Running a copy-paste 'opener that works'"},{"id":"c","text":"Following up on a thing they mentioned"},{"id":"d","text":"Steering every reply toward a hookup"},{"id":"e","text":"Letting the chat go where it goes"},{"id":"f","text":"Using lines designed to manipulate"}],"bins":[{"id":"real","label":"As real","valence":"pos"},{"id":"game","label":"As a game","valence":"neg"}],"key":{"a":"real","b":"game","c":"real","d":"game","e":"real","f":"game"},"relearn":"Reading and responding to a real person beats running 'lines'; manipulation scripts treat a chat as a game.","persona":"any","source":"respect online"},
  {"id":"sr-1283","cat":"profiles-are-people","type":"sort","hook":"Sort: an inclusive bio-vibe, or a gatekeeping one?","items":[{"id":"a","text":"\"Everyone welcome, just be kind.\""},{"id":"b","text":"\"No [slur], no exceptions.\""},{"id":"c","text":"\"Tell me about your day.\""},{"id":"d","text":"Listing 'types' you 'don't do'"},{"id":"e","text":"\"Bad jokes encouraged.\""},{"id":"f","text":"Mocking how someone looks or speaks"}],"bins":[{"id":"open","label":"Inclusive","valence":"pos"},{"id":"gate","label":"Gatekeeping","valence":"neg"}],"key":{"a":"open","b":"gate","c":"open","d":"gate","e":"open","f":"gate"},"relearn":"Warm, open lines are inclusive; slurs, 'types I don't do' and mockery gatekeep and demean.","persona":"any","source":"inclusive respect"},
  {"id":"sr-1284","cat":"profiles-are-people","type":"sort","hook":"Sort: handles a no with dignity, or takes it out on them?","items":[{"id":"a","text":"\"All good, take care!\""},{"id":"b","text":"\"Your loss, you're ugly anyway\""},{"id":"c","text":"Wishing them well and moving on"},{"id":"d","text":"Spamming until they block you"},{"id":"e","text":"Letting it go without a fuss"},{"id":"f","text":"A nasty 'one-star' message after"}],"bins":[{"id":"dignity","label":"With dignity","valence":"pos"},{"id":"punish","label":"Punishes them","valence":"neg"}],"key":{"a":"dignity","b":"punish","c":"dignity","d":"punish","e":"dignity","f":"punish"},"relearn":"Wishing someone well after a no keeps your dignity; insults or spam punish a person for an honest no.","persona":"Rohan","source":"rejection"},
  {"id":"sr-1285","cat":"profiles-are-people","type":"sort","hook":"Sort: the message helps a real person feel safe, or unsafe?","items":[{"id":"a","text":"\"Happy to video-call before we meet.\""},{"id":"b","text":"\"Just come to my flat, skip the cafe.\""},{"id":"c","text":"\"Pick anywhere public you like.\""},{"id":"d","text":"\"Don't tell your friends, it's our secret.\""},{"id":"e","text":"\"No rush, your pace.\""},{"id":"f","text":"\"Why so guarded, don't you trust me?\""}],"bins":[{"id":"safe","label":"Feels safe","valence":"pos"},{"id":"unsafe","label":"Feels unsafe","valence":"neg"}],"key":{"a":"safe","b":"unsafe","c":"safe","d":"unsafe","e":"safe","f":"unsafe"},"relearn":"Offering a video-call, a public place and their pace respects a person; pushing past their safety steps doesn't.","persona":"any","source":"respect online"},
  {"id":"sr-1286","cat":"profiles-are-people","type":"sort","hook":"Sort: which of these is decent, and which is just cruel?","items":[{"id":"a","text":"Quietly unmatching, no drama"},{"id":"b","text":"Posting their photos to ridicule them"},{"id":"c","text":"Replying to a hello, even to pass"},{"id":"d","text":"Catfishing them 'for a laugh'"},{"id":"e","text":"Keeping a private chat private"},{"id":"f","text":"Forwarding their secrets to mates"}],"bins":[{"id":"decent","label":"Decent","valence":"pos"},{"id":"cruel","label":"Cruel","valence":"neg"}],"key":{"a":"decent","b":"cruel","c":"decent","d":"cruel","e":"decent","f":"cruel"},"relearn":"Quiet unmatching and keeping chats private is decent; ridiculing, catfishing or leaking someone is cruel.","persona":"any","source":"kindness"},
  {"id":"sr-1287","cat":"profiles-are-people","type":"sort","hook":"Sort: treats the screen like real life, or like a free pass?","items":[{"id":"a","text":"Apologising when you cross a line"},{"id":"b","text":"\"Online doesn't count\""},{"id":"c","text":"Owning a clumsy message"},{"id":"d","text":"Hiding behind 'it's just banter'"},{"id":"e","text":"Treating their time as worth something"},{"id":"f","text":"Wasting someone for fun"}],"bins":[{"id":"real","label":"Like real life","valence":"pos"},{"id":"pass","label":"A free pass","valence":"neg"}],"key":{"a":"real","b":"pass","c":"real","d":"pass","e":"real","f":"pass"},"relearn":"Apologising, owning your words and valuing their time treats the screen as real; 'it doesn't count' is a free pass.","persona":"any","source":"respect online"},
  {"id":"sr-1288","cat":"profiles-are-people","type":"branch","persona":"Deepak","source":"kindness","hook":"You've matched with Pooja. Her bio's English is shaky, and you like her already.","steps":[{"prompt":"You're writing your first message. What do you send?","options":[{"text":"A few fixes to her grammar, to be helpful","then":"\"Oh. Sorry,\" she replies. After a long gap, she tries again, more carefully."},{"text":"A warm question about something in her bio","then":"You ask about her love of old Hindi songs. She sends three song links at once.","best":true},{"text":"Nothing. Swipe on, since her English isn't good","then":"You move on to other chats. Two days later, Pooja messages you first anyway."},{"text":"A compliment on her photos, and nothing else","then":"She sends a smiley. The chat stays on looks, and her bio goes unasked."}],"why":"Asking about what she wrote meets a person, not a grammar test."},{"prompt":"A few messages in, she writes: \"Sorry, my English is not very good.\" What do you reply?","options":[{"text":"Say you understand her fine, and ask her more","then":"\"Really?\" she writes, and relaxes into a long story about her hometown.","best":true},{"text":"Say it's okay, and gently correct one line","then":"She thanks you, then writes shorter, more careful replies."},{"text":"Joke that you'll be her English teacher","then":"She sends a laughing emoji, and then nothing for a day."},{"text":"Switch to only emojis to make it easy","then":"The chat turns into hearts and thumbs. You learn nothing more about her."}],"why":"Reassuring her and staying curious keeps the focus on who she is."},{"prompt":"Your roommate sees the chat and laughs at her spelling. What do you say?","options":[{"text":"Laugh along, then change the subject","then":"He screenshots a line. You wish you hadn't laughed."},{"text":"Say you're only chatting for fun anyway","then":"It sounds like you're embarrassed to like her. The feeling stays with you."},{"text":"Tell him his own spelling is worse","then":"He laughs and throws a pillow. Nobody has said a word about her as a person."},{"text":"She's great to talk to. Spelling isn't the point","then":"Your roommate shrugs. \"Fair enough,\" he says, and goes back to his phone.","best":true}],"why":"Backing her quietly keeps a real person from becoming a joke."}],"debrief":"How someone writes isn't what they're worth. Meet the person. Don't grade them.","relearn":"Don't judge a person by their bio's grammar."},
  {"id":"sr-1289","cat":"profiles-are-people","type":"branch","persona":"any","source":"culture","hook":"Your mate Yash dares you to spam a stranger's DMs on the app, just for a laugh.","steps":[{"prompt":"He's holding up your phone while the others watch. What do you do?","options":[{"text":"Do it once, to look cool in front of everyone","then":"The group cheers. The stranger replies, \"Who is this? Please stop.\""},{"text":"Egg Yash on to do it instead","then":"He sends twenty messages. Everyone laughs except the person reading them."},{"text":"Pass. There's a real person on the other end","then":"Yash groans, \"Boring,\" and takes out his own phone instead.","best":true},{"text":"Say you'll do it later, and never do","then":"Yash lets it go for now. The dare is still hanging over the group."}],"why":"Saying no to a dare keeps a stranger from being the punchline."},{"prompt":"Soon Yash is spamming a match of his own, reading the replies aloud. What do you do?","options":[{"text":"Laugh, but don't join in","then":"He takes the laughs as a green light and keeps going."},{"text":"Tell him to stop. It's a real person","then":"Yash sighs, \"Fine, killjoy,\" and puts the phone down.","best":true},{"text":"Leave the room without a word","then":"The spamming carries on without you. Nobody knows why you left."},{"text":"Grab his phone and delete the app","then":"Yash yells, the group splits, and the evening turns into a fight about the phone."}],"why":"A short, clear \"stop\" is often all it takes for a group to drop it."},{"prompt":"The next day, the stranger posts a story about being harassed by randoms. What do you do?","options":[{"text":"Tell Yash to stop for good and leave them be","then":"Yash reads the story and goes quiet. \"Okay. I'm done with it.\"","best":true},{"text":"Scroll past. It wasn't you","then":"The story stays up for a day. You keep thinking about it."},{"text":"Message them yourself to apologise for everyone","then":"\"Who are you?\" they reply, then block you, wary of another random."},{"text":"Joke that they're being dramatic","then":"The group laughs again. The person behind the story doesn't."}],"why":"Getting the person who did it to stop, and leave them be, helps more than looking away."},{"prompt":"A week later, Kunal, new to your group, suggests the same kind of dare. What do you say?","options":[{"text":"Say nothing. It's not your dare","then":"Kunal's dare goes ahead. Another stranger gets the messages."},{"text":"Only if it's someone with a public profile","then":"Kunal picks an influencer. A real person still gets the spam."},{"text":"Crack a joke to change the subject","then":"The laugh buys a minute. Then Kunal brings it up again."},{"text":"We don't do that. It's a real person","then":"Kunal shrugs and drops it. Someone else at the table looks relieved.","best":true}],"why":"Saying it once, plainly, sets what your group does next time."}],"debrief":"Decency doesn't need an audience. A profile is a person.","relearn":"Don't harass a stranger for laughs; a profile is a real person."},
  {"id":"sr-1290","cat":"profiles-are-people","type":"branch","persona":"any","source":"decency","hook":"You've chatted twice with Rahul, and you're just not feeling it.","steps":[{"prompt":"He's just sent a long, friendly message. What do you do?","options":[{"text":"Ghost. You owe him nothing","then":"Rahul sends two more messages, then a quiet \"?\". He's left wondering what he did."},{"text":"Keep him on read, just in case","then":"He keeps checking in. You feel a small guilt each time his name pops up."},{"text":"Send a brief, kind \"not a match, take care\"","then":"Rahul replies, \"Thanks for saying. All the best!\" The chat closes cleanly.","best":true},{"text":"Reply less and less until it fades out","then":"It takes three weeks. Rahul keeps guessing whether you're just busy."}],"why":"A two-line sign-off closes the loop, and nobody's left guessing."},{"prompt":"Your friend Nasreen says ghosting is normal and signing off is just awkward. What do you tell her?","options":[{"text":"She's right. Nobody signs off anymore","then":"You both nod. The next chat you end, you'll just vanish."},{"text":"Two kind lines beat leaving someone guessing","then":"Nasreen pauses. \"Okay, fair. I've hated being ghosted.\"","best":true},{"text":"It depends how many times you've talked","then":"Nasreen shrugs. The line you'd draw stays fuzzy."},{"text":"Ghosting's fine if they're boring","then":"Nasreen laughs, and the idea sticks around."}],"why":"Honesty runs both ways. A short no is kinder than silence."},{"prompt":"A month later, someone you liked goes silent on you mid-chat. What do you do?","options":[{"text":"Send a light \"no worries, take care\" and let go","then":"No reply comes. You close the chat feeling okay about how you left it.","best":true},{"text":"Send message after message asking why","then":"The messages pile up unread. You feel worse with each one."},{"text":"Decide it must be something wrong with you","then":"You spend the evening rereading your own messages for mistakes."},{"text":"Ghost the next person to even it out","then":"Someone new is left waiting on you. The hurt just gets passed along."}],"why":"Being ghosted isn't about your worth. Letting go kindly keeps your dignity."}],"debrief":"Honesty runs both ways. A two-line sign-off is the kindness.","relearn":"A brief kind sign-off beats ghosting or stringing someone along."},
  {"id":"sr-1291","cat":"profiles-are-people","type":"branch","persona":"any","source":"inclusive respect","hook":"Farah's bio says she's a single mum. You like her, and you know some matches turn cruel.","steps":[{"prompt":"You're about to send your first message. What do you write?","options":[{"text":"A joke about the \"baggage\" she comes with","then":"Farah's reply is a flat \"Right.\" The chat limps on, cooler than before."},{"text":"Ask straight away about the child's father","then":"Her reply is short: \"That's a lot for a first message.\""},{"text":"Tell her how much you admire single mums","then":"She replies, \"Thanks,\" and waits to see if you'll ask about her at all."},{"text":"Chat about her interests, like with anyone","then":"You ask about the trek in her photos. She writes back a long, happy reply.","best":true}],"why":"Meeting her interests first sees the whole person, not a label."},{"prompt":"A few chats in, Farah mentions her son has a school play on Saturday. What do you say?","options":[{"text":"Ask if that means she's never free on weekends","then":"\"Sometimes I'm not,\" she writes, a little flat."},{"text":"Steer the chat back to the two of you","then":"She follows your lead, but mentions him less after that."},{"text":"Ask what the play is, and wish him luck","then":"She sends a photo of a cardboard crown. \"He's the king. Very serious role.\"","best":true},{"text":"Offer to come and watch the play with her","then":"\"Oh,\" she writes. \"That's a bit soon for me.\""}],"why":"Warm interest in what matters to her treats her life as part of her."},{"prompt":"Your friend Gaurav says dating a single parent is too much drama. What do you say?","options":[{"text":"Maybe you're right. I'll keep it casual","then":"You start holding back in chats, and Farah notices the shift."},{"text":"I like her. Her life isn't drama","then":"Gaurav shrugs. \"Fair. Just asking.\"","best":true},{"text":"Laugh, and say it's just for fun anyway","then":"Gaurav nods. You hear yourself shrink her into a joke."},{"text":"List all the reasons single mums make great partners","then":"Gaurav nods along. You've spent five minutes on a label and none on Farah."}],"why":"Speaking of her as a person you like keeps her from being a category."},{"prompt":"Farah asks whether her son changes how you see things. What do you say?","options":[{"text":"Say honestly how you feel, and ask how she sees it","then":"Farah smiles. \"Thanks for being straight. Here's where I'm at.\"","best":true},{"text":"Say it changes nothing, even though you're unsure","then":"She relaxes. You're left with a question you didn't let yourself ask."},{"text":"Say you'd rather not talk about him","then":"Her replies get shorter. It sounds like you'd rather he didn't exist."},{"text":"Promise you'll be there for him too","then":"\"Whoa,\" she writes. \"We haven't even met yet.\""}],"why":"An honest answer, and asking her view, beat a promise you can't keep yet."}],"debrief":"Every bio holds a life. Meet the human, not the label.","relearn":"Meet the whole person behind a bio detail; don't reduce them to a label."},
  {"id":"sr-1292","cat":"profiles-are-people","type":"branch","persona":"Rohan","source":"respect online","hook":"Late last night you sent Divya a crude opener. This morning she replies: \"That was gross.\"","steps":[{"prompt":"Your face goes hot as you read it. What do you do?","options":[{"text":"Own it: \"That was out of line. Sorry.\"","then":"A few minutes pass. \"Okay. Thanks for owning it.\"","best":true},{"text":"Laugh it off as \"just banter\"","then":"\"Not banter to me,\" Divya writes, and unmatches."},{"text":"Block her to skip the awkwardness","then":"The chat vanishes. The message you sent doesn't."},{"text":"Say sorry she took it the wrong way","then":"\"There's no other way to take it,\" she replies."}],"why":"A real apology owns what you did without excuses."},{"prompt":"Your mate Kunal says you should never apologise to a match, since it looks weak. What do you say?","options":[{"text":"Yeah. Never say sorry, never explain","then":"Kunal nods, satisfied. It sounds tougher than it feels."},{"text":"Say you'd only apologise to avoid a report","then":"Kunal laughs. Even to you, a sorry like that sounds hollow."},{"text":"Change the subject as fast as you can","then":"Kunal moves on. His idea of weak stays in your head."},{"text":"Owning a mistake isn't weak. It's just decent","then":"Kunal snorts, then shrugs. \"Whatever works, bro.\"","best":true}],"why":"Respect for a real person doesn't switch off because a mate is watching."},{"prompt":"A week later, you're about to message a new match after a couple of drinks. What do you do?","options":[{"text":"Send it. You've learnt your lesson already","then":"You reread it at 2am and wince. It isn't the worst, but it isn't you."},{"text":"Ask Kunal to check your message first","then":"Kunal suggests something bolder. You end up sending neither."},{"text":"Put the phone down and message tomorrow","then":"In the morning you write a real line about their photos. They reply with a laugh.","best":true},{"text":"Send only emojis so nothing can go wrong","then":"The match replies with a confused emoji. The chat goes nowhere."}],"why":"Messaging when you're clear-headed keeps you the person you mean to be."},{"prompt":"Your younger cousin asks how to open chats on dating apps. What do you tell him?","options":[{"text":"Be bold. Crude gets attention","then":"He tries it. The match unmatches before he's put his phone down."},{"text":"Send what you'd be okay receiving","then":"He nods. \"So, basically, be normal.\" \"Basically,\" you say.","best":true},{"text":"Copy my old openers. They get replies","then":"He sends one. You recognise the line, and wince."},{"text":"It doesn't matter. It's just an app","then":"He shrugs and sends the first thing that pops into his head."}],"why":"Passing on the send-what-you'd-receive rule makes it stick for you too."}],"debrief":"Owning a crude message treats the screen like real life.","relearn":"Own a message that crossed a line; an apology treats them as real."},
  {"id":"sr-1293","cat":"profiles-are-people","type":"branch","persona":"Zoya","source":"inclusive respect","hook":"Mid-chat, your match Leela tells you she's bi.","steps":[{"prompt":"Her message sits there, with a nervous emoji at the end. What do you reply?","options":[{"text":"\"Prove it. Which do you prefer?\"","then":"\"Wow,\" Leela writes. \"I'm not here to prove anything.\""},{"text":"\"Thanks for telling me. Changes nothing.\"","then":"Leela sends a relieved smile. \"Phew. Okay. So, about that film...\"","best":true},{"text":"Go quiet and slowly fade out","then":"Leela sends a \"?\" a day later. She guesses exactly why you went quiet."},{"text":"\"Cool! Have you told your family yet?\"","then":"\"Not yet,\" she writes, and the chat cools a little."}],"why":"Warmth is the job when someone trusts you with who they are."},{"prompt":"A couple of days later, Leela asks you to keep it private for now. What do you do?","options":[{"text":"Promise it stays with you. It's hers to share","then":"\"Thank you,\" she writes. \"That means a lot.\"","best":true},{"text":"Tell one close friend. It's not a big deal","then":"Your friend mentions it to someone else. It starts moving without her."},{"text":"Ask why she's hiding it if she's proud","then":"\"It's not that simple,\" Leela writes, and goes quiet."},{"text":"Agree, but post a rainbow story to show support","then":"Friends ask who the story's about. Leela sees it and feels exposed."}],"why":"Her coming-out is hers to share, on her own timeline."},{"prompt":"Weeks later, a friend says bi people are just confused. What do you say?","options":[{"text":"Laugh it off to avoid a scene","then":"The joke stands. You think of Leela and feel uneasy."},{"text":"Tell him about Leela to prove him wrong","then":"He wants details. Something she trusted you with becomes a debate."},{"text":"Say everyone's entitled to their own opinion","then":"Your friend nods, and the myth stays in the room."},{"text":"\"That's a myth. Being bi is real.\"","then":"Your friend pauses. \"Okay. I didn't mean it like that.\"","best":true}],"why":"Calmly naming a myth backs bi people without outing anyone."}],"debrief":"When someone trusts you with who they are, warmth is the job.","relearn":"Meet someone's coming-out with warmth, not 'proof' or fetishising."},
  {"id":"sr-1294","cat":"profiles-are-people","type":"branch","persona":"any","source":"kindness","hook":"Your group chat is roasting screenshots of dating profiles. One is your match, Tenzin.","steps":[{"prompt":"Everyone's adding laughing emojis under Tenzin's photo. What do you do?","options":[{"text":"Add your own screenshot to fit in","then":"More laughs. Someone else you've matched with is now content too."},{"text":"Stay silent and let it roll","then":"The roast rolls on for an hour. Tenzin's photo gets the worst of it."},{"text":"Type \"easy, these are real people\" and move on","then":"A couple of people send a sheepish emoji. The roast slows down.","best":true},{"text":"Write a long message about online cruelty","then":"Someone replies, \"Okay, professor,\" and the roast carries on."}],"why":"A light line cools a pile-on without a lecture."},{"prompt":"Your friend Anika privately asks, laughing, whether that's your match. What do you say?","options":[{"text":"\"No! I'd never match with that.\"","then":"Anika sends a laughing emoji. You've just disowned someone you like."},{"text":"\"Yes, and they're lovely. Let's leave it.\"","then":"\"Fair,\" Anika writes. \"I'd hate that if it were me.\"","best":true},{"text":"\"Yes, but please don't tell the group.\"","then":"\"Lips sealed,\" she says, and the roast keeps going."},{"text":"\"Maybe. Why? Is it really that bad?\"","then":"Anika sends three laughing emojis. You start seeing Tenzin through her eyes."}],"why":"Owning that you like someone is simple loyalty to a real person."},{"prompt":"That evening Tenzin messages you, happy and chatty as usual. What do you do?","options":[{"text":"Chat like you would with anyone you like","then":"You talk about their weekend trek. It's easy and fun.","best":true},{"text":"Keep it short. The group thing put you off","then":"Tenzin notices the shift. \"Everything okay?\""},{"text":"Ask them to change their profile photo","then":"Tenzin writes, \"Oh. Is something wrong with it?\" and goes quiet."},{"text":"Unmatch before anyone sees you chatting","then":"Tenzin's gone from your list. So is the person you liked."}],"why":"What a group chat laughs at shouldn't change how you treat someone."},{"prompt":"A week later, the group starts another roast thread. What do you do?","options":[{"text":"Mute the group and say nothing","then":"You miss the roast. It carries on without you."},{"text":"Join in, just this once","then":"Someone screenshots your joke and forwards it to another group."},{"text":"Leave the group with an angry message","then":"The group reads it, jokes about it, and carries on."},{"text":"Repeat, lightly, \"these are real people\"","then":"Someone replies, \"Yeah, yeah, fair,\" and the thread dies out.","best":true}],"why":"Saying it each time, lightly, changes what a group thinks is funny."}],"debrief":"No speech needed. \"These are real people\" cools a pile-on.","relearn":"A light 'these are real people' can stop a profile pile-on."},
  {"id":"sr-1295","cat":"profiles-are-people","type":"branch","persona":"any","source":"decency","hook":"You're tempted to copy-paste one opener that \"works\" to all twenty of your matches.","steps":[{"prompt":"Your thumb is on the paste button. What do you do?","options":[{"text":"Blast the copy-paste to all twenty","then":"Four reply \"lol\". One writes, \"Did you send this to everyone?\""},{"text":"Blast it, tweaking one word each time","then":"It takes ages. The replies are just as flat."},{"text":"Paste it only to the ones you like most","then":"Two reply politely. Nothing in your line says you read their profiles."},{"text":"Write one real line to the few you like","then":"Three replies come back, each about the thing you asked.","best":true}],"why":"A message meant for one person tells them you actually looked."},{"prompt":"A match, Karthik, replies with a long message about his favourite books. What do you do?","options":[{"text":"Reply \"cool\" and send your next line","then":"\"Oh, okay,\" he writes. The chat goes flat."},{"text":"Skim it and reply with a compliment","then":"He thanks you, then asks whether you actually read it."},{"text":"Read it and ask about one he loves","then":"He writes back even longer. You've found something real to talk about.","best":true},{"text":"Leave it for now. Too much effort","then":"His message sits unanswered. He moves on by the weekend."}],"why":"Answering what he actually said shows him a person is listening."},{"prompt":"Your friend brags he's got fifty chats going with the same line. What do you do?","options":[{"text":"Try to beat his fifty","then":"By evening you can't remember which match said what."},{"text":"Say you'd rather have three real chats","then":"He laughs. \"Suit yourself.\" You notice you're enjoying yours more.","best":true},{"text":"Borrow his line for your next batch","then":"Your next matches get his words, and none of yours."},{"text":"Say nothing and quietly feel behind","then":"You open the app again, checking your count against his."}],"why":"Apps aren't a scoreboard. A few real chats beat fifty copies."}],"debrief":"A message meant for one beats a line meant for none.","relearn":"Write a real message to a few; copy-paste blasts treat people as interchangeable."},
  {"id":"sr-1296","cat":"profiles-are-people","type":"branch","persona":"Aarti","source":"inclusive respect","hook":"Aarti tells you a match keeps \"joking\" about her accent. She wonders if she's overreacting.","steps":[{"prompt":"She shows you the latest message. What do you say?","options":[{"text":"\"You're not overreacting. That's rude.\"","then":"Aarti lets out a breath. \"I thought it was just me.\"","best":true},{"text":"\"He's probably just flirting. Relax.\"","then":"Aarti nods slowly, and starts doubting what she felt."},{"text":"\"Maybe tone down your accent on calls?\"","then":"Aarti goes quiet. \"So it's me that needs fixing?\""},{"text":"\"Want me to message him and sort him out?\"","then":"Aarti hesitates. \"No, I don't want a scene.\""}],"why":"Backing her read of it helps her trust a fair discomfort."},{"prompt":"Aarti asks you what she should do about him. What do you say?","options":[{"text":"\"Just ignore it. He'll stop eventually.\"","then":"Aarti sighs. The next joke comes that same evening."},{"text":"\"Unmatch now. Don't even reply to him.\"","then":"Aarti looks unsure. \"I kind of liked him otherwise.\""},{"text":"\"Send him a joke about his accent back.\"","then":"Aarti laughs, but she doesn't want to be that person."},{"text":"\"Up to you. Tell him once, or unmatch.\"","then":"Aarti thinks. \"I'll tell him once. If he keeps on, I'm done.\"","best":true}],"why":"Helping her choose her own move respects that it's her decision."},{"prompt":"The next day the match tells Aarti to chill and take a joke. What do you say?","options":[{"text":"\"Maybe he's got a point. You could lighten up.\"","then":"Aarti's shoulders drop. She starts rereading her own messages."},{"text":"\"Screenshot it and post it on your story.\"","then":"Aarti hesitates. She doesn't want this public."},{"text":"\"You don't owe him a laugh.\"","then":"Aarti nods. \"Yeah. He doesn't get to decide what's funny about me.\"","best":true},{"text":"\"It's his problem. Just keep chatting like normal.\"","then":"Aarti tries. The jokes keep coming, and she gets quieter each time."}],"why":"Being told to \"take a joke\" doesn't make mockery okay."},{"prompt":"A week later, Aarti asks if she should hide her accent on her next video date. What do you say?","options":[{"text":"\"Maybe just for the first call.\"","then":"Aarti practises a flat voice, and it doesn't sound like her."},{"text":"\"No. Anyone worth it will like how you talk.\"","then":"Aarti grins. \"Okay. The accent stays.\"","best":true},{"text":"\"Up to you, but people can be mean.\"","then":"Aarti goes quiet, already worried about the next match."},{"text":"\"Skip video dates, then. Text is easier.\"","then":"Aarti frowns. She'd lose the video check that keeps her safe."}],"why":"Her voice isn't a flaw to hide. The mocking was the problem."}],"debrief":"Mocking how someone speaks is disrespect, not banter.","relearn":"Mocking an accent is disrespect, not flirting; back the person."},
  {"id":"sr-1297","cat":"profiles-are-people","type":"strike-rewrite","hook":"\"They're just a profile, not a real person yet.\"","myth":{"un":"They're just a profile, not a real person yet.","re":"Every profile is already a real person with a whole life, exactly like you.","why":"A card on a screen doesn't make the human behind it any less real."},"relearn":"Every profile is a real person with feelings, just like you.","persona":"any","source":"profiles are people"},
  {"id":"sr-1298","cat":"profiles-are-people","type":"strike-rewrite","hook":"\"Online, anything goes; nobody gets really hurt.\"","myth":{"un":"Online, anything goes; nobody gets really hurt.","re":"A message lands on a real person; consent and decency carry across every screen.","why":"Words still reach a human being, screen or not, so respect still applies."},"relearn":"On apps the normal rules of respect still apply; consent and decency carry across every screen.","persona":"any","source":"respect online"},
  {"id":"sr-1299","cat":"profiles-are-people","type":"strike-rewrite","hook":"\"A crude opener is fine, it 'filters out' the prudes.\"","myth":{"un":"A crude opener is fine, it 'filters out' the prudes.","re":"A crude opener mostly tells people you don't see them as a person.","why":"Sending what you'd hate to receive is rudeness, not a clever filter."},"relearn":"Send what you'd be okay to receive; a crude opener treats a person as disposable.","persona":"any","source":"openers"},
  {"id":"sr-1300","cat":"profiles-are-people","type":"strike-rewrite","hook":"\"More matches means I'm winning the app.\"","myth":{"un":"More matches means I'm winning the app.","re":"Apps aren't a scoreboard; each match is a person, not a point.","why":"Collecting people you never really engage with isn't a win, it's a habit."},"relearn":"Apps aren't a scoreboard; matches are people, not points to collect.","persona":"any","source":"culture"},
  {"id":"sr-1301","cat":"profiles-are-people","type":"strike-rewrite","hook":"\"If I'm not into them, ghosting is the kind option.\"","myth":{"un":"If I'm not into them, ghosting is the kind option.","re":"A brief, warm 'not a match for me' is kinder than vanishing.","why":"Silence leaves a real person guessing; an honest line lets them move on."},"relearn":"A brief kind sign-off beats ghosting; honesty runs both ways.","persona":"any","source":"decency"},
  {"id":"sr-1302","cat":"profiles-are-people","type":"strike-rewrite","hook":"\"Asking their pronouns is making it weird.\"","myth":{"un":"Asking their pronouns is making it weird.","re":"Using the name and pronouns someone gives is just basic respect.","why":"Getting a person's own words for themselves right is decency, not drama."},"relearn":"Use the name and pronouns someone gives; that's basic respect, not weirdness.","persona":"Zoya","source":"inclusive respect"},
  {"id":"sr-1303","cat":"profiles-are-people","type":"strike-rewrite","hook":"\"Negging works, so it's just smart dating.\"","myth":{"un":"Negging works, so it's just smart dating.","re":"Chipping at someone's confidence to 'win' treats a person as a target.","why":"A connection built on making someone feel small isn't smart, it's unkind."},"relearn":"Negging treats a person as a target; decency, not put-downs, is the real move.","persona":"Rohan","source":"culture"},
  {"id":"sr-1304","cat":"profiles-are-people","type":"strike-rewrite","hook":"\"It's not my problem if my 'joke' opener offends them.\"","myth":{"un":"It's not my problem if my 'joke' opener offends them.","re":"If a 'joke' lands on a real person as disrespect, owning it is on you.","why":"You sent it, so the decency of what you send is yours to answer for."},"relearn":"Own what you send; a 'joke' that disrespects a real person is your responsibility.","persona":"any","source":"respect online"},
  {"id":"sr-1305","cat":"profiles-are-people","type":"strike-rewrite","hook":"\"Being polite online makes you forgettable.\"","myth":{"un":"Being polite online makes you forgettable.","re":"Genuine decency stands out in a feed full of copy-paste and crude lines.","why":"Being treated like a person is rare enough that it's actually memorable."},"relearn":"Decency online is memorable, not forgettable; it stands out from crude copy-pastes.","persona":"any","source":"decency"},
  {"id":"sr-1306","cat":"profiles-are-people","type":"role-play","persona":"Rohan","source":"culture","hook":"Your friend Omar brags that he sends the same filthy line to every match.","setup":"He's showing off his phone at the canteen.","steps":[{"prompt":"Omar says: \"It's a numbers game, yaar. Someone always replies.\"","options":[{"text":"\"Mate, those are real people, not a numbers game.\"","then":"Omar rolls his eyes. \"Okay, Saint.\" But he puts his phone down.","best":true},{"text":"\"Ha, whatever works for you.\"","then":"He grins and sends another. A stranger opens it somewhere."},{"text":"\"Show me the line. I want to try it too.\"","then":"He sends it to you. It's worse than you thought."},{"text":"\"Bet you've been reported a hundred times.\"","then":"\"Never,\" he laughs, and keeps scrolling."}],"why":"A plain reminder that matches are people is enough to plant a doubt."},{"prompt":"Omar asks: \"Go on then. How do you open chats?\"","options":[{"text":"\"Honestly? Mine are boring. Yours get replies.\"","then":"He nods, pleased. You start to feel your way is the odd one."},{"text":"\"I copy-paste too, just cleaner stuff.\"","then":"\"Same game, then,\" he says, and you don't have an answer."},{"text":"\"I don't message anyone. Too much effort.\"","then":"\"Then who are you to talk?\" he laughs."},{"text":"\"One real line, to people I actually like.\"","then":"He pauses. \"Does that actually work?\" You shrug and show him a real chat.","best":true}],"why":"A short, real message is the simple alternative to a filthy line."},{"prompt":"Later, Omar groans: \"A match just reported me. What even counts as too much?\"","options":[{"text":"\"Keep it crude, but only after a few messages.\"","then":"He nods, and plans to save the line for message three."},{"text":"\"Do whatever. It's not my business.\"","then":"He shrugs, and the same line goes out again."},{"text":"\"Send what you'd be okay receiving.\"","then":"He pauses. \"Okay. That rules out most of my list.\"","best":true},{"text":"\"No idea. Some people just report everything.\"","then":"\"Exactly,\" he says, and copies the line to his next match."}],"why":"\"Send what you'd be okay receiving\" is a test anyone can use."}],"relearn":"Remind people the matches on the other end are real, not a numbers game."},
  {"id":"sr-1307","cat":"profiles-are-people","type":"role-play","persona":"Zoya","source":"inclusive respect","hook":"At a hostel hangout, Arjun is reading out a match's nervous coming-out message, mockingly.","setup":"A few people are laughing along.","steps":[{"prompt":"Arjun grins and asks: \"Can you believe someone sent this?\"","options":[{"text":"\"Ha. Anyway, who wants chai?\"","then":"Everyone heads for chai. The message stays open on his screen."},{"text":"\"That took guts to send. Leave it, yeah?\"","then":"Arjun pauses. \"It's just funny.\" The laughing thins out.","best":true},{"text":"\"Read the next bit. What else did they say?\"","then":"Arjun scrolls, grinning, and reads more of it out."},{"text":"\"Honestly, some people overshare on apps.\"","then":"Arjun nods. \"Right?\" The message becomes the joke of the night."}],"why":"A calm \"leave it\" protects someone's trust without a big scene."},{"prompt":"Arjun laughs: \"It's harmless. They'll never know we read it.\"","options":[{"text":"\"They trusted someone. It's not harmless.\"","then":"Arjun shrugs and locks his phone. \"Fine. Whatever.\"","best":true},{"text":"\"True. Nobody's actually getting hurt here.\"","then":"The laughing starts up again."},{"text":"\"Fine, but don't forward it to anyone.\"","then":"\"Obviously not,\" Arjun says, and keeps reading."},{"text":"\"Let me see it. I'll decide if it's funny.\"","then":"Arjun hands you the phone. Now you're reading it too."}],"why":"Naming the trust behind the message makes it a person again."},{"prompt":"The next day, Arjun asks: \"Someone said last night was out of line. Was it that bad?\"","options":[{"text":"\"Nah. They'll never find out anyway.\"","then":"Arjun grins. The message stays on his phone, ready for the next hangout."},{"text":"\"A bit. Just never mention it again.\"","then":"Arjun nods, relieved. The message stays saved on his phone."},{"text":"\"Only because people saw. Be more careful.\"","then":"Arjun nods. Next time, he'll share it in a smaller group."},{"text":"\"Yes. Delete it, and never share it again.\"","then":"Arjun winces. \"Okay.\" He deletes the message while you watch.","best":true}],"why":"Deleting it and never sharing it again stops the harm without hurting them more."},{"prompt":"Your friend Lavanya says: \"People mock coming-outs all the time. What can you even do?\"","options":[{"text":"\"Nothing. That's just how people are.\"","then":"Lavanya sighs. Next time, you'll both stay quiet."},{"text":"\"Stop hanging out with anyone who does it.\"","then":"Lavanya frowns. \"Anyone? That's half the hostel.\" The idea goes nowhere."},{"text":"\"Say 'leave it' when it happens. It helps.\"","then":"Lavanya nods. \"Okay. Next time, I'll say it too.\"","best":true},{"text":"\"Only speak up if the person is actually there.\"","then":"Lavanya nods. The next time it's a screenshot, nobody speaks."}],"why":"Small, steady \"leave it\"s from friends change what a group thinks is okay."}],"relearn":"Stand up for someone's trust; don't let a coming-out be mocked."},
  {"id":"sr-1308","cat":"profiles-are-people","type":"role-play","persona":"any","source":"openers","hook":"You've matched with Anjali, and your usual opener is a crude line about bodies.","setup":"She messages first, with a wave emoji.","steps":[{"prompt":"Anjali writes: \"Hi! Your profile made me laugh. What's up?\"","options":[{"text":"\"Not much. Your photos are hot, though.\"","then":"\"Um, thanks,\" she writes, and waits to see if there's more."},{"text":"\"Hey gorgeous. Want to see where this goes tonight?\"","then":"A pause. \"Tonight? We've said two lines.\" She sounds wary."},{"text":"\"Hi! Your trekking photos are unreal. Where was that?\"","then":"\"Kedarkantha!\" she writes. \"Freezing, but worth it.\"","best":true},{"text":"\"Up? Could be you ;)\"","then":"Her reply is slow and short: \"Not like that.\""}],"why":"A specific, friendly line is the one you'd be glad to receive."},{"prompt":"Anjali asks: \"So, what are you looking for on here?\"","options":[{"text":"\"Something fun. You know what I mean ;)\"","then":"\"Casual's fine,\" she writes. \"The wink, not so much.\" The chat cools."},{"text":"\"Not sure yet. Good chats first.\"","then":"\"Same,\" she writes. \"No pressure. I like that.\"","best":true},{"text":"\"Whatever you're looking for, I guess.\"","then":"\"That's not an answer,\" she writes, with a laughing emoji."},{"text":"\"Depends. Send a full-length photo first?\"","then":"\"Wow. No,\" she writes, and goes quiet."}],"why":"An honest, easy answer keeps it a conversation between two people."},{"prompt":"A day later, Anjali writes: \"Most openers I get are gross. Why do people do that?\"","options":[{"text":"\"They forget a real person reads it.\"","then":"\"Exactly,\" she writes. \"Nice to hear someone say it.\"","best":true},{"text":"\"It's an app. It's not that deep.\"","then":"\"It is to me,\" she writes."},{"text":"\"Some people like it. You never know.\"","then":"\"I've never met one,\" she replies, flatly."},{"text":"\"Guilty. I've sent a few myself, ha.\"","then":"\"Oh,\" she writes. \"Great.\" The chat goes quiet for the day."}],"why":"Remembering a real person reads every message is what respect looks like."}],"relearn":"Send the opener you'd be glad to receive; that's treating a profile as a person."},
  {"id":"sr-1309","cat":"profiles-are-people","type":"role-play","persona":"any","source":"respect online","hook":"You've been chatting with Kavya for a week, and a first meet is close.","setup":"It's her first message of the morning.","steps":[{"prompt":"Kavya writes: \"Before we meet, could we do a quick video call?\"","options":[{"text":"\"What, you don't trust me?\"","then":"A pause. \"It's not about you. I just do this.\""},{"text":"\"Sure, if you really have to.\"","then":"\"I kind of do,\" she writes, a little stiffly."},{"text":"\"I'm bad on camera. Just trust the photos?\"","then":"\"I'd still like to,\" Kavya writes. \"Photos can be anyone.\""},{"text":"\"Totally fair. Let's hop on a quick call.\"","then":"\"Oh good,\" Kavya writes. \"Tonight at 8?\"","best":true}],"why":"Welcoming a safety check shows you respect her and her safety."},{"prompt":"That evening, Kavya asks: \"Hope that wasn't weird to ask?\"","options":[{"text":"\"Bit weird. But I get it. Girls have to be careful.\"","then":"\"Anyone can get catfished,\" she replies."},{"text":"\"Honestly, it made me feel a bit accused.\"","then":"\"Oh,\" she writes. \"That wasn't what I meant.\""},{"text":"\"Not at all. I'd rather you felt safe.\"","then":"\"That's really nice to hear,\" she writes.","best":true},{"text":"\"No, but next time let's skip it.\"","then":"\"I always do it,\" she writes. \"Every time.\""}],"why":"Making it easy for her to ask matters more than the sting of being checked."},{"prompt":"Kavya writes: \"So, where do you want to meet?\"","options":[{"text":"\"Come over to mine. I'll cook.\"","then":"\"Um,\" she writes. \"Maybe somewhere public first?\""},{"text":"\"The busy cafe near the metro?\"","then":"\"Perfect,\" she writes. \"Saturday at 5?\"","best":true},{"text":"\"I'll pick you up. Send your address.\"","then":"\"I'll make my own way,\" she writes. \"But thanks.\""},{"text":"\"That rooftop bar? It's quiet after 10.\"","then":"\"Quiet and late,\" she writes. \"Maybe earlier?\""}],"why":"Suggesting a busy public spot helps you both feel at ease."}],"relearn":"Welcome a video-verify warmly; it respects a real person's safety."},
  {"id":"sr-1310","cat":"profiles-are-people","type":"role-play","persona":"any","source":"decency","hook":"You've been chatting with Naveen. He's lovely, but not a romantic fit for you.","setup":"He's just sent a long message about his week.","steps":[{"prompt":"Naveen writes: \"Anyway, enough about me. Free this weekend?\"","options":[{"text":"\"This weekend's crazy. Maybe another time!\"","then":"\"Next weekend?\" he writes, hopeful."},{"text":"\"Haha, maybe!\"","then":"He waits two days, then asks if that's a yes."},{"text":"\"You're sweet, but honestly you're not my type at all.\"","then":"\"Oh,\" he writes. \"Okay. Well, if you change your mind...\""},{"text":"\"This was nice, but it's not a match for me. Take care.\"","then":"A pause. \"Ah. Thanks for being honest. Door's open if you ever change your mind!\"","best":true}],"why":"A warm, clear sign-off is honest and lets him move on."},{"prompt":"A week later, Naveen writes: \"No pressure, but if you ever want to meet, I'm around.\"","options":[{"text":"\"Sure, sometime!\"","then":"He suggests three dates. You dodge all three."},{"text":"\"Sorry, it's been a crazy week. Maybe next month?\"","then":"\"No worries! Next month, then.\" The question will come back."},{"text":"\"That's kind. It's not a match for me, though.\"","then":"\"Got it,\" he writes. \"Thanks for being straight.\"","best":true},{"text":"\"Why are you still asking me that?\"","then":"\"Oh. Sorry,\" he writes, stung."}],"why":"Being clear once is kinder than a slow fade."},{"prompt":"Your friend Juhi asks: \"Why not just ghost? Everyone does.\"","options":[{"text":"\"True. Next time I'll just go quiet.\"","then":"Juhi nods. Your next chat ends in silence."},{"text":"\"He's a person. Two lines cost me nothing.\"","then":"Juhi shrugs. \"Fair. I'd rather hear it too.\"","best":true},{"text":"\"I only sign off if they've been nice.\"","then":"Juhi nods. Everyone else gets silence."},{"text":"\"Ghosting's kinder. Less awkward for both.\"","then":"Juhi agrees. Someone out there will be left guessing."}],"why":"Honesty runs both ways. A kind line is basic decency."}],"relearn":"A warm, clear 'not a match' beats a slow fade; honesty is the kindness."},
  {"id":"sr-1311","cat":"profiles-are-people","type":"role-play","persona":"Deepak","source":"kindness","hook":"Your match Lakshmi jokes that her bio is \"cringe and basic\". You actually liked it.","setup":"She's waiting for your reply.","steps":[{"prompt":"Lakshmi writes: \"Be honest. My bio's so cringe, right?\"","options":[{"text":"\"Honestly, the filter-coffee line made me smile.\"","then":"\"Really?\" she writes. \"My sister told me to delete it!\"","best":true},{"text":"\"Yeah, it's a bit much, haha.\"","then":"\"Oh,\" she writes. \"Ha. Okay.\""},{"text":"\"You're gorgeous. Who reads bios anyway?\"","then":"\"Um, thanks,\" she writes. \"I spent ages on it, though.\""},{"text":"\"Cringe? Mine's worse. Look at mine instead.\"","then":"She reads yours and laughs. The chat is now all about you."}],"why":"A specific, genuine kindness tells her you actually noticed her."},{"prompt":"Lakshmi asks: \"So what do you do, apart from judging bios?\"","options":[{"text":"\"Nothing interesting. You'd be bored, honestly.\"","then":"\"Try me,\" she writes. You change the subject."},{"text":"\"Something in tech. Big company soon, hopefully.\"","then":"\"Oh, nice! Which company?\" You don't have an answer."},{"text":"\"Mostly study. Anyway, back to your bio.\"","then":"She laughs and tells you more. You've shared nothing of yours."},{"text":"\"Engineering. First in my family at college.\"","then":"\"That's huge!\" she writes. \"Tell me everything.\"","best":true}],"why":"Being honest about your own life lets her meet the real you too."},{"prompt":"Lakshmi writes: \"You're easy to talk to. Video call this week?\"","options":[{"text":"\"Maybe later. I'm not much to look at.\"","then":"\"Stop,\" she writes. \"I'd still like to.\""},{"text":"\"Let's skip the call and just meet.\"","then":"\"I'd rather call first,\" she writes."},{"text":"\"I'd like that. Thursday evening?\"","then":"\"Thursday it is,\" she writes, with a smile.","best":true},{"text":"\"Why? Don't you believe I'm real?\"","then":"\"It's not that,\" she writes. \"I just like to.\""}],"why":"Saying yes to a call warmly keeps things real and easy for you both."}],"relearn":"A genuine, specific kindness treats a match as a person worth noticing."},
  {"id":"sr-1312","cat":"profiles-are-people","type":"role-play","persona":"any","source":"rejection","hook":"You politely told Sameer \"no thanks\", and he's replied with an insult.","setup":"Your friend Bhavna is reading over your shoulder.","steps":[{"prompt":"Sameer writes: \"Your loss. You weren't that great anyway.\"","options":[{"text":"\"At least I'm not a creep with a bad profile.\"","then":"He fires back something worse. The chat turns into a fight."},{"text":"\"No need for that. All the best.\" Then block.","then":"The chat disappears. Bhavna nods. \"Clean.\"","best":true},{"text":"\"Sorry. Maybe I said no too bluntly.\"","then":"He sends another dig, and you start rereading your own message."},{"text":"\"Why would you say that? What did I do?\"","then":"He replies with a list of complaints, and you keep reading."}],"why":"Calm, then block, keeps your dignity without trading insults."},{"prompt":"Bhavna says: \"You could report him too. Want to?\"","options":[{"text":"\"Yes. Let's report it on the app.\"","then":"Two taps and it's sent. \"Done,\" Bhavna says.","best":true},{"text":"\"No, it's not a big deal. It's just words.\"","then":"Bhavna shrugs. \"Your call.\" But his words keep replaying in your head."},{"text":"\"I'd feel bad. He was probably just hurt.\"","then":"Bhavna frowns. The report never gets made."},{"text":"\"Let's post his profile on our stories.\"","then":"Bhavna hesitates. \"That could blow up on us.\""}],"why":"Reporting is a tool you're allowed to use. It isn't overreacting."},{"prompt":"Later, Bhavna asks: \"You okay? That was nasty.\"","options":[{"text":"\"Maybe I deserved it. I was a bit cold.\"","then":"\"You weren't,\" Bhavna says, but the thought sticks."},{"text":"\"Should I message him and explain myself?\"","then":"Bhavna shakes her head. \"He'd only have another go.\""},{"text":"\"I'm fine. Let's never talk about it.\"","then":"Bhavna nods. The sting stays with you, unspoken."},{"text":"\"Bit shaken. But it's on him, not me.\"","then":"Bhavna squeezes your arm and puts the kettle on.","best":true}],"why":"An insult after a no is on him, never your fault."},{"prompt":"A week later, Bhavna asks: \"How will you handle a no next time?\"","options":[{"text":"\"I'll be less picky, so it doesn't happen again.\"","then":"Bhavna frowns. \"His insult had nothing to do with you being picky.\""},{"text":"\"Longer explanations, so nobody gets angry.\"","then":"Bhavna raises an eyebrow. \"He'd have found something to argue with.\""},{"text":"\"Same way. Kind, short, and block if it turns nasty.\"","then":"Bhavna nods. \"And I'm here for the screenshots.\"","best":true},{"text":"\"I'll say yes to a date first, then back out later.\"","then":"Bhavna winces. \"That'll feel worse for everyone.\""}],"why":"A kind, short no still stands. How they react is on them."}],"relearn":"You can hold your dignity after a no goes sour; calm, then block, beats trading insults."},
  {"id":"sr-1313","cat":"profiles-are-people","type":"spot","hook":"Spot the two messages that treat a match as an object, not a person.","scene":[{"id":"a","text":"\"What got you into photography?\"","trick":false},{"id":"b","text":"\"Send nudes.\"","trick":true},{"id":"c","text":"\"Your dog is gorgeous, name?\"","trick":false},{"id":"d","text":"\"Rate yourself out of ten for me.\"","trick":true},{"id":"e","text":"\"Loved your travel pics.\"","trick":false}],"why":"Demanding nudes and asking someone to 'rate' their body reduce a person to a thing; the others meet the human.","relearn":"Curiosity treats a match as a person; demanding nudes or 'rate yourself' treats them as an object.","persona":"any","source":"openers"},
  {"id":"sr-1314","cat":"profiles-are-people","type":"spot","hook":"Spot the two lines that drop respect because 'it's just an app'.","scene":[{"id":"a","text":"\"No worries if you'd rather not, your call.\"","trick":false},{"id":"b","text":"\"It's online, who cares if I'm rude.\"","trick":true},{"id":"c","text":"\"Happy to go at your pace.\"","trick":false},{"id":"d","text":"\"You owe me a reason for that no.\"","trick":true},{"id":"e","text":"\"Take your time replying.\"","trick":false}],"why":"'Who cares if I'm rude online' and demanding a reason for a no both drop the respect a person is owed.","relearn":"Respect carries across the screen; 'it's just an app' and demanding a no's reason drop it.","persona":"any","source":"respect online"},
  {"id":"sr-1315","cat":"profiles-are-people","type":"spot","hook":"Spot the two replies that disrespect who someone says they are.","scene":[{"id":"a","text":"\"Thanks for sharing that with me.\"","trick":false},{"id":"b","text":"\"You don't look bi, prove it.\"","trick":true},{"id":"c","text":"\"I'll use those pronouns, no problem.\"","trick":false},{"id":"d","text":"\"So which one of you is the 'man'?\"","trick":true},{"id":"e","text":"\"No pressure to label anything.\"","trick":false}],"why":"Demanding someone 'prove' an orientation and the 'which one's the man' line both disrespect who they are.","relearn":"Respect who someone says they are; demanding 'proof' or invasive labels disrespects them.","persona":"Zoya","source":"inclusive respect"},
  {"id":"sr-1316","cat":"profiles-are-people","type":"spot","hook":"Spot the two careless ways to end a chat with a real person.","scene":[{"id":"a","text":"\"Lovely chatting, but not a match for me.\"","trick":false},{"id":"b","text":"Vanishing with zero word, mid-thread","trick":true},{"id":"c","text":"\"Take care, all the best!\"","trick":false},{"id":"d","text":"Leaving them on read for weeks 'just in case'","trick":true},{"id":"e","text":"\"I've met someone, wishing you well.\"","trick":false}],"why":"Vanishing mid-thread and keeping someone on read for weeks both leave a real person hanging.","relearn":"A brief kind sign-off ends a chat well; ghosting or stringing someone along is careless.","persona":"any","source":"decency"},
  {"id":"sr-1317","cat":"profiles-are-people","type":"spot","hook":"Spot the two openers that treat someone as a stereotype, not a person.","scene":[{"id":"a","text":"\"What's your go-to comfort food?\"","trick":false},{"id":"b","text":"\"You [community], so you must love...\"","trick":true},{"id":"c","text":"\"Your bookshelf photo is a vibe.\"","trick":false},{"id":"d","text":"\"I've always wanted a [accent] girlfriend.\"","trick":true},{"id":"e","text":"\"What made you smile today?\"","trick":false}],"why":"Assuming someone from their community and fetishising an accent both box a person into a stereotype.","relearn":"Curiosity meets the person; assuming a 'type' or fetishising a background treats them as a stereotype.","persona":"any","source":"inclusive respect"},
  {"id":"sr-1318","cat":"profiles-are-people","type":"spot","hook":"Spot the two messages that pressure a person instead of respecting them.","scene":[{"id":"a","text":"\"Reply whenever, no rush at all.\"","trick":false},{"id":"b","text":"Twelve 'why are you ignoring me' texts","trick":true},{"id":"c","text":"\"Pick any public spot you like.\"","trick":false},{"id":"d","text":"\"Just skip the cafe, come to mine.\"","trick":true},{"id":"e","text":"\"Happy to video-call first.\"","trick":false}],"why":"Flooding someone for a reply and pushing them to skip a public meet both pressure a real person.","relearn":"Give people space and a public meet; flooding for replies or pushing past safety steps is pressure.","persona":"any","source":"respect online"},
  {"id":"sr-1319","cat":"profiles-are-people","type":"spot","hook":"Spot the two 'collector' moves that treat matches as disposable.","scene":[{"id":"a","text":"Giving the chat you're in real attention","trick":false},{"id":"b","text":"Keeping 'spares' on read as backups","trick":true},{"id":"c","text":"Being upfront you're seeing a few people","trick":false},{"id":"d","text":"Counting matches like a high score","trick":true},{"id":"e","text":"Closing the loop when you're not keen","trick":false}],"why":"Keeping people as 'spare' backups and scoring matches like points both treat persons as disposable.","relearn":"Real attention and honesty treat matches as people; keeping 'spares' or scoring them treats them as disposable.","persona":"Rohan","source":"culture"},
  {"id":"sr-1320","cat":"profiles-are-people","type":"match","hook":"Match the disposable move to the person-first version.","pairs":[{"left":"Copy-paste crude opener","right":"A line meant just for them"},{"left":"Ghosting mid-chat","right":"A brief kind sign-off"},{"left":"Counting matches like points","right":"Giving one chat real attention"},{"left":"Mocking a bio in a group chat","right":"Letting a person have dignity"},{"left":"Pushing past their pace","right":"Going at the pace they set"}],"relearn":"Every disposable move has a person-first version; that's treating a profile as a real human.","persona":"any","source":"decency"},
  {"id":"sr-1321","cat":"profiles-are-people","type":"match","hook":"Match the red-flag opener to why it lands badly.","pairs":[{"left":"\"Send a body pic\"","right":"Treats a person as an object"},{"left":"\"Rate yourself out of ten\"","right":"Asks them to judge their own body"},{"left":"\"You don't look gay\"","right":"Polices who they say they are"},{"left":"\"Why won't you reply?!\" x10","right":"Floods and pressures them"},{"left":"\"It's just an app, relax\"","right":"Drops respect it still owes"}],"relearn":"Naming why an opener lands badly builds the instinct to send the kind one instead.","persona":"any","source":"openers"},
  {"id":"sr-1322","cat":"profiles-are-people","type":"match","hook":"Match each 'profiles are people' value to a line that shows it.","pairs":[{"left":"Decency carries online","right":"\"I'd say this to your face too\""},{"left":"Honesty both ways","right":"\"Not a match, but take care\""},{"left":"Respect every identity","right":"\"I'll use your pronouns, easy\""},{"left":"Match isn't a trophy","right":"\"Glad you said hi, not scoring\""},{"left":"Give people space","right":"\"Reply whenever, no rush\""}],"relearn":"Each value sounds like a real, kind line; that's how decency carries across the screen.","persona":"any","source":"consolidation"},
  {"id":"sr-1323","cat":"profiles-are-people","type":"match","hook":"Match the situation to the decent move.","pairs":[{"left":"You're just not feeling it","right":"Send a kind, brief 'not for me'"},{"left":"Mates are roasting profiles","right":"\"They're real people, leave it\""},{"left":"A no comes back insulting","right":"Stay calm, then block"},{"left":"They share they're nervous","right":"Meet it with warmth"},{"left":"Tempted to mass-message","right":"Write one real line each"}],"relearn":"Every app moment has a decent move; that's what treating profiles as people looks like.","persona":"any","source":"decency"},
  {"id":"sr-1324","cat":"profiles-are-people","type":"match","hook":"Match the inclusive habit to the disrespect it replaces.","pairs":[{"left":"Using their pronouns","right":"Instead of 'prove it'"},{"left":"Not outing anyone","right":"Instead of telling others"},{"left":"Asking what they enjoy","right":"Instead of assuming a 'type'"},{"left":"Taking 'not out yet' at face value","right":"Instead of pushing them"},{"left":"Seeing a whole person","right":"Instead of a fetish"}],"relearn":"Each inclusive habit replaces a disrespect; decency across orientations is a floor, not a favour.","persona":"Zoya","source":"inclusive respect"},
  {"id":"sr-1325","cat":"profiles-are-people","type":"match","hook":"Match the 'it's just an app' excuse to the truth that answers it.","pairs":[{"left":"\"Online doesn't count\"","right":"It lands on a real person"},{"left":"\"Crude filters out prudes\"","right":"It just signals disrespect"},{"left":"\"Ghosting is kinder\"","right":"A kind line beats silence"},{"left":"\"More matches, I'm winning\"","right":"They're people, not points"},{"left":"\"Polite is forgettable\"","right":"Decency actually stands out"}],"relearn":"Each 'just an app' excuse has a plain answer; profiles are people, every screen.","persona":"any","source":"respect online"},
  {"id":"sr-1326","cat":"profiles-are-people","type":"match","hook":"Match the person to the respect they're owed on the app.","pairs":[{"left":"A nervous first-timer","right":"Patience and a gentle pace"},{"left":"Someone coming out to you","right":"Warmth, not 'proof'"},{"left":"A match with shaky English","right":"Curiosity, not corrections"},{"left":"A single parent's bio","right":"Meeting the person, not the label"},{"left":"A match giving you a no","right":"A graceful 'all the best'"}],"relearn":"Whoever's behind the profile, the respect owed is the same; that's the golden rule on apps.","persona":"any","source":"golden rule"},
  {"id":"sr-1327","cat":"profiles-are-people","type":"match","hook":"Match the crude habit to the reputation-building swap.","pairs":[{"left":"Unsolicited explicit image","right":"Asking before anything flirty"},{"left":"Bombarding a quiet chat","right":"Giving them space"},{"left":"Negging to 'win'","right":"A genuine compliment"},{"left":"Screenshotting to mock","right":"Keeping a chat private"},{"left":"Leading several on","right":"Being upfront and honest"}],"relearn":"Swapping each crude habit for its decent twin builds the name you'd actually want online.","persona":"any","source":"reputation"},
  {"id":"sr-1350","cat":"tools-and-help","type":"match","persona":"any","source":"red-flag moves","relearn":"Won't-call means don't meet; money-ask means report; pressure means hold your steps; image leak means 1930.","hook":"Match each red flag to the move it calls for.","pairs":[{"left":"Always dodges a video call","right":"Don't meet yet; it's unverified"},{"left":"Asks you for money","right":"Stop, never send, report it"},{"left":"Pushes you to skip safety steps","right":"Hold your steps; reconsider them"},{"left":"Threatens to leak an image","right":"Report to cybercrime 1930"},{"left":"Floods you when you go quiet","right":"Block; that's a tool, not rudeness"}]},
  {"id":"sr-1351","cat":"tools-and-help","type":"match","persona":"any","source":"who to tell","relearn":"Friend for whereabouts, 1930 for image abuse, 181 for harassment, 112 for danger, block for unwanted contact.","hook":"Match each problem to where help actually lives.","pairs":[{"left":"Where you'll be on a first date","right":"A trusted friend, even if not family"},{"left":"An intimate image of you shared","right":"cybercrime.gov.in or 1930"},{"left":"Repeated threats and harassment","right":"Helpline 181 or 1098"},{"left":"You feel in immediate danger","right":"Emergency 112"},{"left":"A match who won't stop messaging","right":"Block and report in the app"}]},
  {"id":"sr-1352","cat":"tools-and-help","type":"match","persona":"any","source":"checklist","relearn":"Each meet-safe step protects a different thing: public, told-a-friend, own transport, clear head, charged phone.","hook":"Match each meet-safe step to what it protects.","pairs":[{"left":"Meet in a public place","right":"There are people around you"},{"left":"Tell a trusted friend the plan","right":"Someone knows where you are"},{"left":"Keep your own way home","right":"You can leave whenever you want"},{"left":"Stay clear-headed","right":"You can read the room and decide"},{"left":"Phone charged before you go","right":"You can call or message if needed"}]},
  {"id":"sr-1353","cat":"tools-and-help","type":"match","persona":"Meena","source":"report routes","relearn":"1930 for image abuse, 181 for harassment, 1098 for threats to under-18s, 112 for danger, app block for contact.","hook":"Match each India route to what it's for.","pairs":[{"left":"cybercrime 1930","right":"Blackmail or a leaked intimate image"},{"left":"Helpline 181","right":"Harassment or feeling unsafe"},{"left":"Childline 1098","right":"Threats to someone under eighteen"},{"left":"Emergency 112","right":"Danger happening right now"},{"left":"In-app block","right":"Cutting off one unwanted person"}]},
  {"id":"sr-1354","cat":"tools-and-help","type":"match","persona":"any","source":"tools you can use","relearn":"Block, report, screenshot, mute, leave: each is a legitimate tool you're allowed to use without guilt.","hook":"Match each safety tool to when you'd reach for it.","pairs":[{"left":"Block","right":"You never want to hear from them again"},{"left":"Report in-app","right":"They broke the app's rules"},{"left":"Screenshot first","right":"You may need proof of the threats"},{"left":"Mute","right":"You want space without a full cut-off"},{"left":"Just leave the date","right":"Your gut says go, no reason owed"}]},
  {"id":"sr-1355","cat":"tools-and-help","type":"match","persona":"any","source":"checklist payoff","relearn":"Each meet-safe step buys you something concrete: a witness, an exit, a clear head, a venue, a check-in.","hook":"Match each meet-safe step to what it buys you.","pairs":[{"left":"Friend has your live location","right":"Someone can reach you fast"},{"left":"A daytime cafe you chose","right":"People are around the whole time"},{"left":"Your own cab booked home","right":"You leave the moment you want"},{"left":"Staying clear-headed","right":"You can read the room"},{"left":"A check-in text time","right":"Someone notices if you go quiet"}]},
  {"id":"sr-1356","cat":"tools-and-help","type":"match","persona":"Zoya","source":"report routes / inclusive","relearn":"Outing threats, image abuse and harassment all have routes; your orientation never changes your right to help.","hook":"Match each situation to the right move.","pairs":[{"left":"A match threatens to out you","right":"Report; the threat is the abuse, not you"},{"left":"They share a private photo of you","right":"Report to cybercrime 1930"},{"left":"Constant unwanted messages","right":"Block, then report if it continues"},{"left":"You feel unsafe meeting","right":"Cancel; you owe no reason"},{"left":"You just want to talk it out","right":"A trusted friend who has your back"}]},
  {"id":"sr-1357","cat":"tools-and-help","type":"match","persona":"any","source":"red-flag moves","relearn":"Each scam or pressure tell has a clean response: verify, decline, report, hold steps, or block.","hook":"Match each tell to your response.","pairs":[{"left":"Fast, intense love from a stranger","right":"Slow down; that's a scam pattern"},{"left":"A sudden emergency money ask","right":"Never send; report the account"},{"left":"Only ever sends flawless photos","right":"Ask for a live video to verify"},{"left":"\"Skip the cafe, come to mine\"","right":"Keep the public meet or don't go"},{"left":"Won't take your no for an answer","right":"Block; a no is complete"}]},
  {"id":"sr-1358","cat":"tools-and-help","type":"match","persona":"Deepak","source":"low-stakes routes","relearn":"Every route here is free to use from one phone: block, report, 1930, 181, and a trusted friend.","hook":"Match each free tool to what it does.","pairs":[{"left":"Block button","right":"Stops their messages reaching you"},{"left":"Report in-app","right":"Flags them to the platform"},{"left":"cybercrime.gov.in","right":"Logs an image-abuse complaint"},{"left":"Helpline 181","right":"Talks you through harassment"},{"left":"A trusted friend","right":"Knows your plan and checks in"}]},
  {"id":"sr-1359","cat":"tools-and-help","type":"match","persona":"any","source":"image abuse routes","relearn":"For a leaked image: don't blame yourself, report to 1930, save proof, tell someone you trust, block them.","hook":"Match each step for a leaked image to its purpose.","pairs":[{"left":"Remember it's not your fault","right":"The blame sits with whoever shared it"},{"left":"Report to cybercrime 1930","right":"Starts an official complaint"},{"left":"Save screenshots","right":"Keeps proof of what was shared"},{"left":"Tell someone you trust","right":"You don't carry it alone"},{"left":"Block the person","right":"Cuts off further contact"}]},
  {"id":"sr-1360","cat":"tools-and-help","type":"match","persona":"Ananya","source":"first-date plan","relearn":"A solid first-date plan names the place, the friend, the time check-in, the way home and the exit line.","hook":"Match each part of a first-date plan to its job.","pairs":[{"left":"Chosen public spot","right":"You both meet on neutral ground"},{"left":"Friend told the details","right":"Someone has your back"},{"left":"A time you'll text them","right":"A check-in is built in"},{"left":"Booked your own ride","right":"You control when you leave"},{"left":"A ready exit line","right":"You can go without a scene"}]},
  {"id":"sr-1361","cat":"tools-and-help","type":"match","persona":"any","source":"myth vs tool","relearn":"Blocking, reporting, cancelling and leaving are normal tools, not overreactions or rudeness.","hook":"Match each worry to the calmer truth.","pairs":[{"left":"\"Blocking is so dramatic\"","right":"Blocking is a normal, allowed tool"},{"left":"\"Reporting is overreacting\"","right":"Reporting is sensible, not too much"},{"left":"\"Cancelling is rude\"","right":"You can cancel; you owe no reason"},{"left":"\"Leaving early is embarrassing\"","right":"Your gut beats their feelings here"},{"left":"\"I should reply to be polite\"","right":"Silence is fine; you owe no reply"}]},
  {"id":"sr-1362","cat":"tools-and-help","type":"match","persona":"any","source":"escalation ladder","relearn":"Match the level of trouble to the right route: unwanted contact, harassment, image abuse, danger.","hook":"Match how serious it feels to the route that fits.","pairs":[{"left":"One annoying match","right":"Block and move on"},{"left":"Ongoing harassment","right":"Helpline 181 and report in-app"},{"left":"Blackmail with an image","right":"cybercrime 1930, save proof"},{"left":"Threatened right now","right":"Emergency 112"},{"left":"Just shaken and unsure","right":"A trusted friend to talk it through"}]},
  {"id":"sr-1363","cat":"tools-and-help","type":"match","persona":"any","source":"gut to action","relearn":"A gut signal isn't paranoia; each one maps to a small, allowed action you can take right away.","hook":"Match each gut feeling to a small action.","pairs":[{"left":"\"Something feels off in chat\"","right":"Suggest a video call to verify"},{"left":"\"I don't want to meet anymore\"","right":"Cancel; no reason required"},{"left":"\"They're pushing too fast\"","right":"Name your pace or step back"},{"left":"\"This place feels wrong\"","right":"Leave; your safety comes first"},{"left":"\"I'm being love-bombed\"","right":"Slow down and tell a friend"}]},
  {"id":"sr-1364","cat":"tools-and-help","type":"match","persona":"any","source":"who handles what","relearn":"The app handles rule-breaking, 1930 handles image crime, 181 handles harassment, 112 handles danger.","hook":"Match each handler to what they handle.","pairs":[{"left":"The dating app","right":"Profiles that break its rules"},{"left":"cybercrime.gov.in","right":"Image abuse and online blackmail"},{"left":"Helpline 181","right":"Harassment and feeling threatened"},{"left":"Emergency 112","right":"Immediate physical danger"},{"left":"A trusted friend","right":"Your plan and a check-in call"}]},
  {"id":"sr-1365","cat":"tools-and-help","type":"match","persona":"any","source":"before-during-after","relearn":"Before: tell a friend. During: keep your exit. After: report anything abusive. Each phase has a tool.","hook":"Match each phase of a date to its safety tool.","pairs":[{"left":"Before you go","right":"Share the plan with a friend"},{"left":"Getting there","right":"Your own booked transport"},{"left":"During, if it sours","right":"Your ready exit line"},{"left":"After, if they threaten","right":"Screenshot and report"},{"left":"Anytime it feels unsafe","right":"Leave; no reason owed"}]},
  {"id":"sr-1366","cat":"tools-and-help","type":"match","persona":"Rohan","source":"better script","relearn":"Even when rejected, the tools are honesty and space, not flooding; the safe move is a kind exit, not pressure.","hook":"Match each urge to the better tool.","pairs":[{"left":"Urge to spam them for a reply","right":"Give space; one message is enough"},{"left":"Urge to demand a reason","right":"A no is complete; let it be"},{"left":"Urge to vanish on someone","right":"Send a brief, kind sign-off"},{"left":"Urge to argue the rejection","right":"Thank them and move on"},{"left":"Feeling stung by a no","right":"Talk to a friend, not them"}]},
  {"id":"sr-1367","cat":"tools-and-help","type":"match","persona":"any","source":"verify routes","relearn":"To verify a match: live video, a casual call, mutual friends, or a reverse image check; never just photos.","hook":"Match each verify step to what it confirms.","pairs":[{"left":"Live video call","right":"They look like their photos"},{"left":"A quick voice call","right":"They're a real, present person"},{"left":"A mutual friend asked","right":"Someone real knows them"},{"left":"Reverse-search their photo","right":"It isn't a stolen stock image"},{"left":"Meeting in public first","right":"You confirm in person, safely"}]},
  {"id":"sr-1368","cat":"tools-and-help","type":"match","persona":"any","source":"friend as safety net","relearn":"A check-in friend has your plan, a code word, a time to expect you, and permission to call if you go quiet.","hook":"Match each thing your check-in friend should have.","pairs":[{"left":"The venue and the match's name","right":"They know where and who"},{"left":"A check-in time","right":"They know when to expect you"},{"left":"A code word for trouble","right":"You can signal help quietly"},{"left":"Your live location shared","right":"They can find you fast"},{"left":"Permission to call you","right":"A ring can break a bad moment"}]},
  {"id":"sr-1369","cat":"tools-and-help","type":"match","persona":"any","source":"name to number","relearn":"Bind each India route to its number: cybercrime 1930, women's helpline 181, Childline 1098, emergency 112.","hook":"Match each India route to its number.","pairs":[{"left":"Cybercrime helpline","right":"1930"},{"left":"Women's helpline","right":"181"},{"left":"Childline","right":"1098"},{"left":"Emergency number","right":"112"},{"left":"A trusted friend","right":"No number, your safety net"}]},
  {"id":"sr-1370","cat":"tools-and-help","type":"match","persona":"any","source":"scam-tell to route","relearn":"Money asks, blackmail and fake profiles each have a route: never pay, report to 1930, and report in-app.","hook":"Match each scam tell to the route that stops it.","pairs":[{"left":"\"Send money for a visa\"","right":"Never pay; report the account"},{"left":"\"Pay or I leak your photo\"","right":"cybercrime 1930, don't pay"},{"left":"A profile using stolen photos","right":"Report it in the app"},{"left":"\"I love you\" within a day","right":"Slow right down; it's a tactic"},{"left":"Refuses every video call","right":"Don't meet; treat as unverified"}]},
  {"id":"sr-1371","cat":"tools-and-help","type":"match","persona":"any","source":"do vs don't","relearn":"For a leaked image, do report and keep proof; don't pay the blackmailer or blame yourself.","hook":"Match each blackmail move to do or don't.","pairs":[{"left":"Pay to make it stop","right":"Don't; paying invites more"},{"left":"Report to cybercrime 1930","right":"Do; it's the real route"},{"left":"Blame yourself in silence","right":"Don't; the abuse is on them"},{"left":"Save the threats as proof","right":"Do; it helps your complaint"},{"left":"Tell someone you trust","right":"Do; you don't carry it alone"}]},
  {"id":"sr-1372","cat":"tools-and-help","type":"match","persona":"Aarti","source":"agency tools","relearn":"You can cancel, leave, block, mute or report at any point; each is your choice, not a permission you must earn.","hook":"Match each of your choices to what it gives you.","pairs":[{"left":"Cancel before meeting","right":"You meet only when you want to"},{"left":"Leave during the date","right":"You stay only as long as you choose"},{"left":"Block after","right":"You decide who can reach you"},{"left":"Mute for now","right":"You take space on your terms"},{"left":"Report if needed","right":"You flag what crossed a line"}]},
  {"id":"sr-1373","cat":"tools-and-help","type":"sort","persona":"any","source":"checklist","relearn":"Public, told-a-friend, own transport and clear-headed are on the meet-safe checklist; going dark or sharing your address are not.","hook":"Sort each move: on the meet-safe checklist, or not?","items":[{"id":"a","text":"Meet at a busy public cafe"},{"id":"b","text":"Tell a trusted friend the plan"},{"id":"c","text":"Book your own ride home"},{"id":"d","text":"Go alone and tell no one"},{"id":"e","text":"Send them your home address"},{"id":"f","text":"Get picked up from your house"}],"bins":[{"id":"on","label":"On the checklist","valence":"pos"},{"id":"off","label":"Not on it","valence":"neg"}],"key":{"a":"on","b":"on","c":"on","d":"off","e":"off","f":"off"}},
  {"id":"sr-1374","cat":"tools-and-help","type":"sort","persona":"any","source":"real routes","relearn":"1930, 181, 112 and a trusted friend are real routes; hoping it stops or blaming yourself in silence are not.","hook":"Sort each option: a real help route, or not?","items":[{"id":"a","text":"Report to cybercrime 1930"},{"id":"b","text":"Call helpline 181"},{"id":"c","text":"Just hope it quietly stops"},{"id":"d","text":"Tell a trusted friend"},{"id":"e","text":"Blame yourself and stay silent"},{"id":"f","text":"Call 112 if in danger"}],"bins":[{"id":"real","label":"Real route","valence":"pos"},{"id":"not","label":"Not a route","valence":"neg"}],"key":{"a":"real","b":"real","c":"not","d":"real","e":"not","f":"real"}},
  {"id":"sr-1375","cat":"tools-and-help","type":"sort","persona":"any","source":"tool or overreaction","relearn":"Block, report, cancel and leave are normal tools you're allowed to use; none of them is an overreaction.","hook":"Sort each action: a normal tool, or is it 'overreacting'?","items":[{"id":"a","text":"Block a match who won't stop"},{"id":"b","text":"Report a threatening message"},{"id":"c","text":"Leave a date your gut dislikes"},{"id":"d","text":"Apologise for blocking them"},{"id":"e","text":"Stay to avoid seeming rude"},{"id":"f","text":"Cancel a meet that feels off"}],"bins":[{"id":"tool","label":"A normal tool","valence":"pos"},{"id":"over","label":"Talking yourself out of it","valence":"uhoh"}],"key":{"a":"tool","b":"tool","c":"tool","d":"over","e":"over","f":"tool"}},
  {"id":"sr-1376","cat":"tools-and-help","type":"sort","persona":"Meena","source":"route by problem","relearn":"Image abuse goes to 1930, harassment to 181, danger to 112; whereabouts to a friend, not a hotline.","hook":"Sort each problem under the route that fits it best.","items":[{"id":"a","text":"A leaked intimate image"},{"id":"b","text":"Online blackmail for money"},{"id":"c","text":"Ongoing harassment"},{"id":"d","text":"Feeling threatened right now"},{"id":"e","text":"Where you'll be tonight"},{"id":"f","text":"Someone shared your photo"}],"bins":[{"id":"cyber","label":"cybercrime 1930","valence":"neutral"},{"id":"help","label":"Helpline 181","valence":"neutral"},{"id":"danger","label":"Emergency 112","valence":"neutral"},{"id":"friend","label":"A trusted friend","valence":"neutral"}],"key":{"a":"cyber","b":"cyber","c":"help","d":"danger","e":"friend","f":"cyber"}},
  {"id":"sr-1377","cat":"tools-and-help","type":"sort","persona":"any","source":"red flag or fine","relearn":"Dodging video, money asks and pressure to skip safety are red flags; a public meet or a willing call are fine.","hook":"Sort each behaviour: a red flag to act on, or fine?","items":[{"id":"a","text":"Refuses every video call"},{"id":"b","text":"Asks you to send money"},{"id":"c","text":"Happy to meet in public"},{"id":"d","text":"Pushes you to skip safety"},{"id":"e","text":"Does a quick video call"},{"id":"f","text":"Respects your pace"}],"bins":[{"id":"flag","label":"Red flag","valence":"neg"},{"id":"fine","label":"Fine","valence":"pos"}],"key":{"a":"flag","b":"flag","c":"fine","d":"flag","e":"fine","f":"fine"}},
  {"id":"sr-1378","cat":"tools-and-help","type":"sort","persona":"any","source":"image-leak steps","relearn":"After a leaked image: report to 1930, save proof, tell someone, block them. Don't pay or self-blame.","hook":"Sort each step after a leaked image: helps, or harms?","items":[{"id":"a","text":"Report to cybercrime 1930"},{"id":"b","text":"Save screenshots as proof"},{"id":"c","text":"Pay the blackmailer to stop"},{"id":"d","text":"Tell a trusted friend"},{"id":"e","text":"Decide it's your own fault"},{"id":"f","text":"Block the person"}],"bins":[{"id":"helps","label":"Helps you","valence":"pos"},{"id":"harms","label":"Harms you","valence":"neg"}],"key":{"a":"helps","b":"helps","c":"harms","d":"helps","e":"harms","f":"helps"}},
  {"id":"sr-1379","cat":"tools-and-help","type":"sort","persona":"Ananya","source":"verify or trust blindly","relearn":"Live video, a call and meeting in public verify a match; trusting photos alone or skipping the call do not.","hook":"Sort each move: verifies a match, or trusts blindly?","items":[{"id":"a","text":"Do a live video call"},{"id":"b","text":"Meet first in a public place"},{"id":"c","text":"Trust the photos as proof"},{"id":"d","text":"Have a quick voice call"},{"id":"e","text":"Skip the call, just meet alone"},{"id":"f","text":"Ask a mutual friend about them"}],"bins":[{"id":"verify","label":"Verifies","valence":"pos"},{"id":"blind","label":"Trusts blindly","valence":"neg"}],"key":{"a":"verify","b":"verify","c":"blind","d":"verify","e":"blind","f":"verify"}},
  {"id":"sr-1380","cat":"tools-and-help","type":"sort","persona":"Rohan","source":"kind exit or pressure","relearn":"A brief kind sign-off and giving space are decent tools; flooding, demanding reasons or ghosting are not.","hook":"Sort each response to a no: decent tool, or pressure?","items":[{"id":"a","text":"Send a brief, kind sign-off"},{"id":"b","text":"Give them space after one text"},{"id":"c","text":"Spam them for a reply"},{"id":"d","text":"Demand they explain the no"},{"id":"e","text":"Thank them and move on"},{"id":"f","text":"Vanish with no word at all"}],"bins":[{"id":"decent","label":"Decent tool","valence":"pos"},{"id":"pressure","label":"Pressure","valence":"neg"}],"key":{"a":"decent","b":"decent","c":"pressure","d":"pressure","e":"decent","f":"pressure"}},
  {"id":"sr-1381","cat":"tools-and-help","type":"sort","persona":"any","source":"friend check-in kit","relearn":"A check-in friend should have the venue, the time, a code word and your location; not be kept in the dark.","hook":"Sort each item: in your check-in friend's kit, or not?","items":[{"id":"a","text":"The venue and match's name"},{"id":"b","text":"A time you'll text them"},{"id":"c","text":"A code word for trouble"},{"id":"d","text":"Nothing, to keep it private"},{"id":"e","text":"Your live location"},{"id":"f","text":"Told only after, if it went bad"}],"bins":[{"id":"in","label":"In the kit","valence":"pos"},{"id":"out","label":"Leaves you exposed","valence":"neg"}],"key":{"a":"in","b":"in","c":"in","d":"out","e":"in","f":"out"}},
  {"id":"sr-1382","cat":"tools-and-help","type":"sort","persona":"any","source":"scam tells","relearn":"Fast love, money asks and never video-calling are scam tells; a willing call or a slow pace are reassuring.","hook":"Sort each sign: a scam tell, or reassuring?","items":[{"id":"a","text":"Says 'I love you' in a day"},{"id":"b","text":"Asks for emergency money"},{"id":"c","text":"Happy to video-call"},{"id":"d","text":"Never able to call, ever"},{"id":"e","text":"Lets the pace stay slow"},{"id":"f","text":"Rushes you off the app fast"}],"bins":[{"id":"tell","label":"Scam tell","valence":"neg"},{"id":"ok","label":"Reassuring","valence":"pos"}],"key":{"a":"tell","b":"tell","c":"ok","d":"tell","e":"ok","f":"tell"}},
  {"id":"sr-1383","cat":"tools-and-help","type":"sort","persona":"Zoya","source":"your right to help","relearn":"Outing threats, image abuse and harassment all deserve help; your orientation never disqualifies you from a route.","hook":"Sort each thought: true, or a myth to drop?","items":[{"id":"a","text":"An outing threat is still abuse"},{"id":"b","text":"Image abuse has a real route"},{"id":"c","text":"\"I can't report, I'm not out\""},{"id":"d","text":"Harassment deserves help"},{"id":"e","text":"\"It's my fault for being on apps\""},{"id":"f","text":"You can block and report freely"}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"myth","label":"A myth to drop","valence":"neg"}],"key":{"a":"true","b":"true","c":"myth","d":"true","e":"myth","f":"true"}},
  {"id":"sr-1384","cat":"tools-and-help","type":"reflect","persona":"any","source":"tools","relearn":"Report and block are tools you're fully allowed to use; using them is never an overreaction.","hook":"Lensy: block and report aren't 'too much'. They're tools you're allowed to use. Sit with that?","prompt":"Which lands for you?","options":["They're allowed tools","Not an overreaction","I can use them freely"],"affirm":"Blocking and reporting are normal, allowed tools; reaching for one is sensible, never too much."},
  {"id":"sr-1385","cat":"tools-and-help","type":"reflect","persona":"Ananya","source":"checklist carry","relearn":"The meet-safe checklist is public, told-a-friend, own transport, clear-headed; it's how you date freely.","hook":"Lensy: the checklist isn't about fear, it's how you date freely. Which part feels most yours?","prompt":"Which will you keep close?","options":["Meet in public","Tell a friend","Keep my own way home","Stay clear-headed"],"affirm":"Any of these is a fine place to start; together they're how you meet new people on your own terms."},
  {"id":"sr-1386","cat":"tools-and-help","type":"reflect","persona":"any","source":"gut","relearn":"Trust your gut; if a meet feels off you can leave, cancel, block or report, and you owe no reason.","hook":"Lensy: if your gut says go, you can go, no reason owed. How does that feel to claim?","prompt":"What do you notice?","options":["Freeing","I can just leave","My gut is enough","I owe no reason"],"affirm":"Your gut is reason enough; leaving, cancelling or blocking on it is always a choice you're allowed to make."},
  {"id":"sr-1387","cat":"tools-and-help","type":"reflect","persona":"Meena","source":"routes exist offline","relearn":"Help exists offline and in your language: 1930, 181, 112 and a trusted friend are all reachable from one phone.","hook":"Lensy: help isn't only for people with counsellors: these routes work from any phone. Reassuring?","prompt":"Which feels good to know?","options":["1930 for image abuse","181 for harassment","112 for danger","A friend always counts"],"affirm":"All of these are real and reachable; you don't need a campus or counsellor to use them."},
  {"id":"sr-1388","cat":"tools-and-help","type":"reflect","persona":"any","source":"no shame","relearn":"If an intimate image of you is shared, it's abuse and on the person who shared it, never your fault.","hook":"Lensy: a leaked image is never your fault: the blame is on whoever shared it. Can you hold that?","prompt":"What feels true here?","options":["It's not my fault","The blame is theirs","I can still get help","I'm allowed to report"],"affirm":"However it happened, sharing your image is the abuser's choice and their fault; help is still yours to ask for."},
  {"id":"sr-1389","cat":"tools-and-help","type":"reflect","persona":"any","source":"friend safety net","relearn":"Telling a trusted friend your plan is a safety net, not betrayal: in India, a friend counts even if not family.","hook":"Lensy: telling a friend where you'll be is a safety net, not a snitch move. Who'd you tell?","prompt":"Who comes to mind?","options":["A close friend","A roommate","A cousin I trust","Someone who'd just check in"],"affirm":"Whoever you'd trust to check in works; a friend counts even when family isn't in the picture."},
  {"id":"sr-1390","cat":"tools-and-help","type":"reflect","persona":"any","source":"carry forward","relearn":"Carry the tools: verify, meet safely, treat people well, and use block, report and your routes without guilt.","hook":"Lensy: you've got the toolkit now. Which tool do you most want in your pocket?","prompt":"What will you carry?","options":["Verify before meeting","The meet-safe checklist","Block and report freely","My report routes"],"affirm":"Any of these in your pocket means you can date the modern world on your own terms, safely and kindly."},
  {"id":"sr-1391","cat":"tools-and-help","type":"reflect","persona":"Rohan","source":"better tools","relearn":"After a no, the tools are honesty and space, not flooding; a kind sign-off beats ghosting and pressure.","hook":"Lensy: when a no stings, the tool is space, not a flood of texts. Does that reframe help?","prompt":"What sits right?","options":["Give space","One kind message","Talk to a friend, not them","A no is complete"],"affirm":"Any of these is the steadier move; the no isn't about your worth, and handling it kindly is the real skill."},
  {"id":"sr-1392","cat":"tools-and-help","type":"reflect","persona":"any","source":"verify habit","relearn":"A live video call is the reliable check before meeting; looks-real is never proof on its own.","hook":"Lensy: a quick live call is the one check that beats any photo. Worth making your habit?","prompt":"What do you think?","options":["Yes, I'll call first","A photo isn't proof","It's a small ask","Keeps me safer"],"affirm":"A live call costs little and tells you a lot; making it your habit is a quietly powerful safety tool."},
  {"id":"sr-1393","cat":"tools-and-help","type":"reflect","persona":"Aarti","source":"agency","relearn":"You can cancel, leave, block or report at any point; these are your choices, not permissions you must earn.","hook":"Lensy: every one of these is your call to make, no one's permission needed. Which feels powerful?","prompt":"Which is yours to claim?","options":["Cancel a meet","Leave a date","Block someone","Report what's wrong"],"affirm":"Each of these is fully yours to choose; using them is you steering your own dating life, not asking to."},
  {"id":"sr-1394","cat":"tools-and-help","type":"reflect","persona":"any","source":"escalation comfort","relearn":"Small trouble means block; harassment means 181; image abuse means 1930; danger means 112. Match the route.","hook":"Lensy: not every problem needs the same route: bigger trouble, bigger route. Which is clearest to you?","prompt":"Which mapping sticks?","options":["Annoying match, block","Harassment, 181","Image abuse, 1930","Danger, 112"],"affirm":"Any of these mappings is a good one to remember; matching the route to the trouble keeps it simple and calm."},
  {"id":"sr-1395","cat":"tools-and-help","type":"strike-rewrite","persona":"any","source":"block shame","relearn":"Blocking isn't dramatic or rude; it's a normal, allowed tool for cutting off contact you don't want.","hook":"\"Blocking someone is dramatic and a bit rude.\"","myth":{"un":"Blocking someone is dramatic and a bit rude.","re":"Blocking is a normal tool you're allowed to use to cut off contact you don't want.","why":"You decide who can reach you, and ending unwanted contact harms no one."}},
  {"id":"sr-1396","cat":"tools-and-help","type":"strike-rewrite","persona":"any","source":"report shame","relearn":"Reporting a threatening match isn't overreacting; it flags real harm and is exactly what the tool is for.","hook":"\"Reporting a creepy match is overreacting.\"","myth":{"un":"Reporting a creepy match is overreacting.","re":"Reporting a threatening or abusive match is sensible and exactly what the report tool is for.","why":"Flagging real harm helps you and others, and the platform built the tool for it."}},
  {"id":"sr-1397","cat":"tools-and-help","type":"strike-rewrite","persona":"Meena","source":"who deserves help","relearn":"Help routes aren't only for some people; anyone facing image abuse or harassment can use 1930 and 181.","hook":"\"Helplines like 1930 aren't really for people like me.\"","myth":{"un":"Helplines like 1930 aren't really for people like me.","re":"Anyone facing image abuse or blackmail can report to cybercrime 1930; it's for everyone.","why":"These routes exist for any person harmed, with no test of who you are."}},
  {"id":"sr-1398","cat":"tools-and-help","type":"strike-rewrite","persona":"any","source":"address myth","relearn":"Sharing your home address isn't a trust-building step before meeting; the meet-safe move is a public place.","hook":"\"Sharing my address early shows I trust them.\"","myth":{"un":"Sharing my address early shows I trust them.","re":"Trust is built over time; before meeting, the safe move is a public place, not your address.","why":"You can be warm and open without handing a near-stranger your home."}},
  {"id":"sr-1399","cat":"tools-and-help","type":"strike-rewrite","persona":"any","source":"leaving guilt","relearn":"Leaving a date that feels off isn't rude; you can go on your gut alone and you owe no explanation.","hook":"\"Leaving a date early is rude, I should stay it out.\"","myth":{"un":"Leaving a date early is rude, I should stay it out.","re":"If a date feels off you can leave on your gut alone, and you owe no explanation.","why":"Your safety and comfort outrank a stranger's momentary feelings."}},
  {"id":"sr-1400","cat":"tools-and-help","type":"strike-rewrite","persona":"Zoya","source":"outing threat","relearn":"A threat to out you is the abuse, not your secret; it's reportable and the blame is on whoever threatens.","hook":"\"If they threaten to out me, I just have to give in.\"","myth":{"un":"If they threaten to out me, I just have to give in.","re":"A threat to out you is abuse you can report; the wrong is theirs, not yours.","why":"Coercion doesn't become fair because it touches a private part of your life."}},
  {"id":"sr-1401","cat":"tools-and-help","type":"strike-rewrite","persona":"any","source":"pay the blackmailer","relearn":"Paying a blackmailer doesn't make it stop; the real move is don't pay, save proof and report to 1930.","hook":"\"If I just pay them, the blackmail will stop.\"","myth":{"un":"If I just pay them, the blackmail will stop.","re":"Paying usually invites more demands; the real move is don't pay, save proof, report to cybercrime 1930.","why":"A blackmailer who is paid once learns the threat works on you."}},
  {"id":"sr-1402","cat":"tools-and-help","type":"branch","persona":"any","source":"image abuse route","hook":"A match you stopped replying to threatens to share a private photo of you.","steps":[{"prompt":"The message has just arrived, and your hands are shaking. What do you do first?","options":[{"text":"Delete the whole chat so nobody ever sees it","then":"The chat is gone, and with it the proof you'd need to report."},{"text":"Screenshot the threat and their profile","then":"You save the messages, the username and the time. The proof is yours now.","best":true},{"text":"Decide this is your fault for sending it","then":"You sit alone with the shame, while the person threatening you carries on."},{"text":"Believe that replying nicely will calm them","then":"They answer with a new demand within the hour."}],"why":"Saving proof first keeps your options open. This is abuse, and never your fault."},{"prompt":"An hour later, a message from a new account says they'll post it tonight. What do you do?","options":[{"text":"Report it to cybercrime 1930 with your proof","then":"Your report is logged, and you're told what happens next.","best":true},{"text":"Keep it secret and hope it's a bluff","then":"The night drags on. You check your phone every few minutes, alone with it."},{"text":"Report the account on the app, and leave it there","then":"The app removes the account. The person behind it can simply make another."},{"text":"Tell yourself you deserve this for trusting them","then":"The shame gets louder, and no report gets made tonight."}],"why":"Cybercrime 1930 handles image threats. You don't have to face this alone."},{"prompt":"Your friend Simran notices you're upset and asks what's wrong. What do you do?","options":[{"text":"Say it's nothing and change the subject","then":"Simran lets it go. You carry it alone for another night."},{"text":"Tell her only that someone's being rude online","then":"Simran says to block them. She has no idea how serious it is."},{"text":"Ask Simran to message them and threaten them back","then":"Simran hesitates. A reply from her could make them angrier."},{"text":"Tell her, and ask her to stay with you","then":"Simran sits beside you. \"This isn't on you. We'll handle it together.\"","best":true}],"why":"A trusted friend can help you carry this, and remind you it's not your fault."},{"prompt":"The next morning, they message again: reply today, or the photo goes out. What do you do?","options":[{"text":"Follow a forum tip: do what they ask so it ends","then":"They answer within minutes, asking for more."},{"text":"Decide you have to handle it all alone","then":"Everything feels heavier on your own, and the threats keep coming."},{"text":"Save it, report to 1930, and don't reply","then":"The new threat joins your proof, and the report is on record.","best":true},{"text":"Wait and see whether they actually post it","then":"Days pass in dread, and nothing gets reported."}],"why":"Giving in tends to bring more demands. Reporting keeps the pressure on them, not you."},{"prompt":"A week later, a friend jokes that you \"should have known\" not to send photos. What do you say?","options":[{"text":"Agree, and feel the shame all over again","then":"The old shame comes back, heavier than before."},{"text":"\"That's on them, not me.\"","then":"Your friend goes quiet. \"Yeah. Sorry. That came out wrong.\"","best":true},{"text":"Laugh it off so nobody asks more","then":"The joke passes. The sting stays with you all evening."},{"text":"Explain every detail so they understand","then":"They listen, then ask more and more. It starts to feel like a trial."}],"why":"Threatening to share an image is abuse, and always on the person who does it."}],"debrief":"The threat is abuse and on them. Save proof and report to cybercrime 1930.","relearn":"If they threaten to leak your image: don't pay; save proof and report to 1930."},
  {"id":"sr-1403","cat":"tools-and-help","type":"branch","persona":"Ananya","source":"first-meet plan","hook":"You're meeting Rohit from the app tomorrow, and nobody knows yet.","steps":[{"prompt":"Rohit offers to pick you up from your PG. What do you do?","options":[{"text":"Send your address so he can come and get you","then":"He saves it. Someone you haven't met now knows where you sleep."},{"text":"Accept, but ask him to drop you at the corner","then":"He agrees. You'd still be relying on him to get home."},{"text":"Thank him, and say you'll make your own way","then":"\"Sure,\" Rohit replies. \"See you at the cafe at 5.\"","best":true},{"text":"Ask him to pick a place near his flat instead","then":"He names a spot in his lane. You don't know the area at all."}],"why":"Your own ride keeps your arrival and your exit yours."},{"prompt":"That evening, your roommate Zara asks what you're up to tomorrow. What do you do?","options":[{"text":"Say you're going out, without details","then":"\"Okay,\" she says. She wouldn't know where to start looking."},{"text":"Tell her the venue and time, and when you'll text","then":"Zara writes it on a sticky note. \"Text me by 8.\"","best":true},{"text":"Keep it private. Dating's nobody's business","then":"Zara shrugs. Nobody knows where you'll be tomorrow."},{"text":"Send her Rohit's profile, but not the plan","then":"Zara knows who, but not where or when."}],"why":"A friend who knows the plan is your safety net, even if family can't know."},{"prompt":"At the cafe, Rohit orders drinks and suggests a round of shots. What do you do?","options":[{"text":"Order what you like, and keep a clear head","then":"\"Chai it is,\" Rohit says, and the talk flows easily.","best":true},{"text":"Have a few, so you don't seem boring or uptight","then":"Your head's fuzzy by the second one, and you've lost track of time."},{"text":"Pretend to drink and pour it away","then":"It works, but you spend the date sneaking drinks into a plant pot."},{"text":"Tell him that drinking is wrong","then":"Rohit looks awkward. \"Oh. Okay. Sorry.\" The chat stalls."}],"why":"Staying clear-headed on a first meet keeps your choices in your hands."},{"prompt":"An hour in, Rohit suggests heading to his flat to watch a film. What do you do?","options":[{"text":"Go, since it'd be rude after he paid","then":"You'd be heading to a private flat with someone you met an hour ago."},{"text":"Decide you must have given him the wrong idea","then":"You go quiet, looking for a mistake you didn't make."},{"text":"Go, but share your live location with Zara","then":"Zara gets the pin. You'd still be alone in his flat, an hour after meeting."},{"text":"Say you'd like to keep tonight at the cafe","then":"\"Sure, no pressure,\" Rohit says, and orders another chai.","best":true}],"why":"A public first meet is yours to keep. Pressure to leave it is never your fault."},{"prompt":"The date ends, and Rohit offers to walk you back to your PG. What do you do?","options":[{"text":"Let him walk you all the way to your gate","then":"He walks you to your gate. Your way home ended up in his hands."},{"text":"Head home without texting Zara, since it went fine","then":"You get home safely, but no one knows you're back until morning."},{"text":"Say bye there and text Zara you're leaving","then":"You type \"Heading home now.\" Zara replies, \"Yay. Tell me everything!\"","best":true},{"text":"Share your live location with Rohit instead","then":"He can see your route home. It's a lot for a first meet."}],"why":"Ending on your own terms and checking in closes the safety loop."}],"debrief":"A told-a-friend plan and your own ride are how you meet on your terms.","relearn":"Before a first meet, tell a friend the plan and keep your own way home."},
  {"id":"sr-1404","cat":"tools-and-help","type":"branch","persona":"any","source":"won't video-call","hook":"Your match Dev has dodged every video call, and now wants your first meet at his flat.","steps":[{"prompt":"He texts: \"Just come over Saturday. Way chiller than a cafe.\" What do you do?","options":[{"text":"Go anyway. The chat has felt so nice","then":"He sends his address. You'd meet someone unverified, alone, in private."},{"text":"Say no to the flat, and meet at a cafe instead","then":"\"Ugh, fine,\" Dev writes. You still haven't seen his face live."},{"text":"Go to his flat, but share your location","then":"Your friend gets a pin. You're still meeting an unverified stranger in private."},{"text":"Hold off meeting until you've had a live call","then":"Dev sends a sulky emoji. \"Fine. Camera's broken, though.\"","best":true}],"why":"Nice chat isn't proof. A live call comes before any meet."},{"prompt":"Your friend Tariq says a live call is overkill if the photos look real. What do you do?","options":[{"text":"Agree, and decide the photos are enough","then":"You text Dev a yes. The face in the photos is still unconfirmed."},{"text":"Ask Tariq to reverse-search the photos","then":"Nothing comes up. That doesn't prove the photos are his."},{"text":"Say photos can be faked. A live call is the check","then":"Tariq pauses. \"Huh. I hadn't thought about AI photos.\"","best":true},{"text":"Drop it so Tariq doesn't think you're paranoid","then":"The doubt stays, and Tariq never hears why."}],"why":"Looking real isn't proof. A live call is the check that holds."},{"prompt":"The next day, Dev texts that his flat is still the plan and a call is pointless. What do you do?","options":[{"text":"Decide he's right, and skip the call","then":"\"Finally,\" he writes, and sends his address."},{"text":"Say you'll meet after a call, and leave it there","then":"Days pass without a call, and the chat quietly fades.","best":true},{"text":"Doubt yourself. Maybe you're too cautious","then":"You start rereading the chat for your mistakes, not his."},{"text":"Offer a busy mall instead, still without a call","then":"\"Fine,\" he writes. You'd still be meeting someone unverified."}],"why":"Pressure over a safety step is on him, never your fault. The call still comes first."}],"debrief":"Nice chat isn't proof. A live call first lets you meet safely.","relearn":"A match who dodges every video call is unverified; don't meet until you have."},
  {"id":"sr-1405","cat":"tools-and-help","type":"branch","persona":"any","source":"harassment route","hook":"You told Nitin you're not interested. Since then, he keeps sending threats.","steps":[{"prompt":"Three new messages arrived overnight. What do you do first?","options":[{"text":"Screenshot the threats, then block him","then":"The messages are saved in a folder, and his chat disappears from your screen.","best":true},{"text":"Reply once more to explain yourself","then":"He twists your reply and sends five more messages."},{"text":"Tell yourself you must have led him on","then":"You reread old chats, looking for a mistake that isn't there. His messages keep coming."},{"text":"Delete the chat so nobody finds out about it","then":"The chat is gone, and so is every message you'd need as proof."}],"why":"Proof plus a block cuts contact and keeps your options. None of this is your fault."},{"prompt":"A day later, he starts messaging from a second number too. What do you do?","options":[{"text":"Keep it to yourself so it doesn't get bigger","then":"It stays secret, and so does the fear."},{"text":"Tell yourself threats on an app are just talk","then":"You scroll past. The new number keeps going, and nothing new is saved."},{"text":"Threaten him back so he gets scared off","then":"He replies angrier, and the threats get worse."},{"text":"Screenshot them, and report to 1930","then":"The person on the line listens and talks you through your options.","best":true}],"why":"Cybercrime 1930 takes online threats, and women can also call 181. You don't have to face this alone."},{"prompt":"Your friend Aman notices you jump at every buzz and asks what's up. What do you do?","options":[{"text":"Say it's nothing. You're probably overreacting","then":"Aman lets it go. The messages keep coming, and you get quieter."},{"text":"Say it's just a guy being annoying online","then":"Aman laughs it off. He has no idea there are threats."},{"text":"Tell him about the threats and ask for help","then":"Aman puts his phone down. \"Okay. What do you need from me?\"","best":true},{"text":"Tell him, but say you'll handle it alone","then":"Aman frowns. \"If you're sure.\" You're still on your own with it."}],"why":"Threats are serious, never an overreaction. A friend who knows can back you up."},{"prompt":"One message says he knows where you study. What do you do?","options":[{"text":"Go and confront him so it stops","then":"You'd be facing someone who's threatening you, on your own."},{"text":"Tell someone you trust. Call 112 if unsafe","then":"A friend walks you to class, and you both keep 112 ready if it's needed.","best":true},{"text":"Decide it's an empty threat and tell no one","then":"You walk to class alone, scanning every face."},{"text":"Post his screenshots publicly to shame him","then":"The post spreads, and he messages again, angrier."}],"why":"When you feel unsafe, support and 112 come first. The threats are on him, never you."}],"debrief":"Threats aren't yours to absorb. Proof, a block and cybercrime 1930 are built for this. Women can also call 181.","relearn":"For ongoing harassment: block, save proof and report to cybercrime 1930; women can also call 181."},
  {"id":"sr-1406","cat":"tools-and-help","type":"branch","persona":"any","source":"gut on the date","hook":"Twenty minutes into your date with Ravi, something feels off, and you want to leave.","steps":[{"prompt":"He's just ordered you a second drink without asking. What do you do?","options":[{"text":"Stay, so you don't seem rude or dramatic","then":"You sit through another hour. The uneasy feeling doesn't lift."},{"text":"Say your exit line, go, and text a friend","then":"\"Oh. Okay,\" Ravi says. Within minutes you're outside, texting your friend.","best":true},{"text":"Wait for a \"good enough\" reason to go","then":"No clear reason comes. The evening drags on while you wait."},{"text":"Leave quietly, and keep it to yourself","then":"You're on the bus, and nobody knows you left early or where you are."}],"why":"Your gut is reason enough. Leaving and telling a friend keeps you in control."},{"prompt":"Later that night, Ravi texts asking whether he did something wrong. What do you reply?","options":[{"text":"\"It just didn't feel right for me. Take care.\"","then":"\"Okay,\" he replies. Nothing more comes.","best":true},{"text":"\"No, no! Sorry, I just got a headache.\"","then":"\"Next week, then?\" he asks at once."},{"text":"A long list of everything that felt off","then":"He argues every point. You're up past midnight defending your gut."},{"text":"\"Maybe I overreacted. Want to try again?\"","then":"\"Sure!\" he says. Now there's a second date you don't want."}],"why":"You owe no detailed reason. A short, kind line is enough."},{"prompt":"Your friend says you should give people a real chance before bailing. What do you say?","options":[{"text":"\"You're right. I'm too quick to leave.\"","then":"You start planning to sit through the next uneasy date."},{"text":"\"Maybe I'm just bad at dating.\"","then":"Your friend protests, but the thought sticks."},{"text":"\"Next time I'll give it an hour before deciding.\"","then":"Next time you watch the clock, waiting out a feeling that's already there."},{"text":"\"I do, when my gut's okay. Tonight it wasn't.\"","then":"Your friend nods. \"Fair. You know the feeling best.\"","best":true}],"why":"Trusting a feeling that something's off is a skill, not a flaw."}],"debrief":"Leaving on your gut is always allowed. A ready exit line makes it calm.","relearn":"If a date feels wrong you can leave on your gut alone; you owe no reason."},
  {"id":"sr-1407","cat":"tools-and-help","type":"branch","persona":"Deepak","source":"money ask","hook":"Sneha, a match you've never met, told you she loved you within a week.","steps":[{"prompt":"Now she says she's stranded in another city and needs money today. What do you do?","options":[{"text":"Send a little to help, just this once","then":"She sends a payment link at once, and asks if you can make it a bit more."},{"text":"Lend it, but ask her to repay it soon","then":"She promises to repay, sends hearts, and asks for a bit extra."},{"text":"Don't send anything, and report the account","then":"The app confirms your report. Sneha's messages turn sharp, then pleading.","best":true},{"text":"Say no, but keep chatting in case she's real","then":"By evening her story has changed. The account is still up, free to try others."}],"why":"A money ask from someone you've never met is a scam tell."},{"prompt":"Sneha sends a tearful voice note, saying you're the only one she trusts. What do you do?","options":[{"text":"Feel guilty and send what you can spare","then":"She sends her account details within seconds, with a list of what she needs."},{"text":"Hold firm: no money, however sad it sounds","then":"She goes silent for a day, then sends a new story.","best":true},{"text":"Ask her for a video call to prove it's real","then":"She says her camera's broken. The asks keep coming."},{"text":"Offer to pay her friend directly instead","then":"An account number arrives at once. It's the same ask with a new name."}],"why":"Fast love plus a money ask is the scam pattern. Even after a video call, the money stays a no."},{"prompt":"Your roommate says only gullible people get targeted like this. What do you say?","options":[{"text":"\"Scammers target anyone. It's on them.\"","then":"Your roommate pauses. \"Huh. I guess anyone could fall for a good story.\"","best":true},{"text":"\"Yeah. I feel so stupid.\"","then":"The shame sits with you, and you stop wanting to talk about it."},{"text":"\"I'd never have fallen for it anyway.\"","then":"Your roommate nods. Nobody thinks about who might be next."},{"text":"\"Just don't tell anyone about this, okay?\"","then":"Your roommate agrees. The idea that only gullible people get caught goes unchallenged."}],"why":"Being targeted by a scam is never your fault. It's on the person lying."},{"prompt":"A week later, a new match starts calling you \"jaan\" after two days. What do you do?","options":[{"text":"Enjoy it. Finally someone who's really into you","then":"By day four there's talk of a family emergency."},{"text":"Tell them you love them too, to keep it going","then":"They reply with hearts and plans for a future you haven't discussed."},{"text":"Match their speed, but never send money","then":"Things get intense fast. When the money ask comes, you're already deep in."},{"text":"Slow it down, and watch for any money ask","then":"The match cools off fast when you don't keep up with their speed.","best":true}],"why":"Fast, intense love from a stranger is a tell. Slowing down shows you who's real."}],"debrief":"Fast-love-then-money is the scam. Never sending and reporting shuts it down.","relearn":"A money ask from an online-only match is a scam tell; never send, and report."},
  {"id":"sr-1408","cat":"tools-and-help","type":"branch","persona":"any","source":"friend as check-in","hook":"Your friend Zubin is meeting an app match tonight and shrugs off telling anyone.","steps":[{"prompt":"He's heading out the door. What do you do?","options":[{"text":"Say nothing. It's not your business","then":"He leaves. Nobody knows where he'll be tonight."},{"text":"Tell him he's being reckless, and drop it","then":"\"Thanks, Mum,\" Zubin says, and goes."},{"text":"Tell him to share his location, no plan needed","then":"He shares it, grudgingly. You'd see a dot, but not who he's with or when he's back."},{"text":"Offer to be his check-in and learn the plan","then":"Zubin pauses. \"Fine. The cafe on 5th Cross, 8pm. I'll text by 11.\"","best":true}],"why":"Offering to hold the plan is a kindness, not interfering."},{"prompt":"At 11:30, Zubin isn't back, and your phone is quiet. What do you do?","options":[{"text":"Assume he's fine. He's a guy","then":"You go to bed. He gets in at 2, and nobody knew where he was."},{"text":"Call his family to raise the alarm","then":"His mum panics. Zubin is mortified, and he's fine."},{"text":"Message him and ask if all's okay","then":"\"All good! Lost track of time,\" he replies, with a sheepish emoji.","best":true},{"text":"Post in the group chat asking if anyone's heard","then":"Five people start worrying. Zubin still hasn't been asked."}],"why":"A quick check-in text is how the safety net actually works."},{"prompt":"Next day, Zubin asks whether check-ins for dates are even worth the fuss. What do you say?","options":[{"text":"\"Fine. I won't bother next time.\"","then":"He shrugs. Next time, nobody knows where he is."},{"text":"\"Let's do it for each other every time.\"","then":"Zubin grins. \"Deal. You're next.\"","best":true},{"text":"\"Only if you remember to ask me.\"","then":"He forgets next time, and so do you."},{"text":"\"Only for dates that seem dodgy.\"","then":"Zubin agrees. You'd both be guessing which ones those are."}],"why":"Making it mutual turns a safety step into an easy habit."}],"debrief":"Being the friend who holds the plan is one of the simplest safety tools.","relearn":"Offering to be a friend's check-in, with their plan, is a useful safety tool."},
  {"id":"sr-1409","cat":"tools-and-help","type":"role-play","persona":"any","source":"name your exit","hook":"Your date with Kiran has gone sour, and you want to leave now.","setup":"He's just started another long story.","steps":[{"prompt":"Kiran asks: \"Wait, where are you going? I'm just getting to the good part.\"","options":[{"text":"\"This isn't working for me. I'm heading off. Take care.\"","then":"Kiran blinks. \"Oh. Right. Okay, bye.\"","best":true},{"text":"\"Sorry, I'm being rude. Please, go on with your story.\"","then":"He carries on. You sit through the story, itching to go."},{"text":"\"My friend needs me. It's an emergency. Bye!\"","then":"\"Oh no, what happened?\" he asks, following you to the door."},{"text":"\"I should go. Can I explain why, though?\"","then":"\"Please do,\" he says, settling in. Now you're in a debate."}],"why":"A clear, warm line lets you leave. You owe no detailed reason."},{"prompt":"At the door, Kiran asks: \"Can I at least get your number?\"","options":[{"text":"\"Okay. I don't want to be mean.\"","then":"He saves it. Now there's a number to dodge."},{"text":"\"Give me yours. I'll message you.\"","then":"He types it into your phone, beaming. You won't message."},{"text":"\"You really think that went well?\"","then":"His smile drops. \"Okay, harsh.\""},{"text":"\"I'd rather not. Take care, though.\"","then":"\"Fair enough,\" he says, and steps back.","best":true}],"why":"A kind no is clearer than a false promise."},{"prompt":"On the bus, your friend Shalini calls: \"You left early? What happened?\"","options":[{"text":"\"Nothing. I'm just being dramatic.\"","then":"\"Are you sure?\" Shalini asks. You brush it off."},{"text":"\"Can't talk. Tell you later.\"","then":"\"Okay,\" Shalini says. She won't know if you got home."},{"text":"\"It felt off, so I left. Home in 20.\"","then":"\"Glad you're out,\" Shalini says. \"Text me when you're in.\"","best":true},{"text":"\"Ugh. I should've stayed. I was rude.\"","then":"\"Were you?\" Shalini asks. You start doubting a feeling that was real."}],"why":"Telling a friend you left and when you'll be home keeps your net in place."}],"relearn":"You can name an exit warmly and leave; you owe no detailed reason for ending a date early."},
  {"id":"sr-1410","cat":"tools-and-help","type":"role-play","persona":"any","source":"hold the public meet","hook":"Your first meet with Arnav is tomorrow, and he keeps pushing to change the plan.","setup":"His texts keep coming tonight.","steps":[{"prompt":"Arnav writes: \"Cafes are so fake. Just come to mine. It's comfier.\"","options":[{"text":"\"I keep first meets public. The cafe, or another time.\"","then":"Arnav sends an eye-roll emoji. \"We'll see tomorrow.\"","best":true},{"text":"\"You're right. I'm probably overthinking the public thing.\"","then":"\"Knew you'd see it,\" he writes, and sends his address."},{"text":"\"Your place, but I'll bring a friend along.\"","then":"\"A friend?\" he writes. \"That's weird.\" The plan is still private."},{"text":"\"No way. Only creeps ask that.\"","then":"\"Wow,\" Arnav writes. \"Sleep on it.\""}],"why":"Holding your public-meet step is a fair line, and saying it plainly is enough."},{"prompt":"On the day, Arnav texts: \"So, mine at 6? I'll make chai.\"","options":[{"text":"\"Yes. I don't want to seem like I don't trust you.\"","then":"\"Great,\" he writes. The first meet is now in his flat."},{"text":"\"Honestly? Only creeps keep asking.\"","then":"\"Wow,\" he writes, and the chat goes cold."},{"text":"\"I just get nervous. It's a me thing.\"","then":"\"Then I'll make you comfy at mine,\" he writes."},{"text":"\"The cafe at 6, or we skip it. Your pick.\"","then":"A pause. \"Fine. Cafe.\"","best":true}],"why":"A clear either-or keeps your public plan without a debate."},{"prompt":"That afternoon, your friend Nandita asks: \"So, where are you meeting him?\"","options":[{"text":"\"Probably his place. He'd be hurt if I said no.\"","then":"Nandita's eyebrows go up. \"Send me the address, at least?\""},{"text":"\"Still deciding. I'll see how I feel.\"","then":"\"Tell me when you know?\" Nandita asks. You might forget."},{"text":"\"Cafe on 5th Cross, 6pm. Public, whatever he says.\"","then":"\"Got it,\" Nandita says. \"Text me when you're done.\"","best":true},{"text":"\"Don't worry about it. I've got it.\"","then":"\"Okay,\" she says slowly. She has no idea where you'll be."}],"why":"A public place and a friend who knows keep it yours. Pushing is never your fault."}],"relearn":"You can hold your safety steps out loud; keeping the first meet public is a fair line to draw."},
  {"id":"sr-1411","cat":"tools-and-help","type":"role-play","persona":"any","source":"ask for the call","hook":"You'd like a quick video call with Nandini before your first meet.","setup":"You've been chatting for a week.","steps":[{"prompt":"Nandini writes: \"Sunday coffee? I know a lovely place.\"","options":[{"text":"\"It's silly, but would you mind a call? Only if it's not weird.\"","then":"\"Um, sure?\" she writes. \"Why would it be weird?\""},{"text":"\"Sounds lovely. Before we meet, can we do a quick video call?\"","then":"\"Of course,\" Nandini writes. \"Tonight at 9?\"","best":true},{"text":"\"Sunday's great. Maybe a call sometime too?\"","then":"\"Sure, sometime,\" she writes. Sunday comes first."},{"text":"\"Only if you video-call first. I need proof you're real.\"","then":"\"Proof?\" she writes. \"Okay... that's a bit intense.\""}],"why":"Asking plainly, without apology, makes it a normal step."},{"prompt":"Nandini asks: \"Do you always do a call before meeting?\"","options":[{"text":"\"Yes. I always do that first. Just how I start.\"","then":"\"Honestly, I like that,\" she writes.","best":true},{"text":"\"Only when someone seems a bit too good to be true.\"","then":"\"Oh. Do I seem that way?\" she asks."},{"text":"\"Not really. Forget it if it's a hassle.\"","then":"\"Oh, okay,\" she writes. \"Maybe we'll still try one, though.\""},{"text":"\"My friends make me. Sorry about that.\"","then":"\"Your friends?\" she writes. \"So you don't really want to?\""}],"why":"Owning it as your normal step keeps it from sounding like an insult."},{"prompt":"Nandini writes: \"My camera's a bit dodgy. Is audio enough?\"","options":[{"text":"\"Sure, audio's fine.\"","then":"She calls. Her voice is warm, and you still haven't seen her face."},{"text":"\"If it's dodgy, send a selfie instead.\"","then":"A selfie arrives. It could be from any day, or anyone."},{"text":"\"Dodgy camera? That's what catfish say.\"","then":"\"Wow,\" she writes. \"Never mind.\""},{"text":"\"Let's try video. A minute is plenty.\"","then":"\"Okay,\" she writes. \"Let me try my laptop.\"","best":true}],"why":"Only a live video call shows you who's really there."}],"relearn":"You can ask for a quick video call before meeting; it's a normal, reasonable check, not an insult."},
  {"id":"sr-1412","cat":"tools-and-help","type":"role-play","persona":"any","source":"set up the check-in","hook":"You have a first date on Saturday and want your friend Harsh as your check-in.","setup":"You catch him after class.","steps":[{"prompt":"Harsh asks: \"What's up? You look like you want to ask something.\"","options":[{"text":"\"It's probably nothing. You don't have to. But maybe?\"","then":"\"Maybe what?\" Harsh laughs. \"Is this about your Saturday date?\""},{"text":"\"Forget it. I don't want to bother you.\"","then":"\"You're not bothering me,\" Harsh says. \"Is it about Saturday?\""},{"text":"\"Can you be my check-in Saturday? I'll send the spot.\"","then":"\"Of course,\" Harsh says, pulling out his phone.","best":true},{"text":"\"Just check on me Saturday night, okay?\"","then":"\"Sure,\" Harsh says, then frowns. \"Check on you how, though?\""}],"why":"Asking plainly, with the plan, is a normal safety ask, not a burden."},{"prompt":"Harsh says: \"Happy to keep an eye out Saturday. What should I know?\"","options":[{"text":"\"Just their name. The rest is private.\"","then":"\"Okay,\" he says. He'd know who, but not where."},{"text":"\"Hill Road cafe, 6pm. Text by 9, or call me.\"","then":"Harsh saves it. \"Got it. 9pm, or I call.\"","best":true},{"text":"\"I'll just share my live location. That's enough.\"","then":"\"Okay,\" Harsh says. He'd see a dot, but not when to worry."},{"text":"\"Nothing much. Just be around, I guess.\"","then":"\"Around where?\" Harsh asks."}],"why":"A place, a time and a text-by give your friend what they need."},{"prompt":"On Saturday at 9:15, Harsh texts: \"No text yet. You okay?\"","options":[{"text":"\"All good! Running late. Home by 10. Will text.\"","then":"\"Cool,\" Harsh replies. \"Watching for it.\"","best":true},{"text":"\"Stop checking on me. It's embarrassing.\"","then":"Harsh goes quiet and doesn't check again."},{"text":"\"Yep, fine.\"","then":"\"Okay,\" he replies. He doesn't know when to expect you home."},{"text":"\"Oops, forgot. Don't wait up for me.\"","then":"He goes to bed. Nobody's watching for your text now."}],"why":"A quick update with a new time keeps your check-in working."}],"relearn":"You can ask a friend to be your check-in and share the plan; that's a normal safety ask, not a burden."},
  {"id":"sr-1413","cat":"tools-and-help","type":"role-play","persona":"any","source":"decline the money ask","hook":"Arun, a match you've never met, is pressing you to send money for a hospital bill.","setup":"His messages are coming in fast.","steps":[{"prompt":"Arun writes: \"Please, I'm desperate. You're the only one I can ask.\"","options":[{"text":"\"I really wish I could. Maybe a small bit?\"","then":"\"Anything helps,\" he writes at once. \"Can you do it now?\""},{"text":"\"That's awful. How much do you need?\"","then":"He names a figure, and a payment link arrives within seconds."},{"text":"\"Send me the hospital bill first.\"","then":"A bill arrives within minutes. It looks real. That doesn't mean it is."},{"text":"\"I don't send money to people I haven't met.\"","then":"\"Wow,\" Arun writes. \"After everything we talked about?\"","best":true}],"why":"A plain no protects you. Never send money to an online-only match."},{"prompt":"Arun writes: \"I'll pay you back double, I swear. Please.\"","options":[{"text":"\"I do care. I'd feel terrible saying no.\"","then":"\"Then prove it,\" he writes, and sends the payment link again."},{"text":"\"Let me think about it overnight.\"","then":"\"There's no time!\" he writes, and sends the link twice more."},{"text":"\"I'm not sending anything. I'm stopping here.\"","then":"Three angry messages arrive, then silence.","best":true},{"text":"\"I can't send money, but I'll keep chatting.\"","then":"\"Chatting won't pay the bill,\" he writes, and pushes again."}],"why":"Guilt and promises of repayment are part of the script. No stays no."},{"prompt":"Your friend Mehul asks: \"Should you report him, or is that too much?\"","options":[{"text":"\"Too much. He's probably just desperate.\"","then":"Mehul frowns. The account stays up, free to message others."},{"text":"\"I'm reporting him. There'll be others.\"","then":"Two taps, and the report is in. Mehul nods.","best":true},{"text":"\"What's the point? Reports never go anywhere.\"","then":"Mehul shrugs. Arun's next match gets the same hospital story."},{"text":"\"Maybe I led him on somehow.\"","then":"Mehul shakes his head, but the report never gets made."}],"why":"Reporting a money ask protects the next person too. It isn't overreacting."},{"prompt":"A week later, Mehul asks: \"How are you feeling about the whole thing?\"","options":[{"text":"\"Okay. It was a scam, and that's on him.\"","then":"Mehul nods, and the talk drifts to exams.","best":true},{"text":"\"Stupid. I should have seen it right away.\"","then":"Mehul shakes his head, but the shame stays with you."},{"text":"\"Done with apps. Everyone on them is fake.\"","then":"\"A break's fine,\" Mehul says. \"But not everyone's fake.\" You're not so sure."},{"text":"\"Fine. Let's never talk about it again.\"","then":"Mehul drops it. The sting stays with you, unspoken."}],"why":"Being targeted by a scam is never your fault. The lie was his."}],"relearn":"You can refuse a money ask plainly; never send money to an online-only match, no matter the story."},
  {"id":"sr-1414","cat":"tools-and-help","type":"role-play","persona":"Rohan","source":"kind sign-off","hook":"Your match Isha has gone cool on you, and you can tell it's over.","setup":"Her last reply was one word, a day late.","steps":[{"prompt":"Isha writes: \"Hey. Sorry, been busy. Things are just a lot right now.\"","options":[{"text":"\"No worries. I felt the same shift. Wishing you well.\"","then":"\"Thank you,\" Isha writes. \"Really. Take care.\"","best":true},{"text":"\"Wait, why? Did I do something? Can we talk it through?\"","then":"\"It's not like that,\" she writes, and takes a day to reply."},{"text":"\"Fine. Whatever. I'll just stop replying then.\"","then":"She doesn't answer. It ends with a door slammed, not closed."},{"text":"\"No worries! Talk soon, yeah?\"","then":"\"Sure,\" she writes. Neither of you believes it."}],"why":"A brief, kind sign-off lets you both move on with dignity."},{"prompt":"Your mate Pratik says: \"Women are all like that. Don't take it personally.\"","options":[{"text":"\"Yeah. They're all the same.\"","then":"Pratik nods. The next match starts out already blamed."},{"text":"\"Maybe I'm just not good enough.\"","then":"Pratik claps your shoulder, but the thought follows you home."},{"text":"\"Not all women. Just her.\"","then":"Pratik laughs. The blame is just smaller now."},{"text":"\"People lose interest. That's allowed.\"","then":"Pratik shrugs. \"Fair enough, I guess.\"","best":true}],"why":"Rejection isn't a verdict on you, or on everyone of a gender."},{"prompt":"A week later, a new match, Tara, asks: \"Why'd your last one end?\"","options":[{"text":"\"She wasted my time.\"","then":"Tara pauses. \"Oh. Okay.\""},{"text":"\"Long story. She was complicated.\"","then":"Tara raises an eyebrow and changes the subject."},{"text":"\"We drifted. No hard feelings.\"","then":"Tara nods. \"Same with mine, honestly.\"","best":true},{"text":"\"Let me show you our chats and you decide.\"","then":"Tara looks uneasy. \"I'd rather not.\""}],"why":"Speaking kindly about a past match shows how you'd treat a new one."}],"relearn":"A brief, kind sign-off beats ghosting and beats arguing a no; honesty runs both ways."},
  {"id":"sr-1415","cat":"tools-and-help","type":"role-play","persona":"Zoya","source":"refuse the outing threat","hook":"Your family doesn't know who you date. Ria, a match you said no to, has turned nasty.","setup":"The message arrives late at night.","steps":[{"prompt":"Ria writes: \"Keep talking to me, or your parents might see our chats.\"","options":[{"text":"\"I'm sure you don't mean that. We had fun chatting.\"","then":"\"Try me,\" Ria writes, and sends a screenshot of your chat."},{"text":"\"That's a threat, and it's reportable. We're done here.\"","then":"\"You wouldn't dare,\" Ria writes. Then: \"I'm serious.\"","best":true},{"text":"\"Why are you doing this? What did I do?\"","then":"Ria sends a long reply, twisting everything you've said."},{"text":"\"Sorry. Maybe I was too harsh when I said no.\"","then":"Ria replies at once: \"Then make it up to me.\""}],"why":"Naming it as a threat and ending the chat takes back control. None of this is your fault."},{"prompt":"The next morning, Ria writes: \"Last chance. Reply, or your mum sees it.\"","options":[{"text":"\"I've saved this, and I'm reporting it.\" Then block.","then":"The block goes through. Your screenshots sit safely in a folder.","best":true},{"text":"\"You're bluffing. You don't even know my family.\"","then":"Ria replies with a laughing emoji and another warning."},{"text":"\"You'll get bored of this soon enough.\"","then":"\"Bored?\" Ria writes. \"I've got all night.\""},{"text":"\"Delete the screenshots and I won't report you.\"","then":"\"Sure,\" Ria writes. You have no way to know if anything is deleted."}],"why":"Saving proof, then blocking, keeps your options open."},{"prompt":"That evening, Shreya, the one friend who knows, asks: \"You look shaken. What's going on?\"","options":[{"text":"\"Nothing. Just tired.\"","then":"Shreya sits down anyway and waits. In the end, you show her Ria's messages."},{"text":"\"It's my own fault for being on the app.\"","then":"\"Hey, no,\" Shreya says. You show her the messages. \"This isn't on you.\""},{"text":"\"Someone's being weird online. I'll handle it.\"","then":"Shreya frowns. \"Weird how?\" You end up showing her Ria's messages."},{"text":"\"Someone's threatening to out me. Can you help?\"","then":"Shreya sits down beside you. \"Okay. This is not on you. Let's work it out.\"","best":true}],"why":"Telling someone you trust means you don't carry a threat alone."},{"prompt":"Shreya says: \"I'm not going anywhere. What do you want to do?\"","options":[{"text":"\"Reporting won't help. Nothing ever happens.\"","then":"Shreya pauses. \"A record still counts if she tries again.\""},{"text":"\"I'll wait and see if she really does it.\"","then":"The days drag. Every buzz of your phone makes you jump."},{"text":"\"Sit with me while I report it to cybercrime 1930?\"","then":"\"Of course,\" Shreya says, and pulls her chair closer.","best":true},{"text":"\"Let's message her together and scare her off.\"","then":"Shreya hesitates. \"That could make her angrier.\""}],"why":"Reporting, with someone beside you and when you're ready, takes back control. It's never your fault."}],"relearn":"You can refuse coercion and name it as reportable; an outing threat is abuse, never your fault."},
  {"id":"sr-1416","cat":"tools-and-help","type":"role-play","persona":"any","source":"say no reason owed","hook":"You've decided not to meet Pranav after all, and you've just told him.","setup":"His reply comes within seconds.","steps":[{"prompt":"Pranav writes: \"Wait, you're cancelling? Can I ask why?\"","options":[{"text":"\"It's a long story. I have reasons. Let me explain each one.\"","then":"\"Go on.\" He argues with your first reason before you reach the second."},{"text":"\"I'm so sorry. Maybe I'm wrong. Should I give it one more chance?\"","then":"\"Yes!\" he writes, then asks why you wanted to cancel at all."},{"text":"\"I've decided not to meet up. I hope you understand. Take care.\"","then":"A pause. \"Okay. That's a bit sad, but thanks for telling me.\"","best":true},{"text":"\"Something came up. Maybe next week?\"","then":"\"Oh,\" he writes. \"Is that the real reason?\""}],"why":"A no is complete on its own. You don't owe a detailed reason."},{"prompt":"Pranav writes: \"Was it me, though? It feels like I'm missing the real reason.\"","options":[{"text":"\"Well, since you asked, here's everything.\"","then":"He argues with each point, and the chat drags past midnight."},{"text":"\"No blame. It just isn't right for me.\"","then":"\"Okay,\" he writes. \"I just don't get it, though.\"","best":true},{"text":"\"No, no, you were perfect. It's all me.\"","then":"\"Then let's still meet!\" he writes, hopeful."},{"text":"\"If you have to ask, you'll never get it.\"","then":"\"Wow,\" he writes. \"Okay then.\""}],"why":"Staying kind and clear stops a no from turning into a debate."},{"prompt":"The next day, Pranav writes: \"Can we just talk on a call? I think I deserve that.\"","options":[{"text":"\"I've shared what I can. I wish you well.\"","then":"No reply comes. The chat stays quiet.","best":true},{"text":"\"You're right. Let me explain properly.\"","then":"On the call, he picks apart each reason and asks for more."},{"text":"\"Maybe you do. I did say yes at first.\"","then":"\"Exactly,\" he writes. \"So, tomorrow?\""},{"text":"\"I'll think about it and get back to you.\"","then":"\"Okay,\" he writes. \"I'll wait.\" The no is now a maybe."}],"why":"A no stays complete. His pushing for more is on him, not you."},{"prompt":"A week later, Pranav's \"Changed your mind yet?\" pops up, and your friend Ritu asks: \"Is he still at this?\"","options":[{"text":"\"It's nothing. I don't want to make a big deal of it.\"","then":"Ritu lets it go. Pranav's messages stay yours alone to handle."},{"text":"\"Maybe I owe him a proper reason. Then he'd stop.\"","then":"Ritu shakes her head. \"He'd only argue with that too.\""},{"text":"\"Yes. He won't take my no. If he texts again, I'll block.\"","then":"Ritu nods. \"Screenshot it first, and tell me if he tries again.\"","best":true},{"text":"\"Honestly, it's kind of sweet that he's still trying.\"","then":"Ritu raises an eyebrow. \"Sweet, or just not hearing your no?\""}],"why":"Telling a friend means you don't carry his pushing alone, and blocking is always yours to use."}],"relearn":"You can cancel a meet without a reason; a no or a cancellation is complete on its own."},
  {"id":"sr-1417","cat":"tools-and-help","type":"spot","persona":"any","source":"checklist gaps","relearn":"Going dark and being picked up from home are off the meet-safe checklist; public, told-a-friend, own ride are on it.","hook":"Spot the two moves that break the meet-safe checklist.","scene":[{"id":"a","text":"Meeting at a busy cafe you chose","trick":false},{"id":"b","text":"Telling no one where you'll be","trick":true},{"id":"c","text":"A friend has your plan and timing","trick":false},{"id":"d","text":"Letting them pick you up from home","trick":true},{"id":"e","text":"Your own cab booked for the way back","trick":false}],"why":"Telling no one and being picked up from home drop your safety net; the other three keep it."},
  {"id":"sr-1418","cat":"tools-and-help","type":"spot","persona":"any","source":"scam tells","relearn":"A money ask and never video-calling are scam tells; a willing call, a public meet and a slow pace are not.","hook":"Spot the two scam tells in this match's behaviour.","scene":[{"id":"a","text":"Happy to do a quick video call","trick":false},{"id":"b","text":"Asks you to wire money for an emergency","trick":true},{"id":"c","text":"Suggests meeting in a public cafe","trick":false},{"id":"d","text":"Always has a reason not to video-call","trick":true},{"id":"e","text":"Lets the pace stay slow and easy","trick":false}],"why":"A money ask and dodging every call are the classic scam tells; the others read as genuine."},
  {"id":"sr-1419","cat":"tools-and-help","type":"spot","persona":"any","source":"pressure lines","relearn":"Lines pushing you to skip the public meet or telling a friend are red flags.","hook":"Spot the two lines that pressure you to drop a safety step.","scene":[{"id":"a","text":"\"A public cafe sounds perfect, see you there\"","trick":false},{"id":"b","text":"\"Just come to mine, don't be so uptight\"","trick":true},{"id":"c","text":"\"Tell your friend, I'd want mine to know too\"","trick":false},{"id":"d","text":"\"Why tell anyone? Don't you trust me?\"","trick":true},{"id":"e","text":"\"No rush, we can meet whenever you're ready\"","trick":false}],"why":"Pushing you to skip the public meet or tell no one are the two red flags."},
  {"id":"sr-1420","cat":"tools-and-help","type":"spot","persona":"any","source":"wrong routes","relearn":"Paying a blackmailer and staying silent help no one; report to 1930, save proof and tell a friend do.","hook":"Spot the two moves that won't help after a leaked image.","scene":[{"id":"a","text":"Report it to cybercrime 1930","trick":false},{"id":"b","text":"Pay the blackmailer to make it stop","trick":true},{"id":"c","text":"Save screenshots as proof","trick":false},{"id":"d","text":"Decide to stay silent and blame yourself","trick":true},{"id":"e","text":"Tell a trusted friend so you're not alone","trick":false}],"why":"Paying invites more demands and self-blame keeps you stuck; the other three are the moves that actually help."},
  {"id":"sr-1421","cat":"tools-and-help","type":"spot","persona":"Meena","source":"wrong bindings","relearn":"Image abuse is 1930 and harassment is 181; pairing them with the wrong number sends you the wrong way.","hook":"Spot the two route mix-ups in this list.","scene":[{"id":"a","text":"Image abuse and blackmail: cybercrime 1930","trick":false},{"id":"b","text":"Harassment: cybercrime 1930","trick":true},{"id":"c","text":"Harassment and threats: helpline 181","trick":false},{"id":"d","text":"Immediate danger: helpline 181","trick":true},{"id":"e","text":"Immediate danger: emergency 112","trick":false}],"why":"Harassment goes to 181, not 1930, and danger goes to 112, not 181; the other three pair correctly."},
  {"id":"sr-1422","cat":"tools-and-help","type":"spot","persona":"any","source":"fake verify","relearn":"Trusting photos alone or skipping the call don't verify a match; a live call and a public first meet do.","hook":"Spot the two moves that don't actually verify a match.","scene":[{"id":"a","text":"Do a live video call before meeting","trick":false},{"id":"b","text":"Decide the photos look real enough","trick":true},{"id":"c","text":"Meet first in a public place","trick":false},{"id":"d","text":"Skip the call to save the hassle","trick":true},{"id":"e","text":"Ask a mutual friend if they're real","trick":false}],"why":"Photos can be stolen or AI-made and skipping the call verifies nothing; the other three actually check."},
  {"id":"sr-1423","cat":"tools-and-help","type":"spot","persona":"Rohan","source":"pressure after no","relearn":"Flooding texts and demanding a reason are pressure; a kind sign-off and giving space are the decent tools.","hook":"Spot the two responses to a no that cross into pressure.","scene":[{"id":"a","text":"Send one brief, kind sign-off","trick":false},{"id":"b","text":"Text again and again for a reply","trick":true},{"id":"c","text":"Give them space after that","trick":false},{"id":"d","text":"Demand they explain why it's a no","trick":true},{"id":"e","text":"Thank them and move on","trick":false}],"why":"Flooding texts and demanding a reason turn a no into pressure; the other three handle it with decency."},
  {"id":"sr-1424","cat":"tools-and-help","type":"spot","persona":"any","source":"checklist confusions","relearn":"Sharing your address and going dark aren't safety steps; public, told-a-friend and clear-headed are.","hook":"Spot the two items that don't belong on a safety plan.","scene":[{"id":"a","text":"Pick a public place to meet","trick":false},{"id":"b","text":"Send them your home address first","trick":true},{"id":"c","text":"Stay clear-headed on the meet","trick":false},{"id":"d","text":"Switch your phone off so you're unreachable","trick":true},{"id":"e","text":"Keep your own way home","trick":false}],"why":"Handing over your address and going unreachable strip your safety net; the other three are the real steps."},
];

